function isDeepLinkable(hash) {
    if (typeof hash !== 'string' || !hash) return false;
    return DEEP_LINK_ROUTES.includes(hash.split('?')[0]);
}


function rememberIntendedRoute(hash) {
    if (!isDeepLinkable(hash)) return;
    try {
        sessionStorage.setItem(INTENDED_ROUTE_KEY, hash);
    } catch (err) {
        
        
        console.warn('Could not remember where you were going:', err.message);
    }
}









function takeIntendedRoute() {
    let stored = null;
    try {
        stored = sessionStorage.getItem(INTENDED_ROUTE_KEY);
        sessionStorage.removeItem(INTENDED_ROUTE_KEY);
    } catch (err) {
        return null;
    }
    return isDeepLinkable(stored) ? stored : null;
}




function clearIntendedRoute() {
    try {
        sessionStorage.removeItem(INTENDED_ROUTE_KEY);
    } catch (err) {
        
    }
}


















function reloadAt(hash) {
    window.CEO_RELOAD_PENDING = true;
    if (hash) window.location.hash = hash;
    window.location.reload();
}














