function scrollToTop() {
    if (typeof window === 'undefined') return;
    if (typeof window.scrollTo !== 'function') return;
    try {
        window.scrollTo({ top: 0, left: 0, behavior: 'auto' });
    } catch (err) {
        window.scrollTo(0, 0);
    }
}








const ANCHOR_ID_SHAPE = /^[a-z][a-z0-9-]{0,48}$/;





function sectionAnchorFromHash(hash) {
    if (typeof hash !== 'string' || !hash) return null;
    const query = hash.split('?')[1];
    if (!query) return null;
    
    
    
    for (const pair of query.split('&')) {
        const eq = pair.indexOf('=');
        if (eq < 0) continue;
        if (pair.slice(0, eq) !== 'at') continue;
        let value;
        try {
            value = decodeURIComponent(pair.slice(eq + 1));
        } catch (err) {
            
            return null;
        }
        return ANCHOR_ID_SHAPE.test(value) ? value : null;
    }
    return null;
}












function clearSectionAnchor(hash) {
    const parts = String(hash || '').split('?');
    const path = parts[0];
    const kept = (parts[1] || '')
        .split('&')
        .filter(pair => pair && pair.split('=')[0] !== 'at')
        .join('&');
    const next = kept ? path + '?' + kept : path;
    try {
        window.history.replaceState({}, '', window.location.pathname + next);
    } catch (err) {
        
        
        console.warn('Could not tidy the anchor out of the URL:', err.message);
    }
}






function findAnchorTarget(id) {
    if (!id) return null;
    return document.getElementById(id);
}








function applySectionAnchor(hash) {
    const id = sectionAnchorFromHash(hash);
    if (!id) return false;

    
    
    clearSectionAnchor(hash);

    const target = findAnchorTarget(id);
    if (!target) {
        
        
        console.warn('Link pointed at #' + id + ', which is not on this screen.');
        return false;
    }

    
    
    
    
    
    
    const reduceMotion = window.matchMedia
        && window.matchMedia('(prefers-reduced-motion: reduce)').matches === true;
    try {
        target.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'start' });
    } catch (err) {
        
        if (typeof target.scrollIntoView === 'function') target.scrollIntoView();
    }

    
    
    
    
    
    
    
    if (!reduceMotion) {
        target.classList.remove('anchor-flash');
        
        
        
        void target.offsetWidth;
        target.classList.add('anchor-flash');
        window.setTimeout(function () { target.classList.remove('anchor-flash'); }, 2200);
    }

    return true;
}






































