const SOURCE_PARAMS = ['from', 'src', 'utm_source'];

function readParam(query) {
    if (!query) return null;
    let params = null;
    try {
        params = new URLSearchParams(String(query));
    } catch (err) {
        return null;
    }
    for (const name of SOURCE_PARAMS) {
        const raw = params.get(name);
        if (raw) return raw;
    }
    return null;
}






function normaliseSignupSource(raw) {
    const value = String(raw || '').trim().toLowerCase();
    if (!value || value.length > 32 || !/^[a-z0-9_.-]+$/.test(value)) return null;
    if (knownSignupSource(value)) return value;
    const alias = SOURCE_ALIASES[value];
    return alias && knownSignupSource(alias) ? alias : null;
}




























let clickCounted = false;








function countSignupLinkClick(source) {
    if (clickCounted) return false;

    const channel = normaliseSignupSource(source);
    if (!channel) return false;

    if (typeof window === 'undefined' || !window.db || typeof window.db.rpc !== 'function') {
        return false;
    }

    clickCounted = true;
    try {
        const sent = window.db.rpc('record_signup_link_click', { p_source: channel });
        if (sent && typeof sent.then === 'function') sent.then(() => {}, () => {});
    } catch (err) {
        
        
    }
    return true;
}














function captureSignupSource(hash, search) {
    const rawHash = hash === undefined
        ? (typeof window !== 'undefined' ? window.location.hash : '')
        : hash;
    const rawSearch = search === undefined
        ? (typeof window !== 'undefined' ? window.location.search : '')
        : search;

    const h = String(rawHash || '');
    const q = h.indexOf('?');
    const source = normaliseSignupSource(readParam(q < 0 ? '' : h.slice(q + 1)))
                || normaliseSignupSource(readParam(String(rawSearch || '').replace(/^\?/, '')));

    if (!source) return null;

    try {
        localStorage.setItem(SOURCE_KEY, JSON.stringify({
            source: source,
            at: new Date().toISOString()
        }));
    } catch (err) {
        
        
        
    }

    
    
    
    countSignupLinkClick(source);

    return source;
}






function pendingSignupSource() {
    let raw = null;
    try {
        raw = localStorage.getItem(SOURCE_KEY);
    } catch (err) {
        return null;
    }
    if (!raw) return null;

    let held = null;
    try {
        held = JSON.parse(raw);
    } catch (err) {
        
        
        clearSignupSource();
        return null;
    }

    const source = normaliseSignupSource(held && held.source);
    if (!source) {
        clearSignupSource();
        return null;
    }

    const at = new Date(held && held.at).getTime();
    if (!Number.isFinite(at) || Date.now() - at > SOURCE_DAYS * 86400000) {
        clearSignupSource();
        return null;
    }

    return source;
}

function clearSignupSource() {
    try {
        localStorage.removeItem(SOURCE_KEY);
    } catch (err) {
        
        
    }
}




















