window.refreshAccessState = async function refreshAccessState() {
    try {
        const { data: { session } } = await window.db.auth.getSession();
        if (!session || !session.user) return null;

        let { data: profile, error } = await window.db
            .from('profiles')
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            .select('subscription_status, trial_ends_at, plan_tier, comp_pro, data_erased_at, cancel_at_period_end, current_period_end, pending_plan_tier, is_beta_tester, is_admin')
            .eq('id', session.user.id)
            .maybeSingle();

        
        
        
        
        
        if (error && (error.code === '42703' || /plan_tier|comp_pro|data_erased_at|cancel_at_period_end|current_period_end|pending_plan_tier|is_beta_tester|is_admin/.test(error.message || ''))) {
            console.warn('profiles.plan_tier / comp_pro / data_erased_at / the subscription-period columns / the beta columns are missing — run the migrations. Treating this account as base.');
            ({ data: profile, error } = await window.db
                .from('profiles')
                .select('subscription_status, trial_ends_at')
                .eq('id', session.user.id)
                .maybeSingle());
        }

        
        
        if (error) {
            console.warn('Could not refresh access state:', error.message);
            return null;
        }

        
        if (!profile) {
            localStorage.setItem('ceo_sub_status', 'incomplete');
            localStorage.removeItem('ceo_trial_ends_at');
            localStorage.removeItem('ceo_plan_tier');
            localStorage.removeItem('ceo_comp_pro');
            localStorage.removeItem('ceo_data_erased_at');
            localStorage.removeItem('ceo_cancel_at_period_end');
            localStorage.removeItem('ceo_current_period_end');
            localStorage.removeItem('ceo_pending_plan_tier');
            localStorage.removeItem('ceo_beta_tester');
            localStorage.removeItem('ceo_admin');
            return { status: 'incomplete', daysLeft: 0, trialEndsAt: null, tier: 'base', compPro: false };
        }

        
        
        
        
        
        if (profile.data_erased_at) {
            localStorage.setItem('ceo_data_erased_at', profile.data_erased_at);
        } else {
            localStorage.removeItem('ceo_data_erased_at');
        }

        
        
        
        
        
        
        
        
        
        
        
        
        
        if (profile.cancel_at_period_end === true) {
            localStorage.setItem('ceo_cancel_at_period_end', 'true');
        } else {
            localStorage.removeItem('ceo_cancel_at_period_end');
        }
        if (profile.current_period_end) {
            localStorage.setItem('ceo_current_period_end', profile.current_period_end);
        } else {
            localStorage.removeItem('ceo_current_period_end');
        }
        if (profile.pending_plan_tier === 'base' || profile.pending_plan_tier === 'pro') {
            localStorage.setItem('ceo_pending_plan_tier', profile.pending_plan_tier);
        } else {
            localStorage.removeItem('ceo_pending_plan_tier');
        }

        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        if (profile.is_beta_tester === true) {
            localStorage.setItem('ceo_beta_tester', 'true');
        } else {
            localStorage.removeItem('ceo_beta_tester');
        }
        if (profile.is_admin === true) {
            localStorage.setItem('ceo_admin', 'true');
        } else {
            localStorage.removeItem('ceo_admin');
        }

        const trialEndsAt = profile.trial_ends_at ? new Date(profile.trial_ends_at) : null;
        const compPro = profile.comp_pro === true;
        let status = profile.subscription_status || 'incomplete';
        let daysLeft = null;

        
        
        
        
        
        if (status === 'trialing') {
            if (!trialEndsAt) {
                status = 'trial_expired';
                daysLeft = 0;
            } else {
                const msLeft = trialEndsAt.getTime() - Date.now();
                daysLeft = Math.max(0, Math.ceil(msLeft / 86400000));
                if (msLeft <= 0) status = 'trial_expired';
            }
        }

        
        
        
        
        
        
        
        
        
        
        
        
        
        let tier = 'base';
        if (compPro) {
            
            
            
            
            tier = 'pro';
        } else if (status === 'trialing') {
            tier = 'pro';
        } else if (status === 'active') {
            tier = profile.plan_tier === 'pro' ? 'pro' : 'base';
        }

        localStorage.setItem('ceo_sub_status', status);
        localStorage.setItem('ceo_plan_tier', tier);
        
        
        
        if (compPro) {
            localStorage.setItem('ceo_comp_pro', 'true');
        } else {
            localStorage.removeItem('ceo_comp_pro');
        }
        if (trialEndsAt) {
            localStorage.setItem('ceo_trial_ends_at', trialEndsAt.toISOString());
        } else {
            localStorage.removeItem('ceo_trial_ends_at');
        }

        return { status, daysLeft, trialEndsAt, tier, compPro };
    } catch (err) {
        console.warn('Could not refresh access state:', err.message);
        return null;
    }
};














