const CURRENCIES = [
    { symbol: '£', code: 'GBP', label: '£  British Pound (GBP)' },
    { symbol: '$', code: 'USD', label: '$  US Dollar (USD)' },
    { symbol: '€', code: 'EUR', label: '€  Euro (EUR)' },
    { symbol: 'A$', code: 'AUD', label: 'A$  Australian Dollar (AUD)' },
    { symbol: 'C$', code: 'CAD', label: 'C$  Canadian Dollar (CAD)' },
    { symbol: 'R', code: 'ZAR', label: 'R  South African Rand (ZAR)' }
];




function currencyCodeFor(symbol) {
    const match = CURRENCIES.find(c => c.symbol === symbol);
    return match ? match.code : 'USD';
}




function currencySymbolFor(code) {
    const key = String(code || '').toUpperCase();
    const match = CURRENCIES.find(c => c.code === key);
    return match ? match.symbol : key;
}


function baseCurrencyCode(store) {
    return currencyCodeFor((store && store.settings && store.settings.currency) || '$');
}














function conversionRateFor(store, code, base) {
    const rates = (store && store.settings && store.settings.conversionRates) || {};
    const entry = rates[String(code || '').toUpperCase()];
    if (!entry || typeof entry !== 'object') return null;

    const rate = parseFloat(entry.rate);
    if (!Number.isFinite(rate) || rate <= 0) return null;
    if (entry.base !== base) return null;

    return rate;
}
















function convertImportedEntry(entry, base, store) {
    const code = String(entry.currency || '').toUpperCase();

    
    
    
    
    if (!code || code === base) return entry;

    const rate = conversionRateFor(store, code, base);
    const gross = parseFloat(entry.grossAmount != null ? entry.grossAmount : entry.amount) || 0;

    if (rate === null) {
        return {
            ...entry,
            amount: 0,
            originalAmount: gross,
            originalCurrency: code,
            needsRate: true
        };
    }

    const round = (n) => Math.round(n * 100) / 100;

    return {
        ...entry,
        amount: round((parseFloat(entry.amount) || 0) * rate),
        grossAmount: round(gross * rate),
        
        
        
        
        fee: entry.fee === null || entry.fee === undefined ? entry.fee : round((parseFloat(entry.fee) || 0) * rate),
        originalAmount: gross,
        originalCurrency: code,
        
        
        
        
        conversionRate: rate,
        converted: true
    };
}









function unconvertedSummary(entries) {
    const groups = new Map();

    (entries || []).forEach(e => {
        if (!e || !e.needsRate || e.refunded) return;
        const code = String(e.originalCurrency || '').toUpperCase();
        if (!code) return;

        const current = groups.get(code) || { code, symbol: currencySymbolFor(code), count: 0, originalTotal: 0 };
        current.count += 1;
        current.originalTotal += parseFloat(e.originalAmount) || 0;
        groups.set(code, current);
    });

    return Array.from(groups.values()).sort((a, b) => b.count - a.count);
}




function foreignCurrenciesPresent(entries, base) {
    const codes = new Set();
    (entries || []).forEach(e => {
        const code = String((e && e.currency) || '').toUpperCase();
        if (code && code !== base) codes.add(code);
    });
    return Array.from(codes).sort();
}






































const SOURCE_LABELS = {
    stripe: 'Stripe',
    paypal: 'PayPal',
};

function sourceLabel(source) {
    const key = String(source || '').toLowerCase();
    if (SOURCE_LABELS[key]) return SOURCE_LABELS[key];
    if (!key) return 'Imported';
    return key.charAt(0).toUpperCase() + key.slice(1);
}















async function fetchImportedSales() {
    try {
        
        
        const session = await waitForSession();
        if (!session) return null;

        const { data, error } = await window.db
            .from('imported_sales')
            
            
            .select('source, external_id, amount, currency, occurred_at, description, product_name, product_id, customer_email, refunded, fee, recurring')
            .eq('user_id', session.user.id)
            .order('occurred_at', { ascending: false })
            .limit(500);

        if (error) {
            console.warn('Could not read imported sales:', error.message);
            return null;
        }
        return data || [];
    } catch (err) {
        console.warn('Could not read imported sales:', err.message);
        return null;
    }
}












let importedSalesCache = [];
let importedSalesLoaded = false;

function getImportedSalesCache() {
    return importedSalesCache;
}

function hasLoadedImportedSales() {
    return importedSalesLoaded;
}






















function manualSaleHint() {
    const names = [...new Set(
        getImportedSalesCache().map(e => sourceLabel(e && e.source)).filter(Boolean)
    )];
    if (!names.length) return '';
    const list = names.length === 1
        ? names[0]
        : names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1];
    return `${list} sales come in on their own, so you do not need to add them here. `
        + `Log a sale on this form only if the money came in somewhere else, or it will be counted twice.`;
}




function countImportedFrom(source) {
    const key = String(source || '').toLowerCase();
    return importedSalesCache.filter(e => String(e.sourceKey || '').toLowerCase() === key).length;
}








function toEntryShape(row) {
    const gross = parseFloat(row.amount) || 0;
    const refunded = !!row.refunded;
    const key = String(row.source || 'stripe').toLowerCase();
    const label = sourceLabel(key);
    return {
        
        
        
        
        id: `${key}:${row.external_id}`,
        
        
        
        
        
        date: String(row.occurred_at || ''),
        amount: refunded ? 0 : gross,
        grossAmount: gross,
        refunded,
        
        
        
        
        
        
        
        
        currency: String(row.currency || '').toUpperCase(),
        
        
        source: label,
        
        
        sourceKey: key,
        offer: row.product_name || row.description || `${label} payment`,
        
        
        
        
        
        
        
        
        
        
        productId: row.product_id || '',
        productName: row.product_name || row.description || '',
        type: 'sale',
        imported: true,
        customerEmail: row.customer_email || '',
        
        
        
        
        
        
        
        fee: row.fee === null || row.fee === undefined ? null : (parseFloat(row.fee) || 0),
        recurring: row.recurring === null || row.recurring === undefined ? null : !!row.recurring
    };
}
































function productKeyFor(entry) {
    if (!entry) return null;
    const source = String(entry.sourceKey || 'stripe').toLowerCase();

    const id = String(entry.productId || '').trim();
    if (id) return `${source}:id:${id}`;

    const name = String(entry.productName || '').trim();
    if (name) return `${source}:name:${name.toLowerCase()}`;

    return null;
}






function applyProductOffer(entry, mapping) {
    if (!mapping) return entry;

    const key = productKeyFor(entry);
    if (!key) return entry;

    const mapped = mapping[key];
    
    
    
    if (typeof mapped !== 'string' || mapped.trim() === '') return entry;
    if (mapped === entry.offer) return entry;

    return { ...entry, offer: mapped, originalOffer: entry.offer, mappedOffer: true };
}











function importedProducts(entries) {
    const groups = new Map();

    (entries || []).forEach(e => {
        const key = productKeyFor(e);
        if (!key) return;

        const current = groups.get(key) || {
            key,
            
            
            
            label: e.productName || e.offer || 'Untitled',
            sourceLabel: e.source || 'Imported',
            count: 0,
            total: 0
        };
        current.count += 1;
        current.total += parseFloat(e.amount) || 0;
        groups.set(key, current);
    });

    return Array.from(groups.values()).sort((a, b) => b.count - a.count || b.total - a.total);
}






function unmatchedProducts(entries, mapping) {
    const map = mapping || {};
    return importedProducts(entries).filter(p => typeof map[p.key] !== 'string');
}


async function refreshImportedSales() {
    const rows = await fetchImportedSales();
    
    
    
    
    
    
    
    
    if (rows === null) return importedSalesCache;
    importedSalesCache = rows.map(toEntryShape);
    importedSalesLoaded = true;
    return importedSalesCache;
}




















async function waitForSession(timeoutMs = 8000) {
    const immediate = await getSessionSafely();
    if (immediate) return immediate;

    return new Promise(resolve => {
        let settled = false;
        let subscription = null;
        let poller = null;

        const finish = (session) => {
            if (settled) return;
            settled = true;
            if (poller) clearInterval(poller);
            if (timer) clearTimeout(timer);
            try { subscription?.unsubscribe(); } catch (err) {  }
            resolve(session);
        };

        const timer = setTimeout(() => finish(null), timeoutMs);

        try {
            const { data } = window.db.auth.onAuthStateChange((_event, session) => {
                if (session && session.user) finish(session);
            });
            subscription = data?.subscription;
        } catch (err) {
            
        }

        
        poller = setInterval(async () => {
            const s = await getSessionSafely();
            if (s) finish(s);
        }, 400);
    });
}

async function getSessionSafely() {
    try {
        const { data: { session } } = await window.db.auth.getSession();
        return (session && session.user) ? session : null;
    } catch (err) {
        return null;
    }
}




















async function fetchConnectionRow(table, columns) {
    const session = await waitForSession();
    if (!session) return { state: 'unknown', conn: null };

    try {
        const { data, error } = await window.db
            .from(table)
            .select(columns)
            .eq('user_id', session.user.id)
            .maybeSingle();

        if (error) {
            console.warn(`Could not read ${table}:`, error.message);
            return { state: 'unknown', conn: null };
        }
        return data ? { state: 'connected', conn: data } : { state: 'none', conn: null };
    } catch (err) {
        console.warn(`Could not read ${table}:`, err.message);
        return { state: 'unknown', conn: null };
    }
}

















