function getLocalDateString(date = new Date()) {
    const d = new Date(date);
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}














function quarterCountsFrom(store = getStore()) {
    if (!store.quarterStartDate) return null;
    const d = new Date(store.quarterStartDate);
    if (!Number.isFinite(d.getTime())) return null;
    d.setHours(0, 0, 0, 0);
    return d;
}

function parseDateInput(value) {
    if (!value) return new Date();
    const parts = String(value).split('-').map(Number);
    if (parts.length !== 3 || parts.some(n => !Number.isFinite(n))) return new Date(value);
    const [year, month, day] = parts;
    return new Date(year, month - 1, day, 12, 0, 0, 0);
}




function formatAmount(value) {
    const n = parseFloat(value) || 0;
    return n.toLocaleString(undefined, {
        minimumFractionDigits: Number.isInteger(n) ? 0 : 2,
        maximumFractionDigits: 2
    });
}

const DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];



function getPlanningDayName(store = getStore()) {
    const name = store?.profile?.planningDay;
    return DAY_NAMES.includes(name) ? name : 'Monday';
}

function getPlanningDayIndex(store = getStore()) {
    return DAY_NAMES.indexOf(getPlanningDayName(store));
}









function getReviewDayIndex(store = getStore()) {
    return (getPlanningDayIndex(store) + 6) % 7;
}

function getReviewDayName(store = getStore()) {
    return DAY_NAMES[getReviewDayIndex(store)];
}









function getWeekStart(date = new Date(), store = getStore()) {
    const d = new Date(date);
    const startIdx = getPlanningDayIndex(store);
    
    const back = (d.getDay() - startIdx + 7) % 7;
    d.setDate(d.getDate() - back);
    d.setHours(0, 0, 0, 0);
    return d;
}



function getNextPlanningDay(date = new Date(), store = getStore()) {
    const d = getWeekStart(date, store);
    d.setDate(d.getDate() + 7);
    return d;
}









function firstName(store = getStore()) {
    const full = (store?.profile?.name || '').trim();
    if (!full) return 'CEO';
    return full.split(/\s+/)[0] || 'CEO';
}











function greeting(at = new Date()) {
    const hour = at.getHours();
    if (hour < 12) return 'Good morning';
    if (hour < 18) return 'Good afternoon';
    return 'Good evening';
}
















function roadmapWeekToPlan(store = getStore()) {
    const unapplied = (store.weeklyPlans || [])
        .filter(p => p && p.generated && !p.applied)
        .sort((a, b) => (a.weekNumber || 0) - (b.weekNumber || 0));
    if (unapplied.length === 0) return null;
    
    
    const current = currentRoadmapWeek(store);
    if (current === null) return unapplied[0];
    return unapplied.find(p => Number(p.weekNumber) === current)
        || unapplied.find(p => Number(p.weekNumber) > current)
        || null;
}





function quarterMonthNumber(store = getStore()) {
    const week = currentRoadmapWeek(store);
    if (week === null) return 1;
    return Math.min(3, Math.max(1, Math.ceil(week / 4)));
}

function getWeeksElapsed(store, quarterWeeks = 12, asOf = Date.now()) {
    const start = store?.quarterStartDate ? new Date(store.quarterStartDate) : null;
    if (!start || !Number.isFinite(start.getTime())) return null;

    
    
    const msPerDay = 24 * 60 * 60 * 1000;
    const daysElapsed = Math.floor((asOf - start.getTime()) / msPerDay);
    
    
    
    
    
    const elapsed = Math.ceil(daysElapsed / 7) - pausedWeekNumbers(store).length;
    return Math.min(quarterWeeks, Math.max(1, elapsed));
}

