function getStore() {
    try {
        const data = localStorage.getItem(STORE_KEY);
        if (data) {
            const parsed = JSON.parse(data);
            const finalStore = {
                ...defaultState,
                ...parsed,
                profile: { ...defaultState.profile, ...(parsed.profile || {}) },
                goals: { ...defaultState.goals, ...(parsed.goals || {}) },
                revenue: { ...defaultState.revenue, ...(parsed.revenue || {}), quickOffers: parsed.revenue?.quickOffers || [] },
                leads: { ...defaultState.leads, ...(parsed.leads || {}) },
                contacts: parsed.contacts || [],
                settings: { ...defaultState.settings, ...(parsed.settings || {}) },
                aiReportHistory: parsed.aiReportHistory || [],
                metrics: parsed.metrics || [],
                expenses: parsed.expenses || [],
                quarterStartDate: parsed.quarterStartDate || '',
                pausedWeeks: parsed.pausedWeeks || [],
                pastQuarters: parsed.pastQuarters || [],
                draftQuarterReflection: parsed.draftQuarterReflection || null,
                draftMonthlyReview: parsed.draftMonthlyReview || null,
                quarterPlanDeferred: parsed.quarterPlanDeferred || null,
                weeklyPlans: parsed.weeklyPlans || [],
                reviews: parsed.reviews || [],
                monthlyReviews: parsed.monthlyReviews || [],
                dailyLogs: parsed.dailyLogs || {},
                dailyLogSources: parsed.dailyLogSources || {},
                draftMondayPlan: parsed.draftMondayPlan || null,
                notes: parsed.notes || [],
                coachChat: parsed.coachChat || [],
                setupChecklist: parsed.setupChecklist || [],
                buildPlan: parsed.buildPlan || [],
                planMath: parsed.planMath || null,
                planGeneratedFor: parsed.planGeneratedFor || null,
                planDriftDismissed: parsed.planDriftDismissed || null,
                planFailure: parsed.planFailure || null,
                redFlags: parsed.redFlags || [],
                redFlagSnoozes: parsed.redFlagSnoozes || {},
                monthlyThemes: parsed.monthlyThemes || { month1: '', month2: '', month3: '' },
                digestSnapshot: parsed.digestSnapshot || null,
                focusScores: parsed.focusScores || [],
                goalCelebrations: parsed.goalCelebrations || {}
            };
            
            
            let needsReSave = false;
            if (finalStore.revenue && finalStore.revenue.entries) {
                finalStore.revenue.entries.forEach((entry, idx) => {
                    if (!entry.id) {
                        entry.id = 'legacy_' + Date.now() + '_' + idx;
                        needsReSave = true;
                    }
                    
                    
                    
                    
                    
                    if (!entry.type) {
                        entry.type = 'sale';
                        needsReSave = true;
                    }
                });
            }
            if (finalStore.leads && finalStore.leads.entries) {
                finalStore.leads.entries.forEach(entry => {
                    if (!entry.type) {
                        entry.type = 'lead';
                        needsReSave = true;
                    }
                });
            }
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            const PLACEHOLDER = 'integrated into priorities';
            if (Array.isArray(finalStore.weeklyPlans)) {
                let cleaned = 0;
                finalStore.weeklyPlans.forEach(p => {
                    if (!p) return;
                    ['visibilityAction', 'followUps'].forEach(field => {
                        if (typeof p[field] === 'string'
                            && p[field].trim().toLowerCase() === PLACEHOLDER) {
                            p[field] = '';
                            cleaned++;
                        }
                    });
                });
                if (cleaned > 0) {
                    finalStore.visibilityPlaceholderCleanedAt = new Date().toISOString();
                    needsReSave = true;
                }
            }

            
            
            
            if (!finalStore.quarterStartDate) {
                const stamps = [];
                (finalStore.weeklyPlans || []).forEach(p => stamps.push(new Date(p.date).getTime()));
                (finalStore.revenue?.entries || []).forEach(e => stamps.push(new Date(e.date).getTime()));
                const valid = stamps.filter(t => Number.isFinite(t));
                if (valid.length > 0) {
                    finalStore.quarterStartDate = new Date(Math.min(...valid)).toISOString();
                    needsReSave = true;
                }
            }

            if (needsReSave) {
                localStorage.setItem(STORE_KEY, JSON.stringify(finalStore));
            }

            return finalStore;
        }
    } catch (e) {
        console.error("Failed to load store from LocalStorage", e);
    }
    return defaultState;
}









function warnNotSyncing(detail) {
    console.warn('Not syncing to the cloud: ' + detail);
    if (window._syncErrorAlerted) return;
    window._syncErrorAlerted = true;
    if (typeof showToast === 'function') {
        showToast(
            'Your work is saved on this device but is not reaching your account yet. It will sync on its own once the connection returns. Until it does, stay signed in on this device and avoid using another one, because signing out replaces this copy with the account copy.',
            'error',
            12000
        );
    }
}


























