function mergeImportedSales(manualEntries, importedEntries, store) {
    if (!importedEntries || importedEntries.length === 0) return manualEntries;

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const base = baseCurrencyCode(store);
    const offerMap = (store.settings && store.settings.productOffers) || {};
    const converted = importedEntries
        .map(e => convertImportedEntry(e, base, store))
        .map(e => applyProductOffer(e, offerMap));

    
    
    
    
    
    
    
    
    
    
    
    
    const importedIds = new Set(converted.map(e => String(e.id)));
    
    
    const standsFor = new Map();
    const liveManual = manualEntries.filter(e => {
        const link = e && e.linkedImportedId;
        if (link && importedIds.has(String(link))) {
            standsFor.set(String(link), e);
            return false;
        }
        return true;
    });

    const DAY = 24 * 60 * 60 * 1000;
    const manualStamps = liveManual.map(e => ({
        id: e.id,
        time: new Date(e.date).getTime(),
        amount: parseFloat(e.amount) || 0
    }));

    
    
    
    const dismissed = new Set(((store.settings && store.settings.dismissedDuplicates) || []).map(String));

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const pairedManualIds = new Map();

    const flagged = converted.map(imported => {
        
        
        const twin = standsFor.get(String(imported.id));
        if (twin) {
            return {
                ...imported,
                countsOnce: true,
                linkedManualId: twin.id,
                linkedManualOffer: twin.offer || '',
                linkedManualSource: twin.source || ''
            };
        }
        const time = new Date(imported.date).getTime();
        const amount = imported.grossAmount != null ? imported.grossAmount : imported.amount;
        const match = manualStamps.find(m =>
            Math.abs(m.amount - amount) < 0.01 &&
            Number.isFinite(m.time) &&
            Number.isFinite(time) &&
            Math.abs(m.time - time) <= DAY
        );
        if (!match) return imported;
        if (dismissed.has(duplicatePairKey(imported.id, match.id))) return imported;

        pairedManualIds.set(String(match.id), imported);
        return {
            ...imported,
            possibleDuplicate: true,
            duplicateManualId: match.id
        };
    });

    
    
    const markedManual = liveManual.map(e => {
        const twin = pairedManualIds.get(String(e.id));
        if (!twin) return e;
        return {
            ...e,
            possibleDuplicate: true,
            duplicateImportedId: twin.id,
            duplicateImportedLabel: twin.source || 'Imported',
            duplicateImportedOffer: twin.productName || twin.offer || '',
            duplicateImportedCustomer: twin.customerEmail || '',
            duplicateImportedDate: twin.date
        };
    });

    return markedManual.concat(flagged);
}



function duplicatePairKey(importedId, manualId) {
    return `${importedId}::${manualId}`;
}


























function linkSameSale(manualId, importedId) {
    if (!manualId || !importedId) return false;
    const store = getStore();
    const entry = (store.revenue?.entries || []).find(e => e && String(e.id) === String(manualId));
    if (!entry) return false;
    entry.linkedImportedId = String(importedId);
    saveStore(store);
    return true;
}




function unlinkSameSale(manualId) {
    if (!manualId) return false;
    const store = getStore();
    const entry = (store.revenue?.entries || []).find(e => e && String(e.id) === String(manualId));
    if (!entry || !entry.linkedImportedId) return false;
    delete entry.linkedImportedId;
    saveStore(store);
    return true;
}













function unresolvedDuplicatePairs(store = getStore()) {
    const rows = mergeImportedSales(store.revenue?.entries || [], getImportedSalesCache(), store);
    return rows
        .filter(r => r && !r.imported && r.possibleDuplicate && r.duplicateImportedId)
        .map(r => ({
            manualId: r.id,
            importedId: r.duplicateImportedId,
            amount: parseFloat(r.amount) || 0,
            date: r.date,
            offer: r.offer || '',
            source: r.source || '',
            importedLabel: r.duplicateImportedLabel || 'Imported',
            importedDate: r.duplicateImportedDate || ''
        }));
}

function dismissDuplicatePair(importedId, manualId) {
    const store = getStore();
    const key = duplicatePairKey(importedId, manualId);
    const list = (store.settings.dismissedDuplicates || []).map(String);
    if (!list.includes(key)) list.push(key);
    
    
    store.settings.dismissedDuplicates = list.slice(-200);
    saveStore(store);
}








