function snapshotMonthNeeded(store = getStore(), today = new Date()) {
    const now = new Date(today);
    if (!Number.isFinite(now.getTime())) return null;
    
    
    if (now.getDate() > 7) return null;

    
    
    const endOfLastMonth = new Date(now.getFullYear(), now.getMonth(), 0, 12, 0, 0);

    const already = (store && store.metrics ? store.metrics : []).some(m => {
        const d = new Date(m && m.date);
        return Number.isFinite(d.getTime())
            && d.getMonth() === endOfLastMonth.getMonth()
            && d.getFullYear() === endOfLastMonth.getFullYear();
    });

    return already ? null : endOfLastMonth;
}































function misdatedSnapshot(store = getStore(), today = new Date()) {
    
    
    
    if (!snapshotMonthNeeded(store, today)) return null;

    const now = new Date(today);
    if (!Number.isFinite(now.getTime())) return null;

    let found = null;
    let foundAt = Infinity;
    (store && Array.isArray(store.metrics) ? store.metrics : []).forEach(m => {
        const d = new Date(m && m.date);
        if (!Number.isFinite(d.getTime())) return;
        if (d.getFullYear() !== now.getFullYear() || d.getMonth() !== now.getMonth()) return;
        
        
        if (d.getTime() < foundAt) {
            foundAt = d.getTime();
            found = m;
        }
    });
    return found;
}







const DEFAULT_SOCIAL_PLATFORMS = ['instagram', 'tiktok', 'facebook', 'linkedin', 'x', 'email'];


function activeSocialPlatforms(store = getStore()) {
    const chosen = store?.settings?.socialPlatforms;
    const valid = Array.isArray(chosen)
        ? chosen.filter(k => SOCIAL_PLATFORMS.some(p => p.key === k))
        : [];
    const keys = valid.length ? valid : DEFAULT_SOCIAL_PLATFORMS;
    
    
    return SOCIAL_PLATFORMS.filter(p => keys.includes(p.key));
}

function updateSocialPlatforms(keys) {
    const store = getStore();
    store.settings.socialPlatforms = (Array.isArray(keys) ? keys : [])
        .filter(k => SOCIAL_PLATFORMS.some(p => p.key === k));
    saveStore(store);
}











const EMAIL_METRICS = [
    { key: 'sent',   label: 'Emails sent',  hint: 'Broadcasts sent this month' },
    { key: 'opens',  label: 'Opens',        hint: 'Total opens across those sends' },
    { key: 'clicks', label: 'Clicks',       hint: 'Total link clicks' }
];



function snapshotEmail(snapshot) {
    const email = (snapshot && snapshot.email) || null;
    if (!email) return null;

    const sent = parseFloat(email.sent) || 0;
    const opens = parseFloat(email.opens) || 0;
    const clicks = parseFloat(email.clicks) || 0;
    if (sent <= 0 && opens <= 0 && clicks <= 0) return null;

    return {
        sent,
        opens,
        clicks,
        
        
        
        
        openRate: sent > 0 ? (opens / sent) * 100 : null,
        clickRate: sent > 0 ? (clicks / sent) * 100 : null,
        
        
        clickToOpenRate: opens > 0 ? (clicks / opens) * 100 : null
    };
}




function latestEmailSnapshot(store = getStore()) {
    const metrics = (store && store.metrics) || [];
    for (let i = metrics.length - 1; i >= 0; i--) {
        const email = snapshotEmail(metrics[i]);
        if (email) return { ...email, date: metrics[i].date };
    }
    return null;
}

















function socialGrowth(store = getStore()) {
    const split = (store?.metrics || []).filter(m => m && m.platforms && Object.keys(m.platforms).length);
    if (split.length === 0) return null;

    const sorted = split.slice().sort((a, b) => new Date(a.date) - new Date(b.date));
    const latest = sorted[sorted.length - 1];
    const previous = sorted.length > 1 ? sorted[sorted.length - 2] : null;

    
    
    
    const rows = activeSocialPlatforms(store)
        .filter(pf => latest.platforms[pf.key] !== undefined)
        .map(pf => {
            const value = parseFloat(latest.platforms[pf.key]) || 0;
            const before = previous && previous.platforms[pf.key] !== undefined
                ? parseFloat(previous.platforms[pf.key]) || 0
                : null;

            if (before === null) {
                return { key: pf.key, label: pf.label, source: pf.source, value, previous: null, change: null, changePct: null, direction: 'new' };
            }

            const change = value - before;
            return {
                key: pf.key,
                label: pf.label,
                source: pf.source,
                value,
                previous: before,
                change,
                
                
                
                changePct: before > 0 ? (change / before) * 100 : null,
                direction: change > 0 ? 'up' : (change < 0 ? 'down' : 'flat')
            };
        });

    if (rows.length === 0) return null;

    return {
        date: latest.date,
        previousDate: previous ? previous.date : null,
        
        
        hasComparison: !!previous,
        rows,
        total: rows.reduce((a, r) => a + r.value, 0),
        totalChange: previous ? rows.reduce((a, r) => a + (r.change || 0), 0) : null
    };
}







function snapshotSocial(snapshot) {
    const platforms = (snapshot && snapshot.platforms) || null;
    if (!platforms) {
        return {
            total: parseFloat(snapshot?.social) || 0,
            split: [],
            isSplit: false
        };
    }
    const split = SOCIAL_PLATFORMS
        .filter(p => platforms[p.key] !== undefined && platforms[p.key] !== null && platforms[p.key] !== '')
        .map(p => ({ ...p, value: parseFloat(platforms[p.key]) || 0 }));
    return {
        total: split.reduce((sum, p) => sum + p.value, 0),
        split,
        isSplit: split.length > 0
    };
}















