function readArchived(store, key, decorate) {
    const out = [];
    (Array.isArray(store.pastQuarters) ? store.pastQuarters : []).forEach(q => {
        const rows = (q && Array.isArray(q[key])) ? q[key] : [];
        rows.forEach(row => {
            if (!row) return;
            out.push({ ...row, archived: true, archivedFrom: q.quarterStartDate || '' });
        });
    });
    (Array.isArray(decorate) ? decorate : []).forEach(row => { if (row) out.push(row); });
    return out;
}

