function trackingStartedAt(store = getStore()) {
    const stamps = [];
    (Array.isArray(store.pastQuarters) ? store.pastQuarters : []).forEach(q => {
        if (q && q.quarterStartDate) stamps.push(new Date(q.quarterStartDate).getTime());
    });
    if (store.quarterStartDate) stamps.push(new Date(store.quarterStartDate).getTime());
    const valid = stamps.filter(Number.isFinite);
    return valid.length ? new Date(Math.min(...valid)) : null;
}

const REPORT_GRAINS = ['week', 'month', 'quarter', 'year'];

function calendarBucketFor(date, grain, store) {
    const y = date.getFullYear();
    if (grain === 'year') {
        return { key: String(y), label: String(y), title: String(y), sort: new Date(y, 0, 1).getTime(), year: y };
    }
    if (grain === 'quarter') {
        const q = Math.floor(date.getMonth() / 3) + 1;
        const first = new Date(y, (q - 1) * 3, 1);
        const last = new Date(y, q * 3, 0);
        return {
            key: y + '-Q' + q,
            label: 'Q' + q,
            title: 'Q' + q + ' ' + y + ', ' + first.toLocaleDateString(undefined, { month: 'long' })
                + ' to ' + last.toLocaleDateString(undefined, { month: 'long' }),
            sort: first.getTime(),
            year: y
        };
    }
    if (grain === 'month') {
        const first = new Date(y, date.getMonth(), 1);
        return {
            key: y + '-' + date.getMonth(),
            label: first.toLocaleDateString(undefined, { month: 'short' }),
            title: first.toLocaleDateString(undefined, { month: 'long', year: 'numeric' }),
            sort: first.getTime(),
            year: y
        };
    }
    const ws = getWeekStart(date, store);
    const we = new Date(ws);
    we.setDate(we.getDate() + 6);
    const short = (d) => d.toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
    return {
        key: getLocalDateString(ws),
        label: short(ws),
        title: short(ws) + ' to ' + short(we) + ' ' + we.getFullYear(),
        sort: ws.getTime(),
        year: ws.getFullYear()
    };
}
















function calendarKeyFor(date, grain, store = getStore()) {
    const g = REPORT_GRAINS.includes(grain) ? grain : 'quarter';
    const d = new Date(date);
    if (!Number.isFinite(d.getTime())) return null;
    return calendarBucketFor(d, g, store).key;
}

function revenueByCalendarPeriod(rows, grain, range, store = getStore()) {
    const g = REPORT_GRAINS.includes(grain) ? grain : 'quarter';
    const from = (range && range.from) ? new Date(range.from) : null;
    const to = (range && range.to) ? new Date(range.to) : null;
    if (to && Number.isFinite(to.getTime())) to.setHours(23, 59, 59, 999);

    const okFrom = from && Number.isFinite(from.getTime()) ? from.getTime() : null;
    const okTo = to && Number.isFinite(to.getTime()) ? to.getTime() : null;
    const within = (t) => (okFrom === null || t >= okFrom) && (okTo === null || t <= okTo);

    const buckets = new Map();

    (rows || []).forEach(e => {
        const d = new Date(e && e.date);
        const t = d.getTime();
        if (!Number.isFinite(t) || !within(t)) return;
        const b = calendarBucketFor(d, g, store);
        if (!buckets.has(b.key)) buckets.set(b.key, Object.assign({}, b, { amount: 0, salesCount: 0 }));
        const row = buckets.get(b.key);
        row.amount += parseFloat(e.amount) || 0;
        row.salesCount += 1;
    });

    if (buckets.size === 0) return [];

    const out = [...buckets.values()];
    const months = { month: 1, quarter: 3, year: 12 };
    const cursor = new Date(Math.min(...out.map(b => b.sort)));
    const end = Math.max(...out.map(b => b.sort));
    
    
    for (let i = 0; i < 400 && cursor.getTime() <= end; i++) {
        const b = calendarBucketFor(cursor, g, store);
        if (!buckets.has(b.key)) {
            buckets.set(b.key, Object.assign({}, b, { amount: 0, salesCount: 0 }));
            out.push(buckets.get(b.key));
        }
        if (g === 'week') cursor.setDate(cursor.getDate() + 7);
        else cursor.setMonth(cursor.getMonth() + months[g]);
    }

    out.sort((a, b) => a.sort - b.sort);

    
    
    
    
    
    const started = trackingStartedAt(store);
    if (started && Number.isFinite(started.getTime())) {
        const firstKey = calendarBucketFor(started, g, store).key;
        const row = out.find(b => b.key === firstKey);
        if (row) {
            row.isPartial = true;
            row.startedOn = started.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' });
        }
    }

    return out;
}






















function revenueByCycleWeek(entries, store = getStore()) {
    const startISO = store.quarterStartDate;
    const start = startISO ? getWeekStart(new Date(startISO), store) : null;
    if (!start || !Number.isFinite(start.getTime())) return [];

    const short = (d) => d.toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
    const buckets = [];
    const cursor = new Date(start);
    const today = new Date();

    for (let i = 0; i < 13; i++) {
        if (cursor.getTime() > today.getTime()) break;
        const from = new Date(cursor);
        const to = new Date(cursor);
        to.setDate(to.getDate() + 6);
        buckets.push({
            key: getLocalDateString(cursor),
            label: `W${i + 1}`,
            
            
            title: `Week ${i + 1}: ${short(from)} to ${short(to)}`,
            amount: 0,
            date: from.getTime(),
            isCurrent: today.getTime() >= from.getTime() && today.getTime() <= to.getTime() + 86399999
        });
        cursor.setDate(cursor.getDate() + 7);
    }

    (entries || []).forEach(e => {
        const t = new Date(e.date);
        if (!Number.isFinite(t.getTime())) return;
        const key = getLocalDateString(getWeekStart(t, store));
        const b = buckets.find(x => x.key === key);
        if (b) b.amount += parseFloat(e.amount) || 0;
    });

    return buckets;
}




function revenueByCycleMonth(entries, store = getStore()) {
    const start = quarterCountsFrom(store);
    if (!start) return [];

    const today = new Date();
    const buckets = [];
    const cursor = new Date(start.getFullYear(), start.getMonth(), 1);

    
    for (let i = 0; i < 4; i++) {
        if (cursor.getFullYear() > today.getFullYear()
            || (cursor.getFullYear() === today.getFullYear() && cursor.getMonth() > today.getMonth())) break;
        buckets.push({
            key: `${cursor.getFullYear()}-${cursor.getMonth()}`,
            label: cursor.toLocaleDateString(undefined, { month: 'short' }),
            title: cursor.toLocaleDateString(undefined, { month: 'long', year: 'numeric' }),
            amount: 0,
            date: cursor.getTime(),
            isCurrent: cursor.getFullYear() === today.getFullYear() && cursor.getMonth() === today.getMonth()
        });
        cursor.setMonth(cursor.getMonth() + 1);
    }

    (entries || []).forEach(e => {
        const d = new Date(e.date);
        if (!Number.isFinite(d.getTime())) return;
        const b = buckets.find(x => x.key === `${d.getFullYear()}-${d.getMonth()}`);
        if (b) b.amount += parseFloat(e.amount) || 0;
    });

    return buckets;
}










































function revenueByOwnQuarter(entries, store = getStore()) {
    const live = quarterCountsFrom(store);
    const midnight = (d) => { const c = new Date(d); c.setHours(0, 0, 0, 0); return c; };
    const short = (d) => d.toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
    const DAY = 24 * 60 * 60 * 1000;
    
    
    const FULL_QUARTER = 89 * DAY;

    
    const seen = new Set();
    const bounds = sortArchivedQuarters(store.pastQuarters)
        .map(q => (q && q.quarterStartDate) ? new Date(q.quarterStartDate) : null)
        .concat([live])
        .filter(d => d && Number.isFinite(d.getTime()))
        .map(midnight)
        .filter(d => { const k = d.getTime(); if (seen.has(k)) return false; seen.add(k); return true; })
        .sort((a, b) => a.getTime() - b.getTime());

    const rows = (entries || []);
    const amountOf = (e) => parseFloat(e.amount) || 0;

    
    
    if (bounds.length === 0) {
        const total = rows.reduce((sum, e) => sum + amountOf(e), 0);
        return total === 0 ? [] : [{ key: 'all', label: 'All time', amount: total, date: 0 }];
    }

    const buckets = bounds.map((d, i) => {
        
        const next = bounds[i + 1] || null;
        const isCurrent = Boolean(live) && d.getTime() === midnight(live).getTime();
        const isShort = Boolean(next) && !isCurrent && (next.getTime() - d.getTime()) < FULL_QUARTER;
        
        const lastDay = next ? new Date(next.getTime() - DAY) : null;
        return {
            key: `q-${d.getTime()}`,
            label: isShort ? `${short(d)}–${short(lastDay)}` : short(d),
            amount: 0,
            date: d.getTime(),
            end: next ? next.getTime() : null,
            isCurrent,
            isShort
        };
    });

    rows.forEach(e => {
        const t = new Date(e.date).getTime();
        if (!Number.isFinite(t)) return;
        
        
        
        
        for (let i = buckets.length - 1; i >= 0; i--) {
            if (t >= buckets[i].date) { buckets[i].amount += amountOf(e); break; }
        }
    });

    return buckets;
}



















const PRIORITY_FILLER_WORDS = new Set([
    'the', 'and', 'for', 'with', 'into', 'from', 'that', 'this', 'these', 'those',
    'my', 'our', 'your', 'their', 'its', 'all', 'any', 'each', 'every', 'some',
    'more', 'most', 'less', 'least', 'lot', 'lots', 'much', 'many', 'new', 'own',
    'out', 'off', 'per', 'via', 'onto', 'over', 'than', 'then', 'there', 'here',
    'about', 'across', 'again', 'along', 'around', 'been', 'being', 'have', 'has',
    'had', 'will', 'would', 'can', 'could', 'should', 'want', 'need', 'properly',
    'week', 'weekly', 'month', 'monthly', 'quarter', 'quarterly', 'day', 'daily',
    'consistently', 'really', 'finally', 'actually', 'just'
]);





const PRIORITY_GENERIC_VERBS = new Set([
    'get', 'mak', 'build', 'creat', 'start', 'launch', 'run', 'set', 'grow',
    'improv', 'increas', 'work', 'keep', 'add', 'sort', 'sell', 'post', 'tak'
]);






function stemPriorityWord(word) {
    let w = word;
    if (w.length > 4 && w.endsWith('ing')) w = w.slice(0, -3);
    else if (w.length > 3 && w.endsWith('ed')) w = w.slice(0, -2);
    else if (w.length > 3 && w.endsWith('s') && !w.endsWith('ss')) w = w.slice(0, -1);
    if (w.length > 3 && w.endsWith('e')) w = w.slice(0, -1);
    return w;
}

function normalisePriorityText(text) {
    return String(text || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

function priorityTokens(text) {
    const words = normalisePriorityText(text)
        .split(' ')
        .filter(Boolean)
        
        
        .filter(w => !/^\d+$/.test(w))
        .filter(w => !PRIORITY_FILLER_WORDS.has(w))
        .map(stemPriorityWord)
        .filter(w => w.length > 2 && !PRIORITY_FILLER_WORDS.has(w));
    return new Set(words);
}








function prioritiesMatch(a, b) {
    const na = normalisePriorityText(a);
    const nb = normalisePriorityText(b);
    if (!na || !nb) return false;
    
    if (na === nb) return true;

    const A = priorityTokens(a);
    const B = priorityTokens(b);
    if (A.size === 0 || B.size === 0) return false;

    const shared = [...A].filter(w => B.has(w));
    if (shared.length < 2) return false;
    if (!shared.some(w => !PRIORITY_GENERIC_VERBS.has(w))) return false;
    return shared.length / Math.min(A.size, B.size) >= 0.6;
}









function computePriorityChain(archived, index, anchorText) {
    const chain = [index];
    for (let i = index - 1; i >= 0; i--) {
        const found = (archived[i]?.goals?.priorities || [])
            .some(p => String(p || '').trim() && prioritiesMatch(anchorText, p));
        if (!found) break;
        chain.unshift(i);
    }
    return chain;
}









function recordedCarryFor(record, text) {
    const wanted = normalisePriorityText(text);
    const entry = (Array.isArray(record?.priorityCarry) ? record.priorityCarry : [])
        .find(c => normalisePriorityText(c?.text) === wanted);
    return entry && Number.isFinite(entry.streak) && entry.streak > 0 ? entry : null;
}






function getCarriedPriorities() {
    const store = getStore();
    const archived = sortArchivedQuarters(store.pastQuarters);
    if (archived.length === 0) return [];

    
    
    
    
    const rows = getQuarterHistory().quarters.filter(q => !q.isCurrent).slice().reverse();
    const last = archived.length - 1;
    const decisions = Array.isArray(archived[last].priorityDecisions) ? archived[last].priorityDecisions : [];

    return (archived[last].goals?.priorities || [])
        .map(p => String(p || '').trim())
        .filter(Boolean)
        .map(text => {
            const recorded = recordedCarryFor(archived[last], text);
            const streak = recorded ? Math.min(recorded.streak, archived.length) : computePriorityChain(archived, last, text).length;
            const chainRows = rows.slice(Math.max(0, rows.length - streak));
            const met = chainRows.filter(q => q.goalsMet?.revenue === true);
            const missed = chainRows.filter(q => q.goalsMet?.revenue === false);
            const decision = decisions.find(d => normalisePriorityText(d?.text) === normalisePriorityText(text)) || null;
            return {
                text,
                streak,
                quarterLabels: chainRows.map(q => q.label),
                since: chainRows.length ? chainRows[0].startDate : '',
                sinceLabel: chainRows.length ? chainRows[0].label : '',
                
                
                anyGoalMet: met.length > 0,
                anyGoalMissed: missed.length > 0,
                decision
            };
        });
}















function getCarriedPriorityPrompt() {
    const store = getStore();
    if ((store.pastQuarters || []).length < 3) return null;

    const candidates = getCarriedPriorities().filter(p =>
        p.streak >= 3 && !p.anyGoalMet && p.anyGoalMissed && !p.decision
    );
    if (candidates.length === 0) return null;

    
    
    return candidates.slice().sort((a, b) => b.streak - a.streak)[0];
}









function recordPriorityDecision(text, decision) {
    const store = getStore();
    const archived = sortArchivedQuarters(store.pastQuarters);
    if (archived.length === 0) return false;
    if (decision !== 'keep' && decision !== 'let-go') return false;
    const clean = String(text || '').trim();
    if (!clean) return false;

    const record = archived[archived.length - 1];
    record.priorityDecisions = (Array.isArray(record.priorityDecisions) ? record.priorityDecisions : [])
        .filter(d => normalisePriorityText(d?.text) !== normalisePriorityText(clean));
    record.priorityDecisions.push({ text: clean, decision, at: new Date().toISOString() });
    saveStore(store);
    return true;
}












function getYearTotals(store, quarters) {
    const seen = new Set();
    const years = new Map();

    const add = (entry) => {
        if (entry.id) {
            if (seen.has(entry.id)) return;
            seen.add(entry.id);
        }
        const d = new Date(entry.date);
        if (!Number.isFinite(d.getTime())) return;
        const year = d.getFullYear();
        if (!years.has(year)) years.set(year, { year, revenue: 0, salesCount: 0, quartersFinished: 0 });
        const row = years.get(year);
        row.revenue += parseFloat(entry.amount) || 0;
        row.salesCount += 1;
    };

    (store.pastQuarters || []).forEach(q => (q.revenueEntries || []).forEach(add));
    
    (quarters[quarters.length - 1]?.entries || []).forEach(add);

    quarters.forEach(q => {
        if (q.isCurrent || !q.endDate) return;
        const end = new Date(q.endDate);
        if (!Number.isFinite(end.getTime())) return;
        
        
        
        if (!years.has(end.getFullYear())) {
            years.set(end.getFullYear(), { year: end.getFullYear(), revenue: 0, salesCount: 0, quartersFinished: 0 });
        }
        years.get(end.getFullYear()).quartersFinished += 1;
    });

    return Array.from(years.values()).sort((a, b) => b.year - a.year);
}

function addWeeklyPlan(plan) {
    const store = getStore();
    plan.id = Date.now().toString();
    plan.date = new Date().toISOString();
    store.weeklyPlans.push(plan);

    
    
    
    store.planningStreak = getPlanningStreak(store);

    saveStore(store);
}





































































function tickedTextThisWeek(store, today = new Date()) {
    const ticked = new Set();
    const start = getWeekStart(today, store);
    for (let i = 0; i < 7; i++) {
        const d = new Date(start);
        d.setDate(start.getDate() + i);
        (store.dailyLogs?.[getLocalDateString(d)] || []).forEach(t => {
            if (t && t.done) ticked.add(String(t.text || '').trim());
        });
    }
    
    
    return ticked;
}

function invalidateDerivedPlanText(before, after, updatedFields, store) {
    const supplied = (field) => Object.prototype.hasOwnProperty.call(updatedFields || {}, field);
    const text = (v) => String(v == null ? '' : v).trim();
    const actions = (plan) => (Array.isArray(plan.topActions) ? plan.topActions : (plan.priorities || []));

    if (!supplied('daily3') && Array.isArray(after.daily3)) {
        const was = actions(before);
        const now = actions(after);
        const ticked = tickedTextThisWeek(store);
        after.daily3 = after.daily3.map((step, i) => {
            
            
            if (text(was[i]) === text(now[i])) return step;

            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            if (ticked.has(text(step))) return step;

            return text(now[i]);
        });
    }

    if (!supplied('dailySequence')) {
        delete after.dailySequence;
        delete after.dailySequenceFor;
        delete after.dailySequenceVersion;
        delete after.dailySequenceFailedOn;
    }
}

function updateWeeklyPlan(planId, updatedFields) {
    const store = getStore();
    const index = store.weeklyPlans.findIndex(p => String(p.id) === String(planId));
    if (index !== -1) {
        const before = store.weeklyPlans[index];
        const after = { ...before, ...updatedFields };
        if (planContentKey(after) !== planContentKey(before)) {
            invalidateDerivedPlanText(before, after, updatedFields, store);
        }
        store.weeklyPlans[index] = after;

        
        
        
        
        store.planningStreak = getPlanningStreak(store);

        saveStore(store);
    }
}




function updateDailyLog(dateStr, tasks, source) {
    const store = getStore();
    store.dailyLogs[dateStr] = tasks;

    if (source === undefined) {
        delete store.dailyLogSources[dateStr];
    } else {
        store.dailyLogSources[dateStr] = source;
    }

    saveStore(store);
}















































function stampIdentity(stamp) {
    const s = String(stamp == null ? '' : stamp);
    const hash = s.lastIndexOf('#');
    return hash === -1 ? s : s.slice(0, hash);
}


function logCameFromPlan(store, dateStr, planKey) {
    const stamp = (store.dailyLogSources || {})[dateStr];
    if (stamp === undefined) return false;
    return stampIdentity(stamp) === stampIdentity(planKey);
}


function dayNameFor(dateStr) {
    const d = parseDateInput(dateStr);
    if (!d || !Number.isFinite(d.getTime())) return '';
    return d.toLocaleDateString('en-US', { weekday: 'long' });
}






function daily3DoneThisWeek(planKey, store = getStore(), today = new Date()) {
    const done = {};
    if (!planKey) return done;

    const start = getWeekStart(today, store);
    const todayStr = getLocalDateString(today);

    for (let i = 0; i < 7; i++) {
        const d = new Date(start);
        d.setDate(start.getDate() + i);
        const key = getLocalDateString(d);
        if (key >= todayStr) break; 
        if (!logCameFromPlan(store, key, planKey)) continue;

        (store.dailyLogs?.[key] || []).forEach(task => {
            const text = String((task && task.text) || '').trim();
            if (!text || !task.done || done[text]) return;
            done[text] = { date: key, dayName: dayNameFor(key) };
        });
    }

    return done;
}






function clearDaily3Completion(text, planKey, today = new Date()) {
    const store = getStore();
    const wanted = String(text || '').trim();
    if (!wanted || !planKey) return false;

    const start = getWeekStart(today, store);
    const todayStr = getLocalDateString(today);
    let cleared = false;

    for (let i = 0; i < 7; i++) {
        const d = new Date(start);
        d.setDate(start.getDate() + i);
        const key = getLocalDateString(d);
        if (key >= todayStr) break;
        if (!logCameFromPlan(store, key, planKey)) continue;

        (store.dailyLogs?.[key] || []).forEach(task => {
            if (task && task.done && String(task.text || '').trim() === wanted) {
                task.done = false;
                cleared = true;
            }
        });
    }

    if (cleared) saveStore(store);
    return cleared;
}

































function tickStamp(today = new Date()) {
    return getLocalDateString(today);
}


















function setDailyActionDone(dateStr, text, done, today = new Date()) {
    const store = getStore();
    const wanted = String(text || '').trim();
    const day = parseDateInput(dateStr);
    if (!wanted || !day || !Number.isFinite(day.getTime())) return false;

    const start = getWeekStart(day, store);
    const stamp = tickStamp(today);
    const now = new Date().toISOString();
    let changed = false;

    for (let i = 0; i < 7; i++) {
        const d = new Date(start);
        d.setDate(start.getDate() + i);
        (store.dailyLogs?.[getLocalDateString(d)] || []).forEach(task => {
            if (!task || String(task.text || '').trim() !== wanted) return;
            if (Boolean(task.done) === Boolean(done)) return;
            task.done = Boolean(done);
            if (done) {
                task.doneAt = stamp;
                delete task.doneClearedAt;
            } else {
                delete task.doneAt;
                task.doneClearedAt = now;
            }
            changed = true;
        });
    }

    if (changed) saveStore(store);
    return changed;
}















function lateTickNote(dateStr, task, store = getStore(), today = new Date()) {
    if (!task || !task.done || !task.doneAt || task.doneAt === dateStr) return '';
    const on = parseDateInput(task.doneAt);
    if (!on || !Number.isFinite(on.getTime())) return '';
    const day = parseDateInput(dateStr);
    if (!day || !Number.isFinite(day.getTime())) return '';

    const when = on.toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
    const weekIsClosed = getWeekStart(day, store).getTime() < getWeekStart(today, store).getTime();
    return weekIsClosed
        ? `Ticked on ${when}. No change to focus score.`
        : `Ticked on ${when}.`;
}












function unfinishedDaily3LastWeek(store = getStore(), today = new Date()) {
    const thisWeekStart = getWeekStart(today, store);
    const lastWeekStart = new Date(thisWeekStart);
    lastWeekStart.setDate(thisWeekStart.getDate() - 7);

    const seen = new Map(); 

    for (let i = 0; i < 7; i++) {
        const d = new Date(lastWeekStart);
        d.setDate(lastWeekStart.getDate() + i);
        const log = store.dailyLogs?.[getLocalDateString(d)];
        if (!Array.isArray(log)) continue;

        log.forEach(task => {
            const text = String((task && task.text) || '').trim();
            if (!text) return;
            seen.set(text, Boolean(seen.get(text)) || Boolean(task.done));
        });
    }

    return [...seen.entries()].filter(([, ticked]) => !ticked).map(([text]) => text);
}






































const DAILY_PLACEHOLDERS = ['integrated into priorities'];







function cleanTaskText(t) {
    return stripDayLabel(stripPriorityLabels(String(t == null ? '' : t).trim()));
}


function weekSequence(plan) {
    if (!plan) return [];
    const clean = cleanTaskText;
    const seen = new Set();
    const out = [];
    const add = (t) => {
        const text = clean(t);
        
        
        
        
        
        
        const key = dedupeKey(text);
        if (!text || DAILY_PLACEHOLDERS.indexOf(text.toLowerCase()) !== -1 || seen.has(key)) return;
        seen.add(key);
        out.push(text);
    };
    
    
    const addDistinct = (t) => {
        const text = clean(t);
        if (!text || sameWorkAsAny(text, out)) return;
        add(text);
    };

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    if (Array.isArray(plan.dailySequence) && plan.dailySequence.length > 0) {
        plan.dailySequence.forEach(t => add(t && typeof t === 'object' ? t.text : t));
        return out;
    }

    
    
    
    
    (Array.isArray(plan.daily3) ? plan.daily3 : []).forEach(add);
    (Array.isArray(plan.topActions) ? plan.topActions : (plan.priorities || [])).forEach(add);

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    [plan.buildAction, plan.revenueAction, plan.visibilityAction, plan.followUps]
        .forEach(addDistinct);
    return out;
}




















const SAME_WORK_STOPWORDS = new Set(['a', 'an', 'the', 'and', 'or', 'to', 'of', 'for', 'with', 'on', 'in', 'at', 'your', 'you', 'this', 'that', 'it', 'is', 'are', 'be', 'from', 'by', 'one', 'so', 'not', 'new', 'use', 'then', 'into', 'out', 'up', 'as', 'if', 'they', 'them', 'their', 'my', 'me', 'i', 'do', 'get', 'make', 'each', 'all', 'any', 'no', 'but', 'about', 'over', 'after', 'before', 'more', 'most', 'other', 'some', 'such', 'only', 'own', 'same', 'than', 'too', 'very', 'can', 'will', 'just']);


function dedupeKey(text) {
    return String(text || '').toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
}

function contentWords(text) {
    return [...new Set(dedupeKey(text).split(' ').filter(w => w && !SAME_WORK_STOPWORDS.has(w)))];
}








const SAME_WORK_THRESHOLD = 0.4;







function sameWorkAsAny(text, existing) {
    const words = contentWords(text);
    if (words.length === 0) return false;
    return (existing || []).some(other => {
        const otherWords = contentWords(other);
        if (otherWords.length === 0) return false;
        const shared = words.filter(w => otherWords.includes(w)).length;
        return shared / Math.min(words.length, otherWords.length) >= SAME_WORK_THRESHOLD;
    });
}






const COUNT_WORDS = /\b(\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\b/gi;




















function countsDiffer(a, b) {
    const counts = (t) => new Set((String(t == null ? '' : t).toLowerCase().match(COUNT_WORDS) || []));
    const first = counts(a);
    if (first.size === 0) return false;
    const second = counts(b);
    if (second.size === 0) return false;
    for (const n of first) if (second.has(n)) return false;
    return true;
}


































function sameWorkAsDistinct(text, existing, buckets, opts) {
    const mine = buckets ? buckets[text] : null;
    const countsExempt = !(opts && opts.ignoreCounts);
    return (existing || []).some(other => {
        if (countsExempt && countsDiffer(text, other)) return false;
        const theirs = buckets ? buckets[other] : null;
        if (mine && theirs && mine !== theirs) return false;
        return sameWorkAsAny(text, [other]);
    });
}




























const WEEK_SEQUENCE_VERSION = 5;










const HEARING_BACK = /\b(responses?|replies|replied|reply|answers|sign-?ups|bookings?|booked|yes(es)?)\b/i;































const LOOKING_FOR_REPLY = /\b(check|checks|checked|checking|read|reads|reading|look|looks|looking|see|scan|review|reviewing)\b/i;




const NO_REPLY_BRANCH = /\bno repl(?:y|ies) yet\b|\bor write\b|\bor mark\b|\bor note\b|\bhas ?n[o']?t replied\b|\bhave ?n[o']?t replied\b|\bnot replied\b|\bif (?:no one|nobody|none|nothing|there (?:is|are) no)\b/i;









const ACTS_ON_REPLY = /\b(?:who|whoever|anyone|anybody|those|people|the ones|that|which)\b[^.;]{0,40}\b(?:replied|replies to|answered|responded|got back|said yes|says yes|say yes|booked|signed up|wants?|asked for|requested|enquired)\b/i;





















const THE_REPLIES = /\bthe (?:responses?|replies|reply|answers?|bookings?|sign-?ups)\b/i;

function replyBlocked(text) {
    const t = String(text == null ? '' : text);
    
    if (NO_REPLY_BRANCH.test(t)) return false;
    
    if (LOOKING_FOR_REPLY.test(t) && HEARING_BACK.test(t)) return false;
    return ACTS_ON_REPLY.test(t) || THE_REPLIES.test(t);
}






















































function weekSequenceMeta(plan) {
    const meta = {};
    (Array.isArray(plan && plan.dailySequence) ? plan.dailySequence : []).forEach(t => {
        if (!t || typeof t !== 'object' || !t.text) return;
        const text = cleanTaskText(t.text);
        if (!text) return;
        const minutes = Number(t.minutes);
        const row = {};
        if (Number.isFinite(minutes) && minutes >= 10 && minutes <= 90) row.minutes = Math.round(minutes);
        const bucket = String(t.bucket == null ? '' : t.bucket).trim().toLowerCase();
        if (TASK_BUCKET_KEYS.indexOf(bucket) !== -1) row.bucket = bucket;
        if (Object.keys(row).length) meta[text] = row;
    });
    return meta;
}


const TASK_BUCKET_KEYS = ['build', 'revenue', 'visibility', 'followup'];


function weekSequenceBuckets(plan) {
    const meta = weekSequenceMeta(plan);
    const out = {};
    Object.keys(meta).forEach(text => { if (meta[text].bucket) out[text] = meta[text].bucket; });
    return out;
}

function weekSequenceWaits(plan) {
    const waits = {};
    const inPool = new Set(weekSequence(plan));
    (Array.isArray(plan && plan.dailySequence) ? plan.dailySequence : []).forEach(t => {
        if (!t || typeof t !== 'object' || !t.text || !t.waitsFor) return;
        const text = cleanTaskText(t.text);
        const on = cleanTaskText(t.waitsFor);
        if (!text || !on || !inPool.has(on)) return;
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        const reply = replyBlocked(text);
        waits[text] = { on, reply };
    });
    return waits;
}






function lastWeekTaskRecord(store = getStore(), today = new Date()) {
    const start = getWeekStart(today, store);
    start.setDate(start.getDate() - 7);
    const done = new Set();
    const seen = new Set();
    for (let i = 0; i < 7; i++) {
        const d = new Date(start);
        d.setDate(start.getDate() + i);
        (store.dailyLogs?.[getLocalDateString(d)] || []).forEach(t => {
            const text = String((t && t.text) || '').trim();
            if (!text) return;
            seen.add(text);
            if (t.done) done.add(text);
        });
    }
    return { done: [...done], notDone: [...seen].filter(t => !done.has(t)) };
}






function dailyHistoryThisWeek(planKey, store = getStore(), today = new Date()) {
    const done = new Set();
    const doneOn = {}; 
    const firstShown = new Map(); 
    
    
    
    
    const timesShown = new Map();
    if (!planKey) return { done, doneOn, carried: [] };

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const start = getWeekStart(today, store);
    start.setDate(start.getDate() - PLAN_AHEAD_DAYS);
    const todayStr = getLocalDateString(today);
    for (let i = 0; i < 7 + PLAN_AHEAD_DAYS; i++) {
        const d = new Date(start);
        d.setDate(start.getDate() + i);
        const key = getLocalDateString(d);
        if (key >= todayStr) break;
        if (!logCameFromPlan(store, key, planKey)) continue;
        (store.dailyLogs?.[key] || []).forEach(t => {
            const text = String((t && t.text) || '').trim();
            if (!text) return;
            if (!firstShown.has(text)) firstShown.set(text, key);
            timesShown.set(text, (timesShown.get(text) || 0) + 1);
            if (t.done) { done.add(text); if (!doneOn[text]) doneOn[text] = key; }
        });
    }

    const carried = [...firstShown.entries()]
        .filter(([text]) => !done.has(text))
        .map(([text, date]) => ({ text, date, times: timesShown.get(text) || 1 }));
    return { done, doneOn, carried };
}























































function buildTodaysTasks(plan, planKey, store = getStore(), today = new Date()) {
    const { done, doneOn, carried } = dailyHistoryThisWeek(planKey, store, today);
    const shownEarlier = new Set(carried.map(c => c.text));
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const waits = weekSequenceWaits(plan);
    const dayBefore = (n) => {
        const d = new Date(today);
        d.setDate(d.getDate() - n);
        return getLocalDateString(d);
    };
    const readyBy = { reply: dayBefore(2), step: dayBefore(1) };

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const waitState = (t) => {
        const w = waits[t];
        if (!w) return 'free';
        const ticked = doneOn[w.on];
        return (ticked && ticked <= (w.reply ? readyBy.reply : readyBy.step)) ? 'free' : 'blocked';
    };
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const pool = weekSequence(plan);
    const fromSequence = Array.isArray(plan && plan.dailySequence) && plan.dailySequence.length > 0;
    const buckets = fromSequence ? weekSequenceBuckets(plan) : null;
    
    
    
    
    
    
    
    
    const boardTwin = fromSequence ? { ignoreCounts: true } : undefined;
    const main = [];
    const doneTexts = [...done];

    
    
    
    
    
    
    
    
    
    
    
    
    const place = (text, extra) => {
        if (main.length >= 3) return false;
        if (main.some(x => x.text === text)) return false;
        if (fromSequence && sameWorkAsDistinct(text, main.map(x => x.text), buckets, boardTwin)) return false;
        main.push(Object.assign({ text, done: false }, extra || {}));
        return true;
    };

    
    
    
    
    
    
    
    
    
    
    
    
    
    const held = [];
    pool.forEach(text => {
        if (done.has(text) || shownEarlier.has(text)) return;
        if (waitState(text) !== 'free') return;
        
        
        
        
        
        
        
        
        
        if (fromSequence && sameWorkAsDistinct(text, doneTexts, buckets)) { held.push(text); return; }
        place(text);
    });
    held.forEach(text => place(text));

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    if (main.length < 3) {
        carried.slice()
            .sort((a, b) => (a.times - b.times) || a.date.localeCompare(b.date))
            .forEach(c => {
                if (waitState(c.text) !== 'free') return;
                place(c.text, { reoffered: true });
            });
    }

    
    
    
    
    
    
    
    return main;
}



















function boardShortReason(plan, planKey, store = getStore(), today = new Date()) {
    const pool = weekSequence(plan);
    if (pool.length === 0) return { reason: 'empty-plan', waitingFor: [] };

    const { done, doneOn } = dailyHistoryThisWeek(planKey, store, today);
    
    
    const ticked = new Set(done);
    (store.dailyLogs?.[getLocalDateString(today)] || []).forEach(t => {
        if (t && t.done) ticked.add(String(t.text || '').trim());
    });

    const left = pool.filter(t => !ticked.has(t));
    if (left.length === 0) return { reason: 'all-done', waitingFor: [] };

    const waits = weekSequenceWaits(plan);
    const waitingFor = [];
    let allWaiting = true;
    left.forEach(t => {
        const w = waits[t];
        if (w && w.reply && !doneOn[w.on]) { waitingFor.push(w.on); return; }
        if (w && w.reply) { waitingFor.push(w.on); return; }
        allWaiting = false;
    });
    if (allWaiting) return { reason: 'waiting-on-people', waitingFor: [...new Set(waitingFor)] };
    return { reason: 'nothing-schedulable', waitingFor: [...new Set(waitingFor)] };
}


function weekTaskProgress(plan, planKey, store = getStore(), today = new Date()) {
    const seq = weekSequence(plan);
    const { done } = dailyHistoryThisWeek(planKey, store, today);
    const todayLog = store.dailyLogs?.[getLocalDateString(today)] || [];
    todayLog.forEach(t => { if (t && t.done) done.add(String(t.text || '').trim()); });
    const all = new Set(seq);
    todayLog.forEach(t => all.add(String((t && t.text) || '').trim()));
    return { done: [...done].filter(t => all.has(t)).length, total: all.size };
}





function setWeekSequence(planId, tasks, contentKey) {
    const store = getStore();
    const plan = (store.weeklyPlans || []).find(p => String(p.id) === String(planId));
    if (!plan) return false;
    plan.dailySequence = tasks;
    plan.dailySequenceFor = contentKey;
    plan.dailySequenceVersion = WEEK_SEQUENCE_VERSION;
    delete plan.dailySequenceFailedOn;
    saveStore(store);
    return true;
}


function markWeekSequenceFailed(planId) {
    const store = getStore();
    const plan = (store.weeklyPlans || []).find(p => String(p.id) === String(planId));
    if (!plan) return;
    plan.dailySequenceFailedOn = getLocalDateString();
    saveStore(store);
}


function weekNeedsSequence(plan) {
    if (!plan) return false;
    if (plan.dailySequenceFailedOn === getLocalDateString()) return false;
    const key = planContentKey(plan);
    return !(Array.isArray(plan.dailySequence) && plan.dailySequence.length > 0
        && plan.dailySequenceFor === key && plan.dailySequenceVersion === WEEK_SEQUENCE_VERSION);
}















function quarterRealityRecord(store = getStore(), today = new Date()) {
    const last = lastWeekTaskRecord(store, today);
    const lastWeekStart = getWeekStart(today, store);
    lastWeekStart.setDate(lastWeekStart.getDate() - 7);
    const qStart = store.quarterStartDate ? new Date(store.quarterStartDate) : null;

    
    
    const earlierDone = new Set();
    const earlierSeen = new Set();
    Object.keys(store.dailyLogs || {}).forEach(key => {
        const d = parseDateInput(key);
        if (!d || (qStart && d < new Date(qStart.toDateString())) || d >= lastWeekStart) return;
        (store.dailyLogs[key] || []).forEach(t => {
            const text = String((t && t.text) || '').trim();
            if (!text) return;
            earlierSeen.add(text);
            if (t.done) earlierDone.add(text);
        });
    });
    const allDone = new Set([...earlierDone, ...last.done]);
    const earlierNotDone = [...earlierSeen].filter(t => !allDone.has(t)).slice(-15);

    const inQuarter = (iso) => {
        const d = iso ? new Date(iso) : null;
        return d && Number.isFinite(d.getTime()) && (!qStart || d >= qStart);
    };
    return {
        lastDone: last.done,
        lastNotDone: last.notDone,
        earlierNotDone,
        leads: (store.leads?.entries || []).filter(e => inQuarter(e.date)).length,
        contacts: (store.contacts || []).filter(c => inQuarter(c.createdAt)).length,
        sales: (store.revenue?.entries || []).filter(e => inQuarter(e.date)).length,
        hasRecord: last.done.length + last.notDone.length + earlierSeen.size > 0
    };
}


function weekNeedsRefit(week, store = getStore(), today = new Date()) {
    if (!week || !week.generated || week.applied || !week.id) return false;
    if (Number(week.weekNumber) <= 1) return false; 
    const thisWeek = getLocalDateString(getWeekStart(today, store));
    if (week.refittedFor === thisWeek || week.refitFailedOn === getLocalDateString(today)) return false;
    return quarterRealityRecord(store, today).hasRecord;
}





function applyWeekRefit(weekId, fields, note) {
    const store = getStore();
    const week = (store.weeklyPlans || []).find(p => String(p.id) === String(weekId));
    if (!week) return false;
    if (!week.asWritten) {
        week.asWritten = {
            winCondition: week.winCondition, topActions: week.topActions, buildAction: week.buildAction,
            visibilityAction: week.visibilityAction, revenueAction: week.revenueAction, followUps: week.followUps,
            daily3: week.daily3, successCheck: week.successCheck
        };
    }
    if (fields) {
        if (fields.weeklyFocus) week.winCondition = fields.weeklyFocus;
        if (Array.isArray(fields.topPriorities) && fields.topPriorities.length) week.topActions = cleanPriorities(fields.topPriorities);
        if (fields.buildAction) week.buildAction = fields.buildAction;
        if (fields.visibilityAction) week.visibilityAction = fields.visibilityAction;
        if (fields.revenueAction) week.revenueAction = fields.revenueAction;
        if (fields.followUpAction) week.followUps = fields.followUpAction;
        if (Array.isArray(fields.dailyThree) && fields.dailyThree.length) week.daily3 = cleanDaily3(fields.dailyThree);
        if (fields.successCheck) week.successCheck = fields.successCheck;
    }
    week.refittedFor = getLocalDateString(getWeekStart(new Date(), store));
    week.refitNote = String(note || '').trim();
    delete week.refitFailedOn;
    saveStore(store);
    return true;
}

function markWeekRefitFailed(weekId) {
    const store = getStore();
    const week = (store.weeklyPlans || []).find(p => String(p.id) === String(weekId));
    if (!week) return;
    week.refitFailedOn = getLocalDateString();
    saveStore(store);
}

















function currentRoadmapWeek(store = getStore(), asOf = new Date()) {
    const start = store?.quarterStartDate ? new Date(store.quarterStartDate) : null;
    if (!start || !Number.isFinite(start.getTime())) return null;

    const firstWeekStart = getWeekStart(start, store);
    const nextBoundary = new Date(firstWeekStart);
    nextBoundary.setDate(nextBoundary.getDate() + 7);
    const startDay = new Date(start);
    startDay.setHours(0, 0, 0, 0);
    const daysInFirstWeek = Math.round((nextBoundary - startDay) / 86400000);
    const leadIn = daysInFirstWeek < 3;

    const weeksBetween = Math.round((getWeekStart(asOf, store) - firstWeekStart) / (7 * 86400000));
    const week = weeksBetween + 1 - (leadIn ? 1 : 0) - pausedWeekNumbers(store).length;
    return Math.min(12, Math.max(1, week));
}





function applyRoadmapWeek(planId) {
    const store = getStore();
    const index = (store.weeklyPlans || []).findIndex(p => String(p.id) === String(planId));
    if (index === -1) return false;
    const plan = store.weeklyPlans[index];
    plan.applied = true;
    plan.date = new Date().toISOString();
    store.weeklyPlans.splice(index, 1);
    store.weeklyPlans.push(plan);
    store.planningStreak = getPlanningStreak(store);
    saveStore(store);
    return true;
}








function planIdentityKey(plan) {
    if (!plan) return undefined;
    return String(plan.id || plan.date || '');
}




function stringHash(str) {
    let h = 0x811c9dc5;
    for (let i = 0; i < str.length; i++) {
        h ^= str.charCodeAt(i);
        h = Math.imul(h, 0x01000193) >>> 0;
    }
    return h.toString(36);
}





function planContentKey(plan) {
    if (!plan) return '';
    const text = (v) => String(v == null ? '' : v).trim();
    const list = (v) => (Array.isArray(v) ? v : []).map(text).join('~');
    return stringHash([
        list(plan.topActions || plan.priorities),
        list(plan.daily3),
        text(plan.winCondition),
        text(plan.buildAction),
        text(plan.revenueAction),
        text(plan.visibilityAction),
        text(plan.followUps)
    ].join('|'));
}
















function planSourceKey(plan) {
    if (!plan) return undefined;
    return planIdentityKey(plan) + '#' + planContentKey(plan);
}

