function getLiveDraftMondayPlan(store = getStore()) {
    const draft = store.draftMondayPlan;
    if (!draft) return null;
    const created = new Date(draft.createdAt);
    if (!draft.createdAt || !Number.isFinite(created.getTime())) return draft;

    const active = getActivePlan(store);
    if (active && Number.isFinite(new Date(active.date).getTime()) && new Date(active.date) > created) return null;

    const writtenIn = getWeekStart(created, store);
    const onPlanningDay = getLocalDateString(created) === getLocalDateString(writtenIn);
    const forWeek = onPlanningDay ? writtenIn : getWeekStart(new Date(writtenIn.getTime() + 8 * 86400000), store);
    const thisWeek = getWeekStart(new Date(), store);
    if (getLocalDateString(thisWeek) > getLocalDateString(forWeek)) return null;
    return draft;
}

