const DAY_LABEL = /^\s*(?:mon|tue|tues|wed|weds|thu|thur|thurs|fri|sat|sun|monday|tuesday|wednesday|thursday|friday|saturday|sunday)(?:\s*(?:[-–—/&+]|to|and|,)\s*(?:mon|tue|tues|wed|weds|thu|thur|thurs|fri|sat|sun|monday|tuesday|wednesday|thursday|friday|saturday|sunday))*\s*[:–—-]\s*/i;





const DAY_NUMBER_LABEL = /^\s*days?\s*\d{1,2}(?:\s*(?:[-–—/&+]|to|and|,)\s*\d{1,2})*\s*[:–—-]\s*/i;

function stripDayLabel(task) {
    if (typeof task !== 'string') return task;
    const cleaned = task.replace(DAY_LABEL, '').replace(DAY_NUMBER_LABEL, '').trim();
    if (cleaned === '') return task.trim(); 
    return cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
}
















const PRIORITY_LABEL = /(^|[.!?]\s+)(?:task|execution|action|what|how|step)\s*[:\-–—]\s*/gi;

function stripPriorityLabels(text) {
    if (typeof text !== 'string') return text;
    const cleaned = text.replace(PRIORITY_LABEL, '$1').replace(/\s{2,}/g, ' ').trim()
        
        
        .replace(/([.!?]\s+)([a-z])/g, (m, sep, ch) => sep + ch.toUpperCase());
    if (cleaned === '') return text.trim();
    return cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
}

function cleanPriorities(list) {
    if (!Array.isArray(list)) return list;
    return list.map(stripPriorityLabels);
}

function cleanDaily3(list) {
    if (!Array.isArray(list)) return list;
    return list.map(stripDayLabel);
}







const BUILD_COMPONENTS = ['offer', 'traffic', 'leads', 'sales', 'follow-up', 'foundation'];























function normaliseBuildPlan(list, previous = []) {
    if (!Array.isArray(list)) return [];

    const doneBefore = new Set(
        (Array.isArray(previous) ? previous : [])
            .filter(item => item && item.done && typeof item.task === 'string')
            .map(item => dedupeKey(item.task))
    );

    return list
        .filter(item => item && typeof item.task === 'string' && item.task.trim())
        .map(item => {
            const week = parseInt(item.week, 10);
            const component = String(item.component || '').toLowerCase().trim();
            const task = item.task.trim();
            return {
                task,
                
                
                
                
                
                
                
                
                
                
                parts: Array.isArray(item.parts)
                    ? item.parts
                        .filter(t => typeof t === 'string' && t.trim())
                        .map(t => t.trim())
                        .slice(0, 5)
                    : [],
                component: BUILD_COMPONENTS.includes(component) ? component : 'foundation',
                week: Number.isFinite(week) && week >= 1 && week <= 12 ? week : 1,
                why: typeof item.why === 'string' ? item.why.trim() : '',
                estimatedMinutes: parseInt(item.estimatedMinutes, 10) || 30,
                
                
                done: item.done === true || doneBefore.has(dedupeKey(task))
            };
        })
        .sort((a, b) => a.week - b.week);
}





















function setBuildTaskDone(listName, task, done) {
    const key = listName === 'buildPlan' ? 'buildPlan' : 'setupChecklist';
    const wanted = dedupeKey(String(task || ''));
    if (!wanted) return false;

    const store = getStore();
    const list = Array.isArray(store[key]) ? store[key] : null;
    if (!list) return false;

    const index = list.findIndex(it => it && typeof it.task === 'string' && dedupeKey(it.task) === wanted);
    if (index === -1) return false;

    list[index].done = Boolean(done);
    saveStore(store);
    return true;
}



















const PLAN_GOAL_FIELDS = [
    { key: 'focus', label: 'Main focus', money: false },
    { key: 'outcome', label: 'Measurable outcome', money: false },
    { key: 'revenueGoal', label: '90-day revenue goal', money: true },
    { key: 'offerPrice', label: 'Average offer price', money: true },
    { key: 'leadGoal', label: '90-day lead goal', money: false }
];

function currentGoalStamp(store = getStore()) {
    return {
        focus: (store.goals && store.goals.focus) || '',
        outcome: (store.goals && store.goals.outcome) || '',
        revenueGoal: Number((store.revenue && store.revenue.quarterlyGoal) || 0),
        offerPrice: Number((store.revenue && store.revenue.averageOfferPrice) || 0),
        leadGoal: Number((store.leads && store.leads.quarterlyGoal) || 0)
    };
}

function sameStamp(a, b) {
    if (!a || !b) return false;
    return PLAN_GOAL_FIELDS.every(f => {
        if (f.money || typeof b[f.key] === 'number') return Number(a[f.key] || 0) === Number(b[f.key] || 0);
        return String(a[f.key] || '').trim() === String(b[f.key] || '').trim();
    });
}







function getPlanDrift(store = getStore()) {
    const none = { drifted: false, changes: [], regenerable: 0, stampedAt: null };
    const was = store.planGeneratedFor;
    if (!was) return none;
    if (!(store.weeklyPlans || []).some(p => p.generated)) return none;

    const now = currentGoalStamp(store);
    const changes = [];
    PLAN_GOAL_FIELDS.forEach(f => {
        const before = was[f.key];
        
        
        if (before === undefined || before === null) return;
        const after = now[f.key];
        const differs = (f.money || typeof after === 'number')
            ? Number(before || 0) !== Number(after || 0)
            : String(before).trim() !== String(after).trim();
        if (differs) changes.push({ key: f.key, label: f.label, money: f.money, was: before, now: after });
    });

    if (!changes.length) return none;
    if (sameStamp(store.planDriftDismissed, now)) return none;

    const regenerable = (store.weeklyPlans || []).filter(p => p.generated && !p.applied).length;
    return { drifted: true, changes, regenerable, stampedAt: was.at || null };
}





function dismissPlanDrift() {
    const store = getStore();
    store.planDriftDismissed = currentGoalStamp(store);
    saveStore(store);
}








