function applyGeneratedPlan(plan, meta = {}) {
    
    
    const rawBuild = plan && (plan.buildPlan || plan.setupChecklist);
    if (!plan || !plan.summary || !plan.weeks || plan.weeks.length !== 12 || !rawBuild || !plan.redFlags || !plan.monthlyThemes) {
        console.error("Invalid plan structure passed to applyGeneratedPlan");
        return;
    }

    const store = getStore();

    
    
    
    store.buildPlan = normaliseBuildPlan(rawBuild, store.buildPlan);
    
    
    store.setupChecklist = [];
    store.planMath = plan.planMath || null;
    
    
    store.planGeneratedFor = { ...currentGoalStamp(store), at: new Date().toISOString() };
    
    store.planDriftDismissed = null;
    store.planFailure = null;
    store.redFlags = plan.redFlags;
    store.monthlyThemes = plan.monthlyThemes;
    store.planSummary = plan.summary;
    store.planCalibration = plan.calibration;
    
    
    
    
    
    
    
    
    
    store.planDeferred = Array.isArray(plan.deferred)
        ? plan.deferred
            .filter(d => d && typeof d.component === 'string' && d.component.trim())
            .slice(0, 5)
            .map(d => ({
                component: String(d.component).trim().slice(0, 40),
                why: String(d.why || '').trim().slice(0, 300)
            }))
        : [];

    
    
    
    
    const reason = String(meta.reason || '').trim();
    if (reason) {
        store.planRegenerations = [
            { reason: reason.slice(0, 600), at: new Date().toISOString() },
            ...(store.planRegenerations || [])
        ].slice(0, 5);
    }

    
    
    
    
    const kept = (store.weeklyPlans || []).filter(p => !p.generated || p.applied);
    
    
    
    (store.weeklyPlans || []).filter(p => p.generated && !p.applied).forEach(p => recordDeletion(store, p.id));
    const spokenFor = new Set(
        kept.filter(p => p.generated && p.weekNumber != null).map(p => p.weekNumber)
    );
    store.weeklyPlans = kept;

    const now = Date.now();
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const batch = now.toString(36) + Math.random().toString(36).slice(2, 8);
    plan.weeks.forEach((w, i) => {
        if (spokenFor.has(w.weekNumber)) return; 
        store.weeklyPlans.push({
            id: 'gen_' + batch + '_' + i,
            date: new Date(now + i).toISOString(),
            weekNumber: w.weekNumber,
            monthIndex: w.monthIndex,
            winCondition: w.weeklyFocus,
            topActions: cleanPriorities(w.topPriorities),
            
            
            
            buildAction: w.buildAction || '',
            
            
            
            
            
            
            visibilityAction: w.visibilityAction || '',
            revenueAction: w.revenueAction || '',
            followUps: w.followUpAction || '',
            daily3: cleanDaily3(w.dailyThree),
            successCheck: w.successCheck,
            generated: true,
            applied: false
        });
    });

    saveStore(store);

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    refreshDigestSnapshot({ force: true });
}

























function regenerationImpact(store = getStore()) {
    const plans = store.weeklyPlans || [];

    const replaced = plans
        .filter(p => p.generated && !p.applied && p.weekNumber != null)
        .map(p => Number(p.weekNumber))
        .filter(n => Number.isFinite(n))
        .sort((a, b) => a - b);

    const keptApplied = plans.filter(p => p.generated && p.applied).length;
    const keptOwn = plans.filter(p => !p.generated).length;

    const thisWeek = currentRoadmapWeek(store);
    const thisWeekReplaced = thisWeek != null && replaced.includes(thisWeek);

    
    
    let weeksLabel = '';
    if (replaced.length === 1) {
        weeksLabel = 'week ' + replaced[0];
    } else if (replaced.length > 1) {
        const contiguous = replaced[replaced.length - 1] - replaced[0] === replaced.length - 1;
        weeksLabel = contiguous
            ? 'weeks ' + replaced[0] + ' to ' + replaced[replaced.length - 1]
            : 'weeks ' + replaced.join(', ');
    }

    return { replaced, weeksLabel, keptApplied, keptOwn, thisWeek, thisWeekReplaced };
}










function getRegenerableWeeks() {
    const store = getStore();
    const weeksElapsed = currentRoadmapWeek(store) || 0;
    const start = store.quarterStartDate ? new Date(store.quarterStartDate) : null;
    const startOk = start && Number.isFinite(start.getTime());

    return (store.weeklyPlans || [])
        .filter(p => p.generated && !p.applied && p.weekNumber != null)
        .sort((a, b) => a.weekNumber - b.weekNumber)
        .map(p => {
            
            
            
            
            
            
            
            const isPast = p.weekNumber <= weeksElapsed;
            let endedLabel = null;
            if (isPast && startOk) {
                const end = new Date(start);
                end.setDate(end.getDate() + (p.weekNumber * 7) - 1);
                endedLabel = end.toLocaleDateString(undefined, { day: 'numeric', month: 'long' });
            }
            return { ...p, isPast, endedLabel };
        });
}












function replaceGeneratedWeek(planId, week) {
    if (!week || !week.weeklyFocus) return false;

    const store = getStore();
    const idx = (store.weeklyPlans || []).findIndex(p => String(p.id) === String(planId));
    if (idx === -1) return false;

    const existing = store.weeklyPlans[idx];
    if (!existing.generated || existing.applied) return false;

    
    
    
    
    
    store.weeklyPlans[idx] = {
        ...existing,
        winCondition: week.weeklyFocus,
        topActions: cleanPriorities(week.topPriorities),
        
        
        
        
        buildAction: week.buildAction || existing.buildAction || '',
        visibilityAction: week.visibilityAction,
        revenueAction: week.revenueAction,
        followUps: week.followUpAction,
        daily3: cleanDaily3(week.dailyThree),
        successCheck: week.successCheck,
        generated: true,
        applied: false,
        regeneratedAt: new Date().toISOString()
    };

    saveStore(store);
    return true;
}

