const COACH_CHAT_MAX_MESSAGES = 40;
const COACH_CHAT_MAX_CHARS = 20000;





function trimCoachChat(messages) {
    let trimmed = (messages || [])
        .filter(m => m && (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string')
        .map(m => ({ role: m.role, content: m.content, at: m.at || new Date().toISOString() }))
        .slice(-COACH_CHAT_MAX_MESSAGES);

    let total = trimmed.reduce((sum, m) => sum + m.content.length, 0);
    while (trimmed.length > 1 && total > COACH_CHAT_MAX_CHARS) {
        total -= trimmed[0].content.length;
        trimmed = trimmed.slice(1);
    }

    return trimmed;
}

function getCoachChat() {
    return getStore().coachChat || [];
}





function saveCoachChat(messages) {
    const store = getStore();
    store.coachChat = trimCoachChat(messages);
    saveStore(store);
    return store.coachChat;
}

function clearCoachChat() {
    const store = getStore();
    store.coachChat = [];
    saveStore(store);
}











const AI_REPORT_MAX_CHARS = 20000;



















const AI_REPORT_HISTORY_MAX = 5;
const AI_REPORT_HISTORY_CHARS = 8000;

function saveAiReport(text) {
    if (typeof text !== 'string' || !text.trim()) return null;

    const store = getStore();
    const incoming = text.slice(0, AI_REPORT_MAX_CHARS);

    
    
    
    
    
    
    
    
    
    
    const stampedAt = (() => {
        const taken = [store.aiReport]
            .concat(Array.isArray(store.aiReportHistory) ? store.aiReportHistory : [])
            .filter(r => r && r.at)
            .map(r => new Date(r.at).getTime())
            .filter(Number.isFinite);
        const newest = taken.length ? Math.max(...taken) : -Infinity;
        return new Date(Math.max(Date.now(), newest + 1)).toISOString();
    })();

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const current = store.aiReport;
    if (current
        && typeof current.text === 'string'
        && current.text === incoming
        && (current.quarterStartDate || '') === (store.quarterStartDate || '')) {
        current.at = stampedAt;
        saveStore(store);
        return current;
    }

    
    
    
    
    const outgoing = store.aiReport;
    if (outgoing && typeof outgoing.text === 'string' && outgoing.text.trim()) {
        const history = Array.isArray(store.aiReportHistory) ? store.aiReportHistory : [];
        history.push({
            text: outgoing.text.slice(0, AI_REPORT_HISTORY_CHARS),
            at: outgoing.at,
            quarterStartDate: outgoing.quarterStartDate || ''
        });
        store.aiReportHistory = history.slice(-AI_REPORT_HISTORY_MAX);
    }

    store.aiReport = {
        
        
        
        text: incoming,
        at: stampedAt,
        
        
        quarterStartDate: store.quarterStartDate || ''
    };
    saveStore(store);
    return store.aiReport;
}












function getAiReport() {
    const store = getStore();
    const report = store.aiReport;

    if (!report || typeof report.text !== 'string' || !report.text.trim()) return null;
    if ((report.quarterStartDate || '') !== (store.quarterStartDate || '')) return null;

    return report;
}





















const EXEC_REPORT_STALE_DAYS = 14;


















function getAiReportHistory() {
    const store = getStore();
    const thisQuarter = store.quarterStartDate || '';
    const out = [];

    const current = store.aiReport;
    if (current && typeof current.text === 'string' && current.text.trim()) {
        out.push({
            text: current.text,
            at: current.at || '',
            quarterStartDate: current.quarterStartDate || '',
            isThisQuarter: (current.quarterStartDate || '') === thisQuarter,
            isCurrent: true
        });
    }

    const history = Array.isArray(store.aiReportHistory) ? store.aiReportHistory : [];
    
    for (let i = history.length - 1; i >= 0; i--) {
        const r = history[i];
        if (!r || typeof r.text !== 'string' || !r.text.trim()) continue;
        out.push({
            text: r.text,
            at: r.at || '',
            quarterStartDate: r.quarterStartDate || '',
            isThisQuarter: (r.quarterStartDate || '') === thisQuarter,
            isCurrent: false
        });
    }

    return out;
}












































function quarterKeyForDate(store, iso) {
    const t = iso ? new Date(iso).getTime() : NaN;
    if (!Number.isFinite(t)) return '';

    const archived = Array.isArray(store.pastQuarters) ? store.pastQuarters : [];
    for (const q of archived) {
        const start = q?.quarterStartDate ? new Date(q.quarterStartDate).getTime() : NaN;
        const end = q?.dateArchived ? new Date(q.dateArchived).getTime() : NaN;
        if (Number.isFinite(start) && Number.isFinite(end) && t >= start && t <= end) {
            return q.quarterStartDate;
        }
    }

    const live = store.quarterStartDate ? new Date(store.quarterStartDate).getTime() : NaN;
    if (Number.isFinite(live) && t >= live) return store.quarterStartDate;

    return '';
}



function quarterLabelForKey(store, key) {
    if (!key) return 'Before your first 90 days';
    if (key === (store.quarterStartDate || '')) return quarterRangeLabel(key, '');

    const archived = Array.isArray(store.pastQuarters) ? store.pastQuarters : [];
    const q = archived.find(x => x?.quarterStartDate === key);
    if (q) return quarterRangeLabel(key, q.dateArchived || '');

    
    
    return quarterRangeLabel(key, '');
}

function monthLabel(iso) {
    const d = iso ? new Date(iso) : null;
    if (!d || !Number.isFinite(d.getTime())) return '';
    return d.toLocaleDateString(undefined, { month: 'long', year: 'numeric' });
}

























const PERFORMANCE_PERIODS = { 1: 4, 2: 9, 3: 13 }; 

function contactCallAt(c) {
    if (c.reached && c.reached['call-booked']) return c.reached['call-booked'];
    
    
    return stageRank(c.stage) >= 1 ? (c.stageChangedAt || c.createdAt || '') : '';
}

function contactWonAt(c) {
    if (c.stage !== 'won') return '';
    return (c.reached && c.reached.won) || c.stageChangedAt || c.createdAt || '';
}


function performanceTotals(from, to, store, saleEntries) {
    const inside = (value) => {
        const t = new Date(value).getTime();
        return Number.isFinite(t) && t >= from.getTime() && t < to.getTime();
    };

    const funnel = summariseFunnel(
        (store.leads?.entries || []).filter(l => inside(l.date)),
        (store.metrics || []).filter(m => inside(m.date)),
        []
    );
    const contacts = store.contacts || [];
    const contactLeads = contacts.filter(c => !c.countedInLeads && inside(c.createdAt)).length;
    const contactCalls = contacts.filter(c => inside(contactCallAt(c))).length;
    const contactCloses = contacts.filter(c => inside(contactWonAt(c))).length;

    const sales = saleEntries.filter(e => inside(e.date));
    return {
        revenue: sales.reduce((s, e) => s + (parseFloat(e.amount) || 0), 0),
        sales: sales.length,
        leads: funnel.totalLeads + contactLeads,
        calls: funnel.totalCalls + contactCalls,
        closes: funnel.totalCloses + contactCloses
    };
}

function getPerformanceReport(months = 1, now = new Date()) {
    const store = getStore();
    const weeks = PERFORMANCE_PERIODS[months] || PERFORMANCE_PERIODS[1];
    const saleEntries = getRevenueInsights().entries || [];

    const thisWeek = getWeekStart(now, store);
    const start = new Date(thisWeek);
    start.setDate(start.getDate() - (weeks - 1) * 7);
    const end = new Date(now.getTime() + 1); 

    const buckets = [];
    for (let i = 0; i < weeks; i++) {
        const from = new Date(start);
        from.setDate(from.getDate() + i * 7);
        const next = new Date(from);
        next.setDate(next.getDate() + 7);
        const to = next < end ? next : end;
        buckets.push({ start: from, current: i === weeks - 1, ...performanceTotals(from, to, store, saleEntries) });
    }

    const length = end.getTime() - start.getTime();
    const previousStart = new Date(start.getTime() - length);
    const totals = performanceTotals(start, end, store, saleEntries);
    const previous = performanceTotals(previousStart, start, store, saleEntries);

    return { months, weeks, start, end: now, previousStart, buckets, totals, previous };
}

















function canDeleteReport(kind) {
    return kind === 'executive' || kind === 'monthly';
}






function deleteReport(id) {
    const key = String(id || '');
    const store = getStore();

    if (key.startsWith('exec-')) {
        const at = key.slice('exec-'.length);
        const history = Array.isArray(store.aiReportHistory) ? store.aiReportHistory : [];

        if (store.aiReport && String(store.aiReport.at) === at) {
            
            
            
            
            
            
            
            store.aiReport = null;
            saveStore(store);
            return true;
        }

        const kept = history.filter(h => String(h && h.at) !== at);
        if (kept.length === history.length) return false;
        store.aiReportHistory = kept;
        saveStore(store);
        return true;
    }

    if (key.startsWith('month-')) {
        const mrId = key.slice('month-'.length);
        const reviews = Array.isArray(store.monthlyReviews) ? store.monthlyReviews : [];
        const mr = reviews.find(r => r && String(r.id) === mrId);
        
        
        
        if (!mr || !mr.summary) return false;
        delete mr.summary;
        saveStore(store);
        return true;
    }

    return false;
}

function getReports() {
    const store = getStore();
    const liveKey = store.quarterStartDate || '';
    const rows = [];

    
    
    
    getAiReportHistory().forEach(r => {
        const key = r.quarterStartDate || quarterKeyForDate(store, r.at);
        rows.push({
            id: 'exec-' + (r.at || rows.length),
            kind: 'executive',
            kindLabel: 'AI Executive Report',
            at: r.at,
            text: r.text,
            isLatestOfKind: r.isCurrent,
            quarterKey: key,
            quarterLabel: quarterLabelForKey(store, key),
            covers: quarterLabelForKey(store, key)
        });
    });

    
    
    
    
    
    
    (Array.isArray(store.monthlyReviews) ? store.monthlyReviews : []).forEach(mr => {
        if (!mr) return;
        const summary = typeof mr.summary?.text === 'string' && mr.summary.text.trim() ? mr.summary.text : '';
        const answers = {
            leads: mr.leads || '',
            sales: mr.sales || '',
            eliminate: mr.eliminate || '',
            drain: mr.drain || ''
        };
        const hasAnswers = Object.values(answers).some(v => String(v).trim());
        if (!summary && !hasAnswers) return;
        const at = (summary && mr.summary.at) || mr.date || '';
        const key = quarterKeyForDate(store, at);
        rows.push({
            id: 'month-' + mr.id,
            kind: 'monthly',
            kindLabel: summary ? 'Monthly Review and CEO Summary' : 'Monthly Review',
            at,
            text: summary,
            answers: hasAnswers ? answers : null,
            isLatestOfKind: false,
            quarterKey: key,
            quarterLabel: quarterLabelForKey(store, key),
            covers: monthLabel(mr.date || at)
        });
    });

    
    
    (Array.isArray(store.pastQuarters) ? store.pastQuarters : []).forEach(q => {
        const text = q?.summary?.text || (typeof q?.summary === 'string' ? q.summary : '');
        if (typeof text !== 'string' || !text.trim()) return;
        const key = q.quarterStartDate || '';
        rows.push({
            id: 'quarter-' + (key || q.dateArchived || rows.length),
            kind: 'quarter',
            kindLabel: '90-day summary',
            at: q.summary?.at || q.dateArchived || '',
            text,
            isLatestOfKind: false,
            quarterKey: key,
            quarterLabel: quarterLabelForKey(store, key),
            covers: quarterLabelForKey(store, key)
        });
    });

    rows.forEach(r => { r.isCurrentQuarter = r.quarterKey === liveKey; });

    
    
    rows.sort((a, b) => {
        const at = new Date(a.at || 0).getTime() || 0;
        const bt = new Date(b.at || 0).getTime() || 0;
        return bt - at;
    });

    return rows;
}



function getReportsByQuarter() {
    const store = getStore();
    const liveKey = store.quarterStartDate || '';
    const groups = [];

    getReports().forEach(r => {
        let g = groups.find(x => x.key === r.quarterKey);
        if (!g) {
            g = {
                key: r.quarterKey,
                label: r.quarterLabel,
                isCurrent: r.quarterKey === liveKey,
                reports: []
            };
            groups.push(g);
        }
        g.reports.push(r);
    });

    groups.sort((a, b) => {
        if (a.isCurrent) return -1;
        if (b.isCurrent) return 1;
        return (new Date(b.key || 0).getTime() || 0) - (new Date(a.key || 0).getTime() || 0);
    });

    return groups;
}





























function weekRunKeys(weekStarts, store = getStore()) {
    const weeks = new Set(
        (weekStarts || [])
            .filter(d => d instanceof Date && Number.isFinite(d.getTime()))
            .map(d => getLocalDateString(d))
    );
    if (weeks.size === 0) return [];
    let cursor = getWeekStart(new Date(), store);
    const keyOf = d => getLocalDateString(getWeekStart(d, store));
    const stepBack = () => { const prev = new Date(cursor); prev.setDate(prev.getDate() - 3); cursor = getWeekStart(prev, store); };
    
    if (!weeks.has(keyOf(cursor))) stepBack();
    const run = [];
    while (weeks.has(keyOf(cursor)) && run.length < 520) { run.push(keyOf(cursor)); stepBack(); }
    return run.reverse();
}

function weeksInARow(weekStarts, store = getStore()) {
    return weekRunKeys(weekStarts, store).length;
}











const REVIEW_LATE_DAYS = PLAN_AHEAD_DAYS;









function reviewWeekStart(review, store = getStore()) {
    const written = new Date(review && review.date);
    if (!Number.isFinite(written.getTime())) return null;

    const writtenIn = getWeekStart(written, store);
    const day = new Date(written);
    day.setHours(0, 0, 0, 0);
    
    
    const dayInWeek = Math.round((day.getTime() - writtenIn.getTime()) / 86400000);

    
    
    return dayInWeek < REVIEW_LATE_DAYS
        ? getWeekStart(new Date(writtenIn.getTime() - 6 * 86400000), store)
        : writtenIn;
}




function reviewedWeeks(store = getStore()) {
    return (store.reviews || [])
        .map(r => reviewWeekStart(r, store))
        .filter(Boolean);
}

function plannedWeeks(store = getStore()) {
    
    
    return (store.weeklyPlans || [])
        .filter(p => p && (p.applied || !p.generated))
        .map(p => planWeekStart(p, store))
        .filter(Boolean);
}

function getReviewStreak(store = getStore()) {
    return weeksInARow(reviewedWeeks(store), store);
}

function getPlanningStreak(store = getStore()) {
    return weeksInARow(plannedWeeks(store), store);
}













function streakExplainer(kind, store = getStore()) {
    const weeks = kind === 'plan' ? plannedWeeks(store) : reviewedWeeks(store);
    const noun = kind === 'plan' ? 'planned' : 'reviewed';
    const thing = kind === 'plan' ? 'weekly plan' : 'weekly review';

    const keys = Array.from(new Set(weeks.map(d => getLocalDateString(d)))).sort();
    const total = keys.length;
    if (total === 0) return `No week ${noun} yet. Your first ${thing} starts the count.`;

    
    
    
    
    const run = weekRunKeys(weeks, store);
    const earlier = keys.filter(k => !run.includes(k) && (run.length === 0 || k < run[0]));

    const totalLine = total === 1 ? `1 week ${noun} so far` : `${total} weeks ${noun} so far`;

    if (run.length === 0) {
        return `${totalLine}, but none this week or last, so the run is back to zero.`;
    }
    if (earlier.length === 0) {
        return total === 1
            ? `Your first week ${noun}. Keep it up and the run builds from here.`
            : `${totalLine}, all of them in a row.`;
    }
    
    
    
    
    const missed = getWeekStart(new Date(parseDateInput(run[0]).getTime() - 6 * 86400000), store);
    return `${totalLine}. No ${thing} for the week of ${shortWeekLabel(getLocalDateString(missed))}, so the run restarted after that.`;
}


function shortWeekLabel(dateKey) {
    const d = parseDateInput(dateKey);
    if (!d || !Number.isFinite(d.getTime())) return dateKey;
    return d.toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
}































function summaryPercent(value) {
    return value === null || value === undefined ? null : Math.round(value);
}



function movementClause(change, previousLabel, currency) {
    if (!change) return '';
    if (change.direction === 'level') return ` — exactly what ${previousLabel} earned.`;
    const size = `${currency}${formatAmount(Math.abs(change.delta))}`;
    const word = change.direction === 'up' ? 'more than' : 'less than';
    const pct = change.percent === null
        ? ''
        : `, a ${change.direction === 'up' ? 'rise' : 'fall'} of ${Math.abs(Math.round(change.percent))}%`;
    return ` That is ${size} ${word} ${previousLabel} earned${pct}.`;
}


function goalsMetSentence(q, previous) {
    const met = q.goalsMet || {};
    const both = met.revenue === true && met.leads === true;
    const neither = met.revenue === false && met.leads === false;

    if (both) return `You hit both targets you set yourself in these 90 days, revenue and leads.`;
    if (neither) return `You missed both targets you set yourself in these 90 days.`;
    if (met.revenue === true && met.leads === null) {
        
        
        const before = previous?.goalsMet?.revenue;
        if (before === false) return `You hit your revenue goal in ${q.label} after missing it in ${previous.label}.`;
        if (before === true) return `You hit your revenue goal again, as you did in ${previous.label}.`;
        return `You hit your revenue goal.`;
    }
    if (met.revenue === false && met.leads === null) {
        const before = previous?.goalsMet?.revenue;
        if (before === true) return `You hit your revenue goal in ${previous.label} and missed it in ${q.label}.`;
        return `You missed your revenue goal.`;
    }
    if (met.revenue === true && met.leads === false) return `You hit your revenue goal but not your lead goal.`;
    if (met.revenue === false && met.leads === true) return `You hit your lead goal but not your revenue goal.`;
    if (met.leads === true) return `You hit your lead goal.`;
    if (met.leads === false) return `You missed your lead goal.`;
    return `No targets were set for this quarter, so there is nothing to have hit or missed.`;
}




function quarterSummaryText(q, previous, store = getStore()) {
    const currency = store.settings?.currency || '$';
    const paras = [];

    
    const pct = summaryPercent(q.progressPercent);
    const goalClause = q.goal > 0
        ? ` against a ${currency}${formatAmount(q.goal)} goal${pct === null ? '' : `, ${pct}% of it`}`
        : ', with no revenue goal set';
    paras.push(
        `${q.label} finished on ${currency}${formatAmount(q.revenue)} from `
        + `${formatAmount(q.salesCount)} ${q.salesCount === 1 ? 'sale' : 'sales'}${goalClause}.`
        
        
        
        
        
        + (previous ? movementClause(changeBetween(q.revenue, previous.revenue), previous.label, currency) : '')
    );

    
    paras.push(goalsMetSentence(q, previous));

    
    
    
    const rate = summaryPercent(q.callCloseRate);
    const rateBefore = previous ? summaryPercent(previous.callCloseRate) : null;
    let funnel = `${formatAmount(q.leads)} ${q.leads === 1 ? 'lead' : 'leads'} came in, `
        + `${formatAmount(q.calls)} ${q.calls === 1 ? 'call' : 'calls'} happened and `
        + `${formatAmount(q.closes)} ${q.closes === 1 ? 'deal' : 'deals'} closed`
        + (rate === null ? '.' : `, a close rate of ${rate}%${rateBefore === null ? '.' : ` against ${rateBefore}% in ${previous.label}.`}`);
    if (previous && rate !== null && rateBefore !== null && rate > rateBefore && q.leads < previous.leads) {
        funnel += ` Fewer people arrived than last time, so the gain came from converting better rather than from more of them.`;
    }
    paras.push(funnel);

    
    if (q.focusAverage !== null) {
        const before = previous ? previous.focusAverage : null;
        paras.push(
            `Across ${formatAmount(q.focusScores.length)} ${q.focusScores.length === 1 ? 'week' : 'weeks'} you got through `
            + `${q.focusAverage}% of what you planned for yourself on average`
            + (before === null
                ? `.`
                : (q.focusAverage === before
                    ? `, the same as ${previous.label}.`
                    : `, ${q.focusAverage > before ? 'up' : 'down'} from ${before}% in ${previous.label}.`))
            
            
            
            
            
            + ` You planned ${formatAmount(q.plansCount)} ${q.plansCount === 1 ? 'week' : 'weeks'} and wrote `
            + `${formatAmount(q.reviewsCount)} weekly ${q.reviewsCount === 1 ? 'review' : 'reviews'}.`
        );
    }

    
    if (q.revenue > 0) {
        paras.push(`Most of it came through ${q.topSource}, and your strongest offer was ${q.topOffer}.`);
    }

    
    const change = q.reflection?.changeNextQuarter;
    if (change && String(change).trim()) {
        paras.push(`On the way out you wrote that what should change next quarter is: "${String(change).trim()}"`);
    }

    return paras.join('\n\n');
}



function saveQuarterSummary(quarterStartDate, text, source = 'figures') {
    if (typeof text !== 'string' || !text.trim()) return false;
    const store = getStore();
    const record = (store.pastQuarters || []).find(q => q?.quarterStartDate === quarterStartDate);
    if (!record) return false;
    record.summary = {
        text: text.trim(),
        at: new Date().toISOString(),
        source: source === 'coach' ? 'coach' : 'figures'
    };
    saveStore(store);
    return true;
}








function ensureQuarterSummaries() {
    const store = getStore();
    const archived = sortArchivedQuarters(store.pastQuarters);
    if (archived.length === 0) return 0;

    const rows = archived.map((q, i) => summariseArchivedQuarter(q, i + 1, archived[i - 1], store));
    let written = 0;

    archived.forEach((record, i) => {
        if (normaliseQuarterSummary(record.summary)) return;
        const text = quarterSummaryText(rows[i], rows[i - 1] || null, store);
        if (!text.trim()) return;
        record.summary = { text, at: record.dateArchived || new Date().toISOString(), source: 'figures' };
        written++;
    });

    if (written > 0) saveStore(store);
    return written;
}




function resetQuarter(reflection = null) {
    const store = getStore();

    
    
    
    store.pastQuarters = store.pastQuarters || [];
    const archivedRecord = {
        dateArchived: new Date().toISOString(),
        quarterStartDate: store.quarterStartDate || '',
        pausedWeeks: [...pausedWeekNumbers(store)],
        goals: { ...store.goals },
        reflection: reflection,
        revenueEntries: [...(store.revenue?.entries || [])],
        revenueGoal: store.revenue?.quarterlyGoal || 0,
        leadEntries: [...(store.leads?.entries || [])],
        leadGoal: store.leads?.quarterlyGoal || 0,
        
        
        
        contacts: (store.contacts || []).filter(c => c.stage === 'won' || c.stage === 'lost'),
        metrics: [...(store.metrics || [])],
        
        
        
        expenses: [...(store.expenses || [])],
        weeklyPlans: [...(store.weeklyPlans || [])],
        reviewsCount: store.reviews.length,
        plansCount: store.weeklyPlans.length,
        
        
        
        
        
        plan: {
            buildPlan: [...(store.buildPlan || [])],
            setupChecklist: [...(store.setupChecklist || [])],
            summary: store.planSummary || '',
            calibration: store.planCalibration || '',
            planMath: store.planMath || null,
            monthlyThemes: { ...(store.monthlyThemes || {}) },
            redFlags: [...(store.redFlags || [])],
            deferred: [...(store.planDeferred || [])]
        },
        
        
        
        
        goalsMet: {
            revenue: hasCelebrated('revenue', store),
            leads: hasCelebrated('leads', store)
        },
        
        
        focusScores: [...(store.focusScores || [])],
        dailyLogs: store.dailyLogs ? { ...store.dailyLogs } : {}
    };
    store.pastQuarters.push(archivedRecord);

    
    
    
    
    
    
    
    
    
    try {
        const all = sortArchivedQuarters(store.pastQuarters);
        const i = all.indexOf(archivedRecord);
        archivedRecord.priorityCarry = (archivedRecord.goals?.priorities || [])
            .map(p => String(p || '').trim())
            .filter(Boolean)
            .map(text => {
                const chain = computePriorityChain(all, i, text);
                return {
                    text,
                    streak: chain.length,
                    since: all[chain[0]]?.quarterStartDate || archivedRecord.quarterStartDate || ''
                };
            });
    } catch (err) {
        console.warn('Priority carry markers could not be written for this quarter:', err);
    }

    
    
    
    
    
    
    
    
    
    
    try {
        const all = store.pastQuarters;
        const i = all.length - 1;
        const row = summariseArchivedQuarter(archivedRecord, i + 1, all[i - 1], store);
        const previous = all[i - 1] ? summariseArchivedQuarter(all[i - 1], i, all[i - 2], store) : null;
        const text = quarterSummaryText(row, previous, store);
        if (text.trim()) {
            archivedRecord.summary = { text, at: archivedRecord.dateArchived, source: 'figures' };
        }
    } catch (err) {
        console.warn('Quarter summary could not be written for this quarter:', err);
    }

    
    store.goals = {
        focus: '',
        outcome: '',
        priorities: ['', '', ''],
        milestones: { month1: '', month2: '', month3: '' },
        statement: ''
    };

    
    
    
    if (store.revenue) {
        store.revenue.entries = [];
    }
    if (store.leads) {
        store.leads.entries = [];
    }
    store.metrics = [];
    
    
    
    store.expenses = [];

    
    
    
    
    
    store.contacts = (store.contacts || []).filter(c => c.stage !== 'won' && c.stage !== 'lost');

    
    
    
    
    
    
    store.buildPlan = [];
    store.setupChecklist = [];
    store.planSummary = '';
    store.planCalibration = '';
    store.planMath = null;
    store.monthlyThemes = { month1: '', month2: '', month3: '' };
    store.redFlags = [];
    store.planDeferred = [];
    store.planRegenerations = [];

    
    store.weeklyPlans = [];

    
    store.dailyLogs = {};

    
    
    
    
    

    
    store.quarterStartDate = new Date().toISOString();
    
    
    
    store.pausedWeeks = [];

    
    
    
    store.draftQuarterReflection = null;
    
    
    
    store.quarterPlanDeferred = null;

    saveStore(store);
}










function cycleHasWorkInIt(store = getStore()) {
    const start = quarterCountsFrom(store);
    if (!start) return false;
    if ((store.weeklyPlans || []).length > 0) return true;
    const inside = (rows) => (rows || []).some(e => {
        const t = new Date(e && e.date).getTime();
        return Number.isFinite(t) && t >= start.getTime();
    });
    return inside(store.revenue?.entries) || inside(store.leads?.entries);
}





















function startNewQuarter(date = new Date()) {
    const store = getStore();

    if (cycleHasWorkInIt(store)) {
        store.quarterPlanDeferred = null;
        saveStore(store);
        return false;
    }

    store.quarterStartDate = new Date(date).toISOString();
    
    
    
    
    store.quarterPlanDeferred = null;
    saveStore(store);
    return true;
}


