const DEFAULT_WORKING_DAYS = 5;

function workingDaysTarget(store = getStore()) {
    
    
    
    
    
    const named = businessDayNames(store);
    if (named.length) return named.length;
    const n = parseInt(store?.profile?.workingDaysPerWeek, 10);
    return Number.isFinite(n) && n >= 1 && n <= 7 ? n : DEFAULT_WORKING_DAYS;
}






const DEFAULT_BUSINESS_HOURS = 2;

function businessHoursPerDay(store = getStore()) {
    const n = Number(store?.profile?.hoursPerDay);
    return Number.isFinite(n) && n >= 1 && n <= 12 ? n : DEFAULT_BUSINESS_HOURS;
}









function businessDayNames(store = getStore()) {
    const saved = store?.profile?.businessDays;
    if (!Array.isArray(saved)) return [];
    return DAY_NAMES.filter(d => saved.includes(d));
}











function businessDaysSentence(store = getStore()) {
    return dayListSentence(businessDayNames(store));
}









function dayListSentence(days) {
    const ordered = Array.isArray(days) ? DAY_NAMES.filter(d => days.includes(d)) : [];
    if (!ordered.length) return '';
    if (ordered.length === 1) return ordered[0];
    return ordered.slice(0, -1).join(', ') + ' and ' + ordered[ordered.length - 1];
}










































function planForWeekStart(weekStart, store = getStore()) {
    const target = getWeekStart(weekStart, store).getTime();
    return (store.weeklyPlans || [])
        .filter(p => p && (!p.generated || p.applied))
        .slice()
        .sort((a, b) => new Date(b.date) - new Date(a.date))
        .find(p => {
            const written = new Date(p.date);
            if (!Number.isFinite(written.getTime())) return false;
            const forWeek = planWeekStart(p, store);
            return Boolean(forWeek) && forWeek.getTime() === target;
        }) || null;
}

function getFocusWeek(weekStart, store = getStore()) {
    const start = getWeekStart(weekStart, store);
    const target = workingDaysTarget(store);

    let daysWorked = 0;

    
    
    
    
    
    
    
    
    
    
    
    
    
    const seen = new Map(); 

    for (let i = 0; i < 7; i++) {
        const d = new Date(start);
        d.setDate(start.getDate() + i);
        const log = store.dailyLogs?.[getLocalDateString(d)];
        if (!Array.isArray(log) || log.length === 0) continue;

        let doneToday = 0;
        log.forEach(t => {
            const text = String((t && t.text) || '');
            seen.set(text, Boolean(seen.get(text)) || Boolean(t && t.done));
            if (t && t.done) doneToday++;
        });
        if (doneToday > 0) daysWorked++;
    }

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const plan = planForWeekStart(start, store);
    const hasSequence = Boolean(plan && Array.isArray(plan.dailySequence) && plan.dailySequence.length > 0);
    const planned = hasSequence ? weekSequence(plan) : [];
    const universe = new Set(planned);
    seen.forEach((done, text) => { if (done) universe.add(text); });

    const tasksTotal = planned.length > 0 ? universe.size : seen.size;
    const tasksDone = [...seen.entries()].filter(([, done]) => done).length;

    const end = new Date(start);
    end.setDate(start.getDate() + 6);

    
    
    
    return {
        weekStart: getLocalDateString(start),
        weekEnd: getLocalDateString(end),
        daysExecuted: Math.min(daysWorked, target),
        workingDaysTarget: target,
        tasksDone,
        tasksTotal,
        percent: tasksTotal > 0 ? Math.round((tasksDone / tasksTotal) * 100) : 0
    };
}










function captureFocusScores(store = getStore()) {
    const thisWeekStart = getWeekStart(new Date(), store).getTime();
    const existing = new Set((store.focusScores || []).map(r => r.weekStart));

    
    const dayKeys = Object.keys(store.dailyLogs || {}).sort();
    if (dayKeys.length === 0) return 0;

    const earliest = parseDateInput(dayKeys[0]);
    if (!earliest || !Number.isFinite(earliest.getTime())) return 0;

    const cursor = getWeekStart(earliest, store);
    const rows = [];

    while (cursor.getTime() < thisWeekStart) {
        const key = getLocalDateString(cursor);
        if (!existing.has(key)) {
            const week = getFocusWeek(cursor, store);
            
            if (week.tasksTotal > 0) {
                rows.push({ ...week, capturedAt: new Date().toISOString() });
            }
        }
        cursor.setDate(cursor.getDate() + 7);
    }

    if (rows.length === 0) return 0;

    store.focusScores = [...(store.focusScores || []), ...rows]
        .sort((a, b) => a.weekStart.localeCompare(b.weekStart));
    saveStore(store);
    return rows.length;
}



function getFocusScoreHistory(store = getStore(), limit = 0) {
    const rows = [...(store.focusScores || [])].sort((a, b) => a.weekStart.localeCompare(b.weekStart));
    return limit > 0 ? rows.slice(-limit) : rows;
}



function focusScoreLine(week) {
    if (!week || week.tasksTotal === 0) return '';
    return `${week.daysExecuted} of ${week.workingDaysTarget} working days · `
        + `${week.tasksDone} of ${week.tasksTotal} tasks · ${week.percent}%`;
}
















