function daily3DaysClearedThisWeek(store = getStore(), today = new Date()) {
    const start = getWeekStart(today, store);
    const todayKey = getLocalDateString(today);
    let days = 0;
    for (let i = 0; i < 7; i++) {
        const d = new Date(start);
        d.setDate(d.getDate() + i);
        const key = getLocalDateString(d);
        const main = ((store.dailyLogs || {})[key] || []).filter(t => t && !t.later);
        if (main.length > 0 && main.every(t => t.done)) days++;
        if (key === todayKey) break;
    }
    return days;
}




























