function percentChange(now, before) {
    const a = Number(now);
    const b = Number(before);
    if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
    if (b === 0) return null;
    return ((a - b) / Math.abs(b)) * 100;
}








function comparable(a, b) {
    if (!a || !b) return { ok: false, reason: 'missing' };
    if (a.isPartial || b.isPartial) return { ok: false, reason: 'partial' };
    return { ok: true, reason: '' };
}

















function groupRows(rows, field, options) {
    const opts = options || {};
    const fallback = opts.fallback || 'Not set';
    
    
    const useChannelKey = Boolean(opts.channelKey);

    const buckets = new Map();
    let total = 0;

    (rows || []).forEach(row => {
        if (!row) return;
        const amount = Number(row.amount) || 0;
        const raw = row[field];
        
        
        
        
        
        
        
        
        
        
        const key = useChannelKey
            ? (row.imported ? null : channelKeyFor(raw))
            : (String(raw || '').trim().toLowerCase() || null);

        const id = key === null ? '' : key;
        
        
        const label = key === null ? fallback : String(raw).trim();

        if (!buckets.has(id)) {
            buckets.set(id, { key: id, label, amount: 0, count: 0, share: 0, unplaced: key === null });
        }
        const bucket = buckets.get(id);
        bucket.amount += amount;
        bucket.count += 1;
        total += amount;
    });

    const out = [...buckets.values()];
    out.forEach(b => { b.share = total > 0 ? (b.amount / total) * 100 : 0; });
    
    
    out.sort((a, b) => (b.amount - a.amount) || a.label.localeCompare(b.label));
    return out;
}


function groupByChannel(rows) {
    return groupRows(rows, 'source', { channelKey: true, fallback: NOT_ATTRIBUTED });
}







function withinRange(rows, range) {
    const from = (range && range.from) ? new Date(range.from) : null;
    const to = (range && range.to) ? new Date(range.to) : null;
    if (to && Number.isFinite(to.getTime())) to.setHours(23, 59, 59, 999);

    const okFrom = from && Number.isFinite(from.getTime()) ? from.getTime() : null;
    const okTo = to && Number.isFinite(to.getTime()) ? to.getTime() : null;

    return (rows || []).filter(row => {
        const t = new Date(row && row.date).getTime();
        if (!Number.isFinite(t)) return false;
        return (okFrom === null || t >= okFrom) && (okTo === null || t <= okTo);
    });
}










function periodComparison(periods) {
    const rows = Array.isArray(periods) ? periods : [];
    if (rows.length < 2) return null;

    const latest = rows[rows.length - 1];
    const previous = rows[rows.length - 2];
    const honest = comparable(latest, previous);

    return {
        latest,
        previous,
        deltaMoney: latest.amount - previous.amount,
        
        
        deltaPercent: honest.ok ? percentChange(latest.amount, previous.amount) : null,
        honest: honest.ok,
        reason: honest.reason
    };
}












function samePeriodLastYear(periods, grain) {
    if (grain !== 'quarter' && grain !== 'month') return null;
    const rows = Array.isArray(periods) ? periods : [];
    if (rows.length === 0) return null;

    const latest = rows[rows.length - 1];
    const before = rows.find(p => p.label === latest.label && p.year === latest.year - 1);
    if (!before) return null;

    const honest = comparable(latest, before);
    return {
        latest,
        previous: before,
        deltaMoney: latest.amount - before.amount,
        deltaPercent: honest.ok ? percentChange(latest.amount, before.amount) : null,
        honest: honest.ok,
        reason: honest.reason
    };
}





function yearToDateComparison(rows, asOf) {
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const dateLike = asOf !== null && typeof asOf === 'object' && typeof asOf.getTime === 'function';
    const now = dateLike ? new Date(asOf.getTime()) : new Date();
    if (!Number.isFinite(now.getTime())) return null;

    const year = now.getFullYear();
    const sum = (fromY) => {
        const start = new Date(fromY, 0, 1).getTime();
        
        const end = new Date(fromY, now.getMonth(), now.getDate(), 23, 59, 59, 999).getTime();
        let total = 0;
        let count = 0;
        (rows || []).forEach(r => {
            const t = new Date(r && r.date).getTime();
            if (!Number.isFinite(t) || t < start || t > end) return;
            total += Number(r.amount) || 0;
            count += 1;
        });
        return { total, count };
    };

    const thisYear = sum(year);
    const lastYear = sum(year - 1);

    
    
    const hasLastYear = lastYear.count > 0;

    return {
        year,
        thisYear,
        lastYear,
        hasLastYear,
        deltaMoney: hasLastYear ? thisYear.total - lastYear.total : null,
        deltaPercent: hasLastYear ? percentChange(thisYear.total, lastYear.total) : null
    };
}



function saleShape(rows) {
    const sales = (rows || []).filter(r => r && Number.isFinite(new Date(r.date).getTime()));
    const total = sales.reduce((n, r) => n + (Number(r.amount) || 0), 0);
    const count = sales.length;

    let biggest = null;
    sales.forEach(r => {
        const amount = Number(r.amount) || 0;
        if (!biggest || amount > biggest.amount) {
            biggest = { amount, date: r.date, offer: r.offer || '', customer: r.customer || r.customerEmail || '' };
        }
    });
    
    
    
    if (biggest && total > 0) biggest.share = (biggest.amount / total) * 100;

    return {
        count,
        total,
        average: count > 0 ? total / count : null,
        biggest
    };
}










function bestAndWorst(periods) {
    const rows = (Array.isArray(periods) ? periods : []);
    const whole = rows.filter(p => p && !p.isPartial);
    if (whole.length < 2) return null;

    let best = rows[0];
    rows.forEach(p => { if (p.amount > best.amount) best = p; });

    let worst = whole[0];
    whole.forEach(p => { if (p.amount < worst.amount) worst = p; });

    if (best === worst) return null;
    return { best, worst, excludedPartials: rows.length - whole.length };
}







function longestQuietStretch(rows) {
    const days = [...new Set(
        (rows || [])
            .map(r => {
                const d = new Date(r && r.date);
                return Number.isFinite(d.getTime()) ? getLocalDateString(d) : null;
            })
            .filter(Boolean)
    )].sort();

    if (days.length < 2) return null;

    let longest = null;
    for (let i = 1; i < days.length; i++) {
        
        
        const a = new Date(days[i - 1] + 'T12:00:00');
        const b = new Date(days[i] + 'T12:00:00');
        const gap = Math.round((b - a) / 86400000) - 1;
        if (gap > 0 && (!longest || gap > longest.days)) {
            longest = { days: gap, from: days[i - 1], to: days[i] };
        }
    }
    return longest;
}






function rowsInPeriod(rows, periodKey, grain, store) {
    if (!periodKey) return [];
    return (rows || []).filter(r => r && calendarKeyFor(r.date, grain, store) === periodKey);
}










function groupWithTrend(allRows, latestRows, previousRows, field, options) {
    const main = groupRows(allRows, field, options);
    const index = (rows) => {
        const map = new Map();
        groupRows(rows, field, options).forEach(r => map.set(r.key, r));
        return map;
    };
    const latest = index(latestRows);
    const previous = index(previousRows);
    const hasPeriods = (latestRows || []).length > 0 || (previousRows || []).length > 0;

    return main.map(row => {
        const now = latest.get(row.key);
        const before = previous.get(row.key);
        const nowAmount = now ? now.amount : 0;
        const beforeAmount = before ? before.amount : 0;

        let status = 'none';
        if (hasPeriods) {
            if (now && !before) status = 'new';
            else if (!now && before) status = 'gone';
            else if (now && before) {
                if (nowAmount > beforeAmount) status = 'up';
                else if (nowAmount < beforeAmount) status = 'down';
                else status = 'flat';
            }
        }

        return Object.assign({}, row, {
            
            
            average: row.count > 0 ? row.amount / row.count : null,
            latestAmount: nowAmount,
            previousAmount: beforeAmount,
            status
        });
    });
}









function leadsByChannel(leadRows) {
    const rows = (leadRows || []).filter(l => l && Number.isFinite(new Date(l.date).getTime()));
    const grouped = groupRows(rows, 'source', { channelKey: true, fallback: NOT_ATTRIBUTED });
    const stamps = rows.map(l => new Date(l.date).getTime());

    return {
        
        
        byChannel: grouped,
        total: grouped.reduce((n, r) => n + r.amount, 0),
        earliest: stamps.length ? new Date(Math.min(...stamps)) : null
    };
}













function focusByPeriod(focusRows, grain, store) {
    const buckets = new Map();

    (focusRows || []).forEach(row => {
        if (!row || !row.weekStart) return;
        const percent = Number(row.percent);
        if (!Number.isFinite(percent)) return;
        const key = calendarKeyFor(row.weekStart, grain, store);
        if (!key) return;
        if (!buckets.has(key)) buckets.set(key, { key, total: 0, weeks: 0 });
        const b = buckets.get(key);
        b.total += percent;
        b.weeks += 1;
    });

    const out = new Map();
    buckets.forEach((b, key) => {
        out.set(key, { key, average: Math.round(b.total / b.weeks), weeks: b.weeks });
    });
    return out;
}










function pausedWeeksByPeriod(store, grain) {
    const out = new Map();

    const place = (startISO, weekNumbers) => {
        const start = new Date(startISO);
        if (!Number.isFinite(start.getTime())) return;
        (weekNumbers || []).forEach(n => {
            const week = Number(n);
            if (!Number.isFinite(week) || week < 1) return;
            const day = new Date(start);
            day.setDate(day.getDate() + (week - 1) * 7);
            const key = calendarKeyFor(day, grain, store);
            if (!key) return;
            out.set(key, (out.get(key) || 0) + 1);
        });
    };

    (Array.isArray(store.pastQuarters) ? store.pastQuarters : []).forEach(q => {
        if (q) place(q.quarterStartDate, q.pausedWeeks);
    });
    place(store.quarterStartDate, store.pausedWeeks);

    return out;
}







function goalAccuracy(quarters) {
    const rows = (quarters || []).filter(q =>
        q && !q.isCurrent && Number(q.goal) > 0 && Number.isFinite(Number(q.revenue))
    );
    if (rows.length < 2) return null;

    const ratios = rows.map(q => Number(q.revenue) / Number(q.goal));
    const average = ratios.reduce((n, r) => n + r, 0) / ratios.length;

    return {
        cycles: rows.length,
        averagePercent: Math.round(average * 100),
        
        
        verdict: average >= 1.5 ? 'too-low' : (average <= 0.5 ? 'too-high' : 'about-right')
    };
}


























function funnelByPeriod(leadRows, metricRows, contactRows, grain, store) {
    const buckets = new Map();
    
    
    const undated = { calls: 0, closes: 0 };

    const at = (date) => {
        const key = calendarKeyFor(date, grain, store);
        if (!key) return null;
        if (!buckets.has(key)) {
            buckets.set(key, { key, leads: 0, calls: 0, closes: 0, traffic: 0, anyClosesLogged: false });
        }
        return buckets.get(key);
    };

    (leadRows || []).forEach(l => {
        const b = at(l && l.date);
        if (!b) return;
        b.leads += parseFloat(l.amount) || 0;
        b.calls += parseFloat(l.calls) || 0;
        const closes = parseFloat(l.closes) || 0;
        b.closes += closes;
        if (closes > 0) b.anyClosesLogged = true;
    });

    (metricRows || []).forEach(m => {
        const b = at(m && m.date);
        if (!b) return;
        b.traffic += parseFloat(m.traffic) || 0;
        
        
        b.calls += parseFloat(m.calls) || 0;
        const closes = parseFloat(m.closes) || 0;
        b.closes += closes;
        if (closes > 0) b.anyClosesLogged = true;
    });

    (contactRows || []).forEach(c => {
        if (!c) return;
        
        
        if (!c.countedInLeads) {
            const b = at(c.createdAt);
            if (b) b.leads += 1;
        }
        const callAt = c.reached && c.reached['call-booked'];
        if (callAt) {
            const b = at(callAt);
            if (b) b.calls += 1; else undated.calls += 1;
        } else if (c.stage && c.stage !== 'lead') {
            undated.calls += 1;
        }
        if (c.stage === 'won') {
            const wonAt = (c.reached && c.reached.won) || null;
            const b = wonAt ? at(wonAt) : null;
            if (b) { b.closes += 1; b.anyClosesLogged = true; }
            else undated.closes += 1;
        }
    });

    const out = new Map();
    buckets.forEach((b, key) => {
        out.set(key, Object.assign({}, b, {
            
            
            
            callCloseRate: (b.calls > 0 && b.anyClosesLogged)
                ? (Math.min(b.closes, b.calls) / b.calls) * 100
                : null,
            leadToSale: (b.leads > 0 && b.anyClosesLogged)
                ? (Math.min(b.closes, b.leads) / b.leads) * 100
                : null
        }));
    });

    return { byPeriod: out, undated };
}













function audienceByPeriod(metricRows, grain, store, socialOf, emailOf) {
    const buckets = new Map();

    (metricRows || []).forEach(m => {
        if (!m) return;
        const stamp = new Date(m.date).getTime();
        if (!Number.isFinite(stamp)) return;
        const key = calendarKeyFor(m.date, grain, store);
        if (!key) return;
        if (!buckets.has(key)) {
            buckets.set(key, { key, traffic: 0, social: null, socialAt: 0, emailSent: 0, emailOpens: 0, subscribers: null, subscribersAt: 0 });
        }
        const b = buckets.get(key);
        b.traffic += parseFloat(m.traffic) || 0;

        
        const social = socialOf ? socialOf(m) : null;
        if (social && stamp >= b.socialAt) {
            b.social = social.total;
            b.socialAt = stamp;
            
            
            
            
            
            
            
            const list = (social.split || []).find(x => x.key === 'email');
            b.subscribers = list ? list.value : null;
            b.subscribersAt = stamp;
        }

        const email = emailOf ? emailOf(m) : null;
        if (email) {
            
            b.emailSent += email.sent;
            b.emailOpens += email.opens;
            
        }
    });

    const out = new Map();
    buckets.forEach((b, key) => {
        out.set(key, Object.assign({}, b, {
            openRate: b.emailSent > 0 ? (b.emailOpens / b.emailSent) * 100 : null
        }));
    });
    return out;
}


















function moneyOf(currency, n) {
    return currency + Math.round(n).toLocaleString();
}

function yearVerdict(input) {
    const i = input || {};
    const currency = i.currency || '$';
    const ytd = i.ytd;
    const shape = i.shape;
    if (!ytd || !shape || shape.count === 0) return null;

    const money = (n) => moneyOf(currency, n);
    const points = [];

    
    
    let headline;
    if (!ytd.hasLastYear) {
        headline = `${ytd.year} so far: ${money(ytd.thisYear.total)} from ${ytd.thisYear.count} ${ytd.thisYear.count === 1 ? 'sale' : 'sales'}. There is no earlier year to measure it against, so this is the baseline the next one gets compared with.`;
    } else {
        const up = ytd.deltaMoney >= 0;
        const pct = ytd.deltaPercent === null ? '' : ` (${up ? 'up' : 'down'} ${Math.abs(Math.round(ytd.deltaPercent))}%)`;
        const base = `${ytd.year} is ${up ? 'ahead of' : 'behind'} last year: ${money(ytd.thisYear.total)} against ${money(ytd.lastYear.total)} by the same date${pct}.`;

        
        
        const better = [];
        if (!up && i.lastShape) {
            if (shape.average !== null && i.lastShape.average !== null && shape.average > i.lastShape.average) {
                better.push(`your average sale is bigger (${money(shape.average)} against ${money(i.lastShape.average)})`);
            }
            if (shape.biggest && i.lastShape.biggest &&
                shape.biggest.share !== undefined && i.lastShape.biggest.share !== undefined &&
                shape.biggest.share < i.lastShape.biggest.share - 5) {
                better.push('less of it is riding on one sale');
            }
            if (i.quiet && i.lastQuiet && i.quiet.days < i.lastQuiet.days) {
                better.push(`your longest quiet stretch is shorter (${i.quiet.days} days against ${i.lastQuiet.days})`);
            }
        }

        headline = better.length > 0
            ? `${base} ⚠️ That is not the whole story: ${better.join(', and ')}. A smaller year built on steadier ground is not a worse year.`
            : base;
    }

    
    
    if (ytd.hasLastYear && ytd.lastYear.count > 0) {
        const nowAvg = ytd.thisYear.count > 0 ? ytd.thisYear.total / ytd.thisYear.count : 0;
        const thenAvg = ytd.lastYear.total / ytd.lastYear.count;
        const moreSales = ytd.thisYear.count > ytd.lastYear.count;
        const biggerSales = nowAvg > thenAvg;
        if (moreSales && biggerSales) {
            points.push(`You are selling more often AND for more: ${ytd.thisYear.count} sales at ${money(nowAvg)} on average, against ${ytd.lastYear.count} at ${money(thenAvg)}.`);
        } else if (moreSales) {
            points.push(`That came from selling more often rather than for more: ${ytd.thisYear.count} sales against ${ytd.lastYear.count}, at a similar or smaller average.`);
        } else if (biggerSales) {
            points.push(`That came from bigger sales rather than more of them: ${money(nowAvg)} on average against ${money(thenAvg)}, from fewer sales.`);
        }
    }

    
    
    if (i.extremes) {
        points.push(`${i.extremes.best.title} carried it at ${money(i.extremes.best.amount)}; ${i.extremes.worst.title} was the quietest at ${money(i.extremes.worst.amount)}.`);
    }

    
    
    const realOffers = (i.offers || []).filter(o => !o.unplaced);
    if (realOffers.length > 0) {
        const top = realOffers[0];
        const stopped = realOffers.filter(o => o.status === 'gone');
        points.push(`${top.label} earned the most at ${money(top.amount)}${stopped.length > 0 ? `, while ${stopped.map(o => o.label).join(' and ')} sold nothing in the latest period` : ''}.`);
    }

    
    
    const realChannels = (i.channels || []).filter(c => !c.unplaced);
    if (realChannels.length > 0) {
        const top = realChannels[0];
        points.push(`Of the money you can trace, ${top.label} brought the most at ${money(top.amount)}.`);
    }

    
    if (i.audience && i.audience.audienceUp && !i.audience.moneyUp) {
        points.push(`Your following grew while the money did not, which usually points at the offer or the asking rather than at being seen.`);
    }
    if (i.consistency && i.consistency.matched) {
        points.push(`Your best period for money was also your most consistent.`);
    }

    
    
    
    let oneThing;
    const unattributedShare = (i.quality && i.quality.total > 0)
        ? (i.quality.notAttributed.amount / i.quality.total) * 100
        : 0;

    if (unattributedShare >= 40) {
        oneThing = `Name your products in your payment processor, and pick a Source when you log a sale by hand. ${Math.round(unattributedShare)}% of this year cannot be traced to an offer or a channel, so most of this report is describing money it cannot place.`;
    } else if (shape.biggest && shape.biggest.share >= 40) {
        oneThing = `Spread the risk. ${Math.round(shape.biggest.share)}% of this came from one sale, which makes the year look stronger than the pattern underneath it.`;
    } else if (i.quiet && i.quiet.days >= 21) {
        oneThing = `Shorten the gaps. Your longest run with no sale at all was ${i.quiet.days} days, and closing that is usually worth more than one big month.`;
    } else if (i.audience && i.audience.audienceUp && !i.audience.moneyUp) {
        oneThing = `Work on the offer and the asking rather than on being seen. The audience is already growing; the money is not following it.`;
    } else if (i.leadsUnknown) {
        oneThing = `Log your leads with a source. Your revenue history goes back further than your lead records, so nothing here can yet tell you which channel is actually worth your time.`;
    } else {
        oneThing = `Keep the record straight. The more consistently you name offers and sources, the more this page can tell you next year.`;
    }

    return { headline, points, oneThing };
}











function recurringSplit(rows) {
    let recurring = 0;
    let oneOff = 0;
    let unknown = 0;
    let recurringCount = 0;

    (rows || []).forEach(r => {
        if (!r) return;
        const amount = Number(r.amount) || 0;
        if (r.recurring === true) { recurring += amount; recurringCount += 1; }
        else if (r.recurring === false) { oneOff += amount; }
        else { unknown += amount; }
    });

    const known = recurring + oneOff;
    return {
        recurring,
        recurringCount,
        oneOff,
        unknown,
        
        
        recurringShare: known > 0 ? (recurring / known) * 100 : null
    };
}





















function withCustomerKey(rows) {
    return (rows || []).map(r => {
        if (!r) return r;
        const typed = String(r.customer || '').trim();
        const email = String(r.customerEmail || '').trim();
        return Object.assign({}, r, { customerLabel: typed || email || '' });
    });
}


function customerShape(groupedCustomers) {
    const rows = (groupedCustomers || []).filter(c => !c.unplaced);
    const unidentified = (groupedCustomers || []).find(c => c.unplaced) || null;

    const returning = rows.filter(c => c.count >= 2);
    const identifiedRevenue = rows.reduce((n, c) => n + c.amount, 0);

    return {
        customers: rows.length,
        returning: returning.length,
        
        
        repeatRate: rows.length > 0 ? (returning.length / rows.length) * 100 : null,
        perCustomer: rows.length > 0 ? identifiedRevenue / rows.length : null,
        identifiedRevenue,
        unidentifiedRevenue: unidentified ? unidentified.amount : 0,
        unidentifiedCount: unidentified ? unidentified.count : 0
    };
}








function profitByPeriod(saleRows, expenseRows, grain, store) {
    const out = new Map();

    const bucket = (key) => {
        if (!out.has(key)) {
            out.set(key, { key, revenue: 0, costs: 0, costCount: 0, fees: 0, feeCount: 0 });
        }
        return out.get(key);
    };

    (saleRows || []).forEach(r => {
        const key = calendarKeyFor(r && r.date, grain, store);
        if (!key) return;
        const b = bucket(key);
        b.revenue += Number(r.amount) || 0;
        
        
        
        
        if (r.fee !== null && r.fee !== undefined && Number.isFinite(Number(r.fee))) {
            b.fees += Number(r.fee);
            b.feeCount += 1;
        }
    });

    (expenseRows || []).forEach(e => {
        const key = calendarKeyFor(e && e.date, grain, store);
        if (!key) return;
        const b = bucket(key);
        b.costs += Number(e.amount) || 0;
        b.costCount += 1;
    });

    const result = new Map();
    out.forEach((b, key) => {
        
        
        const hasCosts = b.costCount > 0 || b.feeCount > 0;
        const outgoing = b.costs + b.fees;
        result.set(key, Object.assign({}, b, {
            hasCosts,
            outgoing,
            net: hasCosts ? b.revenue - outgoing : null,
            margin: (hasCosts && b.revenue > 0) ? ((b.revenue - outgoing) / b.revenue) * 100 : null
        }));
    });
    return result;
}










function revenueQuality(rows) {
    const out = {
        total: 0,
        count: 0,
        
        
        
        uncounted: { count: 0, currencies: [] },
        
        
        refunded: { count: 0, amount: 0 },
        
        
        
        duplicatePairs: 0,
        
        
        notAttributed: { count: 0, amount: 0 }
    };

    const currencies = new Set();

    (rows || []).forEach(row => {
        if (!row) return;
        const amount = Number(row.amount) || 0;
        out.total += amount;
        out.count += 1;

        if (row.needsRate) {
            out.uncounted.count += 1;
            if (row.originalCurrency) currencies.add(String(row.originalCurrency).toUpperCase());
        }
        if (row.refunded) {
            out.refunded.count += 1;
            out.refunded.amount += Number(row.grossAmount) || 0;
        }
        
        
        if (row.possibleDuplicate && row.imported) {
            out.duplicatePairs += 1;
        }
        
        
        
        
        
        if (row.imported || channelKeyFor(row.source) === null) {
            out.notAttributed.count += 1;
            out.notAttributed.amount += amount;
        }
    });

    out.uncounted.currencies = [...currencies].sort();
    return out;
}






function qualityNotes(quality, currency) {
    const notes = [];
    if (!quality) return notes;
    const money = (n) => currency + Math.round(n).toLocaleString();

    if (quality.uncounted.count > 0) {
        const list = quality.uncounted.currencies;
        const named = list.length === 0
            ? 'another currency'
            : (list.length === 1
                ? list[0]
                : list.slice(0, -1).join(', ') + ' and ' + list[list.length - 1]);
        notes.push(`${quality.uncounted.count} ${quality.uncounted.count === 1 ? 'sale is' : 'sales are'} missing from this, because ${named} has no exchange rate set. Add one in Settings and they will count.`);
    }

    if (quality.refunded.count > 0) {
        notes.push(`${quality.refunded.count} refunded ${quality.refunded.count === 1 ? 'payment is' : 'payments are'} shown as zero here. ${money(quality.refunded.amount)} came in and went back out.`);
    }

    if (quality.duplicatePairs > 0) {
        notes.push(`${quality.duplicatePairs} ${quality.duplicatePairs === 1 ? 'sale looks' : 'sales look'} like the same sale logged twice, once by hand and once by your payment processor. Both are counted until you settle them on the Revenue screen.`);
    }

    if (quality.notAttributed.amount > 0 && quality.total > 0) {
        const share = (quality.notAttributed.amount / quality.total) * 100;
        
        if (share >= 5) {
            notes.push(`${money(quality.notAttributed.amount)} of this has no channel on it, which is most often imported payments. Where a sale came from is not something your processor knows.`);
        }
    }

    return notes;
}













function coverage(store, key) {
    const archives = Array.isArray(store && store.pastQuarters) ? store.pastQuarters : [];
    const withData = archives.filter(q => q && Array.isArray(q[key]) && q[key].length > 0);

    const starts = withData
        .map(q => q.quarterStartDate)
        .filter(Boolean)
        .sort();

    return {
        cycles: withData.length,
        earliest: starts.length ? starts[0] : (store && store.quarterStartDate) || '',
        
        onlyLive: withData.length === 0
    };
}

function coverageNote(cov, thing) {
    if (!cov) return '';
    const noun = thing || 'this';
    if (cov.onlyLive) {
        return `Covers your current 90 days only. Earlier cycles were not archived, so ${noun} before then is unknown rather than zero.`;
    }
    const when = cov.earliest
        ? new Date(cov.earliest).toLocaleDateString(undefined, { month: 'long', year: 'numeric' })
        : '';
    return `Covers ${cov.cycles + 1} cycles${when ? `, back to ${when}` : ''}.`;
}






































const SESSION_KEY = 'ceo_usage_session';









const ROUTE_SHAPE = /^#\/[a-z-]{0,40}$/;




const EVENT_SHAPE = /^[a-z0-9_.:-]{1,48}$/;




let disabledForThisPage = false;



let cachedUserId = null;




let lastScreen = null;
let lastScreenAt = 0;












function usageTrackingOn() {
    try {
        if (localStorage.getItem('ceo_auth') !== 'true') return false;
        const store = getStore();
        return !(store && store.settings && store.settings.shareUsage === false);
    } catch (err) {
        
        
        return false;
    }
}





function usageSessionId() {
    try {
        let id = sessionStorage.getItem(SESSION_KEY);
        if (id) return id;
        
        
        
        id = (window.crypto && typeof window.crypto.randomUUID === 'function')
            ? window.crypto.randomUUID()
            : 's' + Date.now().toString(36) + Math.random().toString(36).slice(2, 10);
        sessionStorage.setItem(SESSION_KEY, id);
        return id;
    } catch (err) {
        return null;
    }
}




function usageEventNameOk(event) {
    return EVENT_SHAPE.test(String(event || ''));
}


function usageScreenName(path) {
    const raw = String(path || '').split('?')[0].split('&')[0].trim();
    if (!raw) return null;
    if (raw === '#' || raw === '#/') return '#/';
    return ROUTE_SHAPE.test(raw) ? raw : '#/other';
}



function appVersion() {
    try {
        const el = document.querySelector('script[src*="bundle.js"]');
        const match = el && String(el.getAttribute('src') || '').match(/\?v=(\d+)/);
        return match ? match[1] : null;
    } catch (err) {
        return null;
    }
}

async function currentUserId() {
    if (cachedUserId) return cachedUserId;
    try {
        const { data } = await window.db.auth.getSession();
        const user = data && data.session && data.session.user;
        cachedUserId = user ? user.id : null;
        return cachedUserId;
    } catch (err) {
        return null;
    }
}



function forgetUsageIdentity() {
    cachedUserId = null;
    lastScreen = null;
    lastScreenAt = 0;
    disabledForThisPage = false;
    try {
        sessionStorage.removeItem(SESSION_KEY);
    } catch (err) {
        
    }
}








async function trackEvent(event, { screen = null, detail = null } = {}) {
    if (disabledForThisPage) return false;
    if (!usageEventNameOk(event)) return false;
    if (!usageTrackingOn()) return false;
    if (!window.db) return false;

    const userId = await currentUserId();
    if (!userId) return false;

    try {
        const { error } = await window.db.from('usage_events').insert({
            user_id: userId,
            event: event,
            screen: screen ? usageScreenName(screen) : null,
            
            
            detail: detail ? String(detail).slice(0, 64) : null,
            app_version: appVersion(),
            session_id: usageSessionId()
        });

        if (error) {
            
            
            
            if (error.code === '42P01' || error.code === '42501') {
                disabledForThisPage = true;
            }
            
            
            console.debug('Usage event not recorded:', error.message);
            return false;
        }
    } catch (err) {
        
        
        return false;
    }

    return true;
}


function trackScreen(path) {
    const screen = usageScreenName(path);
    if (!screen) return;

    const now = Date.now();
    if (screen === lastScreen && (now - lastScreenAt) < 1000) return;
    lastScreen = screen;
    lastScreenAt = now;

    trackEvent('screen', { screen: screen });
}



function trackAction(event, detail = null) {
    trackEvent(event, { screen: window.location.hash || '#/', detail: detail });
}































