function resolveBusinessModel(raw) {
    const stored = String(raw == null ? '' : raw).trim();
    if (FUNNEL_MODELS[stored]) return { key: stored, stored, assumed: false };
    const alias = BUSINESS_MODEL_ALIASES[stored.toLowerCase()];
    if (alias) return { key: alias, stored, assumed: false };
    return { key: 'Other', stored, assumed: true };
}

function funnelModelFor(businessModel) {
    return FUNNEL_MODELS[resolveBusinessModel(businessModel).key];
}









function modelAssumptionNote(math) {
    if (!math || !math.modelAssumed) return '';
    return math.businessModelStored
        ? `These figures assume a general funnel, because "${math.businessModelStored}" is not one of the business models this works from. Choosing the closest one makes the numbers fit your business.`
        : 'These figures assume a general funnel, because your business model is not set. Choosing one makes the numbers fit your business.';
}












