function evidenceBand(profile) {
    const sold = (profile && profile.soldBefore) || '';
    const audience = (profile && profile.audienceSize) || '';

    if (!sold && !audience) return 'warm'; 

    const soldNothing = !sold || sold === 'Never';
    const noAudience = !audience || audience === 'None yet';
    if (soldNothing && noAudience) return 'cold';

    const sellsRegularly = sold === 'Regularly';
    const realAudience = audience === 'A few hundred' || audience === 'Over a thousand';
    if (sellsRegularly || realAudience) return 'established';

    return 'warm';
}




const BAND_REASON = {
    cold: 'no audience and no sales yet, so the conservative end',
    warm: 'some evidence on one side — a small audience, or a few sales — so the middle of three bands',
    established: 'she sells regularly or reaches an audience in the hundreds, so the top of three bands'
};











function getGoalMath(store, overrides = {}) {
    const profile = (store && store.profile) || {};
    
    
    
    
    
    
    const businessModel = overrides.businessModel || profile.businessModel || '';
    const currency = overrides.currency || (store && store.settings && store.settings.currency) || '$';
    const storedRevenueGoal = (store && store.revenue && store.revenue.quarterlyGoal) || 0;
    const storedPrice = (store && store.revenue && store.revenue.averageOfferPrice) || 0;
    const storedLeadGoal = (store && store.leads && store.leads.quarterlyGoal) || 0;
    const revenueGoal = Number(overrides.revenueGoal !== undefined ? overrides.revenueGoal : storedRevenueGoal) || 0;
    const price = Number(overrides.averageOfferPrice !== undefined ? overrides.averageOfferPrice : storedPrice) || 0;
    const leadGoal = Number(overrides.leadGoal !== undefined ? overrides.leadGoal : storedLeadGoal) || 0;
    const overrideDays = Number(overrides.workingDays);
    const workingDays = (Number.isFinite(overrideDays) && overrideDays > 0) ? overrideDays : workingDaysTarget(store);

    
    
    
    
    
    const resolved = resolveBusinessModel(businessModel);
    const funnel = FUNNEL_MODELS[resolved.key];
    const band = evidenceBand(profile);
    
    
    
    
    const rate = band === 'cold' ? funnel.rateCold
        : band === 'established' ? (funnel.rateEstablished || funnel.rateWarm)
        : funnel.rateWarm;
    
    
    const cold = band === 'cold';

    const known = revenueGoal > 0 && price > 0;
    const salesRequired = known ? Math.ceil(revenueGoal / price) : null;

    
    const unitsRequired = known ? Math.ceil(salesRequired / rate) : null;
    const unitsPerWeek = known ? Math.ceil(unitsRequired / WEEKS_IN_QUARTER) : null;

    
    
    
    
    
    const oddsDenominator = known ? Math.max(2, Math.round(1 / rate)) : null;

    
    
    
    
    
    const salesPerWeek = known ? salesRequired / WEEKS_IN_QUARTER : null;
    const weeksBetweenSales = (known && salesRequired > 1 && salesPerWeek < 1)
        ? Math.round(WEEKS_IN_QUARTER / salesRequired)
        : null;
    const salesEachWeek = (known && salesPerWeek >= 1) ? Math.round(salesPerWeek) : null;

    
    

    const audienceHead = AUDIENCE_HEADCOUNT[profile.audienceSize];
    const leadsPerWeek = leadGoal > 0 ? Math.ceil(leadGoal / WEEKS_IN_QUARTER) : 0;

    return {
        known, currency, workingDays,
        businessModel: resolved.key,
        businessModelStored: resolved.stored,
        modelAssumed: resolved.assumed,
        revenueGoal, price, salesRequired,
        unit: funnel.unit, unitPlural: funnel.unitPlural, lever: funnel.lever,
        unitIsLead: funnel.unitIsLead === true,
        unitLeadShort: funnel.unitLeadShort || funnel.unitPlural,
        unitLeadGloss: funnel.unitLeadGloss || null,
        oddsLead: funnel.oddsLead || 'Not everyone you speak to will buy.',
        rate, ratePercent: Math.round(rate * 1000) / 10, cold, band,
        bandReason: BAND_REASON[band],
        unitsRequired, unitsPerWeek, oddsDenominator,
        weeksBetweenSales, salesEachWeek,
        audienceHead: audienceHead === undefined ? null : audienceHead,
        leadGoal, leadsPerWeek
    };
}

function moneyText(currency, n) {
    return currency + Math.round(n).toLocaleString();
}


















































const HAND_TOUCHES_PER_DAY = 4;

function nicePrice(n) {
    if (!(n > 0)) return 0;
    const step = n < 100 ? 10 : n < 1000 ? 25 : 100;
    return Math.ceil(n / step) * step;
}

function priceVolumeNote(math) {
    if (!math || !math.known || !math.unitIsLead) return '';
    if (!(math.unitsRequired > 0) || !(math.price > 0) || !(math.rate > 0)) return '';

    
    
    
    const handBudget = math.workingDays * HAND_TOUCHES_PER_DAY * WEEKS_IN_QUARTER;
    if (!(handBudget > 0) || math.unitsRequired <= handBudget) return '';

    const priceNeeded = nicePrice(math.revenueGoal / (handBudget * math.rate));
    if (!Number.isFinite(priceNeeded) || priceNeeded <= math.price) return '';

    const thenUnits = Math.ceil(math.revenueGoal / priceNeeded / math.rate);
    if (!(thenUnits > 0) || thenUnits >= math.unitsRequired) return '';

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    return `At her current price of ${moneyText(math.currency, math.price)}, the ${moneyText(math.currency, math.revenueGoal)} goal needs about ${math.unitsRequired.toLocaleString()} ${math.unitLeadShort} across the 90 days. At ${moneyText(math.currency, priceNeeded)} the same goal would need about ${thenUnits.toLocaleString()}.`;
}

function goalMathSentences(math) {
    if (!math || !math.known) return [];
    const s = [];
    s.push(`That is ${math.salesRequired} sale${math.salesRequired === 1 ? '' : 's'} at ${moneyText(math.currency, math.price)} to reach ${moneyText(math.currency, math.revenueGoal)}.`);
    s.push(`${math.oddsLead} If about 1 in ${math.oddsDenominator} do, that is around ${math.unitsRequired.toLocaleString()} ${math.unitLeadShort} across the 90 days${math.unitLeadGloss ? `, ${math.unitLeadGloss}` : ''}.`);
    if (math.weeksBetweenSales) {
        s.push(`That works out at about one sale every ${math.weeksBetweenSales} weeks.`);
    } else if (math.salesEachWeek) {
        s.push(`That works out at about ${math.salesEachWeek} sale${math.salesEachWeek === 1 ? '' : 's'} a week.`);
    }
    s.push(`Your plan will build the systems that bring those in, so the volume does not all rest on your own hours.`);
    return s;
}




















function leadGoalNote(math) {
    if (!math || !math.known || !math.unitIsLead) return '';
    if (!(math.leadGoal > 0) || !(math.unitsRequired > 0)) return '';
    if (math.leadGoal >= math.unitsRequired) {
        return `That covers the ${math.unitsRequired.toLocaleString()} leads this revenue target needs.`;
    }
    return `Your revenue target needs about ${math.unitsRequired.toLocaleString()} leads, and this asks for ${math.leadGoal.toLocaleString()}. Your plan is built to produce the number in this box, so it is worth raising.`;
}





function goalMathPromptBlock(math) {
    if (!math || !math.known) {
        return `THE ARITHMETIC: she has not set both a revenue goal and an offer price, so the sales target cannot be computed. Do NOT assert that the goal is achievable. Say plainly in the calibration that the numbers needed to check it are missing, and name which ones.`;
    }
    const lines = [
        'THE ARITHMETIC (computed by the app, not by you — these are facts, do not recompute or contradict them):',
        `- Sales required in these 90 days: ${math.salesRequired} at ${moneyText(math.currency, math.price)} each.`,
        
        
        
        
        
        
        math.modelAssumed
            ? `- ⚠️ HER BUSINESS MODEL IS NOT SET${math.businessModelStored ? ` ("${math.businessModelStored}" is not one of the models this app works from)` : ''}, so the unit of effort below — ${math.unitPlural} — and the conversion rate are a GENERIC ASSUMPTION, not her answer. Say so plainly in the calibration, in one sentence, and say that choosing a business model in Settings would make these figures fit her business. Do not present the volume as a fact about her market.`
            : `- Her business model is ${math.businessModel}, so the unit of effort is ${math.unitPlural} — ${math.lever}.`,
        `- Assumed conversion rate: ${math.ratePercent}% (${math.bandReason}).`,
        `- Therefore about ${math.unitsRequired.toLocaleString()} ${math.unitPlural} are needed across 12 weeks — roughly ${math.unitsPerWeek.toLocaleString()} a week.`,
        `- She works ${math.workingDays} day${math.workingDays === 1 ? '' : 's'} a week. That sets how much SHE can do each week, not how many ${math.unitPlural} her business can produce.`
    ];
    
    
    
    
    
    
    if (math.audienceHead !== null && math.audienceHead !== undefined) {
        lines.push(math.audienceHead > 0
            ? `- Audience she can already reach: at least ${math.audienceHead.toLocaleString()} people (the bottom of the band she chose, so treat it as a floor, not a measurement). Anything you plan that uses this audience is real, not an invention.`
            : `- Audience she can already reach: none. Every action that needs an audience has to borrow someone else's.`);
    }
    if (math.leadGoal > 0) {
        lines.push(`- Her lead goal is ${math.leadGoal}, which is about ${math.leadsPerWeek} new leads a week. A lead is a person who has given their contact details and can be reached again, not a follower and not a view.`);
    }
    lines.push('');
    lines.push('WHAT YOU MUST DO WITH THE ARITHMETIC. This outranks rule 1 and it is not optional:');
    lines.push(`A. THE WEEKLY VOLUME IN YOUR PLAN MUST RECONCILE WITH THE SALES TARGET. Add up the ${math.unitPlural} your twelve weeks actually ask for. If they do not multiply out at the stated rate to the sales required, the plan does not reach the goal, and you must say that rather than asserting the opposite. A plan that asks for 23 conversations and promises 12 sales is claiming a 52% close rate; that is the exact failure this rule exists to stop. In the calibration, give the NUMBER of ${math.unitPlural} a week this plan expects to be reaching by month 3, and say in plain words whether twelve weeks on that curve add up to the ${math.unitsRequired.toLocaleString()} needed. "It ramps up as your systems grow" without a number is not an answer.`);
    lines.push(`B. STATE THE ASSUMED RATE IN THE CALIBRATION so she can disagree with it. Name the ${math.ratePercent}% and what it means in plain words.`);
    
    
    
    
    
    
    lines.push(`C. ⚠️ DO NOT CAP THE VOLUME BY HER HOURS. Never judge ${moneyText(math.currency, math.revenueGoal)} against how many ${math.unitPlural} she could produce by hand in the days she works, and never substitute a smaller "realistic" revenue figure for her goal. Build this plan to ${moneyText(math.currency, math.revenueGoal)}. The way ${math.unitsPerWeek.toLocaleString()} ${math.unitPlural} a week becomes possible on ${math.workingDays} day${math.workingDays === 1 ? '' : 's'} is SYSTEMS that keep producing without her (capture, automation, referral partners, other people's audiences, content that keeps working), built early and ramping, so the weekly volume grows across the 90 days rather than starting at full pace in week 1. Her working days limit the hands-on tasks you give her each week, never the volume the systems can bring in. If your twelve weeks still cannot add up to the sales required, rule A applies: say so plainly, name what would close the gap (a system that produces more volume, a higher price, or a warmer audience), and never tell her the goal is wrong or that she should lower it.`);
    
    
    
    
    
    
    const touchBudget = math.workingDays * 4;
    lines.push(`D. ⚠️ HER HANDS-ON BUDGET IS ${touchBudget} A WEEK, because she works ${math.workingDays} day${math.workingDays === 1 ? '' : 's'}. Add up every person she must contact and every piece she must create or post in a week's revenue, visibility and follow-up actions together: it may NOT exceed ${touchBudget}. A founder working fewer days gets visibly fewer asks each week than one working more, never the same and never more. When the volume the arithmetic needs is bigger than this budget, the gap is closed by the systems in the build plan, not by asking for more of her time.`);
    return lines.join('\n');
}




















function goalBreakdownLine(revenueGoal, currency) {
    const goal = Number(revenueGoal) || 0;
    
    
    if (goal <= 0) return '';
    const symbol = currency || '$';
    const perMonth = Math.round(goal / 3);
    const perWeek = Math.round(goal / WEEKS_IN_QUARTER);
    
    return `${moneyText(symbol, goal)} in 90 days — about ${moneyText(symbol, perMonth)} a month, or ${moneyText(symbol, perWeek)} a week.`;
}















function focusCurrencyMismatch(focusText, currency) {
    const text = String(focusText || '');
    if (!text) return null;
    const symbol = currency || '$';
    const found = [];
    const re = /(A\$|C\$|[£€$])\s?\d/g;
    let m;
    while ((m = re.exec(text)) !== null) {
        if (m[1] !== symbol && found.indexOf(m[1]) === -1) found.push(m[1]);
    }
    return found.length ? found[0] : null;
}



function focusCurrencyLine(focusText, currency) {
    const other = focusCurrencyMismatch(focusText, currency);
    if (!other) return '';
    return `Your 90-day focus is written in ${other} while this app is set to ${currency || '$'}. Nothing to fix if you meant it, but your coach will quote both.`;
}




























function canConnectStripe() {
    if (!isProUser()) return false;
    return isFeatureLive('payment-import') || localStorage.getItem('ceo_stripe_preview') === '1';
}



















function applyStripePreviewParam() {
    const match = /[?&]stripe_preview=([01])/.exec(window.location.search);
    if (!match) return;

    if (match[1] === '1') {
        localStorage.setItem('ceo_stripe_preview', '1');
    } else {
        localStorage.removeItem('ceo_stripe_preview');
    }

    const cleaned = window.location.search
        .replace(/[?&]stripe_preview=[01]/, '')
        .replace(/^&/, '?');
    window.history.replaceState({}, '', window.location.pathname + (cleaned === '?' ? '' : cleaned) + window.location.hash);
}








