const TRIAL_COUNTDOWN_DAYS = 30;

















function showTrialCountdown() {
    if (!isProTrial()) return false;
    const left = trialDaysLeft();
    if (left === null) return false;
    return left <= TRIAL_COUNTDOWN_DAYS;
}


function trialDaysLeft() {
    const endsAt = localStorage.getItem('ceo_trial_ends_at');
    if (!endsAt) return null;
    const ms = new Date(endsAt).getTime() - Date.now();
    if (Number.isNaN(ms)) return null;
    return Math.max(0, Math.ceil(ms / 86400000));
}
















function trialTimeLeftPhrase() {
    const endsAt = localStorage.getItem('ceo_trial_ends_at');
    if (!endsAt) return null;
    const ms = new Date(endsAt).getTime() - Date.now();
    if (Number.isNaN(ms)) return null;

    
    
    if (ms <= 0) return null;

    const hours = ms / 3600000;
    
    
    
    if (hours >= 48) return `${Math.round(hours / 24)} days`;
    if (hours >= 24) return '1 day';
    if (hours >= 2) return `${Math.floor(hours)} hours`;
    if (hours >= 1) return '1 hour';
    return 'less than an hour';
}


















function trialTimeLeftClause() {
    const phrase = trialTimeLeftPhrase();
    if (phrase === null) return null;
    
    return phrase === 'less than an hour' ? phrase : `another ${phrase}`;
}














function trialEndDateText() {
    const endsAt = localStorage.getItem('ceo_trial_ends_at');
    if (!endsAt) return null;
    const end = new Date(endsAt);
    if (Number.isNaN(end.getTime())) return null;
    
    
    
    
    
    
    
    
    
    
    const opts = { month: 'short', day: 'numeric' };
    if (end.getFullYear() !== new Date().getFullYear()) opts.year = 'numeric';
    return end.toLocaleDateString(undefined, opts);
}











function periodEndDateText() {
    const endsAt = localStorage.getItem('ceo_current_period_end');
    if (!endsAt) return null;
    const end = new Date(endsAt);
    if (Number.isNaN(end.getTime())) return null;
    const opts = { month: 'short', day: 'numeric' };
    if (end.getFullYear() !== new Date().getFullYear()) opts.year = 'numeric';
    return end.toLocaleDateString(undefined, opts);
}



























function subscriptionChangeNotice() {
    const date = periodEndDateText();
    const cancelling = localStorage.getItem('ceo_cancel_at_period_end') === 'true';
    const pending = localStorage.getItem('ceo_pending_plan_tier');

    if (cancelling) {
        return {
            tone: 'ending',
            
            
            
            text: date
                ? `Your subscription is cancelled and ends on ${date}. Nothing changes before then — you keep everything you have until that date.`
                : 'Your subscription is cancelled and ends when your current billing period does. Nothing changes before then.'
        };
    }

    if (pending === 'base' || pending === 'pro') {
        const name = pending === 'pro' ? 'Pro' : 'Base';
        const now = getPlanTier() === 'pro' ? 'Pro' : 'Base';
        return {
            tone: 'changing',
            text: date
                ? `You are moving to ${name} on ${date}. You keep ${now} until then.`
                : `You are moving to ${name} at the end of your current billing period.`
        };
    }

    if (date) {
        return { tone: 'renewing', text: `Your plan renews on ${date}.` };
    }

    return null;
}







