async function fetchReflectionPatterns(reviews) {
    const recent = (reviews || []).slice(-4);
    if (recent.length < 2) return null;

    const system = `You are reading a solo founder her own weekly reviews back to her, at the top of the monthly strategy review she is about to write. The point is that she plans next month from what actually happened rather than from memory.

${VOICE_RULES}

Return JSON in exactly this shape and nothing else:
{"worked":"...","bottleneck":"..."}

Rules:
- "worked" names the pattern across these weeks that genuinely moved things forward.
- "bottleneck" names the one thing that keeps getting in the way. One thing, the one she would get the most back from clearing.
- READ WHAT SHE MEANT, never which words appeared. A week saying email was a nightmare is not a week where email worked, and a week that mentions a call she dreaded is not a week about live teaching.
- Each value is a short phrase that finishes a sentence already in progress, not a sentence of its own: "showing up live and following up the same week", not "You did well at showing up live." No capital letter at the start, no full stop at the end, under 15 words.
- Name what she actually wrote about. A phrase that would fit any founder is a wrong answer.
- If the weeks disagree with each other, say what changed rather than averaging them.`;

    const weeks = recent.map((r, i) => [
        `Week ${i + 1} of ${recent.length}, ${new Date(r.date).toLocaleDateString()}:`,
        `  Worked well: ${r.workedWell || 'not answered'}`,
        `  Difficult: ${r.difficult || 'not answered'}`,
        `  Moved forward: ${r.movedForward || 'not answered'}`,
        r.nextWeekImprove ? `  Wants to improve: ${r.nextWeekImprove}` : '',
        r.energy ? `  Her energy that week: ${r.energy}` : ''
    ].filter(Boolean).join('\n')).join('\n\n');

    const user = `Her last ${recent.length} weekly reviews, oldest first:\n\n${weeks}\n\nHer business:\n\n${businessBrief()}\n\nReturn the two patterns as JSON.`;

    const result = await askLive('reflection-patterns', system, user, 300);
    if (!result) return null;

    const worked = typeof result.worked === 'string' ? result.worked.trim() : '';
    const bottleneck = typeof result.bottleneck === 'string' ? result.bottleneck.trim() : '';
    if (!worked || !bottleneck) return null;

    return { worked, bottleneck };
}
































const INSIGHT_FLOOR_STATES = ['revenue-none', 'energy-burnout', 'traffic-no-leads'];





const REASSURING_PHRASE = /\b(look(s|ing)? (good|clean|great|healthy|strong|solid)|on track|going well|doing (great|well|fine)|nothing (is )?(wrong|obviously|in the way)|no (major |real |big )?(issues|problems|concerns)|keep (it up|going|doing)|well done|great work)\b/i;



function insightFloorViolated(insight, state) {
    if (!INSIGHT_FLOOR_STATES.includes(state)) return false;
    if (!insight) return true;
    
    
    if (String(insight.verdict || '').toLowerCase() === 'fine') return true;
    
    
    return REASSURING_PHRASE.test(String(insight.headline || ''))
        || REASSURING_PHRASE.test(String(insight.body || ''));
}

function weeklyInsightFingerprint(state, store) {
    const rev = getRevenueInsights();
    const funnel = getFunnelInsights();
    return liveAIFingerprint([
        'insight',
        state,
        
        
        Math.round((rev.totalRevenue || 0) / 100),
        Math.round((rev.goal || 0) / 100),
        getWeeksElapsed(store) || 0,
        funnel.totalLeads,
        funnel.totalCalls,
        funnel.totalCloses,
        (store.reviews || []).length
    ]);
}




async function fetchWeeklyInsight(context) {
    if (!context || !context.state || context.state === 'not-enough-data') return null;

    const store = getStore();
    const funnel = getFunnelInsights();
    const rev = getRevenueInsights();

    
    
    const floored = INSIGHT_FLOOR_STATES.includes(context.state);

    const system = `You are looking at one solo founder's 90 days and naming the single thing most likely to be slowing her down, for a card called "Weekly CEO Insight" on the Wins and Progress screen of her planner. You choose what to raise. Nobody has picked the subject for you.

${VOICE_RULES}

Return JSON in exactly this shape and nothing else:
{"focus":"...","verdict":"fine|concern","headline":"...","body":"..."}

How to choose the subject:
- Pick the ONE thing with the most leverage this week. Not a list, not a summary of her 90 days.
- Prefer a cause you can point at in her numbers or her own words over a restatement of a number she can already see. "You have had 12 calls and no closes" is worth saying; "you are behind on revenue" is something the page already told her.
- Her energy answers outrank commercial advice. Telling someone who has logged burnout weeks to book more calls is reading her answer and ignoring it.
- Early in a 90-day cycle, nothing logged yet is normal. Do not manufacture a problem out of week one.

The fields:
- "focus" is a two or three word tag for what you chose, lowercase, e.g. "conversion", "energy", "follow-up", "pricing".
- "verdict" is "fine" ONLY if there is genuinely nothing worth raising. Otherwise "concern".
- "headline" is four to seven words, sentence case, no full stop. Names the situation, not a grade.
- "body" is two or three sentences, under 60 words, ending on ONE thing she could start today.

Hard rules:
- Use her actual numbers, offers and channel names. A sentence that would fit any founder is a wrong answer.
- NEVER deliver a verdict on these 90 days. They still have weeks left in them. Name what is true, then what moves it.
- Do not congratulate her for anything the numbers do not show, and do not invent a cause she has not written down.${floored ? `
- ⚠️ THIS FOUNDER IS NOT FINE. The numbers below show a serious situation. "verdict" MUST be "concern" and your text must not reassure her. An answer that says things look good will be discarded and she will see the app's own wording instead.` : ''}`;

    const reviewLines = (context.reviews || []).slice(-3).map((r, i) => [
        `Review ${i + 1}: energy "${r.energy || 'not answered'}"`,
        r.difficult ? `  hardest part: ${r.difficult}` : '',
        (r.workedWell || r.well) ? `  worked well: ${r.workedWell || r.well}` : '',
        (r.forward || r.movedForward) ? `  moved forward: ${r.forward || r.movedForward}` : ''
    ].filter(Boolean).join('\n')).join('\n');

    const planLines = (store.weeklyPlans || []).slice(-3).map((p, i) => [
        `Plan ${i + 1}${p.weekNumber ? ` (week ${p.weekNumber})` : ''}: ${p.winCondition || 'no focus set'}`,
        p.visibilityAction ? `  visibility: ${p.visibilityAction}` : '  visibility: none set',
        p.revenueAction ? `  revenue action: ${p.revenueAction}` : '  revenue action: none set',
        p.followUps ? `  follow-ups: ${p.followUps}` : '  follow-ups: none set'
    ].join('\n')).join('\n');

    const user = [
        'Her business:',
        businessBrief(),
        '',
        'Her pipeline in these 90 days:',
        
        
        `  visitors logged ${funnel.snapshotTraffic}, leads ${funnel.totalLeads}, calls ${funnel.totalCalls}, closes ${funnel.totalCloses}`,
        `  pace: ${rev.momentum || 'not enough data'}${rev.paceDeficitPercent ? `, ${rev.paceDeficitPercent}% short of the pace her goal needs` : ''}`,
        '',
        'Her last weekly plans:',
        planLines || '  none written yet',
        '',
        'Her last weekly reviews:',
        reviewLines || '  none written yet',
        '',
        
        
        
        
        `For reference only, the app's own rule-based read of this is "${context.state}". You may disagree with it if her numbers and her own words point somewhere more useful.`,
        '',
        'Choose the one thing and return it as JSON.'
    ].join('\n');

    const result = await askLive('weekly-insight', system, user, 350);
    if (!result) return null;

    const headline = typeof result.headline === 'string' ? result.headline.trim() : '';
    const body = typeof result.body === 'string' ? result.body.trim() : '';
    
    
    if (!headline || !body) return null;

    const insight = {
        headline,
        body,
        focus: typeof result.focus === 'string' ? result.focus.trim() : '',
        verdict: typeof result.verdict === 'string' ? result.verdict.trim() : ''
    };

    
    
    
    
    
    
    
    
    if (insightFloorViolated(insight, context.state)) {
        console.warn(`Live AI (weekly-insight) was discarded: it read as reassurance on a "${context.state}" quarter. Showing the app's own wording instead.`);
        return null;
    }

    return insight;
}










function liveAINote(text) {
    if (!canUseLiveAI()) return '';
    return `
        <p class="live-ai-note">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3l1.9 5.8L20 10.7l-4.9 3.6L16.4 20 12 16.8 7.6 20l1.3-5.7L4 10.7l6.1-1.9z"></path></svg>
            <span>${escapeText(text)}</span>
        </p>
    `;
}




function markLivePending(el) {
    if (el) el.classList.add('live-ai-pending');
}

function clearLivePending(el) {
    if (el) el.classList.remove('live-ai-pending');
}

















async function hydrateDaily3() {
    const request = window._liveAIDaily3;
    if (!request) return;
    delete window._liveAIDaily3;

    if (!canUseLiveAI() || !budgetAllows()) return;

    const container = document.getElementById('daily-3-list');
    markLivePending(container);
    const tasks = await fetchDaily3(request);
    clearLivePending(container);
    if (!tasks) return;

    putCachedLive('daily-3', daily3Fingerprint(request.dateStr, request.planKey, request.priorities), tasks);
    applyDaily3(tasks, request);
}

function applyDaily3(tasks, request) {
    const store = getStore();
    const existing = store.dailyLogs?.[request.dateStr] || [];

    if (existing.some(t => t && t.done)) return;
    if (existing.length === tasks.length && existing.every((t, i) => t.text === tasks[i])) return;

    updateDailyLog(request.dateStr, tasks.map(text => ({ text, done: false })), request.planKey);

    tasks.forEach((text, i) => {
        const label = document.querySelector(`#daily-task-${i}`)?.parentElement?.querySelector('span');
        if (label) label.textContent = text;
    });
}



async function hydrateAdvisorPulses() {
    const request = window._liveAIAdvisor;
    if (!request) return;
    delete window._liveAIAdvisor;

    if (!canUseLiveAI() || !budgetAllows()) return;
    if (!request.revenue && !request.pipeline) return;

    const pulses = await fetchAdvisorPulses(request);
    if (!pulses) return;

    putCachedLive('advisor-pulses', advisorFingerprint(request.dateStr, request.revenue, request.pipeline, request.revenueTotal), pulses);
    applyAdvisorPulses(pulses);
}



function applyAdvisorPulses(pulses) {
    ['revenue', 'pipeline'].forEach(key => {
        const pulse = pulses && pulses[key];
        if (!pulse || typeof pulse.message !== 'string') return;
        const messageEl = document.getElementById(`pulse-${key}-message`);
        if (messageEl) messageEl.textContent = pulse.message.trim();
    });
}

















function planSuggestionsPendingHtml() {
    return `
        <li class="plan-idea plan-idea-empty plan-idea-pending">
            <span class="plan-idea-spinner" aria-hidden="true"></span>
            <p role="status">Writing this week's ideas for your business…</p>
        </li>`;
}



async function hydratePlanSuggestions(rebuild) {
    if (!window._liveAIPlanNeedsFetch) return;
    delete window._liveAIPlanNeedsFetch;

    
    
    
    if (!canUseLiveSurface('plan-suggestions')) {
        planSuggestionsUnavailable();
        return;
    }

    
    
    if (readBudget().stopped) {
        planSuggestionsUnavailable();
        return;
    }

    
    
    
    
    if (!budgetAllows()) {
        planSuggestionsFailed(rebuild);
        return;
    }

    await runPlanSuggestions(rebuild);
}







async function runPlanSuggestions(rebuild, { force = false } = {}) {
    const list = document.getElementById('plan-suggestions-list');
    if (list) list.innerHTML = planSuggestionsPendingHtml();
    markLivePending(list);
    const suggestions = await fetchPlanSuggestions({ force });
    clearLivePending(document.getElementById('plan-suggestions-list'));

    
    
    
    if (!suggestions) {
        planSuggestionsFailed(rebuild);
        return;
    }

    putCachedLive('plan-suggestions', planSuggestionsFingerprint(getStore()), suggestions);
    rebuild(suggestions);
}










function planSuggestionsFailed(rebuild) {
    const list = document.getElementById('plan-suggestions-list');
    if (!list) return;
    list.innerHTML = `
        <li class="plan-idea plan-idea-empty plan-idea-failed">
            <p>This week's ideas could not be written just now. Your own plan is unaffected — everything from your 90-Day Action Plan is already in the boxes below.</p>
            <button type="button" class="btn btn-outline btn-sm" id="btn-retry-plan-ideas">Try again</button>
        </li>`;

    const btn = document.getElementById('btn-retry-plan-ideas');
    if (!btn) return;
    btn.addEventListener('click', () => {
        
        btn.disabled = true;
        
        
        
        
        
        runPlanSuggestions(rebuild, { force: true }).catch(err => {
            console.warn('Retrying this week\'s ideas failed:', err && err.message);
            planSuggestionsFailed(rebuild);
        });
    });
}






function planSuggestionsUnavailable() {
    const list = document.getElementById('plan-suggestions-list');
    if (!list) return;

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    if (list.querySelector('.plan-idea:not(.plan-idea-empty)')) return;
    list.innerHTML = `
        <li class="plan-idea plan-idea-empty">
            <p>This week's ideas could not be written just now. Your own plan is unaffected — everything from your 90-Day Action Plan is already in the boxes below, and ideas are tried again next time you open this page.</p>
        </li>`;
}




