let signingOut = false;

async function signOutAndClear() {
    
    
    
    
    if (signingOut) return;
    signingOut = true;

    
    
    
    const link = document.getElementById('nav-logout');
    if (link) {
        link.textContent = 'Signing out…';
        link.style.opacity = '0.7';
        link.style.pointerEvents = 'none';
    }

    try {
        
        
        
        
        
        
        await window.db.auth.signOut({ scope: 'local' });
    } catch (err) {
        
        
        console.warn('Supabase sign-out failed, clearing locally anyway:', err?.message);
    }
    localStorage.removeItem('ceo_auth');
    localStorage.removeItem('ceo_sub_status');
    localStorage.removeItem('ceo_trial_ends_at');
    localStorage.removeItem('ceo_plan_tier');
    
    localStorage.removeItem('ceo_comp_pro');
    
    
    
    
    localStorage.removeItem('ceo_tz_sent');
    
    
    
    
    localStorage.removeItem('ceo_data_erased_at');
    
    
    
    
    localStorage.removeItem('ceo_cancel_at_period_end');
    localStorage.removeItem('ceo_current_period_end');
    localStorage.removeItem('ceo_pending_plan_tier');
    
    
    
    
    localStorage.removeItem('ceo_beta_tester');
    localStorage.removeItem('ceo_admin');
    
    
    
    
    clearFeedbackNews();
    
    
    
    
    forgetUsageIdentity();
    
    
    
    localStorage.removeItem('ceo_beta_code');
    
    
    
    localStorage.removeItem('ceo_beta_loops_synced');
    localStorage.removeItem('ceoPlanner_store');
    
    
    
    localStorage.removeItem('ceo_last_sync');
    localStorage.removeItem('ceo_server_stamp');
    localStorage.removeItem('ceo_own_stamps');
    
    
    
    clearStoreOwner();
    
    
    clearLiveAICache();
    clearAiAllowance();
    
    clearAfterSetupRoute();
    
    
    signingOut = false;
    
    
    
    reloadAt('#/login');
}










