function renderTooltip(whatStr, whyStr, position = 'top', labels = {}) {
    
    const id = 'tt_' + Math.random().toString(36).substr(2, 9);

    const whatLabel = labels.what || 'What it is';
    const whyLabel = labels.why || 'Why it matters';

    let content = '';
    if (whatStr) {
        content += `<span class="tooltip-section"><strong>${whatLabel}:</strong> ${whatStr}</span>`;
    }
    if (whyStr) {
        content += `<span class="tooltip-section"><strong>${whyLabel}:</strong> ${whyStr}</span>`;
    }

    return `
        <span class="tooltip-container ${position === 'bottom' ? 'tooltip-bottom' : ''}" tabindex="0" aria-describedby="${id}">
            <svg class="info-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <circle cx="12" cy="12" r="10"></circle>
                <line x1="12" y1="16" x2="12" y2="12"></line>
                <line x1="12" y1="8" x2="12.01" y2="8"></line>
            </svg>
            <span class="tooltip-content" id="${id}" role="tooltip">
                ${content}
            </span>
        </span>
    `;
}














const TOAST_CONTAINER_ID = 'ceo-toast-container';

function getToastContainer() {
    let container = document.getElementById(TOAST_CONTAINER_ID);
    if (!container) {
        container = document.createElement('div');
        container.id = TOAST_CONTAINER_ID;
        container.className = 'toast-container';
        
        
        container.setAttribute('aria-live', 'polite');
        container.setAttribute('role', 'status');
        document.body.appendChild(container);
    }
    return container;
}


function showToast(message, type = 'success', duration = 3500) {
    const container = getToastContainer();

    const toast = document.createElement('div');
    toast.className = `toast toast-${type}`;

    const icon = type === 'error' ? '⚠️' : (type === 'info' ? 'ℹ️' : '✅');
    toast.innerHTML = `<span class="toast-icon">${icon}</span><span class="toast-message"></span>`;
    
    toast.querySelector('.toast-message').textContent = message;

    container.appendChild(toast);

    let dismissed = false;
    const dismiss = () => {
        if (dismissed) return;
        dismissed = true;
        toast.classList.add('toast-leaving');
        setTimeout(() => toast.remove(), 250);
    };

    toast.addEventListener('click', dismiss);
    
    setTimeout(dismiss, type === 'error' ? Math.max(duration, 6000) : duration);

    return dismiss;
}



function showConfirm(message, opts = {}) {
    const {
        title = 'Are you sure?',
        confirmText = 'Confirm',
        cancelText = 'Cancel',
        danger = false
    } = opts;

    return new Promise(resolve => {
        const overlay = document.createElement('div');
        overlay.className = 'confirm-overlay';
        overlay.innerHTML = `
            <div class="confirm-card card" role="dialog" aria-modal="true" aria-labelledby="confirm-title">
                <h3 id="confirm-title" class="confirm-title"></h3>
                <p class="confirm-message"></p>
                <div class="confirm-actions">
                    <button type="button" class="btn btn-ghost confirm-cancel"></button>
                    <button type="button" class="btn ${danger ? 'btn-danger' : 'btn-primary'} confirm-ok"></button>
                </div>
            </div>
        `;
        overlay.querySelector('.confirm-title').textContent = title;
        overlay.querySelector('.confirm-message').textContent = message;
        overlay.querySelector('.confirm-cancel').textContent = cancelText;
        overlay.querySelector('.confirm-ok').textContent = confirmText;

        const previouslyFocused = document.activeElement;

        const close = (result) => {
            document.removeEventListener('keydown', onKeydown);
            overlay.remove();
            if (previouslyFocused && typeof previouslyFocused.focus === 'function') {
                previouslyFocused.focus();
            }
            resolve(result);
        };

        const onKeydown = (e) => {
            if (e.key === 'Escape') close(false);
        };

        overlay.querySelector('.confirm-ok').addEventListener('click', () => close(true));
        overlay.querySelector('.confirm-cancel').addEventListener('click', () => close(false));
        overlay.addEventListener('click', (e) => {
            if (e.target === overlay) close(false);
        });
        document.addEventListener('keydown', onKeydown);

        document.body.appendChild(overlay);
        overlay.querySelector(danger ? '.confirm-cancel' : '.confirm-ok').focus();
    });
}




