let activeStop = null;
let leaveBound = false;
function bindStopOnLeave() {
    if (leaveBound) return;
    leaveBound = true;
    const run = () => { if (activeStop) activeStop(); };
    window.addEventListener('hashchange', run);
    window.addEventListener('pagehide', run);
}



function attachVoiceReflection(prefix, boxSelector, defaultBoxId) {
    const panel = document.getElementById(`${prefix}-voice-panel`);
    const btn = document.getElementById(`${prefix}-voice-btn`);
    const btnText = document.getElementById(`${prefix}-voice-text`);
    const status = document.getElementById(`${prefix}-voice-status`);
    if (!panel || !btn) return () => {};

    if (!voiceReflectionSupported()) {
        panel.style.display = 'none';
        return () => {};
    }

    let target = document.getElementById(defaultBoxId);
    document.querySelectorAll(boxSelector).forEach(box => {
        box.addEventListener('focus', (e) => { target = e.target; });
    });

    const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new Recognition();
    recognition.continuous = true;
    recognition.interimResults = true;
    let recording = false;

    const showIdle = () => {
        btn.classList.add('btn-secondary');
        btn.classList.remove('btn-primary');
        if (btnText) btnText.textContent = 'Start Voice Reflection';
        if (status) status.style.display = 'none';
    };

    
    
    
    
    
    
    
    
    
    
    let wantsToRecord = false;
    
    
    let restarts = 0;
    const MAX_RESTARTS = 50;

    const stop = () => {
        wantsToRecord = false;
        if (recording) {
            recording = false;
            try { recognition.stop(); } catch (err) {  }
        }
        showIdle();
        if (activeStop === stop) activeStop = null;
    };

    recognition.onstart = () => {
        recording = true;
        btn.classList.remove('btn-secondary');
        btn.classList.add('btn-primary');
        if (btnText) btnText.textContent = 'Stop Recording';
        if (status) status.style.display = 'block';
    };

    recognition.onresult = (event) => {
        let spoken = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
            if (event.results[i].isFinal) spoken += event.results[i][0].transcript;
        }
        
        
        restarts = 0;
        if (!spoken.trim() || !target || !target.isConnected) return;
        target.value += (target.value ? ' ' : '') + spoken.trim() + '.';
        
        target.dispatchEvent(new Event('input', { bubbles: true }));
    };

    recognition.onerror = (event) => {
        console.error('Speech recognition error', event.error);
        
        
        
        if (event.error === 'no-speech' || event.error === 'aborted') return;
        stop();
        showToast("We couldn't reach your microphone. Check the site's permissions and try again.", 'error');
    };

    recognition.onend = () => {
        recording = false;
        if (wantsToRecord && restarts < MAX_RESTARTS) {
            restarts += 1;
            try {
                recognition.start();
                return; 
            } catch (err) {
                console.warn('Could not resume voice reflection', err);
            }
        }
        wantsToRecord = false;
        showIdle();
    };

    btn.addEventListener('click', () => {
        if (recording) {
            stop();
            return;
        }
        if (activeStop && activeStop !== stop) activeStop();
        try {
            wantsToRecord = true;
            restarts = 0;
            recognition.start();
            activeStop = stop;
        } catch (err) {
            wantsToRecord = false;
            console.error(err);
        }
    });

    bindStopOnLeave();
    return stop;
}




























function attachMicButton(btn, input, indicator, options) {
    if (!btn || !input) return () => {};
    const opts = options || {};
    const Recognition = typeof window !== 'undefined' && (window.SpeechRecognition || window.webkitSpeechRecognition);

    if (!Recognition) {
        if (opts.hideWhenUnsupported) {
            btn.style.display = 'none';
            return () => {};
        }
        btn.addEventListener('click', () => {
            showToast("Voice recording isn't supported in this browser. Chrome or Safari will work.", 'info');
        });
        return () => {};
    }

    const recognition = new Recognition();
    recognition.continuous = Boolean(opts.continuous);
    recognition.interimResults = true;
    let isRecording = false;

    const showIdle = () => {
        btn.classList.remove('is-recording');
        if (indicator) indicator.style.display = 'none';
    };

    
    
    
    
    
    
    let wantsToRecord = false;
    let restarts = 0;
    const MAX_RESTARTS = 50;

    const stop = () => {
        wantsToRecord = false;
        if (isRecording) {
            isRecording = false;
            try { recognition.stop(); } catch (err) {  }
        }
        showIdle();
        if (activeStop === stop) activeStop = null;
    };

    recognition.onstart = () => {
        isRecording = true;
        btn.classList.add('is-recording');
        if (indicator) indicator.style.display = 'flex';
    };

    recognition.onresult = (event) => {
        let finalTranscript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
            if (event.results[i].isFinal) finalTranscript += event.results[i][0].transcript;
        }
        restarts = 0;
        if (!finalTranscript || !input.isConnected) return;
        const current = input.value;
        input.value = current + (current.length > 0 && !current.endsWith(' ') ? ' ' : '') + finalTranscript;
        
        
        input.dispatchEvent(new Event('input', { bubbles: true }));
    };

    recognition.onerror = (event) => {
        console.error('Speech recognition error', event.error);
        
        if (opts.continuous && (event.error === 'no-speech' || event.error === 'aborted')) return;
        stop();
    };

    recognition.onend = () => {
        isRecording = false;
        if (opts.continuous && wantsToRecord && restarts < MAX_RESTARTS) {
            restarts += 1;
            try {
                recognition.start();
                return; 
            } catch (err) {
                console.warn('Could not resume dictation', err);
            }
        }
        wantsToRecord = false;
        showIdle();
        if (activeStop === stop) activeStop = null;
    };

    btn.addEventListener('click', () => {
        if (isRecording) {
            stop();
            return;
        }
        if (activeStop && activeStop !== stop) activeStop();
        try {
            wantsToRecord = true;
            restarts = 0;
            recognition.start();
            activeStop = stop;
        } catch (err) {
            wantsToRecord = false;
            console.error('Failed to start speech recognition', err);
        }
    });

    bindStopOnLeave();
    return stop;
}






























const NO_BILLING_CODES = ['no_customer', 'no_subscription'];




async function readPortalError(error) {
    let code = null;
    let message = null;

    try {
        if (error && error.context && typeof error.context.json === 'function') {
            const body = await error.context.json();
            if (body) {
                code = body.code || null;
                message = body.error || body.message || null;
            }
        }
    } catch (err) {
        
    }

    if (!message) message = await window.readFunctionError(error);
    return { code, message };
}







async function openBillingPortal(intent) {
    try {
        const { data, error } = await window.db.functions.invoke('stripe-portal', {
            method: 'POST',
            body: intent ? { intent } : {}
        });

        if (error) {
            const { code, message } = await readPortalError(error);

            if (NO_BILLING_CODES.includes(code)) {
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                const status = localStorage.getItem('ceo_sub_status');
                if (status === 'active' || status === 'past_due') {
                    
                    
                    
                    
                    const message = "Your plan is active here but we can't find it with our payment provider, so there is nothing for us to open. Email " + SUPPORT_EMAIL + " and we'll sort it out.";
                    showToast(message, 'error', 12000);
                    return message;
                }

                showToast("You don't have a subscription on this account yet. Here are the plans.", 'info');
                window.location.hash = '#/billing';
                return null;
            }

            showToast(message, 'error');
            return message;
        }

        if (!data || !data.url) {
            showToast('We could not open your billing page. Please try again in a moment.', 'error');
            return 'No portal URL returned.';
        }

        window.location.href = data.url;
        return null;
    } catch (err) {
        
        
        
        console.warn('Portal session failed, falling back to the login link:', err && err.message);
        if (window.CEO_BILLING_PORTAL) {
            window.location.href = window.CEO_BILLING_PORTAL;
            return null;
        }
        showToast('We could not open your billing page. Please try again in a moment.', 'error');
        return 'Portal unreachable.';
    }
}















function canUpgradeToPro() {
    const status = localStorage.getItem('ceo_sub_status');
    if (status !== 'active' && status !== 'past_due') return false;
    if (localStorage.getItem('ceo_comp_pro') === 'true') return false;
    if (localStorage.getItem('ceo_plan_tier') === 'pro') return false;
    return anyProFeatureLive();
}















const RETURN_POLL_MS = 2000;
const RETURN_TIMEOUT_MS = 20000;

function hasBillingReturnMarker() {
    const hash = window.location.hash || '';
    const q = hash.indexOf('?');
    const inHash = q !== -1 && /[?&]billing=updated/.test(hash.slice(q));
    return inHash || /[?&]billing=updated/.test(window.location.search);
}

function clearBillingReturnMarker() {
    const hash = (window.location.hash || '').split('?')[0];
    window.history.replaceState({}, '', window.location.pathname + (hash || '#/account'));
}

async function watchForPlanChange() {
    if (!hasBillingReturnMarker()) return;

    const before = localStorage.getItem('ceo_plan_tier');
    const startedAt = Date.now();

    
    
    clearBillingReturnMarker();

    const timer = setInterval(async () => {
        const access = await window.refreshAccessState();
        const changed = access && access.tier && access.tier !== before;

        if (changed) {
            clearInterval(timer);
            showToast("You're on the new plan. Everything it unlocks is available now.", 'success');
            
            setTimeout(() => window.location.reload(), 1200);
            return;
        }

        if (Date.now() - startedAt >= RETURN_TIMEOUT_MS) {
            clearInterval(timer);
            
            
            
            
        }
    }, RETURN_POLL_MS);
}




































function esc(s) {
    return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}



