const REPORT_SECTIONS = [
    { key: 'chart', label: 'Revenue by week' },
    { key: 'funnel', label: 'The funnel' },
    { key: 'sources', label: 'Revenue sources' },
    { key: 'transactions', label: 'Every transaction' },
    { key: 'pipeline', label: 'Open pipeline' },
    { key: 'coach', label: "Coach's summary" }
];

const DEFAULT_REPORT_OPTIONS = {
    chart: true,
    funnel: true,
    sources: true,
    transactions: false,
    pipeline: true,
    coach: true
};




function readReportOptions() {
    const saved = getStore().settings?.reportOptions;
    const out = { ...DEFAULT_REPORT_OPTIONS };
    if (saved && typeof saved === 'object') {
        REPORT_SECTIONS.forEach(({ key }) => {
            if (typeof saved[key] === 'boolean') out[key] = saved[key];
        });
    }
    return out;
}

function readPreparedFor() {
    const value = getStore().settings?.reportPreparedFor;
    return typeof value === 'string' ? value : '';
}



function esc(value) {
    return String(value === null || value === undefined ? '' : value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}








function brandColours() {
    const fallback = {
        '--color-primary': '#00C2CB',
        '--color-primary-dark': '#0099A1',
        '--color-primary-light': '#E5F9FA',
        '--color-secondary': '#F2C21D',
        '--color-secondary-dark': '#D1A511',
        '--color-accent-dark': '#D47E8D',
        '--color-black': '#0F172A',
        '--color-text-main': '#334155',
        '--color-text-muted': '#64748B'
    };

    const out = {};
    let computed = null;
    try {
        computed = window.getComputedStyle(document.documentElement);
    } catch (err) {
        computed = null;
    }

    Object.keys(fallback).forEach(key => {
        const live = computed ? String(computed.getPropertyValue(key) || '').trim() : '';
        out[key.replace('--color-', '')] = live || fallback[key];
    });
    return out;
}

function stageLabel(key) {
    const found = PIPELINE_STAGES.find(s => s.key === key);
    return found ? found.label : 'Lead';
}

function probabilityLabel(key) {
    const found = PIPELINE_PROBABILITIES.find(p => p.key === key);
    return found ? found.label : 'Not set';
}

function shortDate(value) {
    const d = value instanceof Date ? value : new Date(value);
    if (!Number.isFinite(d.getTime())) return '';
    return d.toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
}

function longDate(value) {
    const d = value instanceof Date ? value : new Date(value);
    if (!Number.isFinite(d.getTime())) return '';
    return d.toLocaleDateString(undefined, { day: 'numeric', month: 'long', year: 'numeric' });
}











function weeklyChartSvg(insights, store, colours, currency) {
    const startISO = store.quarterStartDate;
    const start = startISO ? getWeekStart(new Date(startISO)) : null;
    if (!start || !Number.isFinite(start.getTime())) return '';

    
    
    
    
    const buckets = revenueByCycleWeek(insights.quarterEntries || [], store)
        .map(b => ({ key: b.key, start: new Date(b.date), amount: b.amount }));
    if (buckets.length === 0) return '';

    
    
    
    const weeklyGoal = insights.goal > 0 ? insights.goal / 12 : 0;
    const peak = Math.max(...buckets.map(b => b.amount), weeklyGoal, 1);

    const W = 720;
    const H = 260;
    const padL = 8;
    const padR = 8;
    const padTop = 26;   
    const padBottom = 34; 
    const plotH = H - padTop - padBottom;
    const slot = (W - padL - padR) / buckets.length;
    const barW = Math.min(46, slot * 0.6);

    const bars = buckets.map((b, i) => {
        const h = peak > 0 ? (b.amount / peak) * plotH : 0;
        const x = padL + (slot * i) + (slot - barW) / 2;
        const y = padTop + plotH - h;
        const label = b.amount > 0
            ? `<text x="${(x + barW / 2).toFixed(1)}" y="${(y - 6).toFixed(1)}" class="bar-value">${esc(currency + formatAmount(Math.round(b.amount)))}</text>`
            : '';
        return `
            <rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${barW.toFixed(1)}" height="${Math.max(h, b.amount > 0 ? 2 : 0).toFixed(1)}" rx="3" class="bar"></rect>
            ${label}
            <text x="${(x + barW / 2).toFixed(1)}" y="${(padTop + plotH + 18).toFixed(1)}" class="bar-label">${esc(shortDate(b.start))}</text>
        `;
    }).join('');

    const goalY = weeklyGoal > 0 ? padTop + plotH - (weeklyGoal / peak) * plotH : null;
    const goalLine = goalY === null ? '' : `
        <line x1="${padL}" y1="${goalY.toFixed(1)}" x2="${W - padR}" y2="${goalY.toFixed(1)}" class="goal-line"></line>
        <text x="${W - padR}" y="${(goalY - 5).toFixed(1)}" class="goal-label" text-anchor="end">Weekly target ${esc(currency + formatAmount(Math.round(weeklyGoal)))}</text>
    `;

    return `
        <svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Revenue by week in these 90 days">
            <style>
                .bar { fill: ${colours.secondary}; }
                .bar-value { font: 600 10px 'Helvetica Neue', Arial, sans-serif; fill: ${colours.black}; text-anchor: middle; }
                .bar-label { font: 600 9px 'Helvetica Neue', Arial, sans-serif; fill: ${colours['text-muted']}; text-anchor: middle; }
                .goal-line { stroke: ${colours['primary-dark']}; stroke-width: 1.5; stroke-dasharray: 5 4; }
                .goal-label { font: 600 9px 'Helvetica Neue', Arial, sans-serif; fill: ${colours['primary-dark']}; }
                .axis { stroke: #E2E8F0; stroke-width: 1; }
            </style>
            <line x1="${padL}" y1="${padTop + plotH}" x2="${W - padR}" y2="${padTop + plotH}" class="axis"></line>
            ${goalLine}
            ${bars}
        </svg>
    `;
}



function buildReportHtml(options, preparedFor) {
    const opts = options || readReportOptions();
    const preparedForLine = typeof preparedFor === 'string' ? preparedFor.trim() : readPreparedFor().trim();
    const store = getStore();
    const insights = getRevenueInsights();
    const funnel = getFunnelInsights();
    const pipeline = getPipelineInsights();
    const colours = brandColours();
    const currency = store.settings?.currency || '$';
    const money = (n) => currency + formatAmount(n);

    const businessName = store.profile?.businessName || store.profile?.name || 'My business';
    const ownerName = store.profile?.name || '';
    const logo = store.profile?.logo || '';
    const quarterEnd = getQuarterEnd(store);
    const range = quarterRangeLabel(
        store.quarterStartDate,
        quarterEnd ? quarterEnd.toISOString() : null
    );

    
    
    
    const beatGoal = insights.goal > 0 && insights.totalRevenue > insights.goal;

    const kpis = [
        {
            label: 'Revenue in these 90 days',
            value: money(insights.totalRevenue),
            note: insights.goal > 0
                ? `${insights.progressPercent.toFixed(0)}% of the ${money(insights.goal)} goal`
                : 'No 90-day goal set'
        },
        {
            label: 'Pace',
            value: esc(insights.momentum),
            note: insights.goal > 0
                ? `Projecting ${money(Math.round(insights.projectedRevenue))} by the end of these 90 days`
                : 'Set a revenue goal to see a projection'
        },
        {
            label: 'Where we are',
            value: `Week ${insights.weeksElapsed} of 12`,
            note: insights.weeksRemaining > 0
                ? `${insights.weeksRemaining} week${insights.weeksRemaining === 1 ? '' : 's'} left`
                : 'Final week of these 90 days'
        },
        {
            label: 'Needed each week from here',
            value: money(Math.round(insights.weeklyTargetLength)),
            note: insights.hasOfferPrice
                ? `About ${insights.salesRequiredPerWeek} sale${insights.salesRequiredPerWeek === 1 ? '' : 's'} a week at ${money(insights.averageOfferPrice)}`
                : 'Set an average offer price to see this in sales'
        }
    ];

    
    
    
    
    
    
    if (insights.hasOfferPrice && insights.goal > 0) {
        kpis.push({
            label: 'Still to sell',
            value: insights.salesRemaining > 0 ? `about ${insights.salesRemaining}` : 'Target reached',
            note: insights.salesRemaining > 0
                ? `at ${money(insights.averageOfferPrice)} each, to reach ${money(insights.goal)}`
                : `${money(insights.totalRevenue)} against a ${money(insights.goal)} goal`
        });
    }
    kpis.push({
        label: 'Sales logged',
        value: String(insights.quarterEntryCount),
        note: insights.revenueBeforeQuarter > 0
            ? `Plus ${money(insights.revenueBeforeQuarter)} logged before these 90 days began`
            : insights.salesMade > 0
                ? `${money(insights.averageSaleValue)} a sale on average`
                : 'Entries dated inside these 90 days'
    });

    const kpiHtml = kpis.map(k => `
        <div class="kpi">
            <p class="kpi-label">${esc(k.label)}</p>
            <p class="kpi-value">${k.value}</p>
            <p class="kpi-note">${k.note}</p>
        </div>
    `).join('');

    
    
    
    
    
    
    const closeRate = funnel.callCloseRate === null
        ? '—'
        : `${funnel.callCloseRate.toFixed(1)}%`;
    const visitorRate = funnel.visitorToCallRate === null
        ? '—'
        : `${funnel.visitorToCallRate.toFixed(1)}%`;
    const leadSplit = (funnel.bulkLeads > 0 && funnel.contactLeads > 0)
        ? `${funnel.bulkLeads} logged in bulk, ${funnel.contactLeads} named contacts`
        : '';

    const funnelRows = [
        ['Website visitors', funnel.snapshotTraffic.toLocaleString(), 'From your monthly snapshots'],
        ['Leads', funnel.totalLeads.toLocaleString(), leadSplit],
        ['Calls booked', funnel.totalCalls.toLocaleString(), ''],
        ['Calls closed', funnel.anyClosesEverLogged ? funnel.totalCloses.toLocaleString() : '—',
            funnel.anyClosesEverLogged ? '' : 'Not recorded yet'],
        ['Visitor to call', visitorRate, ''],
        ['Call close rate', closeRate, funnel.callCloseRate === null && funnel.totalCalls > 0
            ? 'Calls logged, closes never recorded' : '']
    ].map(([label, value, note]) => `
        <tr>
            <td>${esc(label)}</td>
            <td class="num">${esc(value)}</td>
            <td class="note">${esc(note)}</td>
        </tr>
    `).join('');

    
    
    
    
    
    
    
    const sourceTotals = {};
    (insights.quarterEntries || []).forEach(e => {
        const key = e.source || 'Not recorded';
        sourceTotals[key] = (sourceTotals[key] || 0) + (parseFloat(e.amount) || 0);
    });
    
    
    
    
    
    const sourceRows = Object.keys(sourceTotals)
        .sort((a, b) => sourceTotals[b] - sourceTotals[a])
        .map(name => {
            const amount = sourceTotals[name];
            const pct = insights.totalRevenue > 0 ? (amount / insights.totalRevenue) * 100 : 0;
            const share = insights.totalRevenue > 0 ? `${pct.toFixed(0)}%` : '—';
            const bar = insights.totalRevenue > 0
                ? `<div class="share-track"><div class="share-fill" style="width: ${Math.max(1, Math.min(100, pct)).toFixed(1)}%;"></div></div>`
                : '';
            return `<tr><td>${esc(name)}</td><td class="num">${money(amount)}</td><td class="num share-cell">${share}${bar}</td></tr>`;
        }).join('');

    const sourceSection = (opts.sources && sourceRows) ? `
        <section class="block">
            <h2>Where this revenue came from</h2>
            <table>
                <thead><tr><th>Source</th><th class="num">Revenue</th><th class="num">Share</th></tr></thead>
                <tbody>${sourceRows}</tbody>
            </table>
        </section>
    ` : '';

    
    
    
    
    
    
    
    
    
    const txSorted = (insights.quarterEntries || []).slice().sort((a, b) => {
        const at = new Date(a.date).getTime();
        const bt = new Date(b.date).getTime();
        if (Number.isFinite(at) && Number.isFinite(bt)) return bt - at;
        return 0;
    });

    
    
    
    
    
    
    
    const originNote = (e) => {
        if (e.needsRate) {
            return `<div class="tx-origin">${esc(currencySymbolFor(e.originalCurrency))}${formatAmount(e.originalAmount || 0)} ${esc(e.originalCurrency || '')} — no exchange rate set, so it counts as zero</div>`;
        }
        if (e.converted) {
            const rate = (e.conversionRate === undefined || e.conversionRate === null)
                ? ''
                : ` at ${Number(e.conversionRate).toFixed(4)}`;
            return `<div class="tx-origin">Converted from ${esc(currencySymbolFor(e.originalCurrency))}${formatAmount(e.originalAmount || 0)} ${esc(e.originalCurrency || '')}${esc(rate)}</div>`;
        }
        return '';
    };

    const txRows = txSorted.map(e => `
        <tr>
            <td class="nowrap">${esc(shortDate(e.date))}</td>
            <td>${esc(e.offer || '—')}</td>
            <td>${esc(e.source || 'Not recorded')}</td>
            <td class="note">${esc(e.notes || '')}</td>
            <td class="num">${money(parseFloat(e.amount) || 0)}${originNote(e)}</td>
        </tr>
    `).join('');

    
    
    
    
    const unconverted = insights.unconvertedSales || [];
    const unconvertedBlock = unconverted.length ? `
        <p class="caveat">Not included in any figure in this report: ${unconverted.map(g =>
            `${g.count} sale${g.count === 1 ? '' : 's'} totalling ${esc(g.symbol)}${formatAmount(g.originalTotal)} in ${esc(g.code)}`
        ).join(', ')}. No exchange rate has been set for ${unconverted.length === 1 ? 'that currency' : 'those currencies'}, so ${unconverted.length === 1 ? 'it is' : 'they are'} counted as zero rather than guessed at. Set a rate on the Settings screen and regenerate this report to include ${unconverted.length === 1 ? 'it' : 'them'}.</p>
    ` : '';

    const txSection = (opts.transactions && txRows) ? `
        <section class="block page-break">
            <h2>Every transaction</h2>
            <p class="lede">${txSorted.length} sale${txSorted.length === 1 ? '' : 's'} dated inside ${esc(range)}, newest first. These are the entries every figure above is built from.</p>
            <table class="tx-table">
                <thead><tr><th>Date</th><th>Offer</th><th>Source</th><th>Note</th><th class="num">Amount</th></tr></thead>
                <tbody>${txRows}</tbody>
                <tfoot><tr><td colspan="4">Total</td><td class="num">${money(insights.totalRevenue)}</td></tr></tfoot>
            </table>
            ${unconvertedBlock}
        </section>
    ` : '';

    
    
    
    
    
    
    const open = pipeline.contacts.filter(c => c.isOpen);
    const openSorted = open.slice().sort((a, b) => {
        if (a.closeDate && b.closeDate) return String(a.closeDate).localeCompare(String(b.closeDate));
        if (a.closeDate) return -1;
        if (b.closeDate) return 1;
        return (parseFloat(b.value) || 0) - (parseFloat(a.value) || 0);
    });
    const shown = openSorted.slice(0, 20);

    const pipelineRows = shown.map(c => `
        <tr>
            <td>${esc(c.name || 'Unnamed')}</td>
            <td>${esc(stageLabel(c.stage))}</td>
            <td class="num">${c.value ? money(c.value) : '—'}</td>
            <td>${esc(probabilityLabel(c.probability))}</td>
            <td>${c.closeDate ? esc(shortDate(c.closeDate)) : '—'}</td>
        </tr>
    `).join('');

    const pipelineCaveats = [];
    if (pipeline.unweightedCount > 0) {
        pipelineCaveats.push(`${pipeline.unweightedCount} open deal${pipeline.unweightedCount === 1 ? ' has' : 's have'} no likelihood set, so ${money(pipeline.unweightedValue)} of the total is not in the weighted figure.`);
    }
    if (pipeline.noCloseDateCount > 0) {
        pipelineCaveats.push(`${pipeline.noCloseDateCount} open deal${pipeline.noCloseDateCount === 1 ? ' has' : 's have'} no expected close date, so ${pipeline.noCloseDateCount === 1 ? 'it is' : 'they are'} not counted in what is expected this quarter.`);
    }
    if (shown.length < openSorted.length) {
        pipelineCaveats.push(`Showing the first ${shown.length} of ${openSorted.length} open deals.`);
    }

    const pipelineSection = (!opts.pipeline || open.length === 0) ? '' : `
        <section class="block">
            <h2>Open pipeline</h2>
            <p class="lede">Money that might arrive. None of it is counted in the revenue figures above.</p>
            <div class="mini-kpis">
                <div class="mini"><span>${money(pipeline.openValue)}</span><small>${pipeline.openCount} open deal${pipeline.openCount === 1 ? '' : 's'}</small></div>
                <div class="mini"><span>${money(pipeline.weightedValue)}</span><small>Weighted by likelihood (${pipeline.weightedCount} deal${pipeline.weightedCount === 1 ? '' : 's'})</small></div>
                <div class="mini"><span>${money(pipeline.expectedThisQuarter)}</span><small>Expected before these 90 days end</small></div>
            </div>
            <table>
                <thead><tr><th>Contact</th><th>Stage</th><th class="num">Value</th><th>Likelihood</th><th>Expected close</th></tr></thead>
                <tbody>${pipelineRows}</tbody>
            </table>
            ${pipelineCaveats.length ? `<p class="caveat">${pipelineCaveats.map(esc).join(' ')}</p>` : ''}
        </section>
    `;

    
    let aiSection = '';
    const savedReport = getAiReport();
    if (opts.coach && savedReport) {
        let bodyHtml;
        try {
            bodyHtml = window.marked
                ? window.marked.parse(savedReport.text)
                : `<pre class="plain">${esc(savedReport.text)}</pre>`;
        } catch (err) {
            bodyHtml = `<pre class="plain">${esc(savedReport.text)}</pre>`;
        }
        aiSection = `
            <section class="block page-break">
                <h2>The coach's read on these 90 days</h2>
                <p class="lede">Generated ${esc(longDate(savedReport.at))} from the numbers in this report.</p>
                <div class="prose">${bodyHtml}</div>
            </section>
        `;
    }

    const chart = opts.chart ? weeklyChartSvg(insights, store, colours, currency) : '';
    const chartSection = chart ? `
        <section class="block">
            <h2>Revenue by week</h2>
            ${(insights.quarterEntries || []).length === 0
                ? '<p class="lede">Nothing logged in these 90 days yet, so every week reads as zero.</p>'
                : ''}
            ${chart}
        </section>
    ` : '';

    const funnelSection = opts.funnel ? `
        <section class="block">
            <h2>The funnel</h2>
            <table>
                <thead><tr><th>Stage</th><th class="num">Figure</th><th>Note</th></tr></thead>
                <tbody>${funnelRows}</tbody>
            </table>
        </section>
    ` : '';

    const goalNote = beatGoal
        ? `<p class="banner-note">Goal beaten by ${money(insights.totalRevenue - insights.goal)}.</p>`
        : '';

    const barWidth = insights.goal > 0 ? Math.min(100, insights.progressPercent) : 0;

    return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>${esc(businessName)} — 90-day report</title>
<style>
    /* Colour survives the print dialogue. Without this Chrome strips every
       background and the report prints as grey text on white. */
    * { -webkit-print-color-adjust: exact; print-color-adjust: exact; box-sizing: border-box; }
    @page { size: A4; margin: 14mm 12mm; }
    body {
        margin: 0;
        padding: 28px 32px 40px 32px;
        font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
        color: ${colours['text-main']};
        background: #FFFFFF;
        font-size: 13px;
        line-height: 1.55;
    }
    header.masthead {
        display: flex; align-items: center; justify-content: space-between;
        gap: 24px; padding-bottom: 16px; margin-bottom: 24px;
        border-bottom: 3px solid ${colours.primary};
    }
    .masthead-id { display: flex; align-items: center; gap: 14px; }
    .masthead-logo { max-height: 56px; max-width: 150px; object-fit: contain; }
    h1 { margin: 0; font-size: 20px; color: ${colours.black}; letter-spacing: -0.01em; }
    .masthead-sub { margin: 2px 0 0 0; font-size: 12px; color: ${colours['text-muted']}; }
    .masthead-meta { text-align: right; font-size: 11px; color: ${colours['text-muted']}; }
    .masthead-meta strong { display: block; font-size: 13px; color: ${colours.black}; }

    .banner {
        background: ${colours['primary-light']};
        border: 1px solid ${colours.primary};
        border-radius: 10px; padding: 18px 20px; margin-bottom: 22px;
    }
    .banner-top { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; flex-wrap: wrap; }
    .banner-figure { font-size: 30px; font-weight: 700; color: ${colours['primary-dark']}; margin: 0; }
    .banner-goal { font-size: 12px; color: ${colours['text-main']}; margin: 0; }
    .track { height: 10px; background: #FFFFFF; border-radius: 999px; margin-top: 12px; overflow: hidden; border: 1px solid rgba(0,0,0,0.06); }
    .track-fill { height: 100%; background: ${colours.primary}; border-radius: 999px; }
    .banner-note { margin: 10px 0 0 0; font-size: 12px; font-weight: 600; color: ${colours['primary-dark']}; }

    .kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 26px; }
    .kpi { border: 1px solid #E2E8F0; border-radius: 10px; padding: 12px 14px; }
    .kpi-label { margin: 0; font-size: 9.5px; text-transform: uppercase; letter-spacing: 0.06em; font-weight: 700; color: ${colours['text-muted']}; }
    .kpi-value { margin: 5px 0 3px 0; font-size: 19px; font-weight: 700; color: ${colours.black}; }
    .kpi-note { margin: 0; font-size: 11px; color: ${colours['text-muted']}; line-height: 1.4; }

    section.block { margin-bottom: 26px; page-break-inside: avoid; }
    section.page-break { page-break-before: auto; page-break-inside: auto; }
    h2 {
        margin: 0 0 10px 0; font-size: 14px; color: ${colours.black};
        border-left: 4px solid ${colours.secondary}; padding-left: 9px;
    }
    .lede { margin: 0 0 10px 0; font-size: 11.5px; color: ${colours['text-muted']}; }

    table { width: 100%; border-collapse: collapse; font-size: 12px; }
    th {
        text-align: left; font-size: 9.5px; text-transform: uppercase; letter-spacing: 0.05em;
        color: ${colours['text-muted']}; border-bottom: 2px solid #E2E8F0; padding: 6px 8px;
    }
    td { padding: 7px 8px; border-bottom: 1px solid #F1F5F9; vertical-align: top; }
    td.num, th.num { text-align: right; white-space: nowrap; }
    td.note { color: ${colours['text-muted']}; font-size: 11px; }
    tbody tr:nth-child(even) { background: #FAFCFD; }

    .prepared-for { display: block; margin-top: 2px; font-weight: 600; color: ${colours['text-main']}; }

    /* The share bar beside each revenue-source percentage. Sits under the number
       in the same cell, so the column still reads as a column of figures. */
    .share-cell { min-width: 86px; }
    .share-track {
        height: 5px; margin-top: 4px; border-radius: 999px;
        background: #EEF2F6; overflow: hidden;
    }
    .share-fill { height: 100%; background: ${colours.primary}; border-radius: 999px; }

    /* The transaction table can run past a page break, so unlike every other
       block it is allowed to split — and its header repeats on each page, which
       is what thead does in a print renderer once the table is not inside a
       page-break-inside: avoid box. */
    .tx-table { page-break-inside: auto; }
    .tx-table thead { display: table-header-group; }
    .tx-table tr { page-break-inside: avoid; }
    .tx-table tfoot td {
        border-top: 2px solid #E2E8F0; border-bottom: 0;
        font-weight: 700; color: ${colours.black};
    }
    td.nowrap { white-space: nowrap; }

    .mini-kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 14px; }
    .mini { border-left: 3px solid ${colours['accent-dark']}; padding-left: 10px; }
    .mini span { display: block; font-size: 16px; font-weight: 700; color: ${colours.black}; }
    .mini small { font-size: 10.5px; color: ${colours['text-muted']}; }
    .caveat { margin: 10px 0 0 0; font-size: 11px; color: ${colours['text-muted']}; font-style: italic; }
    .tx-origin { font-size: 10px; font-weight: 400; color: ${colours['text-muted']}; white-space: nowrap; }

    .prose { font-size: 12.5px; }
    .prose h1, .prose h2, .prose h3 { font-size: 13px; color: ${colours.black}; margin: 16px 0 6px 0; border: 0; padding: 0; }
    .prose p { margin: 0 0 9px 0; }
    .prose ul, .prose ol { margin: 0 0 9px 0; padding-left: 18px; }
    .prose li { margin-bottom: 4px; }
    .plain { white-space: pre-wrap; font-family: inherit; font-size: 12px; margin: 0; }

    footer {
        margin-top: 30px; padding-top: 12px; border-top: 1px solid #E2E8F0;
        font-size: 10.5px; color: ${colours['text-muted']};
    }
</style>
</head>
<body>
    <header class="masthead">
        <div class="masthead-id">
            ${logo ? `<img class="masthead-logo" src="${esc(logo)}" alt="">` : ''}
            <div>
                <h1>${esc(businessName)}</h1>
                <p class="masthead-sub">90-day executive report${ownerName ? ` · ${esc(ownerName)}` : ''}</p>
            </div>
        </div>
        <div class="masthead-meta">
            <strong>${esc(range)}</strong>
            Prepared ${esc(longDate(new Date()))}
            ${preparedForLine ? `<span class="prepared-for">for ${esc(preparedForLine)}</span>` : ''}
        </div>
    </header>

    <div class="banner">
        <div class="banner-top">
            <p class="banner-figure">${money(insights.totalRevenue)}</p>
            <p class="banner-goal">${insights.goal > 0
                ? `of a ${money(insights.goal)} goal · ${insights.progressPercent.toFixed(0)}% · ${esc(insights.momentum)}`
                : 'No 90-day revenue goal set'}</p>
        </div>
        ${insights.goal > 0 ? `<div class="track"><div class="track-fill" style="width: ${barWidth.toFixed(1)}%;"></div></div>` : ''}
        ${goalNote}
    </div>

    <div class="kpis">${kpiHtml}</div>

    ${chartSection}

    ${funnelSection}

    ${sourceSection}

    ${txSection}

    ${pipelineSection}

    ${aiSection}

    <footer>
        Generated by CEO Planner on ${esc(longDate(new Date()))}. Revenue figures cover
        ${esc(range)} and count only entries dated inside the 90 days. Pipeline values are
        forecasts, not income.
    </footer>
</body>
</html>`;
}






function showPdfReportModal() {
    
    
    
    if (!canExportPdf()) return;

    
    
    
    const opts = readReportOptions();
    let preparedFor = readPreparedFor();

    let html;
    try {
        html = buildReportHtml(opts, preparedFor);
    } catch (err) {
        console.error('Report build failed:', err);
        showToast("We couldn't build your report just now. Please try again.", 'error');
        return;
    }

    
    
    
    const sectionsOffered = REPORT_SECTIONS.filter(sec => sec.key !== 'coach' || getAiReport());

    const optionsHtml = sectionsOffered.map(sec => `
        <label class="pdf-report-opt">
            <input type="checkbox" data-section="${sec.key}"${opts[sec.key] ? ' checked' : ''}>
            <span>${esc(sec.label)}</span>
        </label>
    `).join('');

    
    
    
    
    
    
    
    
    
    
    
    
    const store = getStore();
    const brandSet = !!(store.profile?.businessName || store.profile?.name) && !!store.profile?.logo;
    const brandHint = brandSet ? '' : `
        <p class="pdf-report-hint">Your business name and logo sit at the top of every report —
        <a href="#/settings" class="pdf-report-settings-link">add them in Settings</a>.</p>
    `;

    const overlay = document.createElement('div');
    overlay.className = 'confirm-overlay';
    overlay.innerHTML = `
        <div class="confirm-card card pdf-report-card" role="dialog" aria-modal="true" aria-labelledby="pdf-report-title">
            <div class="pdf-report-head">
                <h3 id="pdf-report-title" class="confirm-title" style="margin: 0; display: flex; align-items: center; gap: 0.5rem;">
                    ${proBadge()} Your 90-day report
                </h3>
                <button type="button" class="pdf-report-x" aria-label="Close">&times;</button>
            </div>
            <p class="pdf-report-note">Print it and choose <strong>Save as PDF</strong> as the destination. Everything below is exactly what comes out.</p>
            <div class="pdf-report-options">
                <p class="pdf-report-options-title">What goes in</p>
                <div class="pdf-report-opts">${optionsHtml}</div>
                <label class="pdf-report-prepared">
                    <span>Prepared for <small>(optional)</small></span>
                    <input type="text" class="form-control pdf-report-prepared-input" maxlength="80"
                           placeholder="Your accountant, a partner, a lender" value="${esc(preparedFor)}">
                </label>
                ${brandHint}
            </div>
            <iframe class="pdf-report-frame" title="Report preview"></iframe>
            <div class="confirm-actions pdf-report-actions">
                <button type="button" class="btn btn-outline pdf-report-tab">Open in a new tab</button>
                <button type="button" class="btn btn-primary pdf-report-print">Print or save as PDF</button>
            </div>
        </div>
    `;

    
    let flushPrepared = null;

    const previouslyFocused = document.activeElement;
    const close = () => {
        document.removeEventListener('keydown', onKeydown);
        
        
        if (flushPrepared) flushPrepared();
        overlay.remove();
        if (previouslyFocused && typeof previouslyFocused.focus === 'function') {
            previouslyFocused.focus();
        }
    };
    const onKeydown = (e) => { if (e.key === 'Escape') close(); };
    document.addEventListener('keydown', onKeydown);
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });

    document.body.appendChild(overlay);

    
    
    
    
    const frame = overlay.querySelector('.pdf-report-frame');

    
    
    
    const paint = (docHtml) => {
        try {
            const doc = frame.contentDocument || frame.contentWindow.document;
            doc.open();
            doc.write(docHtml);
            doc.close();
            return true;
        } catch (err) {
            console.error('Report preview failed:', err);
            showToast("We couldn't show the preview. Try 'Open in a new tab'.", 'error');
            return false;
        }
    };

    paint(html);

    
    
    
    
    const rebuild = () => {
        try {
            html = buildReportHtml(opts, preparedFor);
        } catch (err) {
            console.error('Report rebuild failed:', err);
            showToast("We couldn't rebuild your report just now.", 'error');
            return;
        }
        paint(html);
    };

    overlay.querySelectorAll('.pdf-report-opt input[type="checkbox"]').forEach(box => {
        box.addEventListener('change', () => {
            opts[box.dataset.section] = box.checked;
            updateSettings({ reportOptions: { ...opts } });
            rebuild();
        });
    });

    
    
    const preparedInput = overlay.querySelector('.pdf-report-prepared-input');
    let preparedTimer = null;
    let preparedDirty = false;
    preparedInput.addEventListener('input', () => {
        preparedFor = preparedInput.value;
        preparedDirty = true;
        window.clearTimeout(preparedTimer);
        preparedTimer = window.setTimeout(() => {
            preparedDirty = false;
            updateSettings({ reportPreparedFor: preparedFor });
            rebuild();
        }, 400);
    });

    flushPrepared = () => {
        window.clearTimeout(preparedTimer);
        if (preparedDirty) {
            preparedDirty = false;
            updateSettings({ reportPreparedFor: preparedFor });
        }
    };

    const settingsLink = overlay.querySelector('.pdf-report-settings-link');
    if (settingsLink) settingsLink.addEventListener('click', () => close());

    overlay.querySelector('.pdf-report-x').addEventListener('click', close);

    overlay.querySelector('.pdf-report-print').addEventListener('click', () => {
        try {
            frame.contentWindow.focus();
            frame.contentWindow.print();
        } catch (err) {
            console.error('Print failed:', err);
            showToast("Your browser wouldn't open the print dialogue. Try 'Open in a new tab', then print from there.", 'error');
        }
    });

    
    
    
    overlay.querySelector('.pdf-report-tab').addEventListener('click', () => {
        try {
            const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
            const url = URL.createObjectURL(blob);
            const win = window.open(url, '_blank');
            if (!win) {
                showToast('Your browser blocked the new tab. Allow pop-ups for this site and try again.', 'error');
            }
            
            
            setTimeout(() => URL.revokeObjectURL(url), 60000);
        } catch (err) {
            console.error('Report tab failed:', err);
            showToast("We couldn't open the report in a new tab.", 'error');
        }
    });
}















const PERIOD_KEY = 'ceo_perf_months';



function canUsePerformanceReport() {
    return isProUser() && isFeatureLive('performance-report');
}



function savedMonths() {
    try {
        const n = parseInt(localStorage.getItem(PERIOD_KEY), 10);
        return [1, 2, 3].includes(n) ? n : 1;
    } catch (err) {
        return 1;
    }
}

function rememberMonths(n) {
    try { localStorage.setItem(PERIOD_KEY, String(n)); } catch (err) {  }
}

function shortDate(d) {
    return new Date(d).toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
}

function money(currency, n) {
    return currency + formatAmount(Math.round(n));
}



function changeLine(current, previous, weeks) {
    const span = `the ${weeks} weeks before`;
    if (previous <= 0 && current <= 0) return `Nothing in ${span} either`;
    if (previous <= 0) return `Nothing in ${span}`;
    const pct = Math.round(((current - previous) / previous) * 100);
    if (pct === 0) return `Level with ${span}`;
    return `${pct > 0 ? 'Up' : 'Down'} ${Math.abs(pct)}% on ${span}`;
}

function changeTone(current, previous) {
    if (previous <= 0) return 'muted';
    if (current > previous) return 'up';
    if (current < previous) return 'down';
    return 'muted';
}




function weeklyChart(buckets, key, label, fill, colours, format) {
    const W = 600;
    const H = 170;
    const padL = 6;
    const padR = 6;
    const padTop = 22;
    const padBottom = 28;
    const plotH = H - padTop - padBottom;
    const slot = (W - padL - padR) / buckets.length;
    const barW = Math.min(40, slot * 0.62);
    const peak = Math.max(1, ...buckets.map(b => b[key]));
    
    const labelEvery = buckets.length > 9 ? 2 : 1;

    const bars = buckets.map((b, i) => {
        const v = b[key];
        const h = (v / peak) * plotH;
        const x = padL + slot * i + (slot - barW) / 2;
        const y = padTop + plotH - h;
        const showLabel = (buckets.length - 1 - i) % labelEvery === 0;
        return `
            <rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${barW.toFixed(1)}" height="${Math.max(h, v > 0 ? 2 : 0).toFixed(1)}" rx="3"
                  style="fill: ${fill}; opacity: ${b.current ? 0.55 : 1};"></rect>
            ${v > 0 && showLabel ? `<text x="${(x + barW / 2).toFixed(1)}" y="${(y - 5).toFixed(1)}" text-anchor="middle" style="font: 600 10px sans-serif; fill: ${colours.black};">${format(v)}</text>` : ''}
            ${showLabel ? `<text x="${(x + barW / 2).toFixed(1)}" y="${(H - 10).toFixed(1)}" text-anchor="middle" style="font: 600 9px sans-serif; fill: ${colours.muted};">${b.current ? 'This week' : shortDate(b.start)}</text>` : ''}
        `;
    }).join('');

    return `
        <svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="${label} by week">
            <line x1="${padL}" y1="${padTop + plotH}" x2="${W - padR}" y2="${padTop + plotH}" style="stroke: ${colours.axis}; stroke-width: 1;"></line>
            ${bars}
        </svg>
    `;
}

const PAGE_COLOURS = {
    revenue: 'var(--color-secondary)',
    leads: 'var(--color-primary)',
    calls: 'var(--color-accent)',
    black: 'var(--color-black)',
    muted: 'var(--color-text-muted)',
    axis: '#E2E8F0'
};

function printColours() {
    const c = brandColours();
    return {
        revenue: c.secondary,
        leads: c.primary,
        calls: c['accent-dark'],
        black: c.black,
        muted: c['text-muted'],
        axis: '#E2E8F0'
    };
}


function reportBody(report, currency, colours) {
    const { totals, previous, buckets, weeks } = report;
    const nothing = totals.revenue === 0 && totals.leads === 0 && totals.calls === 0;

    const tile = (label, value, current, prev, sub) => `
        <div class="perf-tile">
            <p class="perf-tile-label">${label}</p>
            <p class="perf-tile-value">${value}</p>
            <p class="perf-tile-change perf-${changeTone(current, prev)}">${changeLine(current, prev, weeks)}</p>
            ${sub ? `<p class="perf-tile-sub">${sub}</p>` : ''}
        </div>
    `;

    const callRate = totals.leads > 0 ? Math.round((totals.calls / totals.leads) * 100) : null;

    const tiles = `
        <div class="perf-tiles">
            ${tile('Revenue', money(currency, totals.revenue), totals.revenue, previous.revenue,
                `${totals.sales} sale${totals.sales === 1 ? '' : 's'}`)}
            ${tile('Leads', formatAmount(totals.leads), totals.leads, previous.leads, '')}
            ${tile('Calls', formatAmount(totals.calls), totals.calls, previous.calls,
                callRate === null ? '' : `${callRate}% of your leads booked a call`)}
        </div>
    `;

    if (nothing) {
        return tiles + `
            <p class="perf-empty">Nothing has been logged in these ${weeks} weeks yet. Sales, leads and calls you log on
            Revenue and Pipeline appear here week by week.</p>
        `;
    }

    const chart = (key, label, fill, format) => `
        <div class="perf-chart">
            <p class="perf-chart-title">${label} by week</p>
            ${weeklyChart(buckets, key, label, fill, colours, format)}
        </div>
    `;

    return tiles
        + chart('revenue', 'Revenue', colours.revenue, v => money(currency, v))
        + chart('leads', 'Leads', colours.leads, v => formatAmount(v))
        + chart('calls', 'Calls', colours.calls, v => formatAmount(v));
}

function rangeLine(report) {
    return `${shortDate(report.start)} to today, ${report.weeks} weeks. The lighter bar is this week so far.`;
}

function cardInner(months) {
    const store = getStore();
    const currency = store.settings?.currency || '$';
    const report = getPerformanceReport(months);
    return `
        <div class="perf-head">
            <p class="perf-title">${proCardHeading('performance-report', 'Performance report')}${renderTooltip("Your revenue, leads and calls over the last one, two or three months, drawn week by week and set against the same stretch before it.", "It shows at a glance whether the business is really moving, and the week it stalled if it did.", 'bottom')}</p>
            <div class="perf-controls">
                <div class="perf-periods" role="group" aria-label="Period">
                    ${[1, 2, 3].map(n => `
                        <button type="button" class="perf-seg${n === months ? ' is-on' : ''}" data-perf-months="${n}" aria-pressed="${n === months}">
                            ${n === 1 ? '1 month' : `${n} months`}
                        </button>`).join('')}
                </div>
                <button type="button" class="btn btn-outline btn-sm" id="btn-perf-print">Print</button>
            </div>
        </div>
        <p class="perf-range">${rangeLine(report)}</p>
        ${reportBody(report, currency, PAGE_COLOURS)}
    `;
}



