const PLAN_PROGRESS_STEPS = [
    { at: 0, text: 'Working out what your goal actually takes…' },
    { at: 15, text: 'Sequencing the twelve weeks…' },
    { at: 45, text: 'Writing your weekly actions…' },
    { at: 120, text: 'Still going — this one takes a few minutes, and it is thinking properly.' },
    { at: 240, text: 'Nearly there. Keep this tab open.' },
    
    
    
    
    
    { at: 420, text: 'Longer than usual, and still working. It has not failed — keep this tab open.' }
];










const PLAN_WAIT_HINT = 'This takes several minutes, often more than five, and it is working the whole time. Keep this tab open.';





function startPlanProgress(el) {
    if (!el) return () => {};
    el.innerHTML = `
        <div style="text-align: center;">
            <p id="plan-progress-text" style="margin: 0 0 0.6rem 0; font-weight: 600; color: var(--color-primary-dark);">${PLAN_PROGRESS_STEPS[0].text}</p>
            <div style="height: 6px; background: var(--color-bg-light); border-radius: 999px; overflow: hidden; max-width: 320px; margin: 0 auto;">
                <div id="plan-progress-bar" style="height: 100%; width: 2%; background: var(--color-primary); border-radius: 999px; transition: width 0.5s linear;"></div>
            </div>
            <p style="margin: 0.6rem 0 0 0; font-size: 0.82rem; color: var(--color-text-muted);">${PLAN_WAIT_HINT}</p>
        </div>`;

    const started = Date.now();
    const textEl = el.querySelector('#plan-progress-text');
    const barEl = el.querySelector('#plan-progress-bar');

    planProgressReported = false;

    const tick = setInterval(() => {
        
        
        
        if (planProgressReported) return;
        const seconds = (Date.now() - started) / 1000;
        const step = PLAN_PROGRESS_STEPS.filter(s => seconds >= s.at).pop();
        if (textEl && step && textEl.textContent !== step.text) textEl.textContent = step.text;
        
        
        if (barEl) barEl.style.width = Math.min(95, 2 + 93 * (1 - Math.exp(-seconds / 35))).toFixed(1) + '%';
    }, 500);

    return () => {
        clearInterval(tick);
        planProgressReported = false;
        if (barEl) barEl.style.width = '100%';
    };
}










let planProgressReported = false;

function reportPlanProgress(done, total, label) {
    planProgressReported = true;
    const textEl = document.getElementById('plan-progress-text');
    const barEl = document.getElementById('plan-progress-bar');
    if (textEl) {
        
        textEl.textContent = total > 0 && done < total
            ? `${label}… (step ${done + 1} of ${total})`
            : `${label}…`;
    }
    
    
    if (barEl && total > 0) {
        barEl.style.width = Math.min(95, 4 + 91 * (done / total)).toFixed(1) + '%';
    }
}






function planFailureText(err) {
    const reason = (err && err.reason) || 'connection';
    if (reason === 'auth') {
        return {
            headline: 'Your session expired while the plan was being written.',
            next: 'Sign in again and press Generate — nothing you entered has been lost.'
        };
    }
    if (reason === 'service') {
        return {
            headline: 'The planner is busy or has hit today’s limit.',
            next: 'Nothing was lost. Try again in a few minutes.'
        };
    }
    
    
    
    
    
    
    
    
    
    
    
    if (reason === 'overloaded') {
        return {
            headline: 'The planner ran out of room before it wrote anything down.',
            next: 'Pressing Generate again will usually do the same thing. A shorter 90-day goal, or one with fewer moving parts, gives it less to work out — or leave it with us and we will get the planner back inside its limits.'
        };
    }
    if (reason === 'malformed') {
        return {
            headline: 'The plan came back incomplete, so it was not saved.',
            next: 'Press Generate again — this one usually works on the second go.'
        };
    }
    
    
    
    if (reason === 'timeout') {
        return {
            headline: 'The planner took too long, so the app stopped waiting.',
            next: 'Nothing was saved, and it did count towards today’s AI. Give it a minute, then press Generate again.'
        };
    }
    return {
        headline: 'The connection dropped before your plan came back.',
        next: 'It takes about half a minute, so a sleeping phone or a lost signal will do it. Check your connection and try again.'
    };
}


function planFailureLine(err) {
    const text = planFailureText(err);
    return `${text.headline} ${text.next}`;
}

















async function runPlanRegeneration({ progressEl = null, skipConfirm = false, reason = '' } = {}) {
    if (!skipConfirm) {
        const confirmed = await showConfirm(
            regenerationImpactLines().join(' '),
            { title: 'Rewriting your 90-Day Plan', confirmText: 'I understand, rewrite it' }
        );
        if (!confirmed) return false;
    }

    const stop = startPlanProgress(progressEl);
    try {
        
        
        const plan = await generate90DayActionPlan({
            reason,
            onProgress: progressEl ? reportPlanProgress : undefined
        });
        applyGeneratedPlan(plan, { reason });
        
        
        
        
        showToast('Your 90-Day Plan has been regenerated');
        trackAction('plan.regenerated');
        return true;
    } catch (err) {
        console.error('90-day plan generation failed:', err);
        showToast(planFailureLine(err), 'error', 7000);
        return false;
    } finally {
        stop();
        if (progressEl) progressEl.innerHTML = '';
    }
}


















const REGEN_REASON_MAX = 600;



















function regenerationImpactLines(impact = regenerationImpact()) {
    const lines = [];

    lines.push(impact.replaced.length
        ? `This rewrites ${impact.weeksLabel} of your 90-Day Plan.`
        : 'This writes a fresh set of twelve weeks. Every week you have already started stays exactly as you worked it.');

    if (impact.thisWeekReplaced) {
        lines.push('That includes the week you are in now, so your Weekly Plan and your Daily 3 will be replaced with new ones, and anything you have ticked off this week will not carry over.');
    } else if (impact.replaced.length) {
        lines.push('This week is not one of them. Your Weekly Plan and your Daily 3 stay as they are.');
    }

    const kept = [];
    if (impact.keptApplied) {
        kept.push(impact.keptApplied === 1
            ? 'the week you have already applied'
            : `the ${impact.keptApplied} weeks you have already applied`);
    }
    if (impact.keptOwn) {
        kept.push(impact.keptOwn === 1
            ? 'the plan you wrote yourself'
            : `the ${impact.keptOwn} plans you wrote yourself`);
    }
    if (kept.length) lines.push(`Kept exactly as they are: ${kept.join(', and ')}.`);

    return lines;
}

const REGEN_QUICK_PICKS = [
    "I've already done some of these weeks in my business",
    "It asks for more than my week can take",
    'My goal or focus has changed',
    "It doesn't fit how my business actually works"
];





function askWhyRegenerating() {
    return new Promise((resolve) => {
        const impact = regenerationImpact();
        const warning = regenerationImpactLines(impact);
        const overlay = document.createElement('div');
        overlay.className = 'confirm-overlay';
        overlay.innerHTML = `
            <div class="confirm-card week-regen-card" role="dialog" aria-modal="true" aria-labelledby="regen-why-title">
                <h3 id="regen-why-title" class="confirm-title">Rewriting your 90-Day Plan</h3>
                <div class="regen-impact${impact.thisWeekReplaced ? ' regen-impact-loud' : ''}" role="note">
                    <p class="regen-impact-head">Before you do, here is what this changes</p>
                    ${warning.map(line => `<p class="regen-impact-line">${escapeText(line)}</p>`).join('')}
                </div>
                <p style="font-size: 0.88rem; line-height: 1.55; color: var(--color-text-muted); margin: 0 0 0.9rem 0;">Telling me what's wrong with it is the whole difference between a new plan and the same plan written again. Pick one, or write your own.</p>
                <div id="regen-why-picks" style="display: flex; flex-direction: column; gap: 0.4rem; margin-bottom: 0.9rem;">
                    ${REGEN_QUICK_PICKS.map((text, i) => `
                        <button type="button" class="btn btn-outline btn-sm regen-why-pick" data-pick="${i}" style="text-align: left; justify-content: flex-start;">${text}</button>
                    `).join('')}
                </div>
                <label class="form-label" for="regen-why-note">In your own words <span style="font-weight: 400; color: var(--color-text-muted);">(optional)</span></label>
                <textarea id="regen-why-note" class="form-input" rows="3" maxlength="${REGEN_REASON_MAX}" placeholder="I've already built the offer and priced it, so weeks 1 and 2 are done..."></textarea>
                <p style="font-size: 0.8rem; color: var(--color-text-muted); margin: 0.35rem 0 1.25rem 0;">Anything you've already finished, I'll leave out of the new twelve weeks.</p>
                <div class="confirm-actions">
                    <button type="button" class="btn btn-ghost regen-why-cancel">Cancel</button>
                    <button type="button" class="btn btn-primary regen-why-go">I understand, rewrite it</button>
                </div>
            </div>`;

        const previouslyFocused = document.activeElement;
        const note = overlay.querySelector('#regen-why-note');

        const finish = (value) => {
            document.removeEventListener('keydown', onKeydown);
            overlay.remove();
            if (previouslyFocused && typeof previouslyFocused.focus === 'function') {
                previouslyFocused.focus();
            }
            resolve(value);
        };

        const onKeydown = (e) => { if (e.key === 'Escape') finish(null); };
        document.addEventListener('keydown', onKeydown);
        overlay.addEventListener('click', (e) => { if (e.target === overlay) finish(null); });

        
        
        
        overlay.querySelectorAll('.regen-why-pick').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const text = REGEN_QUICK_PICKS[Number(e.currentTarget.getAttribute('data-pick'))] || '';
                const current = note.value.trim();
                if (current.includes(text)) return;
                note.value = current ? `${current}. ${text}` : text;
                note.focus();
            });
        });

        overlay.querySelector('.regen-why-cancel').addEventListener('click', () => finish(null));
        overlay.querySelector('.regen-why-go').addEventListener('click', () => {
            finish(note.value.trim().slice(0, REGEN_REASON_MAX));
        });

        document.body.appendChild(overlay);
        note.focus();
    });
}







const refitsInFlight = {};



















const REFIT_WAIT_MS = 12000;





const refitWaitOver = {};





const refitDiscard = {};

function runWeekRefit(week) {
    if (!week || !week.id) return Promise.resolve(null);
    if (refitsInFlight[week.id]) return refitsInFlight[week.id];
    refitsInFlight[week.id] = refitWeekToReality(week).then(result => {
        if (refitDiscard[week.id]) {
            delete refitDiscard[week.id];
            
            
            
            
            
            
            
            
            
            
            
            
            
            markWeekRefitFailed(week.id);
            return null;
        }
        if (result) applyWeekRefit(week.id, result.fields, result.changed);
        else markWeekRefitFailed(week.id);
        return result;
    }).finally(() => { delete refitsInFlight[week.id]; });
    return refitsInFlight[week.id];
}


function stopWaitingForRefit(weekId) {
    if (weekId) refitWaitOver[String(weekId)] = true;
}


function shouldRefitNow(week) {
    if (!week || refitWaitOver[String(week.id)]) return false;
    return typeof window.invokeChat === 'function' && weekNeedsRefit(week);
}



const refitWaitStops = {};












function startRefitWait(week, onDone) {
    if (!week || !week.id) return;
    const key = String(week.id);
    let finished = false;
    const finish = (repaint) => {
        if (finished) return;
        finished = true;
        clearTimeout(timer);
        delete refitWaitStops[key];
        if (repaint && typeof onDone === 'function') onDone();
    };
    const timer = setTimeout(() => {
        refitWaitOver[key] = true;
        finish(true);
    }, REFIT_WAIT_MS);
    refitWaitStops[key] = () => finish(false);
    runWeekRefit(week).finally(() => finish(true));
}






function refitBeforeApply(week) {
    if (!week || !week.id) return Promise.resolve(null);
    const key = String(week.id);
    return new Promise(resolve => {
        let settled = false;
        const done = (value) => { if (!settled) { settled = true; resolve(value); } };
        const timer = setTimeout(() => {
            refitDiscard[key] = true;
            done(null);
        }, REFIT_WAIT_MS);
        runWeekRefit(week).then(result => {
            clearTimeout(timer);
            done(result);
        }).catch(() => {
            clearTimeout(timer);
            done(null);
        });
    });
}

