function wireCalendarPrompt() {
    const modal = document.getElementById('calendar-prompt-modal');
    if (!modal) return;

    
    markCalendarPrompted();

    const close = () => modal.remove();
    document.getElementById('btn-calendar-prompt-no')?.addEventListener('click', close);
    
    
    document.getElementById('btn-calendar-prompt-yes')?.addEventListener('click', close);
    
    
    modal.addEventListener('click', (e) => { if (e.target === modal) close(); });
}





