function wizardResumeStep(store) {
    const p = (store && store.profile) || {};
    if (p.trialStartDate) return 1;
    const saved = parseInt(p.wizardStep, 10);
    if (saved >= 2 && saved <= TOTAL_STEPS - 1) return saved;
    if (p.strategyMode) return 6;
    if (p.bottleneck) return 5;
    if (store && store.goals && store.goals.focus) return 4;
    return 1;
}



