function wizFocusChecks(text) {
    const t = String(text || '');
    const oneThing = t.trim().length > 0 && t.length <= 160 && (t.match(/,| and /g) || []).length <= 2;
    const hasNumber = /[0-9]/.test(t);
    return [['One clear outcome', oneThing], ['Has a number you can count', hasNumber]].map(([label, on]) =>
        `<span class="wiz-check${on ? ' is-on' : ''}">${on ? '✓' : '○'} ${label}</span>`
    ).join('');
}

function wizIcon(d, size = 20) {
    return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${d}"></path></svg>`;
}

