function renderLastCycleEvidence() {
    const store = getStore();
    const history = previousPlanRecord(store);
    if (!history.cycles) return '';

    const rows = [];
    if (history.lastChange) {
        rows.push(['What you said you would change', history.lastChange]);
    }
    if (history.lastWorked) {
        rows.push(['What you said worked', history.lastWorked]);
    }
    if (history.built.length) {
        rows.push(['Already built, so it does not need building again',
            history.built.map(b => b.component).join(', ')]);
    }
    if (history.deferred.length) {
        rows.push(['Left for later by your last plan',
            history.deferred.map(d => d.component).join(', ')]);
    }
    if (!rows.length) return '';

    return `
        <section class="card wiz-evidence" id="wiz-evidence">
            <p class="wiz-evidence-label">From your last 90 days</p>
            <dl class="wiz-evidence-list">
                ${rows.map(([k, v]) => `
                <div class="wiz-evidence-row">
                    <dt>${escapeText(k)}</dt>
                    <dd>${escapeText(v)}</dd>
                </div>`).join('')}
            </dl>
            <p class="wiz-evidence-note">This is here to help you choose, not to choose for you. Your focus below is yours to write, and the plan is built around whatever you put in it.</p>
        </section>
    `;
}

