function renderWizard() {
    window.setScreenModule({ attachEvents: wizardAttachEvents });
    
    if (!getStore().goals?.focus && currentStep === TOTAL_STEPS) currentStep = 1;

    
    if (!resumeChecked) {
        resumeChecked = true;
        if (currentStep === 1) currentStep = wizardResumeStep(getStore());
    }

    
    
    
    
    
    
    
    
    if (!startedCounted && currentStep === 1 && !getStore().goals?.focus) {
        startedCounted = true;
        trackAction('setup.started');
    }

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    if (!stepsCounted.has(currentStep)) {
        stepsCounted.add(currentStep);
        trackAction('setup.step' + currentStep);
    }

    const pct = Math.round(currentStep / TOTAL_STEPS * 100);
    return `
        <div class="wiz">
            <aside class="wiz-side">
                <span class="wiz-side-dot wiz-side-dot-white" aria-hidden="true"></span>
                <span class="wiz-side-dot wiz-side-dot-pink" aria-hidden="true"></span>
                <span class="wiz-side-dot wiz-side-dot-yellow" aria-hidden="true"></span>
                <div class="wiz-brand"><span class="wiz-mark" aria-hidden="true"><span></span></span>CEO Planner</div>
                <div class="wiz-side-title">
                    <p class="wiz-side-eyebrow">Build your</p>
                    <h2 class="wiz-side-h">90-Day CEO Plan</h2>
                </div>
                <ol class="wiz-steps">
                    ${WIZ_STEP_NAMES.map((name, i) => {
                        const n = i + 1;
                        const state = n < currentStep ? 'is-done' : n === currentStep ? 'is-now' : 'is-todo';
                        return `<li class="wizard-step ${state}"${n === currentStep ? ' aria-current="step"' : ''}><span class="wiz-step-badge">${n < currentStep ? '✓' : n}</span><span class="wiz-step-name">${name}</span></li>`;
                    }).join('')}
                </ol>
                <div class="wiz-side-foot">
                    <!-- ⚠️ Jen, 30 Sept 2026, from her own run: "it's taking quite
                         a bit longer than that". It said "About 5 minutes" here
                         and "(3 mins)" on the dashboard's setup banner, so the app
                         disagreed with itself as well as with the clock. Nine
                         steps, two of them multi-field, then a ~30 second plan
                         generation -- and this is a founder deciding her 90-day
                         focus and her revenue targets, which is thinking time, not
                         typing time. Under-promising here is what makes somebody
                         abandon halfway: they budgeted five minutes.
                         ⚠️ 10 is an ESTIMATE pending Jen's real figure. If she
                         times it, put her number here and on the banner. -->
                    <p>About 10 minutes, plus a few more at the end while your plan is written. You can change any answer later in Settings.</p>
                    <!--
                        ACC-17, 17 Sept 2026. The wizard has no nav, and the router
                        sends every route back here until setup is done, so there was
                        no way out: Jen had to answer every question to leave it.
                        id="nav-logout" on purpose, so the delegated handler in app.js
                        (bindGlobalNavEvents) signs out exactly as the sidebar does.
                    -->
                    <p><a href="#/login" id="nav-logout" class="wiz-signout">Sign out</a></p>
                </div>
            </aside>

            <main class="wiz-main">
                <div class="wiz-progress">
                    <p class="wiz-progress-label">Step ${currentStep} of ${TOTAL_STEPS}<span class="wiz-progress-name"> · ${WIZ_STEP_NAMES[currentStep - 1]}</span></p>
                    <div class="wiz-bar" aria-hidden="true"><span style="width: ${pct}%;"></span></div>
                </div>
                <div id="wizard-content" class="wiz-content">
                    ${renderStepContent()}
                </div>
            </main>
        </div>
    `;
}

function renderStepContent() {
    const store = getStore();
    const g = store.goals;

    if (currentStep === 1) {
        return `
            <div class="wiz-hello">
                ${erasureNotice(store)}
                ${afterSetupNotice()}
                ${homeScreenPromptHtml()}
                <span class="wiz-hello-icon" aria-hidden="true"><svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"></circle><circle cx="12" cy="12" r="5"></circle><circle cx="12" cy="12" r="1.5" fill="currentColor"></circle></svg></span>
                <h1 class="wiz-hello-title">Welcome to<br>CEO Planner</h1>
                <p class="wiz-hello-sub">Let's set your 90-day goal. It takes a few minutes and unlocks your personalised Daily 3 action plan.</p>
                <div class="wiz-value-grid">
                    <div class="card wiz-value wiz-value-teal">
                        <span class="wiz-tone wiz-tone-teal">${wizIcon('M12 3a9 9 0 1 0 0 18a9 9 0 1 0 0-18zM12 8a4 4 0 1 0 0 8a4 4 0 1 0 0-8z')}</span>
                        <p class="wiz-value-title">Set your 90-day goal</p>
                        <p class="wiz-value-sub">One clear focus, so you stop idea-hopping.</p>
                    </div>
                    <div class="card wiz-value wiz-value-pink">
                        <span class="wiz-tone wiz-tone-pink">${wizIcon('M5 5h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2zM3 10h18M8 3v4M16 3v4')}</span>
                        <p class="wiz-value-title">Get twelve weeks, mapped out</p>
                        <p class="wiz-value-sub">Your plan, built week by week from your answers.</p>
                    </div>
                    <div class="card wiz-value wiz-value-yellow">
                        <span class="wiz-tone wiz-tone-yellow">${wizIcon('M5 12l5 5 9-10')}</span>
                        <p class="wiz-value-title">Unlock your Daily 3</p>
                        <p class="wiz-value-sub">Three actions a day that move the needle.</p>
                    </div>
                </div>
                <form id="wizard-form-1">
                    <button type="submit" class="btn btn-primary wiz-btn-big">Let's Begin →</button>
                </form>
            </div>
        `;
    }

    if (currentStep === 2) {
        return `
            <div class="wiz-head">
                <h1 class="wiz-title">CEO Profile Setup</h1>
                <p class="wiz-sub">Set up your basic business identity and daily commitment.</p>
            </div>

            <form id="wizard-form-2" class="wiz-form">
                <section class="card wiz-card">
                    <div class="wiz-grid-2">
                        <div class="wiz-field">
                            <label class="form-label" for="set-name">Your Name</label>
                            <input type="text" id="set-name" class="form-input" value="${escapeText(store.profile.name || '')}" placeholder="Enter your name" required>
                        </div>
                        <div class="wiz-field">
                            <label class="form-label" for="set-biz">Business Name</label>
                            <input type="text" id="set-biz" class="form-input" value="${escapeText(store.profile.businessName || '')}" placeholder="Enter your business name" required>
                        </div>
                    </div>
                    <div class="wiz-field">
                        <label class="form-label" for="set-logo-url">Business Logo / Image</label>
                        <!-- Both elements always rendered, one hidden, see the
                             note on the same block in settings.js (batch item 16).
                             The wizard has the identical shape, and it is where an
                             uploaded photo lands first, so the way out belongs
                             here too. -->
                        <div class="wiz-logo-row">
                            <div class="wiz-logo-box">
                                <span id="logo-preview-placeholder" style="${store.profile.logo ? 'display: none; ' : ''}">${wizIcon('M12 5v14M5 12h14', 22)}</span>
                                <img src="${store.profile.logo || ''}" id="logo-preview-img" alt="" style="${store.profile.logo ? '' : 'display: none; '}">
                            </div>
                            <input type="text" id="set-logo-url" class="form-input" value="${escapeText(store.profile.logo && store.profile.logo.startsWith('http') ? store.profile.logo : '')}" placeholder="Paste Image URL..." aria-label="Image URL">
                            <label for="set-logo-file" class="btn btn-outline btn-sm wiz-upload">Upload File</label>
                            <input type="file" id="set-logo-file" accept="image/*" style="display: none;">
                            <input type="hidden" id="set-logo-base64" value="${escapeText(store.profile.logo && store.profile.logo.startsWith('data:image') ? store.profile.logo : '')}">
                            <button type="button" id="btn-remove-logo" class="btn btn-ghost btn-sm wiz-remove" style="${store.profile.logo ? 'display: inline-flex; ' : 'display: none; '}">Remove</button>
                        </div>
                        <p class="wiz-hint">Recommended: Paste an Image URL or Upload a File.</p>
                    </div>
                </section>

                <section class="soft-panel wiz-soft">
                    <label class="wiz-flabel" for="set-commitment">Your CEO commitment <span class="wiz-optional">(optional)</span></label>
                    <p class="wiz-hint">
                        One sentence about <em>how</em> you want to work these 90 days, not what you want to achieve.
                        It sits on your dashboard every day as a reminder of the promise you made yourself.
                        Most people write about the habit they keep breaking. You can change it any time in Settings.
                    </p>
                    <p class="wiz-example"><strong>Example:</strong> <em>"I commit to protecting two deep-work mornings a week, no matter what the inbox says."</em></p>
                    <textarea id="set-commitment" class="form-input" placeholder="I commit to doing my top tasks before I check email, and to trusting the plan I set.">${escapeText(store.goals.statement || '')}</textarea>
                </section>
                ${wizNav()}
            </form>
        `;
    }

    if (currentStep === 3) {
        return `
            <div class="wiz-head">
                <h1 class="wiz-title">Define your 90-Day Focus</h1>
                <p class="wiz-sub">What is the ONE main objective you are driving towards? A tight focus prevents idea-hopping.</p>
            </div>

            <form id="wizard-form-3" class="wiz-form wiz-form-tight">
                <div class="wiz-block">
                    <p class="wiz-flabel wiz-numbered"><span class="wiz-num">1</span>What kind of goal is it?</p>
                    <div class="wiz-gtypes">
                        ${WIZ_GOAL_TYPES.map((t, i) => `
                        <button type="button" class="wiz-gtype" data-gt="${i}" aria-pressed="false">
                            <span class="wiz-tone wiz-tone-${t.tone} wiz-tone-sm">${wizIcon(t.d, 18)}</span>
                            <strong>${t.label}</strong>
                        </button>`).join('')}
                    </div>
                </div>

                <div class="wiz-block">
                    <p class="wiz-flabel wiz-numbered"><span class="wiz-num">2</span>Pick an example to start from, then make it yours</p>
                    <div id="wiz-examples" class="wiz-examples">
                        <p class="wiz-empty">Tap a goal type above and three ready-made examples appear here.</p>
                    </div>
                </div>

                ${renderLastCycleEvidence()}

                <section class="hero wiz-focus-hero">
                    <div class="hero-bg" aria-hidden="true"><span class="hero-dot wiz-focus-dot"></span></div>
                    <label for="goal-focus" class="wiz-focus-label"><span class="wiz-num wiz-num-light">3</span>What's your main focus for the next 90 days?</label>
                    <p class="wiz-focus-pattern">Try this pattern: <strong>I will</strong> [do what] <strong>so that I reach</strong> [a number] <strong>by day 90.</strong></p>
                    <textarea class="form-input" id="goal-focus" rows="2" placeholder="e.g., Launch Signature Course, Double Email List" required>${escapeText(g.focus || '')}</textarea>
                    <div class="wiz-checks">
                        <span id="wiz-focus-checks" class="wiz-checks-list">${wizFocusChecks(g.focus || '')}</span>
                        <span class="wiz-checks-tip">Tip: choose something that is mostly in your control, like sales calls you book rather than followers you gain.</span>
                    </div>
                </section>
                ${wizNav()}
            </form>
        `;
    }

    if (currentStep === 4) {
        return `
            <div class="wiz-head">
                <h1 class="wiz-title">Tell Us About Your Business</h1>
                <p class="wiz-sub">Knowing your model, niche, audience, and bottleneck helps the Executive AI Coach tailor all recommendations and content hooks directly to you.</p>
            </div>

            <form id="wizard-form-4" class="wiz-form">
                <section class="card wiz-card wiz-grid-2">
                    <div class="wiz-field">
                        <label class="form-label" for="biz-model">What kind of business is it?</label>
                        <select class="form-input" id="biz-model" required>
                            <option value="Coaching/Consulting" ${store.profile.businessModel === 'Coaching/Consulting' ? 'selected' : ''}>Coaching / Consulting</option>
                            <option value="Agency/Service Provider" ${store.profile.businessModel === 'Agency/Service Provider' ? 'selected' : ''}>Agency / Service Provider</option>
                            <option value="SaaS/Software" ${store.profile.businessModel === 'SaaS/Software' ? 'selected' : ''}>SaaS / Software</option>
                            <option value="E-commerce/Physical Products" ${store.profile.businessModel === 'E-commerce/Physical Products' ? 'selected' : ''}>E-commerce / Physical Products</option>
                            <option value="Creator/Info Products" ${store.profile.businessModel === 'Creator/Info Products' ? 'selected' : ''}>Creator / Info Products</option>
                            <option value="Other" ${store.profile.businessModel === 'Other' ? 'selected' : ''}>Other</option>
                        </select>
                    </div>
                    <div class="wiz-field">
                        <label class="form-label" for="biz-bottleneck">What is the one thing most getting in your way right now?</label>
                        <input type="text" class="form-input" id="biz-bottleneck" value="${escapeText(store.profile.bottleneck || '')}" placeholder="e.g. not enough people know I exist, people book calls but do not buy, I run out of time to sell" required />
                        <div class="wiz-presets">
                            ${['Sales Conversion', 'Lead Generation', 'Delivery Overwhelm', 'Offer/Niche Fit', 'Marketing Routine'].map(v =>
                                `<button type="button" class="wiz-preset btn-wizard-bottleneck-preset" data-value="${v}">${v}</button>`).join('')}
                        </div>
                        <p class="wiz-hint">What is the main constraint holding your business back?</p>
                    </div>
                    <div class="wiz-field wiz-span-2">
                        <label class="form-label" for="industry-niche">What industry or niche are you in?</label>
                        <textarea class="form-input" id="industry-niche" rows="2" placeholder="e.g., Business Coaching, Fitness, B2B Copywriting, E-commerce Fashion" required>${escapeText(store.profile.industryNiche || '')}</textarea>
                    </div>
                    <div class="wiz-field wiz-span-2">
                        <label class="form-label" for="target-audience">Who is your ideal client / target audience?</label>
                        <textarea class="form-input" id="target-audience" rows="2" placeholder="e.g., women who have just left a job and want their first paying client" required>${escapeText(store.profile.targetAudience || '')}</textarea>
                    </div>
                    <div class="wiz-field wiz-span-2">
                        <label class="form-label" for="offer-promise">In one sentence, what does your offer promise them? <span class="wiz-optional">(optional)</span></label>
                        <textarea class="form-input" id="offer-promise" rows="2" placeholder="e.g., I help career-changers land their first paying client in 60 days, without an audience">${escapeText(store.profile.offerPromise || '')}</textarea>
                        <p class="wiz-hint">This is the sentence your market actually hears, so your coach and your plan are written around it. Leave it blank if it is not clear yet, and your plan will give you a week to work it out.</p>
                    </div>
                </section>
                ${wizNav()}
            </form>
        `;
    }

    if (currentStep === 5) {
        const currentStage = store.profile.stage || '';
        const currentMode = store.profile.strategyMode || '';
        const choice = (name, value, label, hint, icon, checked) => `
                        <label class="wiz-choice">
                            <input type="radio" name="${name}" value="${value}" ${checked ? 'checked' : ''} required class="wiz-choice-input">
                            <span class="wiz-tone wiz-tone-${icon[1]}">${wizIcon(icon[0])}</span>
                            <strong class="wiz-choice-label">${label}</strong>
                            <span class="wiz-choice-hint">${hint}</span>
                            <span class="wiz-choice-tick" aria-hidden="true">✓</span>
                        </label>`;
        return `
            <div class="wiz-head">
                <h1 class="wiz-title">Where You Are &amp; How You'll Play It</h1>
                <p class="wiz-sub">These two answers shape your entire 90-day plan: how hard each week pushes, and what kind of actions it asks for.</p>
            </div>

            <form id="wizard-form-5" class="wiz-form">
                <fieldset class="wiz-fieldset">
                    <legend class="wiz-flabel">What stage is your business at?</legend>
                    <div class="wiz-choices wiz-choices-3">
                        ${BUSINESS_STAGES.map((s, i) => choice('biz-stage', s.value, s.value, s.hint, WIZ_STAGE_ICONS[s.value] || ['', 'grey'], currentStage === s.value || (!currentStage && i === 0))).join('')}
                    </div>
                </fieldset>

                <fieldset class="wiz-fieldset">
                    <legend class="wiz-flabel">Which describes these 90 days best?</legend>
                    <div class="wiz-choices wiz-choices-2">
                        ${STRATEGY_MODES.map((m, i) => choice('strategy-mode', m.value, m.label, m.hint, WIZ_MODE_ICONS[m.value] || ['', 'grey'], currentMode === m.value || (!currentMode && i === 0))).join('')}
                    </div>
                </fieldset>
                ${wizNav(undefined, 'You can change this later in Settings.')}
            </form>
        `;
    }

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    if (currentStep === 6) {
        const p = store.profile || {};
        const currentDays = parseInt(p.workingDaysPerWeek, 10);
        const currentBusinessDays = businessDayNames(store);
        
        
        
        const currentHours = parseInt(p.hoursPerDay, 10);
        return `
            <div class="wiz-head">
                <h1 class="wiz-title">How You Work, And What You Already Have</h1>
                <!-- ⚠️ The COUNT, kept honest. This said "Five" while the step
                     already asked six — the working-days question was added
                     later and the sentence was not. Seven on 2 Nov 2026 when
                     the planning day joined it, and EIGHT since 3 Nov: the
                     hours question was added and the working-days band was
                     replaced by the named days rather than added to, so the
                     step grew by one question and not by two. Jen's rule from
                     the 10-minute estimate in the sidebar: under-promising the
                     effort is what makes somebody abandon halfway. -->
                <p class="wiz-sub">Eight quick questions, no typing. They stop your plan asking you to follow up with contacts you don't have, or to work five days when you have three. There are no wrong answers here, nothing is compared to anyone else, and honest beats impressive every time.</p>
            </div>

            <form id="wizard-form-6" class="wiz-form">
                <section class="card wiz-card wiz-how">
                ${ASSET_QUESTIONS.map((q, qi) => {
                    const current = p[q.field] || '';
                    return `
                    <fieldset class="wiz-how-row">
                        <legend class="wiz-how-q"><span class="wiz-num">${qi + 1}</span>${q.question}</legend>
                        <div class="wiz-pills">
                            ${q.options.map((o, i) => `
                            <label class="wiz-pill${o.hint ? ' has-hint' : ''}">
                                <input type="radio" name="${q.name}" value="${o.value}" ${current === o.value ? 'checked' : ''} required class="wiz-pill-input">
                                <span class="wiz-pill-label">${o.value}</span>
                                ${o.hint ? `<span class="wiz-pill-hint">${o.hint}</span>` : ''}
                            </label>
                            `).join('')}
                        </div>
                    </fieldset>
                    `;
                }).join('')}

                    <!-- ⚠️ THIS REPLACED "How many days a week do you work on
                         your business?" on 3 Nov 2026, it did not join it. The
                         band ('3 to 4 days') and a list of named days are the
                         same question asked twice, and two answers that can
                         disagree is exactly what Jen said to avoid. The count
                         is derived from the ticks on save, so the Focus Score
                         and everything else downstream read what they always
                         did.
                         ⚠️ THE WORDING IS LOAD-BEARING. Not "available days",
                         not "working days": both read either way to someone
                         with an employed job. Jen is at Devonshire on Mondays
                         and Wednesdays, so for her those are the two days this
                         question must NOT collect.
                         ⚠️ Not required, and nothing pre-ticked. The planning
                         day question below set that precedent on 2 Nov — the
                         wizard is where people give up — and a pre-ticked
                         default here would be the app guessing which days
                         somebody is free, which is the whole failure. -->
                    <fieldset class="wiz-how-row">
                        <legend class="wiz-how-q"><span class="wiz-num">${ASSET_QUESTIONS.length + 1}</span>Which days do you work on your business?</legend>
                        <div class="wiz-pills" id="wiz-business-days">
                            ${DAY_NAMES.map(d => `
                            <label class="wiz-pill">
                                <input type="checkbox" name="business-days" value="${d}" ${currentBusinessDays.includes(d) ? 'checked' : ''} class="wiz-pill-input">
                                <span class="wiz-pill-label">${d.slice(0, 3)}</span>
                            </label>
                            `).join('')}
                        </div>
                        <p class="wiz-hint wiz-how-note" id="wiz-business-days-echo">${wizardDaysEcho(currentBusinessDays)}</p>
                    </fieldset>

                    <fieldset class="wiz-how-row">
                        <legend class="wiz-how-q"><span class="wiz-num">${ASSET_QUESTIONS.length + 2}</span>On one of those days, how long do you have for the business?</legend>
                        <div class="wiz-pills">
                            ${BUSINESS_HOURS_OPTIONS.map(h => `
                            <label class="wiz-pill">
                                <input type="radio" name="hours-per-day" value="${h.value}" ${currentHours === h.value ? 'checked' : ''} class="wiz-pill-input">
                                <span class="wiz-pill-label">${h.label}</span>
                            </label>
                            `).join('')}
                        </div>
                        <p class="wiz-hint wiz-how-note">Your Daily 3 is sized to this, so say what you really have rather than the day you wish you had.</p>
                    </fieldset>

                    <!-- Added 2 Nov 2026. See PLANNING_DAY_OPTIONS in store.js for
                         the evidence: this was a store default nobody was ever
                         shown, and the two people who had found it in Settings
                         were the only two with a planning streak.
                         ⚠️ Monday stays pre-selected and this is NOT required
                         with nothing ticked — the wizard is already where people
                         give up, so the fix is making the question visible, not
                         compulsory. -->
                    <fieldset class="wiz-how-row">
                        <legend class="wiz-how-q"><span class="wiz-num">${ASSET_QUESTIONS.length + 3}</span>Which day do you want to plan your week on?</legend>
                        <div class="wiz-pills">
                            ${PLANNING_DAY_OPTIONS.map(day => `
                            <label class="wiz-pill">
                                <input type="radio" name="planning-day" value="${day}" ${(p.planningDay || 'Monday') === day ? 'checked' : ''} class="wiz-pill-input">
                                <span class="wiz-pill-label">${day}</span>
                            </label>
                            `).join('')}
                        </div>
                        <p class="wiz-hint wiz-how-note">This is when your plan asks you to set the week up, and when your Weekly Review lands. Plenty of people plan on a Sunday rather than fight Monday morning. You can change it later in Settings.</p>
                    </fieldset>
                </section>
                ${wizNav(undefined, 'You can change any of these later in Settings.')}
            </form>
        `;
    }

    if (currentStep === 7) {
        const cur = store.settings?.currency || '$';
        return `
            <div class="wiz-head">
                <h1 class="wiz-title">Financial Targets</h1>
                <p class="wiz-sub">Set a clear, measurable milestone for this 90-day period. These drive your progress bars, your pace alerts, and the number of sales your plan asks for.</p>
            </div>

            <form id="wizard-form-7" class="wiz-form">
                <section class="card wiz-card">
                    <div class="wiz-field wiz-currency">
                        <label class="form-label" for="set-currency">Which currency do you work in?</label>
                        <select class="form-input" id="set-currency" required>
                            ${CURRENCIES.map(c => `<option value="${c.symbol}" ${cur === c.symbol ? 'selected' : ''}>${c.label}</option>`).join('')}
                        </select>
                    </div>

                    <div class="wiz-grid-3">
                        <div class="wiz-field">
                            <label class="form-label" for="rev-goal">How much do you want to earn in the next 90 days?</label>
                            <div class="wiz-money">
                                <span class="currency-prefix">${cur}</span>
                                <input type="number" class="form-input" id="rev-goal" value="${store.revenue?.quarterlyGoal || ''}" min="0" step="any" placeholder="e.g., 15000" required />
                            </div>
                            <!-- Batch items 7 and 38. The same number a month and a week
                                 at a time, and a note if the focus she typed on step 3 is
                                 written in a different currency to the one she just
                                 picked. Both update as she types, because the point is
                                 that she sees them while she can still change her mind. -->
                            <div id="rev-goal-breakdown"></div>
                        </div>

                        <div class="wiz-field">
                            <label class="form-label" for="offer-price">What does your main offer sell for?</label>
                            <div class="wiz-money">
                                <span class="currency-prefix">${cur}</span>
                                <input type="number" class="form-input" id="offer-price" value="${store.revenue?.averageOfferPrice || ''}" min="0" step="any" placeholder="e.g., 500" required />
                            </div>
                            <p class="wiz-hint">Used to work out how many sales your target needs. A rough average is fine.</p>
                        </div>

                        <div class="wiz-field">
                            <label class="form-label" for="lead-goal">How many new leads do you want in the next 90 days?</label>
                            <input type="number" class="form-input" id="lead-goal" value="${store.leads?.quarterlyGoal || ''}" min="0" step="1" placeholder="e.g., 30" required />
                            <!-- The app's own definition, which until 22 Sept 2026
                                 only the planner prompt ever said out loud. The
                                 banner below now counts in leads, so the word has
                                 to mean something definite on this screen. -->
                            <p class="wiz-hint">${LEAD_DEFINITION} If you are not sure, pick something modest.</p>
                            <!-- Filled by updateHint() once a revenue target and
                                 an offer price exist, so the lead goal can be
                                 checked against the leads they need. -->
                            <p class="wiz-hint wiz-lead-note" id="lead-goal-note"></p>
                        </div>
                    </div>
                </section>

                <!-- Filled by updateHint() in wizardAttachEvents as she types. -->
                <section class="hero wiz-calc" id="sales-required-hint" aria-live="polite">
                    <div class="hero-bg" aria-hidden="true"><span class="hero-dot wiz-calc-dot"></span></div>
                    <div class="wiz-calc-main">
                        <p class="wiz-calc-eyebrow">What your target means</p>
                        <p class="wiz-calc-line" id="wiz-calc-line">Add your target and your offer price to see how many sales it takes.</p>
                        <p class="wiz-calc-more" id="wiz-calc-more"></p>
                    </div>
                    <div class="wiz-calc-fig"><p class="wiz-calc-num" id="wiz-calc-sales">–</p><p class="wiz-calc-cap" id="wiz-calc-sales-cap">sales in 90 days</p></div>
                    <!-- ⚠️ This tile was "N a week" and the number was SALES a
                         week, while the sentence beside it gave CONVERSATIONS a
                         week. Two unlabelled weekly figures, and at £2,000 on a
                         £1,000 offer they both come out as 1, which is how it
                         survived to 22 Sept 2026. At £15,000 on a £500 offer the
                         banner read "roughly 9 a week" next to a big 3. It now
                         shows the quarter's units, captioned with their name,
                         and updateHint() writes both. -->
                    <div class="wiz-calc-fig"><p class="wiz-calc-num" id="wiz-calc-units">–</p><p class="wiz-calc-cap" id="wiz-calc-units-cap">conversations in 90 days</p></div>
                </section>
                ${wizNav()}
            </form>
        `;
    }

    if (currentStep === 8) {
        const prio = (n, tone, placeholder) => `
                    <div class="card wiz-prio">
                        <span class="wiz-prio-num wiz-prio-${tone}">${n}</span>
                        <div class="wiz-field wiz-grow">
                            <label class="form-label" for="p${n}">Priority ${n}</label>
                            <input type="text" class="form-input" id="p${n}" value="${escapeText(g.priorities[n - 1] || '')}" placeholder="${placeholder}" required />
                        </div>
                    </div>`;
        
        
        
        
        
        
        
        
        
        const focusText = (g.focus || '').trim();
        return `
            <div class="wiz-head">
                <h1 class="wiz-title">Choose Your Top 3 Priorities</h1>
                <p class="wiz-sub">Your focus is <strong>what you want to be true by day 90</strong>. Your priorities are <strong>the three pieces of work that get you there</strong>.</p>
            </div>

            <form id="wizard-form-8" class="wiz-form">
                ${focusText ? `
                <section class="card wiz-recall">
                    <p class="wiz-recall-label">Your 90-day focus, from step 3</p>
                    <p class="wiz-recall-focus">${escapeText(focusText)}</p>
                    <p class="wiz-recall-note">That is the destination. It does not go in the boxes below — the three priorities are how you get to it.</p>
                </section>
                ` : ''}

                <section class="card wiz-explain">
                    <p class="wiz-explain-title">What makes something a priority</p>
                    <p>A priority is a big piece of work you will build or run across the whole 90 days, like an offer, a way of getting in front of people, or a routine you keep. It is not a task and it is not a number. If you could finish it in an afternoon it is a task, and your plan will create those for you.</p>
                    <p class="wiz-explain-eg"><strong>For example,</strong> if your focus is <em>"Sign 5 new coaching clients by day 90"</em>, that is the outcome. The three priorities behind it might be <em>build a simple page that explains the offer</em>, <em>run a weekly outreach routine</em>, and <em>host a monthly live workshop</em>. None of those is the goal; together they produce it.</p>
                    <p class="wiz-explain-note">Three is the limit on purpose. Your 90-day plan breaks these into twelve weeks, and the weeks into daily actions.</p>
                </section>

                ${renderCarriedPriority()}

                <div class="wiz-prios">
                    ${prio(1, 'teal', 'e.g., Build course sales page')}
                    ${prio(2, 'pink', 'e.g., Map out 4-week launch email sequence')}
                    ${prio(3, 'yellow', 'e.g., Host weekly IG live Q&As')}
                </div>
                <div class="wiz-nav" id="wizard-step-8-buttons">
                    <button type="button" class="btn btn-outline" id="btn-back">← Back</button>
                    <button type="submit" class="btn btn-primary wiz-btn-generate" id="btn-complete-setup">✨ Generate My 90-Day Plan</button>
                </div>
                <!-- Batch item 12. This said "about 20 seconds" over a bare
                     spinner; the real measurement from the edge function logs is
                     31-36 seconds, so the promise was broken on every successful
                     run. startPlanProgress() fills it with the honest number, a
                     line that changes as the phases pass and a bar that moves. -->
                <div id="wizard-loading" class="card wiz-loading" style="display: none;"></div>
                <!-- Where a failure is explained. The toast goes as well, but a
                     message that disappears after three seconds is no use to
                     someone who has just watched a spinner for half a minute. -->
                <div id="wizard-plan-error" style="display: none;"></div>
            </form>
        `;
    }

    if (currentStep === 9) {
        return `
            <div class="wiz-hello">
                <div class="wiz-done-dots" aria-hidden="true"><span></span><span></span><span></span><span></span></div>
                <!-- Batch item 95. This used to say "Your Daily 3 is ready!" over
                     "Head to your dashboard to see today's most important actions", and
                     neither was true yet: the button just pressed reads "Generate My
                     90-Day Plan" and the spinner under it says "Building your 90-day
                     roadmap", so nothing in this step builds a Daily 3. The next screen
                     contradicted it outright -- the dashboard greets a new account with
                     "Your 90-day plan is ready. The next step is turning week one into
                     three actions you'll actually do." The wizard promised a finished
                     deliverable and the dashboard immediately explained it still had to
                     be made. These are the dashboard's own words, which were right. -->
                <h1 class="wiz-hello-title">Your 90-day plan is ready!</h1>
                <p class="wiz-hello-sub">Twelve weeks, mapped out. The next step is turning week one into three actions you'll actually do, and your dashboard will walk you through it.</p>
                <div class="wiz-value-grid">
                    <div class="card wiz-next"><span class="wiz-next-badge is-done">✓</span><div><p class="wiz-value-title">Twelve weeks, mapped out</p><p class="wiz-value-sub">Done. It's waiting on your 90-Day Plan.</p></div></div>
                    <div class="card wiz-next"><span class="wiz-next-badge is-now">2</span><div><p class="wiz-value-title">Turn week one into three actions</p><p class="wiz-value-sub">Your first Daily 3.</p></div></div>
                    <div class="card wiz-next"><span class="wiz-next-badge">3</span><div><p class="wiz-value-title">Your dashboard walks you through it</p><p class="wiz-value-sub">One step at a time.</p></div></div>
                </div>
                <div class="wiz-done-actions">
                    <button id="btn-go-dashboard" class="btn btn-primary wiz-btn-big">${afterSetupLabel(peekAfterSetupRoute()) ? `Go to ${afterSetupLabel(peekAfterSetupRoute())}` : 'Go to Dashboard'} →</button>
                    <a href="#/help" id="btn-wiz-tour" class="btn btn-outline wiz-btn-big"><svg width="24" height="17" viewBox="0 0 28 20" aria-hidden="true"><rect width="28" height="20" rx="5" fill="#FF0000"></rect><path d="M11 5.5v9l8-4.5z" fill="#FFFFFF"></path></svg>Watch the quick tour first</a>
                </div>
            </div>
        `;
    }
}






















function showWizardStep() {
    const container = document.getElementById('app-container');
    if (!container) return;

    
    
    if (currentStep >= 2 && currentStep <= TOTAL_STEPS - 1) {
        updateProfile({ wizardStep: currentStep });
    }

    container.innerHTML = renderWizard();
    wizardAttachEvents();

    
    
    
    
    scrollToTop();
}

function wizardAttachEvents() {
    const form = document.getElementById(`wizard-form-${currentStep}`);
    const btnBack = document.getElementById('btn-back');

    
    
    
    wireHomeScreenPrompt();

    
    
    
    
    
    
    
    
    if (erasureClearPending) {
        erasureClearPending = false;
        if (typeof window.clearDataErasedStamp === 'function') window.clearDataErasedStamp();
    }

    if (btnBack) {
        btnBack.addEventListener('click', () => {
            if (currentStep > 1) {
                currentStep--;
                showWizardStep();
            }
        });
    }

    if (currentStep === 2) {
        
        const fileInput = document.getElementById('set-logo-file');
        const urlInput = document.getElementById('set-logo-url');
        const base64Input = document.getElementById('set-logo-base64');
        const previewImg = document.getElementById('logo-preview-img');
        const previewPlaceholder = document.getElementById('logo-preview-placeholder');
        const removeLogoBtn = document.getElementById('btn-remove-logo');

        
        
        
        const showLogo = (src) => {
            if (previewImg) {
                previewImg.src = src || '';
                previewImg.style.display = src ? 'block' : 'none';
            }
            if (previewPlaceholder) previewPlaceholder.style.display = src ? 'none' : 'block';
            if (removeLogoBtn) removeLogoBtn.style.display = src ? 'inline-block' : 'none';
        };

        
        
        
        
        if (fileInput) {
            fileInput.addEventListener('change', function (e) {
                const file = e.target.files[0];
                if (!file) return;
                downscaleImageFile(file).then(result => {
                    base64Input.value = result.dataUrl;
                    urlInput.value = '';
                    showLogo(result.dataUrl);
                    if (result.resized) {
                        showToast(`Image resized to ${describeBytes(result.bytes)} so it does not slow your account down.`, 'info');
                    }
                }).catch(err => {
                    fileInput.value = '';
                    showToast(err.message, 'error');
                });
            });
        }

        if (urlInput) {
            urlInput.addEventListener('input', function (e) {
                const url = e.target.value;
                if (url) {
                    base64Input.value = '';
                    showLogo(url);
                } else if (!base64Input.value) {
                    showLogo('');
                }
            });
        }

        
        
        
        if (removeLogoBtn) {
            removeLogoBtn.addEventListener('click', () => {
                if (urlInput) urlInput.value = '';
                if (base64Input) base64Input.value = '';
                if (fileInput) fileInput.value = '';
                showLogo('');
            });
        }
    }

    
    
    
    
    
    const wizDayGrid = document.getElementById('wiz-business-days');
    if (wizDayGrid) {
        wizDayGrid.addEventListener('change', () => {
            const chosen = Array.from(wizDayGrid.querySelectorAll('input[name="business-days"]:checked')).map(b => b.value);
            const echo = document.getElementById('wiz-business-days-echo');
            if (echo) echo.textContent = wizardDaysEcho(chosen);
        });
    }

    if (currentStep === 3) {
        const focusInput = document.getElementById('goal-focus');
        const checks = document.getElementById('wiz-focus-checks');
        const examples = document.getElementById('wiz-examples');
        const refreshChecks = () => {
            if (checks && focusInput) checks.innerHTML = wizFocusChecks(focusInput.value);
        };
        focusInput?.addEventListener('input', refreshChecks);

        document.querySelectorAll('.wiz-gtype').forEach(btn => {
            btn.addEventListener('click', () => {
                const type = WIZ_GOAL_TYPES[parseInt(btn.getAttribute('data-gt'), 10)];
                if (!type || !examples) return;
                document.querySelectorAll('.wiz-gtype').forEach(b => {
                    const on = b === btn;
                    b.classList.toggle('is-on', on);
                    b.setAttribute('aria-pressed', on ? 'true' : 'false');
                });
                examples.innerHTML = type.examples.map((text, i) => `
                    <div class="wiz-example-row">
                        <p>${escapeText(text)}</p>
                        <button type="button" class="btn btn-outline btn-sm" data-ex="${i}">Use this</button>
                    </div>`).join('');
                examples.querySelectorAll('[data-ex]').forEach(use => {
                    use.addEventListener('click', () => {
                        if (!focusInput) return;
                        focusInput.value = type.examples[parseInt(use.getAttribute('data-ex'), 10)];
                        refreshChecks();
                        focusInput.focus();
                    });
                });
            });
        });
    }

    
    
    
    
    
    if (currentStep === 8) {
        const card = document.getElementById('wiz-carried');
        const answer = (decision, text) => {
            recordPriorityDecision(text, decision);
            if (card) {
                card.innerHTML = `<p class="wiz-carried-label">One thing before you choose</p>
                    <p class="wiz-carried-text">${decision === 'keep'
                        ? 'Kept for another 90 days. It is in the box below, and you can reword it.'
                        : 'Noted. It is not in the boxes below unless you put it there.'}</p>`;
            }
        };

        const keep = document.getElementById('wiz-carried-keep');
        if (keep) {
            keep.addEventListener('click', () => {
                const text = keep.closest('.wiz-carried')?.querySelector('strong')?.textContent || '';
                const empty = ['p1', 'p2', 'p3']
                    .map(id => document.getElementById(id))
                    .find(el => el && !el.value.trim());
                if (empty) {
                    empty.value = text;
                    empty.focus();
                }
                answer('keep', text);
            });
        }

        const drop = document.getElementById('wiz-carried-drop');
        if (drop) {
            drop.addEventListener('click', () => {
                const text = drop.closest('.wiz-carried')?.querySelector('strong')?.textContent || '';
                answer('let-go', text);
            });
        }
    }

    if (currentStep === 7) {
        const currencySelect = document.getElementById('set-currency');
        const revGoalInput = document.getElementById('rev-goal');
        const offerPriceInput = document.getElementById('offer-price');
        const hint = document.getElementById('sales-required-hint');

        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        
        const updateHint = () => {
            if (!hint) return;
            const goal = parseFloat(revGoalInput?.value) || 0;
            const price = parseFloat(offerPriceInput?.value) || 0;
            const symbol = currencySelect?.value || '$';
            
            
            
            
            const math = getGoalMath(getStore(), {
                revenueGoal: goal,
                averageOfferPrice: price,
                leadGoal: parseFloat(document.getElementById('lead-goal')?.value) || 0,
                currency: symbol
            });
            
            
            
            
            const set = (id, text) => { const el = document.getElementById(id); if (el) el.textContent = text; };
            
            
            
            set('wiz-calc-units-cap', `${math.unitLeadShort} in 90 days`);
            const leadNote = document.getElementById('lead-goal-note');
            if (leadNote) {
                const note = leadGoalNote(math);
                leadNote.textContent = note;
                leadNote.classList.toggle('is-short', !!note && math.leadGoal < math.unitsRequired);
                leadNote.style.display = note ? '' : 'none';
            }
            if (!math.known) {
                set('wiz-calc-line', 'Add your target and your offer price to see how many sales it takes.');
                set('wiz-calc-more', '');
                set('wiz-calc-sales', '–');
                set('wiz-calc-units', '–');
                return;
            }
            const sentences = goalMathSentences(math);
            set('wiz-calc-line', sentences[0]);
            
            
            
            
            const assumedNote = modelAssumptionNote(math);
            set('wiz-calc-more', [sentences.slice(1).join(' '),
                assumedNote ? assumedNote + ' You can set it on the business step, or later in Settings.' : ''
            ].filter(Boolean).join(' '));
            set('wiz-calc-sales', math.salesRequired.toLocaleString());
            set('wiz-calc-sales-cap', `${math.salesRequired === 1 ? 'sale' : 'sales'} in 90 days`);
            set('wiz-calc-units', math.unitsRequired.toLocaleString());
        };

        
        
        
        
        
        
        
        
        const updateGoalBreakdown = () => {
            const box = document.getElementById('rev-goal-breakdown');
            if (!box) return;
            const symbol = currencySelect?.value || getStore().settings?.currency || '$';
            const goal = parseFloat(revGoalInput?.value) || 0;
            const lines = [
                goalBreakdownLine(goal, symbol),
                focusCurrencyLine(getStore().goals?.focus || '', symbol)
            ].filter(Boolean);
            box.innerHTML = lines.length
                ? `<p class="wiz-hint wiz-breakdown">${lines.join('<br>')}</p>`
                : '';
        };

        if (currencySelect) {
            currencySelect.addEventListener('change', () => {
                document.querySelectorAll('.currency-prefix').forEach(el => {
                    el.textContent = currencySelect.value;
                });
                updateHint();
                updateGoalBreakdown();
            });
        }
        revGoalInput?.addEventListener('input', updateHint);
        revGoalInput?.addEventListener('input', updateGoalBreakdown);
        offerPriceInput?.addEventListener('input', updateHint);
        document.getElementById('lead-goal')?.addEventListener('input', updateHint);
        updateHint();
        updateGoalBreakdown();
    }

    if (form) {
        form.addEventListener('submit', (e) => {
            e.preventDefault();
            const store = getStore();
            const currentGoals = store.goals;

            if (currentStep === 1) {
                currentStep++;
                showWizardStep();
            }
            else if (currentStep === 2) {
                const name = document.getElementById('set-name').value.trim();
                const bizName = document.getElementById('set-biz').value.trim();
                const commitment = document.getElementById('set-commitment').value.trim();
                
                const urlVal = document.getElementById('set-logo-url').value.trim();
                const base64Val = document.getElementById('set-logo-base64').value;
                const finalLogo = urlVal || base64Val || '';
                
                updateProfile({
                    name: name,
                    businessName: bizName,
                    logo: finalLogo
                });
                
                currentGoals.statement = commitment;
                updateGoals(currentGoals);

                currentStep++;
                showWizardStep();
            }
            else if (currentStep === 3) {
                currentGoals.focus = document.getElementById('goal-focus').value.trim();
                updateGoals(currentGoals);

                currentStep++;
                showWizardStep();
            }
            else if (currentStep === 4) {
                const businessModel = document.getElementById('biz-model').value;
                const targetAudience = document.getElementById('target-audience').value.trim();
                const industryNiche = document.getElementById('industry-niche').value.trim();
                const bottleneck = document.getElementById('biz-bottleneck').value.trim();
                
                
                const offerPromise = document.getElementById('offer-promise').value.trim();
                updateProfile({ businessModel, targetAudience, industryNiche, offerPromise, bottleneck });

                currentStep++;
                showWizardStep();
            }
            else if (currentStep === 5) {
                const stage = document.querySelector('input[name="biz-stage"]:checked')?.value || '';
                const strategyMode = document.querySelector('input[name="strategy-mode"]:checked')?.value || '';
                updateProfile({ stage, strategyMode });

                currentStep++;
                showWizardStep();
            }
            
            else if (currentStep === 6) {
                const answers = {};
                ASSET_QUESTIONS.forEach(q => {
                    answers[q.field] = document.querySelector(`input[name="${q.name}"]:checked`)?.value || '';
                });
                
                
                
                
                
                
                const businessDays = Array.from(document.querySelectorAll('input[name="business-days"]:checked')).map(b => b.value);
                if (businessDays.length) {
                    answers.businessDays = businessDays;
                    answers.workingDaysPerWeek = businessDays.length;
                }
                const hours = parseInt(document.querySelector('input[name="hours-per-day"]:checked')?.value, 10);
                if (Number.isFinite(hours)) answers.hoursPerDay = hours;
                
                
                
                
                const planningDay = document.querySelector('input[name="planning-day"]:checked')?.value;
                if (PLANNING_DAY_OPTIONS.indexOf(planningDay) !== -1) answers.planningDay = planningDay;
                updateProfile(answers);

                currentStep++;
                showWizardStep();
            }
            else if (currentStep === 7) {
                const currency = document.getElementById('set-currency').value;
                const quarterlyGoal = parseFloat(document.getElementById('rev-goal').value) || 0;
                const averageOfferPrice = parseFloat(document.getElementById('offer-price').value) || 0;
                const leadGoal = parseFloat(document.getElementById('lead-goal').value) || 0;

                updateSettings({ currency });
                updateRevenueSettings({ quarterlyGoal, averageOfferPrice });
                updateLeadGoal(leadGoal);

                currentStep++;
                showWizardStep();
            }
            else if (currentStep === 8) {
                currentGoals.priorities = [
                    document.getElementById('p1').value.trim(),
                    document.getElementById('p2').value.trim(),
                    document.getElementById('p3').value.trim()
                ];
                currentGoals.outcome = `Achieve 90-day focus: ${currentGoals.focus}`;
                currentGoals.milestones = {
                    month1: `Build out and execute priorities for ${currentGoals.priorities[0]}`,
                    month2: `Promote and launch ${currentGoals.priorities[1]}`,
                    month3: `Scale and stabilize ${currentGoals.priorities[2]}`
                };
                
                updateGoals(currentGoals);

                
                
                
                

                
                
                
                
                const buttonsDiv = document.getElementById('wizard-step-8-buttons');
                const loadingDiv = document.getElementById('wizard-loading');
                const errorDiv = document.getElementById('wizard-plan-error');
                if (errorDiv) {
                    errorDiv.style.display = 'none';
                    errorDiv.innerHTML = '';
                }
                if (buttonsDiv && loadingDiv) {
                    buttonsDiv.style.display = 'none';
                    loadingDiv.style.display = 'block';
                }
                const stopProgress = startPlanProgress(loadingDiv);

                
                
                
                
                const showFailure = (err) => {
                    stopProgress();
                    if (buttonsDiv && loadingDiv) {
                        buttonsDiv.style.display = 'flex';
                        loadingDiv.style.display = 'none';
                        loadingDiv.innerHTML = '';
                    }
                    const text = planFailureText(err);
                    if (errorDiv) {
                        errorDiv.style.display = 'block';
                        errorDiv.innerHTML = `
                            <div style="border-left: 3px solid #B42318; background: var(--color-bg-light); padding: 0.85rem 1rem; border-radius: var(--radius-sm); text-align: left;">
                                <p style="margin: 0 0 0.35rem 0; font-weight: 600; color: var(--color-text-main);">${text.headline}</p>
                                <p style="margin: 0; font-size: 0.9rem; color: var(--color-text-muted); line-height: 1.5;">${text.next}</p>
                            </div>`;
                    }
                    showToast(text.headline, 'error', 7000);
                };

                
                
                
                
                generate90DayActionPlan({ onProgress: reportPlanProgress }).then(plan => {
                    stopProgress();
                    if (plan) {
                        applyGeneratedPlan(plan);

                        
                        
                        startNewQuarter();

                        
                        
                        
                        updateProfile({
                            trialStartDate: new Date().toISOString(),
                            bottleneck: store.profile?.bottleneck || 'Lead Generation'
                        });

                        
                        
                        
                        
                        
                        
                        
                        
                        
                        
                        
                        
                        
                        
                        
                        
                        
                        trackAction('setup.complete');

                        currentStep = 9;
                        showWizardStep();
                    } else {
                        
                        
                        
                        
                        showFailure({ reason: 'malformed' });
                    }
                }).catch(err => {
                    console.error("AI action plan generation failed", err);
                    showFailure(err);
                });
            }
        });
    }

    
    document.querySelectorAll('.btn-wizard-bottleneck-preset').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.preventDefault();
            const val = e.target.getAttribute('data-value');
            const input = document.getElementById('biz-bottleneck');
            if (input) {
                input.value = val;
            }
        });
    });

    const btnGoDashboard = document.getElementById('btn-go-dashboard');
    if (btnGoDashboard) {
        btnGoDashboard.addEventListener('click', () => {
            currentStep = 1; 
            
            
            
            
            
            
            
            trackAction('setup.dashboard', 'dashboard');
            
            window.location.hash = takeAfterSetupRoute() || '#/dashboard';
        });
    }

    
    
    
    
    
    document.getElementById('btn-wiz-tour')?.addEventListener('click', () => {
        currentStep = 1;
        
        
        
        
        
        
        
        
        trackAction('setup.dashboard', 'tour');
    });
}












































let dashImportedCountAtRender = 0;























const STARTER_STEPS = [
    
    
    
    
    { key: 'planMade',   text: 'Your first task is to plan this week.',    label: 'Plan this week', sub: '5 mins' },
    
    
    
    
    { key: 'coachAsked', text: 'Not sure how to start your first action?',  label: 'Ask the coach', showsTask: true },
    { key: 'taskTicked', text: 'Do your first action, then tick it off.',   label: 'Check out my Daily 3' }
];




function starterCardHtml(steps, firstTask = '') {
    const task = String(firstTask || '').trim();
    const rows = STARTER_STEPS.map((step, i) => {
        const done = Boolean(steps[step.key]);
        
        
        const firstOpen = STARTER_STEPS.findIndex(s => !steps[s.key]);
        const isNow = !done && i === firstOpen;
        const state = done ? 'is-done' : isNow ? 'is-now' : 'is-todo';
        
        
        
        
        const showTask = step.showsTask && isNow && task;
        return `
            <li class="starter-step ${state}">
                <span class="starter-badge" aria-hidden="true">${done ? '✓' : i + 1}</span>
                <div class="starter-step-main">
                    ${showTask ? `
                        <p class="starter-task-label">Your first task is</p>
                        <p class="starter-task">${escapeText(task)}</p>` : ''}
                    <p class="starter-step-text">${step.text}</p>
                    ${isNow ? `
                        <button type="button" class="btn btn-primary btn-sm btn-starter" data-starter-step="${step.key}">
                            ${escapeText(step.label)}${step.sub ? ` · ${escapeText(step.sub)}` : ''}
                        </button>` : ''}
                </div>
            </li>`;
    }).join('');

    return `
        <section class="card dash-starter" id="dash-starter">
            <div class="starter-head">
                <p class="starter-label">Start here</p>
                <p class="starter-count">${steps.doneCount} of 3</p>
            </div>
            <p class="starter-intro">Your 90 days are mapped. These three turn it into something you can act on today.</p>
            ${













''}
            <p class="starter-watch"><a href="#/help?at=help-videos">Prefer to watch first? Guide videos &rarr;</a></p>
            <ol class="starter-list">${rows}</ol>
        </section>`;
}

























function starterFirstTask(store) {
    const todayStr = getLocalDateString();
    const tasks = (store.dailyLogs || {})[todayStr] || [];
    
    
    const task = tasks.find(t => t && !t.done && !t.later) || tasks.find(t => t && !t.later);
    return task ? String(task.text || '').trim() : '';
}

function starterCoachQuestion(store) {
    const text = starterFirstTask(store);
    if (!text) return '';
    return `My first action this week is "${text}". How should I actually execute that? Give me the concrete steps.`;
}



function bindStarterButtons() {
    document.querySelectorAll('.btn-starter').forEach(btn => {
        btn.addEventListener('click', () => {
            const step = btn.getAttribute('data-starter-step');

            if (step === 'planMade') {
                window.location.hash = '#/monday-plan';
                return;
            }

            if (step === 'coachAsked') {
                const question = starterCoachQuestion(getStore());
                if (!question) {
                    
                    
                    showToast('Plan this week first, then your coach can talk you through the first action.');
                    return;
                }
                
                
                
                
                if (askCoach(question)) {
                    
                    
                    
                    markStarterCoachAsked();
                    trackAction('starter.coach');
                    
                    
                    window.dispatchEvent(new Event('hashchange'));
                } else {
                    showToast('Your coach could not be opened just now. Try the chat button, bottom right.');
                }
                return;
            }

            if (step === 'taskTicked') {
                
                
                
                
                const list = document.getElementById('daily-3-list');
                if (list && typeof list.scrollIntoView === 'function') {
                    list.scrollIntoView({ behavior: 'smooth', block: 'center' });
                }
            }
        });
    });

    const closeStarterDone = document.getElementById('btn-close-starter-done');
    const starterDoneModal = document.getElementById('starter-done-modal');
    if (closeStarterDone && starterDoneModal) {
        closeStarterDone.addEventListener('click', () => {
            starterDoneModal.style.display = 'none';
            window.dispatchEvent(new Event('hashchange'));
        });
    }
    const starterUpgrade = document.getElementById('btn-starter-upgrade');
    if (starterUpgrade) {
        starterUpgrade.addEventListener('click', () => trackAction('starter.upgrade_taken'));
    }
}

