function suggestionDestination(type) {
    if (type.includes('revenue')) return 'Revenue-Generating Actions';
    if (type.includes('visibility')) return 'Visibility & Marketing';
    if (type.includes('follow')) return 'Follow-ups & Conversations';
    return 'Top 3 Most Important Actions';
}

function suggestionItemHtml(s) {
    const type = String(s.type || '').toLowerCase().replace(/[^a-z-]/g, '');
    return `
        <li class="plan-idea">
            <span class="tag-chip plan-chip-${type}">${escapeText(s.type)}</span>
            <p>${escapeText(s.action)}</p>
            <div class="plan-idea-foot">
                <span class="plan-idea-dest">Goes to: ${escapeText(suggestionDestination(type))}</span>
                <button type="button" class="btn btn-primary btn-sm apply-suggestion-btn" data-type="${escapeText(type)}" data-action="${escapeText(s.action)}">Apply</button>
            </div>
            <div class="plan-slot-picker" hidden></div>
        </li>
    `;
}





function openSlotPicker(btn, actionText) {
    const card = btn.closest('.plan-idea');
    const picker = card && card.querySelector('.plan-slot-picker');
    if (!picker) return;
    const clip = (t) => t.length > 48 ? t.slice(0, 46).trimEnd() + '\u2026' : t;
    picker.innerHTML = `
        <p class="plan-slot-q">Your top 3 are full. Which one should this replace?</p>
        ${[1, 2, 3].map(n => {
            const current = (document.getElementById('pa-' + n)?.value || '').trim();
            return `<button type="button" class="plan-slot-btn" data-slot="${n}"><span class="plan-slot-num">${n}</span><span class="plan-slot-text">${escapeText(clip(current))}</span></button>`;
        }).join('')}
        <button type="button" class="btn btn-ghost btn-sm plan-slot-cancel">Cancel</button>`;
    picker.hidden = false;
    picker.querySelectorAll('.plan-slot-btn').forEach(slotBtn => {
        slotBtn.addEventListener('click', () => {
            const el = document.getElementById('pa-' + slotBtn.getAttribute('data-slot'));
            if (el) el.value = actionText;
            picker.hidden = true;
            picker.innerHTML = '';
            btn.textContent = 'Applied \u2713';
            btn.classList.add('is-applied');
            btn.disabled = true;
        });
    });
    picker.querySelector('.plan-slot-cancel')?.addEventListener('click', () => {
        picker.hidden = true;
        picker.innerHTML = '';
    });
}

function plannerAttachEvents() {
    document.getElementById('btn-check-this-week')?.addEventListener('click', async (e) => {
        const btn = e.currentTarget;
        const plan = getActivePlan(getStore());
        if (!plan) return;
        btn.disabled = true;
        btn.textContent = 'Checking it against what you did…';
        const result = await runWeekRefit(plan);
        showToast(result
            ? (result.changed ? 'This week has been adjusted. The note at the top says what changed.' : 'Checked: nothing in this week needed changing.')
            : 'Could not check it just now. Your plan is unchanged; try again later.', result ? 'success' : 'error', 6000);
        rerenderScreen();
    });

    

    bindApplySuggestionButtons();

    
    document.querySelectorAll('.ask-coach-task').forEach(btn => {
        btn.addEventListener('click', () => {
            const field = document.getElementById(btn.getAttribute('data-task-field'));
            const task = field ? field.value.trim() : '';

            
            
            
            if (!task) {
                showToast('Write the action first, then your Executive AI Coach can walk you through it.', 'info');
                if (field) field.focus();
                return;
            }

            
            
            
            askCoach(`Walk me through exactly how to do this, step by step, for my business: "${task}"`);
        });
    });

    
    
    
    
    const pauseBtn = document.getElementById('toggle-week-pause');
    if (pauseBtn) {
        pauseBtn.addEventListener('click', () => {
            const week = parseInt(pauseBtn.dataset.week, 10);
            const wasPaused = pauseBtn.dataset.paused === '1';
            const result = setWeekPaused(week, !wasPaused);

            if (!result.ok) {
                showToast(`You can pause up to ${MAX_PAUSED_WEEKS} weeks in a 90-day cycle, and you have used all of them.`, 'error');
                return;
            }

            const endLabel = result.status ? result.status.endLabel : null;
            showToast(wasPaused
                ? `Week ${week} is back on the clock${endLabel ? `, and your 90 days end ${endLabel}` : ''}.`
                : `Week ${week} paused${endLabel ? `. Your 90 days now end ${endLabel}` : ''}.`);
            rerenderScreen();
        });
    }


    
    
    
    
    
    
    
    
    
    
    hydratePlanSuggestions(suggestions => {
        const list = document.getElementById('plan-suggestions-list');
        if (!list) return;
        list.innerHTML = suggestions.map(suggestionItemHtml).join('');
        bindApplySuggestionButtons();
    });

    const form = document.getElementById('planner-form');
    if (form) {
        form.addEventListener('submit', (e) => {
            e.preventDefault();

            
            
            
            
            const wasFirstPlan = !hasEverPlanned();

            const p1 = document.getElementById('pa-1').value;
            const p2 = document.getElementById('pa-2').value;
            const p3 = document.getElementById('pa-3').value;

            const plan = {
                winCondition: document.getElementById('plan-win').value,
                topActions: [p1, p2, p3],
                buildAction: document.getElementById('plan-build').value,
                revenueAction: document.getElementById('plan-revenue').value,
                visibilityAction: document.getElementById('plan-visibility').value,
                followUps: document.getElementById('plan-followup').value,
            };

            const planId = form.getAttribute('data-plan-id');
            const genId = form.getAttribute('data-gen-id');

            if (planId && planId !== '') {
                
                plan.date = new Date().toISOString();
                updateWeeklyPlan(planId, plan);
                showToast('Weekly plan updated');
            } else if (genId && genId !== '') {
                
                plan.applied = true;
                plan.date = new Date().toISOString(); 
                updateWeeklyPlan(genId, plan);

                
                const storeStateForMove = getStore();
                if (storeStateForMove) {
                   const idx = storeStateForMove.weeklyPlans.findIndex(p => String(p.id) === String(genId));
                   if (idx !== -1) {
                       const p = storeStateForMove.weeklyPlans.splice(idx, 1)[0];
                       storeStateForMove.weeklyPlans.push(p);
                       saveStore(storeStateForMove);
                   }
                }
                showToast('Weekly plan applied. Have a great week, CEO.');
            } else {
                addWeeklyPlan(plan);
                showToast('Weekly plan saved. Have a great week, CEO.');
            }

            if (wasFirstPlan) trackAction('plan.first', 'planner');

            
            
            
            
            
            
            
            
            
            
            
            
            
            
            

            
            window.location.hash = '#/dashboard';
        });
    }
}

function bindApplySuggestionButtons() {
    
    document.querySelectorAll('.apply-suggestion-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const type = e.target.getAttribute('data-type');
            const actionText = e.target.getAttribute('data-action');

            let targetId = '';
            if (type.includes('revenue')) targetId = 'plan-revenue';
            else if (type.includes('visibility')) targetId = 'plan-visibility';
            else if (type.includes('follow')) targetId = 'plan-followup';
            else {
                
                const actionBoxes = ['pa-1', 'pa-2', 'pa-3'];
                const store = getStore();
                const defaultPriorities = store.goals?.priorities || [];
                
                for (let i = 0; i < actionBoxes.length; i++) {
                    const id = actionBoxes[i];
                    const el = document.getElementById(id);
                    if (el) {
                        const val = el.value.trim();
                        
                        if (val === '' || val === (defaultPriorities[i] || '').trim()) {
                            targetId = id;
                            break;
                        }
                    }
                }
                
                if (!targetId) {
                    openSlotPicker(e.target, actionText);
                    return;
                }
            }

            if (targetId) {
                const el = document.getElementById(targetId);
                if (el) {
                    if (targetId.startsWith('pa-')) {
                        
                        el.value = actionText;
                    } else if (el.value.trim() !== '') {
                        
                        el.value += '\n' + actionText;
                    } else {
                        el.value = actionText;
                    }
                    
                    e.target.textContent = 'Applied ✓';
                    e.target.classList.add('is-applied');
                    e.target.disabled = true;
                }
            }
        });
    });
}

function getSuggestedFocus(mode) {
    if (!mode) return "What is the ONE thing that moves the needle this week?";

    const m = mode.toLowerCase();

    if (m.includes('first sale')) {
        return "You're in the First Sale Sprint! Your primary focus must be visibility and direct conversations. Aim to make at least 5 direct invitations to your offer this week.";
    }

    if (m.includes('launch')) {
        return "This is an Offer Launch! This week, prioritize tasks that move your launch timeline forward (e.g. warming up the audience, finalizing promo assets, or sending sales emails). Ignore distractions.";
    }

    if (m.includes('audience')) {
        return "Audience Growth is your focus. Dedicate 60% of your time to creating high-value content, driving traffic to a lead magnet, and engaging with new ideal clients.";
    }

    if (m.includes('reset')) {
        return "You are in CEO Reset mode. Your priority is to simplify your delivery, automate where possible, and document your processes so you can scale without burning out.";
    }

    return "What is the ONE thing that moves the needle this week based on your current big goal?";
}

function getSmartPrompts(mode) {
    const m = (mode || '').toLowerCase();

    if (m.includes('first sale')) {
        return {
            revenueHelper: "Your priority is direct sales. e.g., Pitching 3 people in DMs, sending a direct sales email, inviting people to a discovery call.",
            visibilityHelper: "Keep this simple. It's just to support your outreach. e.g., 1 post sharing your story and offer.",
            followupHelper: "Critical: Follow up with anyone who showed interest in the past 30 days."
        };
    }
    if (m.includes('launch')) {
        return {
            revenueHelper: "Focus on launch mechanics. e.g., Finalizing the sales page, writing the launch email sequence, opening the cart.",
            visibilityHelper: "Warm up your audience. e.g., Teasing the launch, sharing behind-the-scenes, hosting a free masterclass.",
            followupHelper: "Follow up with waitlist members or highly engaged leads."
        };
    }
    if (m.includes('audience')) {
        return {
            revenueHelper: "Secondary focus for these 90 days. e.g., Mention your evergreen offer at the end of content.",
            visibilityHelper: "MAJOR FOCUS: How are you driving new traffic? e.g., Collaborations, Pinterest pins, SEO blogs, daily short-form video.",
            followupHelper: "Engage with new followers, reply to all comments."
        };
    }
    if (m.includes('reset')) {
        return {
            revenueHelper: "Keep the baseline running. e.g., Automated sales sequences or passive income streams.",
            visibilityHelper: "Maintain consistency without burning out. e.g., Repurposing old content.",
            followupHelper: "Clear out your inbox and delegate customer service if possible."
        };
    }

    return {
        revenueHelper: "How will you actively generate sales or leads this week? (e.g., DM outreach, sending a promo email, hosting a webinar)",
        visibilityHelper: "How will you show up visibly? (e.g., 3 IG Posts, 1 YouTube video)",
        followupHelper: "Who do you need to reply to or follow up with to close loops?"
    };
}







































