function renderQuickOfferSlot(index, offer) {
    const o = offer || { name: '', price: '', source: 'Instagram' };

    
    
    
    
    
    
    
    
    
    
    
    const saved = String(o.source || '').trim();
    const options = CONTACT_SOURCES.includes(saved) || !saved
        ? CONTACT_SOURCES
        : [saved, ...CONTACT_SOURCES];
    const selected = saved || 'Instagram';

    return `
        <div data-offer-slot style="background: var(--color-bg-light); padding: 0.75rem; border-radius: var(--radius-sm); margin-bottom: 0.75rem;">
            <label style="font-size: 0.75rem; font-weight: 600; color: var(--color-text-main); display: block; margin-bottom: 0.25rem;">Slot ${index + 1}</label>
            <input type="text" class="form-control qo-name" placeholder="Offer Name (e.g. Mastermind)" value="${escapeText(o.name)}" style="margin-bottom: 0.25rem;">
            <div style="display: flex; gap: 0.5rem;">
                <input type="number" class="form-control qo-price" placeholder="Price" value="${escapeText(o.price)}" step="any">
                <select class="form-control qo-source" style="min-width: 0;" aria-label="Default source for this offer">
                    ${options.map(src => `<option value="${escapeText(src)}"${src === selected ? ' selected' : ''}>${escapeText(src)}</option>`).join('')}
                </select>
            </div>
        </div>
    `;
}











function readQuickOfferSlots(root) {
    const offers = [];
    if (!root) return offers;

    root.querySelectorAll('[data-offer-slot]').forEach(slot => {
        const name = slot.querySelector('.qo-name').value.trim();
        const price = slot.querySelector('.qo-price').value;
        const source = slot.querySelector('.qo-source').value.trim();
        if (name) {
            offers.push({ name, price, source });
        }
    });

    return offers;
}










function renderExpenseList(store, currency) {
    const rows = (store.expenses || [])
        .slice()
        .sort((a, b) => new Date(b.date) - new Date(a.date));

    if (rows.length === 0) {
        return `<p class="rev-event-meta" style="margin-top: 1rem;">No costs logged in these 90 days yet.</p>`;
    }

    const total = rows.reduce((sum, e) => sum + (parseFloat(e.amount) || 0), 0);

    
    
    
    const caption = `${currency}${formatAmount(total)} across ${rows.length} cost${rows.length === 1 ? '' : 's'} in these 90 days. Archived when you start your next 90 days.`;

    const items = rows.map(e => {
        const meta = [
            new Date(e.date).toLocaleDateString(),
            e.category ? escapeText(e.category) : '',
            e.note ? escapeText(e.note) : ''
        ].filter(Boolean).join(' · ');
        return `
            <div class="rev-event">
                <span class="tag-chip" style="background: #FEF3F2; color: #B42318;">Cost</span>
                <div class="rev-event-body">
                    <p class="rev-event-amount">${currency}${formatAmount(parseFloat(e.amount) || 0)}</p>
                    <p class="rev-event-meta">${meta}</p>
                </div>
                <button type="button" class="rev-bin btn-delete-expense" data-id="${escapeText(String(e.id))}" aria-label="Delete this cost">${REV_BIN_ICON}</button>
            </div>
        `;
    }).join('');

    return `
        <div style="margin-top: 1.25rem;">
            <p class="rev-field-label" style="margin-bottom: 0.25rem;">Logged costs</p>
            <p class="rev-event-meta" style="margin: 0 0 0.5rem;">${caption}</p>
            ${items}
        </div>
    `;
}











function renderUnconvertedWarning(insights, currency) {
    const groups = insights.unconvertedSales || [];
    if (groups.length === 0) return '';

    const lines = groups.map(g => {
        const sales = g.count === 1 ? '1 sale' : `${g.count} sales`;
        return `<strong>${sales}</strong> in ${g.code} (${g.symbol}${formatAmount(g.originalTotal)})`;
    });

    
    
    const list = lines.length === 1
        ? lines[0]
        : lines.slice(0, -1).join(', ') + ' and ' + lines[lines.length - 1];

    return `
        <div class="card mb-6" style="border-left: 4px solid #F79009; background: #FFFAEB; padding: 1.25rem; border-radius: 12px;">
            <h4 style="margin: 0 0 0.4rem 0; font-size: 1rem; color: #B54708; font-weight: 700;">
                Some sales are not in your totals yet
            </h4>
            <p style="margin: 0 0 0.9rem 0; font-size: 0.9rem; line-height: 1.6; color: #7A2E0E;">
                You have ${list} that we have no exchange rate for, so they are
                <strong>not counted</strong> in the figures below. We would rather show you the
                gap than add a number we had to guess at. Set a rate and they will count from
                then on, including in past quarters.
            </p>
            <a href="#/settings?at=conversion-rates-block" class="btn btn-secondary btn-sm" style="font-weight: 600;">Set an exchange rate</a>
        </div>
    `;
}

