const REVIEW_MIC_ICON = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3a3 3 0 0 0-3 3v6a3 3 0 0 0 6 0V6a3 3 0 0 0-3-3z"></path><path d="M5 11a7 7 0 0 0 14 0"></path><path d="M12 18v3"></path></svg>';



function energyParts(option) {
    const m = /^(.*?)\s*\((.*)\)$/.exec(option);
    return m ? [m[1], m[2]] : [option, ''];
}



function reviewWeek(store, currency) {
    
    
    const today = new Date();
    const lateReview = getLocalDateString(today) === getLocalDateString(getWeekStart(today, store));
    const asOf = new Date(today);
    if (lateReview) asOf.setDate(asOf.getDate() - 1);
    return {
        lateReview,
        which: lateReview ? 'Last week' : 'This week',
        number: currentRoadmapWeek(store, asOf),
        activity: getWeekActivity(store, { previousWeek: lateReview }),
        currency
    };
}


















function renderWeekNumbers(week) {
    const { activity, which, lateReview, currency } = week;
    const leadsLabel = `${activity.leads.toLocaleString()} ${activity.leads === 1 ? 'lead' : 'leads'}`;
    const moneyLabel = `${currency}${formatAmount(activity.revenue)}`;

    const summary = (activity.leads === 0 && activity.revenue === 0)
        ? `Nothing logged ${lateReview ? 'last week' : 'this week yet'}. If you made a sale or picked up a lead, log it on the Revenue screen and it will show up here.`
        : `${which} you logged ${leadsLabel} and ${moneyLabel}.`;

    return `
                <section class="soft-panel review-numbers">
                    <p class="review-numbers-label">
                        ${which}'s numbers
                        ${renderTooltip(lateReview ? "Read straight from what you logged last week, the week this review closes out." : "Read straight from what you logged.", "You already log leads and sales as they happen, so the review reads them back instead of asking you to remember. These are the same figures the Revenue tab shows.")}
                    </p>
                    <div class="review-numbers-tiles">
                        <div class="review-tile"><p class="review-tile-num">${activity.leads.toLocaleString()}</p><p class="review-tile-unit">${activity.leads === 1 ? 'lead' : 'leads'} logged</p></div>
                        <div class="review-tile review-tile-win"><p class="review-tile-num">${moneyLabel}</p><p class="review-tile-unit">revenue</p></div>
                    </div>
                    <p class="review-numbers-summary">${summary}</p>
                    <a href="#/revenue" class="btn btn-sm btn-outline">Open Revenue</a>
                </section>
    `;
}





