function renderHistorySummary(store) {
    const currency = store.settings?.currency || '$';
    const history = getQuarterHistory();
    
    
    
    
    const sp = canUseHistory() ? history.samePoint : null;

    let body;
    if (sp) {
        const weeks = sp.weeksElapsed;
        const level = sp.delta === 0;
        const ahead = sp.delta > 0;
        body = level
            ? `${weeks === 1 ? 'One week' : `${weeks} weeks`} in, you are level with where you were at this point in ${sp.previousLabel}.`
            : `${weeks === 1 ? 'One week' : `${weeks} weeks`} in, you are
               <strong style="color: ${ahead ? 'var(--color-secondary-dark)' : '#B42318'};">${currency}${formatAmount(Math.abs(sp.delta))} ${ahead ? 'ahead of' : 'behind'}</strong>
               where you were at this point in ${sp.previousLabel}.`;
    } else if (history.hasHistory) {
        body = `${history.archivedCount} finished ${history.archivedCount === 1 ? '90-day cycle is' : '90-day cycles are'} kept here, with everything you wrote on the way out of ${history.archivedCount === 1 ? 'it' : 'them'}.`;
    } else {
        body = `Your first 90 days are still running. Finish them with a reset and all of it is kept here instead of cleared, ready for the next to be measured against.`;
    }

    
    const historyTip = renderTooltip("Every 90 days you finish, archived rather than cleared, with everything you wrote on the way out of it.", "Looking back at them tells you whether these 90 days are genuinely better than the last, or it just feels that way.", 'bottom');
    const heading = canUseHistory()
        ? `<p class="rep-card-head">${proCardHeading('history', 'Your quarters')}${historyTip}</p>`
        : `<p class="rep-card-head">Your quarters${historyTip}</p>`;
    return `
        <section class="card rep-history${canUseHistory() ? ' rep-pro-card' : ''}">
            <!-- The PRO chip only where it is true. On Base this card is the way
                 into an archive that is not a Pro feature any more, and a chip
                 above it would say the opposite of what the button does. -->
            ${heading}
            <p class="rep-card-text">${body}</p>
            <a href="#/history" class="btn btn-primary btn-sm rep-card-btn">Open your quarters</a>
        </section>
    `;
}

