function helpAttachEvents() {

    
    
    
    
    
    document.querySelectorAll('[data-help-view]').forEach(btn => {
        btn.addEventListener('click', () => {
            helpVideoView = btn.getAttribute('data-help-view') === 'todo' ? 'todo' : 'all';
            rerenderScreen();
        });
    });

    const form = document.getElementById('help-ask-form');
    const input = document.getElementById('help-ask-input');
    const submit = document.getElementById('help-ask-submit');
    const answer = document.getElementById('help-ask-answer');
    if (!form || !input || !submit || !answer) return;

    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const question = input.value.trim();
        if (!question || submit.disabled) return;

        submit.disabled = true;
        const original = submit.textContent;
        submit.textContent = 'Asking...';
        answer.innerHTML = `<p style="color: var(--color-text-muted); font-style: italic; font-size: 0.9rem;">Reading the guide...</p>`;

        try {
            
            
            
            const reply = await generateAIResponse(
                [{ role: 'user', content: question }],
                { support: true }
            );
            answer.innerHTML = `
                <div class="help-answer">
                    ${window.marked ? window.marked.parse(reply) : escapeText(reply)}
                </div>
                <p style="font-size: 0.75rem; color: var(--color-text-muted); margin: 0.75rem 0 0 0;">
                    Not right, or not what you meant? Email <a href="${supportMailto('CEO Planner help')}">${escapeText(SUPPORT_EMAIL)}</a>.
                </p>`;
            input.value = '';
        } catch (err) {
            
            
            
            answer.innerHTML = `
                <p style="color: var(--color-error); font-size: 0.9rem; margin: 0 0 0.5rem 0;">That didn't work: ${escapeText(err.message)}</p>
                <p style="font-size: 0.875rem; margin: 0;">Email <a href="${supportMailto('CEO Planner help')}">${escapeText(SUPPORT_EMAIL)}</a> and we'll answer it ourselves.</p>`;
        } finally {
            submit.disabled = false;
            submit.textContent = original;
        }
    });
}












































function rateLookupLink(code, base) {
    const query = encodeURIComponent(`1 ${code} in ${base}`);
    return `
        <a href="https://www.google.com/search?q=${query}"
           target="_blank" rel="noopener noreferrer"
           style="font-size:0.75rem;color:var(--color-primary-dark);text-decoration:underline;white-space:nowrap;">
            Look up today's rate
        </a>
    `;
}












function renderConversionRates(store, currencyOverride) {
    const baseSymbol = currencyOverride || store.settings?.currency || '$';
    const base = currencyCodeFor(baseSymbol);
    const codes = foreignCurrenciesPresent(getImportedSalesCache(), base);
    if (codes.length === 0) return '';

    const rows = codes.map(code => {
        const rate = conversionRateFor(store, code, base);
        const symbol = currencySymbolFor(code);
        
        
        
        const value = rate === null ? '' : rate;
        return `
            <div style="display:flex;align-items:center;gap:0.6rem;margin-bottom:0.6rem;flex-wrap:wrap;">
                <span style="font-weight:600;color:var(--color-black);white-space:nowrap;">1 ${code} =</span>
                <div style="position:relative;display:flex;align-items:center;flex:1 1 120px;min-width:110px;">
                    <span style="position:absolute;left:0.75rem;z-index:1;font-weight:600;color:var(--color-text-muted);">${baseSymbol}</span>
                    <input type="number" step="0.0001" min="0"
                           class="form-input conversion-rate-input"
                           data-code="${code}"
                           value="${value}"
                           placeholder="0.00"
                           style="padding-left:2.25rem;width:100%;"
                           aria-label="Conversion rate from ${code} to ${base}">
                </div>
                <span style="display:flex;align-items:center;gap:0.5rem;flex-wrap:wrap;">
                    ${rate === null
                        ? `<span style="font-size:0.75rem;font-weight:600;color:#B54708;background:#FFFAEB;padding:0.15rem 0.5rem;border-radius:4px;white-space:nowrap;">not counted yet</span>`
                        : `<span style="font-size:0.75rem;color:var(--color-text-muted);white-space:nowrap;">${symbol}100 = ${baseSymbol}${(100 * rate).toFixed(2)}</span>`}
                    ${rateLookupLink(code, base)}
                </span>
            </div>
        `;
    }).join('');

    return `
    <div class="form-group mb-4" style="border:1px solid var(--color-border);border-radius:12px;padding:1rem;background:var(--color-bg-light);">
        <label class="form-label" style="font-weight: 600;">Exchange rates for imported sales</label>
        <p style="color:var(--color-text-muted);font-size:0.85rem;line-height:1.6;margin:0 0 0.9rem;">
            Some of your imported payments came in a different currency to the one above.
            Set the rate you want to use and they will count towards your 90 days.
            <strong>Until you do, they are shown but not counted</strong> — we would rather
            leave a visible gap than quietly add a number that is wrong.
        </p>
        ${rows}
        <span class="form-helper">
            Use whatever your bookkeeping uses — the rate on the day the money landed, or the
            one your accountant works to. Once you set it, it stays put, so figures you have
            already reported to someone don't move underneath you. Change it whenever you like.
        </span>
    </div>
    `;
}















let pendingPermission = null;
let confirmationShown = false;

















function reminderPermissionNoticeHtml(permission, reminderTimes) {
    const on = Array.isArray(reminderTimes) ? reminderTimes.length : 0;
    
    
    if (on === 0) return '';
    if (permission === 'granted') return '';

    if (permission === 'unsupported') {
        return `<p class="set-note">These are ticked, but this browser cannot show notifications at all, so none will arrive.
                   Everything they would have told you is still on your dashboard when you open the app.</p>`;
    }

    
    
    
    if (permission === 'denied') {
        return `<p class="set-note">⚠️ These are ticked, but notifications are <strong>blocked for this site</strong> in your
                   browser, so none of them can arrive. Unblock them in your browser's site settings for this page, then
                   come back. Until then everything they would have told you is still on your dashboard.</p>`;
    }

    
    return `<p class="set-note">⚠️ These are ticked, but your browser has not been asked for permission yet, so
               <strong>nothing will arrive</strong> until it is.
               <button type="button" id="btn-allow-reminders" class="btn btn-sm">Turn on notifications</button></p>`;
}

function requestNotificationPermission() {
    if (!('Notification' in window)) return Promise.resolve('denied');
    if (Notification.permission !== 'default') return Promise.resolve(Notification.permission);

    if (!pendingPermission) {
        pendingPermission = Promise.resolve(Notification.requestPermission())
            .then(result => {
                pendingPermission = null;
                if (result === 'granted' && !confirmationShown) {
                    confirmationShown = true;
                    
                    
                    
                    
                    
                    
                    
                    if ('serviceWorker' in navigator) {
                        navigator.serviceWorker.ready.then(registration => {
                            registration.showNotification('Reminders are on', {
                                body: "You'll get the first one when it's due.",
                                icon: './icon-192.png'
                            });
                        }).catch(() => {  });
                    }
                }
                return result;
            })
            .catch(err => {
                pendingPermission = null;
                throw err;
            });
    }

    return pendingPermission;
}





























function liveBusinessDayCount() {
    return document.querySelectorAll('#set-business-days .set-day-input:checked').length;
}

function businessDaysEcho(days) {
    const sentence = dayListSentence(days);
    if (!sentence) return 'Not answered yet, so your reminders can land on any day.';
    return `We'll remind you on ${sentence}.`;
}

