function accountAttachEvents() {
    
    
    
    
    
    
    
    
    
    const importedCountAtRender = getImportedSalesCache().length;
    refreshImportedSales().then(sales => {
        if (sales.length !== importedCountAtRender) rerenderScreen();
    }).catch(() => {  });

    
    
    
    
    
    

    
    
    
    
    
    
    
    fetchAiAllowance().then(paintAiUsage);

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const showEmailFallback = () => {
        const el = document.getElementById('account-email');
        if (!el) return;
        el.textContent = 'Signed out on this device — sign in again to see it';
        el.style.color = 'var(--color-text-muted)';
    };

    window.db.auth.getSession().then(({ data }) => {
        const email = data?.session?.user?.email;
        if (!email) {
            showEmailFallback();
            return;
        }
        const el = document.getElementById('account-email');
        if (el) el.textContent = email;
    }).catch(showEmailFallback);

    
    
    watchForPlanChange();

    
    
    const btnManageSub = document.getElementById('btn-manage-subscription');
    if (btnManageSub) {
        btnManageSub.addEventListener('click', () => {
            if (localStorage.getItem('ceo_sub_status') === 'trialing') {
                window.location.hash = '#/billing';
                return;
            }
            portalOnClick(btnManageSub, 'Opening…');
        });
    }

    const btnUpgrade = document.getElementById('btn-upgrade-pro');
    if (btnUpgrade) {
        btnUpgrade.addEventListener('click', () => portalOnClick(btnUpgrade, 'Opening…', 'upgrade'));
    }

    
    
    
    
    
    
    const btnSaveOffers = document.getElementById('btn-save-product-offers');
    if (btnSaveOffers) {
        btnSaveOffers.addEventListener('click', () => {
            const selects = Array.from(document.querySelectorAll('.product-offer-select'));
            if (!selects.length) return;

            
            
            
            
            
            const productOffers = { ...(getStore().settings?.productOffers || {}) };
            selects.forEach(sel => {
                const key = sel.dataset.key;
                if (key) productOffers[key] = sel.value;
            });

            updateSettings({ productOffers });
            showToast('Saved. Your imported sales now count under your own offer names.', 'success');
            rerenderScreen();
        });
    }

    
    
    
    const btnPassword = document.getElementById('btn-change-password');
    if (btnPassword) {
        mountCaptcha('auth', 0, 'account-captcha');

        btnPassword.addEventListener('click', async () => {
            const { data } = await window.db.auth.getSession();
            const email = data?.session?.user?.email;
            if (!email) {
                showToast('We could not read your account. Please sign out and back in, then try again.', 'error');
                return;
            }

            btnPassword.disabled = true;
            const original = btnPassword.textContent;
            btnPassword.textContent = 'Sending…';

            
            
            
            
            const token = captchaToken('auth');
            if (captchaAppliesTo('auth') && !token) {
                btnPassword.disabled = false;
                btnPassword.textContent = original;
                showToast('Just finishing the security check. Try that again in a moment.', 'error');
                return;
            }

            const { error } = await window.db.auth.resetPasswordForEmail(email, {
                
                
                redirectTo: window.location.origin + window.location.pathname,
                captchaToken: token
            });

            btnPassword.disabled = false;
            btnPassword.textContent = original;

            
            
            resetCaptcha();

            
            
            
            
            
            
            if (error && !isRateLimit(error)) {
                console.warn('Password reset email from Account failed:', error.message);
                showToast(authErrorMessage(error, 'forgot'), 'error');
            } else if (error) {
                showToast(authErrorMessage(error, 'forgot'), 'success', 6000);
            } else {
                showToast(`Check ${email} for a link to set a new password.`, 'success', 6000);
            }
        });
    }

    const btnSignout = document.getElementById('btn-account-signout');
    if (btnSignout) {
        btnSignout.addEventListener('click', () => signOutAndClear());
    }

    
    
    
    
    const resetBtn = document.getElementById('btn-reset-data');
    if (resetBtn) {
        resetBtn.addEventListener('click', async () => {
            const confirmed = await showConfirm(
                
                
                
                
                
                
                "This permanently deletes your plans, revenue log, coach conversation, imported sales and any payment connections, from this device and from our servers. Your account stays open so you can start again, but the data cannot be recovered.",
                { title: 'Erase all your data?', confirmText: 'Erase everything', danger: true }
            );
            if (!confirmed) return;

            const originalText = resetBtn.textContent;
            resetBtn.disabled = true;
            resetBtn.textContent = 'Erasing…';

            try {
                const { data: sessionData } = await window.db.auth.getSession();
                const user = sessionData?.session?.user;
                if (user) {
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    const { data: erasedCounts, error } = await window.db.rpc('erase_all_my_data');
                    if (error) throw error;
                    
                    
                    
                    console.info('Erase All My Data removed, per table:', erasedCounts);
                }
            } catch (err) {
                
                
                
                console.error('Cloud data deletion failed:', err);
                resetBtn.disabled = false;
                resetBtn.textContent = originalText;
                showToast("We couldn't delete your data from the server, so nothing has been erased. Please check your connection and try again. If it keeps failing, email " + SUPPORT_EMAIL + " and we'll erase it for you.", 'error');
                return;
            }

            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            await window.markDataErased();

            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            try {
                Object.keys(localStorage)
                    .filter(k => k.startsWith('ceoPlanner_rescue_'))
                    .forEach(k => localStorage.removeItem(k));
            } catch (err) {
                console.warn('Could not clear rescue copies:', err && err.message);
            }

            localStorage.removeItem('ceoPlanner_store');

            
            
            
            
            
            

            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            try {
                sessionStorage.setItem('ceo_erased', '1');
            } catch (err) {
                
            }
            signOutAndClear();
        });
    }
}






























const CALENDAR_FEED_BASE =
    'https://ekzpbpoadiktlflcrrwm.supabase.co/functions/v1/calendar-feed/';




function calendarFeedUrl(token) {
    if (!/^[0-9a-f]{32}$/.test(String(token || ''))) return '';
    return CALENDAR_FEED_BASE + token;
}









function calendarFeedWebcal(token) {
    const https = calendarFeedUrl(token);
    return https ? https.replace(/^https:\/\//, 'webcal://') : '';
}




function calendarFeedGoogleUrl(token) {
    const https = calendarFeedUrl(token);
    return https
        ? 'https://calendar.google.com/calendar/r?cid=' + encodeURIComponent(https)
        : '';
}










function calendarFeedContents(store = getStore()) {
    const reminders = (store.profile && store.profile.reminderTimes) || [];
    const days = businessDayNames(store);
    const out = [];

    if (reminders.includes(REMINDER_DAILY) && days.length) {
        const hours = businessHoursPerDay(store);
        out.push({
            title: 'Your Daily 3',
            when: `${businessDaysSentence(store)}, ${hours} hour${hours === 1 ? '' : 's'}`
        });
    }
    if (reminders.includes(REMINDER_WEEKLY)) {
        out.push({ title: 'Plan your week', when: `Every ${getPlanningDayName(store)}` });
    }
    if (reminders.includes(REMINDER_FRIDAY)) {
        out.push({ title: 'Weekly Review', when: `Every ${getReviewDayName(store)}` });
    }
    return out;
}





















function calendarFeedNeeds(store = getStore()) {
    const reminders = (store.profile && store.profile.reminderTimes) || [];
    const wanted = [REMINDER_DAILY, REMINDER_WEEKLY, REMINDER_FRIDAY];
    return {
        
        
        
        needsDays: !businessDayNames(store).length,
        
        
        
        
        remindersOff: !wanted.some(r => reminders.includes(r))
    };
}


const CONNECT_DEFAULT_REMINDERS = [REMINDER_DAILY, REMINDER_WEEKLY, REMINDER_FRIDAY];

function contentsHtml(store) {
    const items = calendarFeedContents(store);
    if (!items.length) return '';
    return `
        <ul class="conn-list">
            ${items.map(i => `
            <li class="conn-list-row">
                <span class="conn-list-title">${escapeText(i.title)}</span>
                <span class="conn-list-when">${escapeText(i.when)}</span>
            </li>`).join('')}
        </ul>`;
}


function chosenConnDays(grid) {
    const ticked = Array.from(grid.querySelectorAll('.set-day-input:checked')).map(b => b.value);
    return DAY_NAMES.filter(d => ticked.includes(d));
}

