let flushPendingReflection = null;
let reflectionFlushBound = false;
function bindReflectionFlushOnLeave() {
    if (reflectionFlushBound) return;
    reflectionFlushBound = true;
    const run = () => { if (flushPendingReflection) flushPendingReflection(); };
    window.addEventListener('hashchange', run);
    window.addEventListener('pagehide', run);
}

function quarterResetAttachEvents() {

    
    
    
    const closeEarly = document.getElementById('qr-early-close');
    if (closeEarly) {
        closeEarly.addEventListener('click', () => {
            earlyChoice = 'close';
            rerenderScreen();
        });
    }

    const falseStart = document.getElementById('qr-early-false');
    if (falseStart) {
        falseStart.addEventListener('click', () => {
            
            
            
            
            
            
            
            earlyChoice = null;
            resetWizardProgress();
            showToast('Nothing archived. Re-plan these 90 days and they will keep running to the date they already had.', 'info', 6000);
            window.location.hash = '#/wizard';
        });
    }

    const form = document.getElementById('quarter-reset-form');
    if (!form) return;

    
    
    
    
    
    
    
    
    
    
    
    document.querySelectorAll('.qr-dup-same').forEach(btn => {
        btn.addEventListener('click', () => {
            if (linkSameSale(btn.getAttribute('data-manual-id'), btn.getAttribute('data-imported-id'))) {
                showToast('Counted once. Your hand-logged copy is kept, just not added again.');
                rerenderScreen();
            }
        });
    });
    document.querySelectorAll('.qr-dup-both').forEach(btn => {
        btn.addEventListener('click', () => {
            dismissDuplicatePair(btn.getAttribute('data-imported-id'), btn.getAttribute('data-manual-id'));
            showToast('Kept both. We will not flag those two again.');
            rerenderScreen();
        });
    });

    const readReflection = () => {
        const out = {};
        REFLECTION_FIELDS.forEach(([id, key]) => {
            out[key] = document.getElementById(id)?.value || '';
        });
        return out;
    };

    
    
    
    
    
    
    
    
    
    
    
    
    let saveTimer = null;
    let pending = null;
    const flush = () => {
        if (saveTimer) { clearTimeout(saveTimer); saveTimer = null; }
        if (!pending) return;
        const draft = pending;
        pending = null;
        saveQuarterReflectionDraft(draft);
    };
    const queueSave = () => {
        pending = readReflection();
        if (saveTimer) clearTimeout(saveTimer);
        saveTimer = setTimeout(flush, 800);
    };
    flushPendingReflection = flush;
    bindReflectionFlushOnLeave();

    
    
    const stopVoice = attachVoiceReflection('qr', '#quarter-reset-form .form-textarea', 'qr-worked');

    REFLECTION_FIELDS.forEach(([id]) => {
        const box = document.getElementById(id);
        if (!box) return;
        box.addEventListener('input', queueSave);
        
        
        box.addEventListener('blur', () => {
            pending = readReflection();
            flush();
        });
    });

    
    
    
    document.getElementById('qr-finish-later')?.addEventListener('click', () => {
        stopVoice();
        if (saveTimer) { clearTimeout(saveTimer); saveTimer = null; }
        pending = null;
        const draft = readReflection();
        saveQuarterReflectionDraft(draft);
        const typedSomething = Object.values(draft).some(v => String(v).trim() !== '');
        showToast(typedSomething
            ? 'Saved. Your wrap-up will be here when you come back.'
            : 'Nothing to save yet. Your 90 days are untouched.');
        window.location.hash = '#/progress';
    });

    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        stopVoice();

        
        
        
        
        flush();

        const answers = readReflection();
        const reflection = {
            date: new Date().toISOString(),
            worked: answers.worked,
            didntWork: answers.didntWork,
            results: answers.results,
            changeNextQuarter: answers.changeNextQuarter
        };

        const confirmIt = await showConfirm(
            'Your goals, revenue, leads and this reflection are archived, then you decide when to plan the next 90 days.',
            { title: 'Archive these 90 days?', confirmText: 'Archive and start fresh' }
        );
        if (!confirmIt) return;

        
        
        
        resetQuarter(reflection);
        
        
        
        clearLiveAICache();
        
        
        resetWizardProgress();

        
        
        
        
        
        
        const planNow = await showConfirm(
            'Your 90 days are archived and safe. You can set your next 90-day focus now, or come back to it when you have the headspace.',
            {
                title: 'Ready to plan your next 90 days?',
                confirmText: "Yes, let's plan it",
                cancelText: 'Not right now'
            }
        );

        if (planNow) {
            showToast('Archived. Time to plan your next 90 days.');
            window.location.hash = '#/wizard';
            return;
        }

        
        
        
        
        deferQuarterPlanning();
        showToast('Archived. Plan your next 90 days whenever you are ready.');
        window.location.hash = '#/dashboard';
    });
}





