const NOTE_MIC_ICON = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3a3 3 0 0 0-3 3v6a3 3 0 0 0 6 0V6a3 3 0 0 0-3-3z"></path><path d="M5 11a7 7 0 0 0 14 0"></path><path d="M12 18v3"></path></svg>';



















const NOTE_CLAMP_LINES = 4;
const NOTE_CLAMP_CHARS = 220;

function noteNeedsClamp(text) {
    const t = String(text || '');
    return t.length > NOTE_CLAMP_CHARS || t.split('\n').length > NOTE_CLAMP_LINES;
}

function renderNoteCard(n) {
    const when = new Date(n.date).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });
    const edited = n.editedAt
        ? ` · edited ${new Date(n.editedAt).toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' })}`
        : '';
    const long = noteNeedsClamp(n.text);
    return `
        <div class="note-card" data-id="${escapeText(n.id)}">
            <p class="note-text${long ? ' note-text-clamp' : ''}" style="font-size: 0.95rem; color: var(--color-black); margin-bottom: 0.5rem; white-space: pre-wrap;">${escapeText(n.text)}</p>
            ${long ? '<button type="button" class="note-expand" aria-expanded="false">Show more</button>' : ''}
            <div class="note-footer" style="display: flex; justify-content: space-between; align-items: flex-end; gap: 0.5rem; flex-wrap: wrap;">
                <span style="font-size: 0.75rem; color: var(--color-text-muted);">${when}${edited}</span>
                <span style="display: flex; gap: 0.25rem;">
                    <button type="button" class="btn btn-ghost btn-sm btn-edit-note" data-id="${escapeText(n.id)}" style="padding: 0.25rem 0.5rem; color: var(--color-primary-dark); font-size: 0.8rem; position: relative; z-index: 10;">Edit</button>
                    <button type="button" class="btn btn-ghost btn-sm btn-delete-note" data-id="${escapeText(n.id)}" style="padding: 0.25rem 0.5rem; color: var(--color-text-muted); font-size: 0.8rem; cursor: pointer; position: relative; z-index: 10;">Delete</button>
                </span>
            </div>
        </div>`;
}

function rerenderNotepad() {
    const appContainer = document.getElementById('app-container');
    if (appContainer) {
        appContainer.innerHTML = renderCoach();
        coachAttachEvents();
    }
}

function openNoteEditor(card) {
    const id = card.getAttribute('data-id');
    const note = (getStore().notes || []).find(n => String(n.id) === String(id));
    if (!note) return;

    card.innerHTML = `
        <div class="note-input-wrap">
            <textarea class="form-textarea note-edit-input" aria-label="Edit note"></textarea>
            <button type="button" class="note-mic note-edit-mic" title="Add by voice" aria-label="Add by voice">${NOTE_MIC_ICON}</button>
        </div>
        <div class="note-edit-recording" style="display: none; color: #D92D20; font-size: 0.85rem; margin: 0.5rem 0; align-items: center; gap: 0.5rem;">
            <span class="pulse-dot" style="width: 8px; height: 8px; background: #D92D20; border-radius: 50%; display: inline-block;"></span> Recording... (Speak now)
        </div>
        <div style="display: flex; justify-content: flex-end; gap: 0.5rem; margin-top: 0.6rem;">
            <button type="button" class="btn btn-ghost btn-sm note-edit-cancel">Cancel</button>
            <button type="button" class="btn btn-primary btn-sm note-edit-save">Save changes</button>
        </div>`;

    const input = card.querySelector('.note-edit-input');
    
    input.value = note.text || '';
    input.focus();
    input.setSelectionRange(input.value.length, input.value.length);
    bindMicButton(card.querySelector('.note-edit-mic'), input, card.querySelector('.note-edit-recording'));

    
    card.addEventListener('click', (e) => e.stopPropagation());
    card.querySelector('.note-edit-cancel').addEventListener('click', rerenderNotepad);
    card.querySelector('.note-edit-save').addEventListener('click', () => {
        const text = input.value.trim();
        if (!text) {
            showToast('A note needs some words. Use Delete to remove it instead.', 'error');
            return;
        }
        updateNote(id, text);
        showToast('Note updated');
        rerenderNotepad();
    });
}











function toLocalInputValue(date) {
    const pad = (n) => String(n).padStart(2, '0');
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

function defaultReminderTime() {
    const d = new Date(Date.now() + 3600000);
    d.setMinutes(0, 0, 0);
    return d;
}

function reminderWhen(dueAt) {
    const d = new Date(dueAt);
    if (!Number.isFinite(d.getTime())) return 'No time set';
    const today = new Date();
    const tomorrow = new Date(); tomorrow.setDate(today.getDate() + 1);
    const time = d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
    if (d.toDateString() === today.toDateString()) return `Today, ${time}`;
    if (d.toDateString() === tomorrow.toDateString()) return `Tomorrow, ${time}`;
    return d.toLocaleDateString(undefined, { weekday: 'short', day: 'numeric', month: 'short' }) + ', ' + time;
}



function calendarStamp(date) {
    return date.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
}

function googleCalendarUrl(r) {
    const start = new Date(r.dueAt);
    const end = new Date(start.getTime() + 15 * 60000);
    const q = (k, v) => `${k}=${encodeURIComponent(v)}`;
    return 'https://calendar.google.com/calendar/render?' + [
        q('action', 'TEMPLATE'),
        q('text', r.text),
        q('dates', `${calendarStamp(start)}/${calendarStamp(end)}`),
        q('details', 'Reminder from your CEO Planner')
    ].join('&');
}



function reminderIcs(r) {
    const start = new Date(r.dueAt);
    const end = new Date(start.getTime() + 15 * 60000);
    const esc = (t) => String(t || '').replace(/\\/g, '\\\\').replace(/\n/g, '\\n').replace(/,/g, '\\,').replace(/;/g, '\\;');
    return [
        'BEGIN:VCALENDAR',
        'VERSION:2.0',
        'PRODID:-//CEO Planner//Reminders//EN',
        'BEGIN:VEVENT',
        `UID:${r.id}@ceoplanner`,
        `DTSTAMP:${calendarStamp(new Date())}`,
        `DTSTART:${calendarStamp(start)}`,
        `DTEND:${calendarStamp(end)}`,
        `SUMMARY:${esc(r.text)}`,
        'DESCRIPTION:Reminder from your CEO Planner',
        'BEGIN:VALARM',
        'ACTION:DISPLAY',
        `DESCRIPTION:${esc(r.text)}`,
        'TRIGGER:PT0M',
        'END:VALARM',
        'END:VEVENT',
        'END:VCALENDAR'
    ].join('\r\n');
}

function renderReminderRow(r) {
    const overdue = !r.done && new Date(r.dueAt).getTime() < Date.now();
    const id = escapeText(r.id);
    return `
        <div class="reminder-row" data-id="${id}" style="background: var(--color-bg-light); padding: 0.85rem 1rem; border-radius: var(--radius-sm); border-left: 3px solid ${r.done ? 'var(--color-border)' : (overdue ? '#F59E0B' : 'var(--color-accent)')};">
            <div style="display: flex; gap: 0.75rem; align-items: flex-start;">
                <input type="checkbox" class="reminder-done" data-id="${id}" ${r.done ? 'checked' : ''} aria-label="Mark done" style="width: 18px; height: 18px; margin-top: 0.2rem; accent-color: var(--color-primary); flex-shrink: 0;">
                <div style="flex: 1; min-width: 0;">
                    <p style="margin: 0 0 0.2rem 0; font-size: 0.95rem; white-space: pre-wrap; ${r.done ? 'text-decoration: line-through; color: var(--color-text-muted);' : 'color: var(--color-black);'}">${escapeText(r.text)}</p>
                    <p style="margin: 0; font-size: 0.8rem; color: ${overdue ? '#B54708' : 'var(--color-text-muted)'}; font-weight: ${overdue ? '600' : '400'};">${overdue ? 'Overdue · ' : ''}${escapeText(reminderWhen(r.dueAt))}</p>
                </div>
            </div>
            ${r.done ? `
                <div style="display: flex; justify-content: flex-end; margin-top: 0.4rem;">
                    <button type="button" class="btn btn-ghost btn-sm btn-delete-reminder" data-id="${id}" style="font-size: 0.8rem; color: var(--color-text-muted);">Delete</button>
                </div>` : `
                <div style="display: flex; justify-content: flex-end; gap: 0.25rem; flex-wrap: wrap; margin-top: 0.4rem;">
                    <a class="btn btn-ghost btn-sm" href="data:text/calendar;charset=utf-8,${encodeURIComponent(reminderIcs(r))}" download="reminder.ics" style="font-size: 0.8rem; color: var(--color-primary-dark);">iPhone / Outlook calendar</a>
                    <a class="btn btn-ghost btn-sm" href="${escapeText(googleCalendarUrl(r))}" target="_blank" rel="noopener" style="font-size: 0.8rem; color: var(--color-primary-dark);">Google Calendar</a>
                    <button type="button" class="btn btn-ghost btn-sm btn-edit-reminder" data-id="${id}" style="font-size: 0.8rem; color: var(--color-primary-dark);">Edit</button>
                    <button type="button" class="btn btn-ghost btn-sm btn-delete-reminder" data-id="${id}" style="font-size: 0.8rem; color: var(--color-text-muted);">Delete</button>
                </div>`}
        </div>`;
}

function renderRemindersCard(store) {
    const all = Array.isArray(store.reminders) ? store.reminders : [];
    const upcoming = all.filter(r => !r.done).sort((a, b) => new Date(a.dueAt) - new Date(b.dueAt));
    const done = all.filter(r => r.done).sort((a, b) => new Date(b.updatedAt || b.dueAt) - new Date(a.updatedAt || a.dueAt)).slice(0, 5);
    const canNotify = typeof Notification !== 'undefined';
    const askPermission = canNotify && Notification.permission === 'default';

    return `
        <section class="card note-card-frame" id="reminders-card">
            <h2 class="note-h2">
                Reminders
                ${renderTooltip("Set a reminder for a time and the app alerts you when it is due.", "The app can only alert you while it is open. Tap a calendar button on the reminder and your phone's own calendar will alert you even when the app is closed.")}
            </h2>
            <form id="reminder-form" class="note-form">
                <div class="note-input-wrap">
                    <textarea class="form-textarea note-input-short" id="reminder-input" placeholder="What do you need reminding about?" required></textarea>
                    <button type="button" id="btn-voice-reminder" class="note-mic" title="Say your reminder" aria-label="Say your reminder">${NOTE_MIC_ICON}</button>
                </div>
                <div id="reminder-recording-indicator" style="display: none; color: #D92D20; font-size: 0.85rem; margin-bottom: 0.75rem; align-items: center; gap: 0.5rem;">
                    <span class="pulse-dot" style="width: 8px; height: 8px; background: #D92D20; border-radius: 50%; display: inline-block;"></span> Recording... (Speak now)
                </div>
                <label class="form-label" for="reminder-when">When</label>
                <input type="datetime-local" class="form-input" id="reminder-when" required value="${toLocalInputValue(defaultReminderTime())}">
                <button type="submit" class="btn btn-primary note-save-btn">Set Reminder</button>
            </form>
            ${askPermission ? `
                <p id="reminder-permission" style="margin: 0 0 1rem 0; font-size: 0.85rem; line-height: 1.5; color: var(--color-text-muted);">
                    Want a pop-up notification when one is due?
                    <button type="button" class="btn btn-ghost btn-sm" id="btn-allow-reminder-alerts" style="color: var(--color-primary-dark); font-weight: 600; padding: 0.1rem 0.35rem;">Allow alerts on this device</button>
                </p>` : ''}
            <p style="margin: 0 0 1rem 0; font-size: 0.8rem; line-height: 1.5; color: var(--color-text-muted);">The app alerts you while it's open. For an alert when it's closed, add the reminder to your calendar.</p>
            <div id="reminders-list" style="display: flex; flex-direction: column; gap: 0.75rem;">
                ${upcoming.length === 0 ? '<p style="color: var(--color-text-muted); font-size: 0.9rem; text-align: center; margin: 0;">No reminders set.</p>' : upcoming.map(renderReminderRow).join('')}
                ${done.length ? `<p style="margin: 0.5rem 0 0 0; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.05em; font-weight: 700; color: var(--color-text-muted);">Done</p>${done.map(renderReminderRow).join('')}` : ''}
            </div>
        </section>`;
}

function openReminderEditor(row) {
    const id = row.getAttribute('data-id');
    const r = (getStore().reminders || []).find(x => String(x.id) === String(id));
    if (!r) return;
    row.innerHTML = `
        <textarea class="form-textarea reminder-edit-text" style="min-height: 60px; margin-bottom: 0.5rem;" aria-label="Edit reminder"></textarea>
        <input type="datetime-local" class="form-input reminder-edit-when" aria-label="When">
        <div style="display: flex; justify-content: flex-end; gap: 0.5rem; margin-top: 0.6rem;">
            <button type="button" class="btn btn-ghost btn-sm reminder-edit-cancel">Cancel</button>
            <button type="button" class="btn btn-primary btn-sm reminder-edit-save">Save changes</button>
        </div>`;
    const text = row.querySelector('.reminder-edit-text');
    const when = row.querySelector('.reminder-edit-when');
    text.value = r.text || '';
    const due = new Date(r.dueAt);
    when.value = toLocalInputValue(Number.isFinite(due.getTime()) ? due : defaultReminderTime());
    text.focus();
    row.addEventListener('click', (e) => e.stopPropagation());
    row.querySelector('.reminder-edit-cancel').addEventListener('click', rerenderNotepad);
    row.querySelector('.reminder-edit-save').addEventListener('click', () => {
        const newText = text.value.trim();
        const newWhen = new Date(when.value);
        if (!newText || !Number.isFinite(newWhen.getTime())) {
            showToast('A reminder needs words and a time.', 'error');
            return;
        }
        updateReminder(id, { text: newText, dueAt: newWhen.toISOString() });
        showToast('Reminder updated. If it is in your calendar, update it there too.', 'success', 5000);
        rerenderNotepad();
    });
}

function bindReminderEvents() {
    bindMicButton(document.getElementById('btn-voice-reminder'), document.getElementById('reminder-input'), document.getElementById('reminder-recording-indicator'));

    document.getElementById('reminder-form')?.addEventListener('submit', (e) => {
        e.preventDefault();
        const text = document.getElementById('reminder-input').value.trim();
        const when = new Date(document.getElementById('reminder-when').value);
        if (!text || !Number.isFinite(when.getTime())) return;
        addReminder({ text, dueAt: when.toISOString() });
        showToast(`Reminder set for ${reminderWhen(when.toISOString())}.`, 'success');
        rerenderNotepad();
    });

    document.getElementById('btn-allow-reminder-alerts')?.addEventListener('click', async () => {
        try {
            const answer = await Notification.requestPermission();
            showToast(answer === 'granted'
                ? 'Alerts are on for this device.'
                : 'Alerts stay off. You will still see a reminder card in the app when one is due.', 'info', 5000);
        } catch (err) {  }
        rerenderNotepad();
    });

    const list = document.getElementById('reminders-list');
    if (!list) return;
    list.addEventListener('change', (e) => {
        const box = e.target.closest('.reminder-done');
        if (!box) return;
        updateReminder(box.getAttribute('data-id'), { done: box.checked });
        rerenderNotepad();
    });
    list.addEventListener('click', async (e) => {
        const edit = e.target.closest('.btn-edit-reminder');
        if (edit) {
            openReminderEditor(edit.closest('.reminder-row'));
            return;
        }
        const del = e.target.closest('.btn-delete-reminder');
        if (del) {
            const ok = await showConfirm('This reminder will be removed. If you added it to your calendar, delete it there too.', {
                title: 'Delete this reminder?', confirmText: 'Delete', danger: true
            });
            if (!ok) return;
            deleteReminder(del.getAttribute('data-id'));
            showToast('Reminder deleted');
            rerenderNotepad();
        }
    });
}










