const NEGATIVE_MARKERS = [
    'nightmare', 'hated', 'hate', 'awful', 'terrible', 'horrible', 'dreadful',
    'flopped', 'flop', 'failed', 'failing', 'waste', 'wasted', 'pointless',
    'useless', 'draining', 'drained', 'exhausting', 'dreaded', 'dread',
    'struggled', 'struggling', 'no luck', 'nothing came', 'fell flat',
    'did not work', "didn't work", 'didnt work', 'never again', 'gave up',
    'too hard', 'a slog', 'a chore', 'burnt me out'
];

const EFFECTIVE_BUCKETS = [
    { label: 'live teaching and showing up visible', terms: ['teaching', 'taught', 'live', 'webinar', 'workshop', 'masterclass', 'training'] },
    { label: 'direct follow-ups and outreach', terms: ['follow up', 'follow-up', 'followed up', 'following up', 'dm', 'dms', 'outreach', 'pitch', 'pitched', 'reached out', 'sales call', 'discovery call', 'consult call'] },
    { label: 'email marketing campaigns', terms: ['email', 'emails', 'emailed', 'newsletter', 'broadcast', 'sequence'] },
    { label: 'consistent content creation', terms: ['content', 'post', 'posts', 'posted', 'reel', 'reels', 'video', 'videos', 'tiktok', 'carousel'] },
    { label: 'backend systems and automation', terms: ['system', 'systems', 'automation', 'automated', 'funnel', 'workflow', 'landing page', 'sales page'] }
];

const DRAIN_BUCKETS = [
    { label: 'unclear weekly focus and distraction', terms: ['focus', 'unfocused', 'scattered', 'distracted', 'distraction', 'distractions', 'shiny'] },
    { label: 'time management and boundary setting', terms: ['time', 'schedule', 'scheduling', 'late', 'behind', 'boundaries', 'boundary'] },
    { label: 'content creation bottlenecks', terms: ['content', 'write', 'writing', 'wrote', 'edit', 'editing', 'post', 'posts', 'filming'] },
    { label: 'over-committing to too many tasks', terms: ['overwhelm', 'overwhelmed', 'burnout', 'burnt out', 'burned out', 'tired', 'exhausted', 'too much'] },
    { label: 'technology and tool friction', terms: ['tech', 'tool', 'tools', 'broken', 'glitch', 'glitches', 'crashed'] }
];




function positiveClauses(text) {
    return String(text || '')
        .toLowerCase()
        .split(/[.!?;\n]+|\bbut\b|\balthough\b|\bthough\b|\bhowever\b|\bexcept\b/)
        .map(c => c.trim())
        .filter(c => c && !NEGATIVE_MARKERS.some(marker => c.includes(marker)));
}

function allClauses(text) {
    return String(text || '')
        .toLowerCase()
        .split(/[.!?;\n]+/)
        .map(c => c.trim())
        .filter(Boolean);
}

function matchBuckets(clauses, buckets) {
    const haystack = clauses.join(' | ');
    return buckets
        .filter(bucket => bucket.terms.some(term => {
            const escaped = term.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&');
            return new RegExp('\\b' + escaped + '\\b').test(haystack);
        }))
        .map(bucket => bucket.label);
}





function reflectionPatterns(reviews) {
    const all = reviews || [];

    if (all.length < 2) {
        return {
            ready: false,
            count: all.length,
            message: 'Not enough yet. Finish two or three weekly reviews and this reads them back to you, so you plan the month from what actually happened rather than from memory.'
        };
    }

    const recent = all.slice(-4);

    const winClauses = recent.reduce((acc, r) => acc.concat(positiveClauses((r.workedWell || '') + '. ' + (r.movedForward || ''))), []);
    const effective = matchBuckets(winClauses, EFFECTIVE_BUCKETS);

    
    
    const drainClauses = recent.reduce((acc, r) => acc.concat(allClauses((r.difficult || '') + '. ' + (r.nextWeekImprove || ''))), []);
    const drains = matchBuckets(drainClauses, DRAIN_BUCKETS);

    return {
        ready: true,
        count: recent.length,
        worked: effective.slice(0, 2).join(' and ') || 'focused, uninterrupted action',
        bottleneck: drains[0] || 'maintaining execution consistency'
    };
}





function formatMonthlySummaryHtml(text) {
    const raw = String(text || '');
    if (!raw.trim()) return '';
    if (window.marked && typeof window.marked.parse === 'function') {
        return window.marked.parse(raw);
    }
    return escapeText(raw)
        .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
        .replace(/#{3} (.*?)(?:\n|$)/g, '<h4 style="margin-top: 1.5rem; color: var(--color-primary-dark);">$1</h4>')
        .replace(/\n/g, '<br>');
}
































function correctionPromptHtml() {
    const flag = mostUrgentRedFlag(getStore().redFlags);
    if (!flag) return '';
    const correction = String(flag.flag.correctiveAction || '').trim();
    if (!correction) return '';
    const metric = String(flag.flag.metric || flag.measureLabel || '').trim();
    const standing = flag.expectedText
        ? `${flag.actualText}, against about ${flag.expectedText} expected by now`
        : flag.actualText;
    return `
        <div class="win-panel" style="margin-bottom: 1rem;">
            <p style="margin: 0 0 0.35rem; font-weight: 700;">Your plan flagged this</p>
            <p style="margin: 0 0 0.5rem;">${escapeText(metric)}: ${escapeText(String(standing))}. When you set these 90 days up you said you would fix it like this:</p>
            <p style="margin: 0 0 0.75rem; font-style: italic;">${escapeText(correction)}</p>
            <button type="button" id="btn-use-correction" class="btn btn-outline btn-sm"
                    data-correction="${escapeText(correction)}">Use this as my revenue action</button>
        </div>
    `;
}

