let daily3Request = null;   
let daily3Slow = false;     
let daily3Note = '';        

const DAILY3_SLOTS = ['w-d1', 'w-d2', 'w-d3'];




const DAILY3_WAIT_MS = 12000;








function captureDaily3Boxes() {
    const els = DAILY3_SLOTS.map(id => document.getElementById(id));
    if (els.some(el => !el)) return false;
    mondayPlanData.daily3 = els.map(el => el.value);
    return true;
}









function applyDaily3Suggestions(suggestions) {
    captureDaily3Boxes();
    const next = (mondayPlanData.daily3 || ['', '', '']).slice();
    let filled = 0;
    DAILY3_SLOTS.forEach((id, i) => {
        const text = String(suggestions[i] || '');
        if (text.trim() === '') return;
        filled++;
        next[i] = text;
        const el = document.getElementById(id);
        if (el) el.value = text;
    });
    mondayPlanData.daily3 = next;
    return filled;
}


function aiButtonLabel() {
    if (daily3Request) {
        return daily3Slow
            ? 'Still working, these will fill in when it lands'
            : '✨ Breaking down your priorities…';
    }
    return daily3Note || '✨ Auto-Suggest based on Priorities';
}









function paintAiButton() {
    const skip = document.getElementById('btn-ai-daily-skip');
    if (skip) skip.hidden = !(daily3Request && daily3Slow);

    const btn = document.getElementById('btn-ai-daily');
    if (!btn) return;
    btn.disabled = Boolean(daily3Request);
    btn.textContent = aiButtonLabel();
    btn.classList.toggle('btn-outline', !daily3Request && Boolean(daily3Note));
}










function stopWaitingForDaily3() {
    if (!daily3Request) return;
    daily3Request = null;
    daily3Slow = false;
    const filled = applyDaily3Suggestions(generateDaily3Suggestions(mondayPlanData));
    daily3Note = filled > 0
        ? 'Filled from your priorities. Edit them into your own words.'
        : 'Add a priority above first';
    paintAiButton();
}













function startDaily3Breakdown() {
    daily3Slow = false;
    daily3Note = '';

    const slowTimer = setTimeout(() => {
        if (!daily3Request) return;
        daily3Slow = true;
        paintAiButton();
    }, DAILY3_WAIT_MS);

    const request = aiDaily3Breakdown(mondayPlanData)
        .catch(() => null)
        .then(tasks => {
            clearTimeout(slowTimer);
            if (daily3Request !== request) return;
            daily3Request = null;
            daily3Slow = false;
            if (tasks) {
                const filled = applyDaily3Suggestions(tasks);
                daily3Note = filled > 0 ? '✨ Tasks Applied!' : 'Add a priority above first';
            } else {
                
                
                
                const filled = applyDaily3Suggestions(generateDaily3Suggestions(mondayPlanData));
                daily3Note = filled > 0
                    ? 'Filled from your priorities (AI unavailable)'
                    : 'Add a priority above first';
            }
            paintAiButton();
        });

    daily3Request = request;
    paintAiButton();
}

