function mondayPlanToWeeklyPlan(data, store = getStore()) {
    const plan = {
        winCondition: data.weeklyFocus,
        priorities: data.priorities, 
        topActions: data.priorities, 
        revenueAction: data.revenueAction,
        daily3: data.daily3,
        id: data.generatedPlanId ? data.generatedPlanId : undefined,
        applied: data.generatedPlanId ? true : undefined,
        date: new Date().toISOString() 
    };

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    if (!data.generatedPlanId) {
        const roadmapWeek = roadmapWeekToPlan(store) || {};
        plan.visibilityAction = roadmapWeek.visibilityAction || '';
        plan.followUps = roadmapWeek.followUps || '';
    }

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const build = String(data.buildAction == null ? '' : data.buildAction).trim();
    if (build) {
        plan.buildAction = build;
    } else if (!data.generatedPlanId) {
        plan.buildAction = roadmapWeekToPlan(store)?.buildAction || '';
    }

    return plan;
}

function mondayPlanAttachEvents() {
    
    const skipBtn = document.getElementById('btn-skip-monday');
    if (skipBtn) {
        skipBtn.addEventListener('click', () => {
            
            sessionStorage.setItem('skippedMondayPlan', new Date().toDateString());
            window.location.hash = '#/dashboard';
        });
    }

    
    const backBtn = document.getElementById('btn-back');
    if (backBtn) {
        backBtn.addEventListener('click', () => {
            if (mondayStep > 1) {
                
                
                
                
                
                
                
                if (mondayStep === 4) captureDaily3Boxes();
                mondayStep--;
                document.getElementById('app-container').innerHTML = renderMondayPlan();
                mondayPlanAttachEvents();
            }
        });
    }

    
    if (mondayStep === 1) {
        document.getElementById('monday-form-1')?.addEventListener('submit', (e) => {
            e.preventDefault();
            mondayPlanData.weeklyFocus = document.getElementById('w-focus').value;
            mondayStep++;
            reRender();
        });
    }
    else if (mondayStep === 2) {
        document.getElementById('monday-form-2')?.addEventListener('submit', (e) => {
            e.preventDefault();
            mondayPlanData.priorities = [
                document.getElementById('w-p1').value,
                document.getElementById('w-p2').value,
                document.getElementById('w-p3').value
            ];
            mondayStep++;
            reRender();
        });
    }
    else if (mondayStep === 3) {
        
        
        document.getElementById('btn-use-correction')?.addEventListener('click', (e) => {
            const field = document.getElementById('w-rev');
            if (!field) return;
            field.value = e.currentTarget.getAttribute('data-correction') || '';
            field.focus();
            trackAction('correction_used_in_plan');
        });
        document.getElementById('monday-form-3')?.addEventListener('submit', (e) => {
            e.preventDefault();
            mondayPlanData.revenueAction = document.getElementById('w-rev').value;
            mondayPlanData.buildAction = document.getElementById('w-build')?.value || '';
            mondayStep++;
            reRender();
        });
    }
    else if (mondayStep === 4) {
        document.getElementById('monday-form-4')?.addEventListener('submit', (e) => {
            e.preventDefault();
            captureDaily3Boxes();
            
            mondayStep++;
            reRender();
        });

        
        
        
        
        document.querySelectorAll('.btn-carry-over').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const text = e.currentTarget.getAttribute('data-carry-text') || '';
                const slots = DAILY3_SLOTS.map(id => document.getElementById(id));
                const target = slots.find(el => el && el.value.trim() === '');
                if (!target) {
                    e.currentTarget.textContent = 'All three are full';
                    return;
                }
                target.value = text;
                
                
                captureDaily3Boxes();
                e.currentTarget.textContent = 'Kept ✓';
                e.currentTarget.disabled = true;
            });
        });

        
        const aiBtn = document.getElementById('btn-ai-daily');
        if (aiBtn) {
            
            
            
            paintAiButton();

            aiBtn.addEventListener('click', () => {
                
                
                
                
                if (daily3Request) return;

                
                
                
                if (!prioritiesDifferFromPlan(mondayPlanData)) {
                    const filled = applyDaily3Suggestions(generateDaily3Suggestions(mondayPlanData));
                    daily3Note = filled > 0 ? '✨ Tasks Applied!' : 'Add a priority above first';
                    paintAiButton();
                    return;
                }

                startDaily3Breakdown();
            });
        }

        
        
        
        document.getElementById('btn-ai-daily-skip')?.addEventListener('click', () => {
            stopWaitingForDaily3();
        });
    }

    
    const finishBtn = document.getElementById('btn-finish');
    if (finishBtn) {
        finishBtn.addEventListener('click', () => {
            
            
            
            
            const newPlan = mondayPlanToWeeklyPlan(mondayPlanData);

            
            
            const wasFirstPlan = !hasEverPlanned();

            
            if (newPlan.id) {
                updateWeeklyPlan(newPlan.id, newPlan);
            } else {
                addWeeklyPlan(newPlan);
            }

            if (wasFirstPlan) trackAction('plan.first', 'monday');

            
            
            
            
            const todayStr = getLocalDateString();
            const cleanTasks = mondayPlanData.daily3.map(t => ({ text: t, done: false }));
            
            
            
            
            
            
            const stored = getStore().weeklyPlans.find(p => String(p.id) === String(newPlan.id));
            updateDailyLog(todayStr, cleanTasks, planSourceKey(stored || newPlan));

            
            
            
            
            
            
            
            daily3Request = null;
            daily3Slow = false;
            daily3Note = '';
            mondayStep = 1;
            mondayPlanData = { weeklyFocus: '', priorities: ['', '', ''], revenueAction: '', buildAction: '', daily3: ['', '', ''], loadedFromDraft: false, generatedPlanId: null, fromReviewDraft: false, loadedStamp: '', loadedSnapshot: '' };
            clearDraftMondayPlan();

            
            sessionStorage.setItem('skippedMondayPlan', new Date().toDateString());

            
            window.location.hash = '#/dashboard';
        });
    }
}













function renderCarryOver(store) {
    const left = unfinishedDaily3LastWeek(store).slice(0, 3);
    if (left.length === 0) return '';

    return `
        <div class="mon-carry">
            <p class="mon-label">Left over from last week</p>
            <p class="mon-carry-text">
                ${left.length === 1 ? 'This action never got ticked' : `These ${left.length} actions never got ticked`}.
                Keep ${left.length === 1 ? 'it' : 'whichever still matters'} if it still matters, or leave ${left.length === 1 ? 'it' : 'them'} behind — a week that moved on is not a failure.
            </p>
            <div class="mon-carry-list">
                ${left.map((text, i) => `
                    <div class="mon-carry-row">
                        <button type="button" class="btn btn-outline btn-sm btn-carry-over" data-carry-text="${escapeText(text)}" data-carry-index="${i}">Keep this</button>
                        <span class="mon-carry-item">${escapeText(text)}</span>
                    </div>
                `).join('')}
            </div>
        </div>`;
}



































function reRender() {
    trackAction('plan.step', String(mondayStep));
    document.getElementById('app-container').innerHTML = renderMondayPlan();
    mondayPlanAttachEvents();
    window.scrollTo(0, 0);
}


function suggestionSourceWeek(data) {
    const store = getStore();
    const plans = store.weeklyPlans || [];
    
    
    return data.fromReviewDraft
        ? null
        : data.generatedPlanId
            ? plans.find(p => String(p.id) === String(data.generatedPlanId))
            : roadmapWeekToPlan(store);
}















function prioritiesDifferFromPlan(data) {
    const source = suggestionSourceWeek(data);
    const norm = (t) => stripPriorityLabels(String(t || '')).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
    const planPriorities = (source && Array.isArray(source.topActions)) ? source.topActions : [];
    return (data.priorities || []).some((typed, i) => {
        const t = norm(typed);
        
        
        if (!t) return false;
        return t !== norm(planPriorities[i]);
    });
}



































async function aiDaily3Breakdown(data) {
    const priorities = (data.priorities || []).map(t => String(t || '').trim()).filter(Boolean);
    if (priorities.length === 0) return null;

    
    
    
    
    
    
    
    const source = suggestionSourceWeek(data) || {};

    const actions = await generateDaily3Breakdown({
        weeklyFocus: data.weeklyFocus || '',
        priorities: priorities,
        revenueAction: data.revenueAction || '',
        visibilityAction: source.visibilityAction || '',
        followUps: source.followUps || ''
    });

    if (!Array.isArray(actions) || actions.length === 0) return null;
    const first = actions.slice(0, 3)
        .map(t => stripDayLabel(String(t || '').trim()))
        .filter(Boolean);
    return first.length > 0 ? first : null;
}







function generateDaily3Suggestions(data) {
    
    
    
    
    const source = suggestionSourceWeek(data);

    const fromPlan = (source && Array.isArray(source.daily3))
        ? source.daily3.filter(t => typeof t === 'string' && t.trim() !== '').map(stripDayLabel)
        : [];

    if (!prioritiesDifferFromPlan(data) && fromPlan.length >= 3) return fromPlan.slice(0, 3);

    
    
    
    
    
    
    
    
    const tasks = [];
    const p1 = data.priorities[0] || '';
    tasks.push(breakdownTask(p1, ''));

    const p2 = data.priorities[1] || '';
    tasks.push(breakdownTask(p2, ''));

    
    
    
    
    
    
    
    
    
    
    
    
    const p3 = data.priorities[2] || '';
    tasks.push(breakdownTask(p3.trim() !== '' ? p3 : (data.revenueAction || ''), ''));

    
    
    
    
    
    for (let i = 0; i < fromPlan.length && i < 3; i++) {
        if (String(tasks[i] || '').trim() === '') tasks[i] = fromPlan[i];
    }

    return tasks;
}

function breakdownTask(taskText, fallback) {
    if (!taskText || taskText.trim() === '') return fallback;

    
    
    let clean = taskText.replace(/^\s*task:\s*/i, '').split(/\bexecution:\s*/i)[0].trim();
    if (clean.length > 80) clean = clean.substring(0, 77).trim() + '...';
    const lower = clean.toLowerCase();

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    void lower;
    return `Make a start on: ${clean}`;
}































function isAdminAccount() {
    try {
        return localStorage.getItem('ceo_admin') === 'true';
    } catch (err) {
        return false;
    }
}







function quietFor(iso) {
    if (!iso) return { label: 'never', days: null };
    const then = new Date(iso);
    if (!Number.isFinite(then.getTime())) return { label: 'never', days: null };
    const days = Math.floor((Date.now() - then.getTime()) / 86400000);
    if (days <= 0) return { label: 'today', days: 0 };
    if (days === 1) return { label: 'yesterday', days: 1 };
    if (days < 30) return { label: days + ' days ago', days: days };
    const months = Math.round(days / 30);
    return { label: months === 1 ? 'a month ago' : months + ' months ago', days: days };
}



function quietClass(days) {
    if (days === null) return 'adm-quiet-never';
    if (days <= 7) return 'adm-quiet-ok';
    if (days <= 21) return 'adm-quiet-warn';
    return 'adm-quiet-gone';
}














function looksLikeTestAccount(email) {
    const e = String(email || '').toLowerCase();
    if (!e) return true;
    if (e.includes('@example.com')) return true;
    
    
    if (e.includes('+')) return true;
    if (e.startsWith('test') || e.includes('tester')) return true;
    if (e.startsWith('demo')) return true;
    if (e === String(SUPPORT_EMAIL || '').toLowerCase()) return true;
    
    
    
    
    
    const local = e.split('@')[0];
    if (local.includes('jeanette') || local.includes('spencer')) return true;
    return false;
}
































const NUMBER_WORDS = ['no', 'one', 'two', 'three', 'four', 'five', 'six',
                      'seven', 'eight', 'nine', 'ten'];

function inWords(n) {
    const v = Number(n);
    if (!Number.isFinite(v) || v < 0) return '0';
    return v <= 10 ? NUMBER_WORDS[v] : String(v);
}




function countPhrase(n, total, noun = 'accounts') {
    const a = Number(n) || 0;
    const b = Number(total) || 0;
    if (b === 0) return 'no ' + noun;
    
    
    
    if (a === 0) return b === 2 ? 'neither of the two ' + noun
                                : 'none of the ' + inWords(b) + ' ' + noun;
    if (a === b) {
        return b === 1
            ? 'the one ' + noun.replace(/s$/, '')
            : 'every one of the ' + inWords(b) + ' ' + noun;
    }
    return inWords(a) + ' of the ' + inWords(b) + ' ' + noun;
}



function hasHave(n) {
    return Number(n) === 1 ? 'has' : 'have';
}




function hasStarted(row) {
    return (Number(row.weekly_plans) || 0) > 0
        || (Number(row.daily_logs) || 0) > 0
        || (Number(row.reviews) || 0) > 0;
}

function daysBetween(a, b) {
    const t1 = new Date(a).getTime();
    const t2 = new Date(b).getTime();
    if (!Number.isFinite(t1) || !Number.isFinite(t2)) return null;
    return Math.round((t2 - t1) / 86400000);
}




const FEATURE_CHECKS = [
    {
        key: 'reviews',
        noun: 'saved a review',
        depends: 'The streak, the momentum score and most of Wins & Progress are all computed from reviews, so those screens are running on nothing.'
    },
    {
        key: 'daily_logs',
        noun: 'ticked anything off a Daily 3',
        depends: 'The Daily 3 is the loop the whole app is built around. A plan that is made and never ticked off is a plan nobody came back to.'
    },
    {
        key: 'coach_msgs',
        noun: 'asked the coach anything',
        depends: 'The coach is one of the things Pro is sold on, so this is worth knowing before the next round of upgrade emails.'
    },
    {
        key: 'contacts',
        noun: 'added a contact',
        depends: 'The lead pipeline is empty, which means the revenue screens have nothing to connect a sale back to.'
    }
];




function usageFindings(accounts, overview) {
    const rows = Array.isArray(accounts) ? accounts : [];
    const findings = [];

    const started = rows.filter(hasStarted);
    const total = started.length;

    
    
    
    if (total < 2) {
        findings.push({
            id: 'too-few',
            headline: 'Too few accounts to read anything into yet.',
            evidence: countPhrase(total, total || 1, 'accounts') + ' have built anything at all, so nothing below would mean much.',
            meaning: 'This fills in on its own as people join. The table underneath is still worth reading one row at a time.',
            names: []
        });
        return findings;
    }

    
    FEATURE_CHECKS.forEach(check => {
        const without = started.filter(r => (Number(r[check.key]) || 0) === 0);
        
        
        if (without.length === total) {
            findings.push({
                id: 'unused-' + check.key,
                headline: 'Nobody has ' + check.noun + '.',
                evidence: 'Not one of the ' + inWords(total)
                    + ' accounts that have started using the app has ever done it.',
                meaning: check.depends,
                names: []
            });
        } else if (total >= 4 && without.length >= total - 1) {
            findings.push({
                id: 'nearly-unused-' + check.key,
                headline: 'Almost nobody has ' + check.noun + '.',
                evidence: countPhrase(total - without.length, total) + ' has ever done it.',
                meaning: check.depends,
                names: []
            });
        }
    });

    
    
    
    
    
    const planNoLog = started.filter(r =>
        (Number(r.weekly_plans) || 0) >= 4 && (Number(r.daily_logs) || 0) <= 1);
    if (planNoLog.length) {
        findings.push({
            id: 'plans-no-logs',
            headline: 'They plan the week, then never tick anything off.',
            evidence: countPhrase(planNoLog.length, total) + ' ' + hasHave(planNoLog.length)
                + ' four or more weekly plans but at most one day ever logged.',
            meaning: 'Planning is landing and the daily habit is not. Whatever brings somebody back on a Tuesday is the thing missing.',
            names: planNoLog.map(r => r.email)
        });
    }

    
    
    
    
    
    const oneAndDone = started.filter(r => {
        const life = daysBetween(r.signed_up, r.last_active);
        const age = daysBetween(r.signed_up, new Date().toISOString());
        if (life === null || age === null) return false;
        
        
        
        return life <= 2 && age >= 7
            && ((Number(r.coach_msgs) || 0) >= 3 || (Number(r.ai_calls) || 0) >= 5);
    });
    if (oneAndDone.length) {
        findings.push({
            id: 'one-session',
            headline: 'Somebody arrived, did a lot in one sitting, and never came back.',
            evidence: countPhrase(oneAndDone.length, total) + ' did everything they have ever done within two days of signing up, and have not been back since.',
            meaning: 'Their coach thread is the closest thing to a recording of a first session. Reading it says what they came for and whether they got it.',
            names: oneAndDone.map(r => r.email)
        });
    }

    
    const quiet = started.filter(r => {
        const q = quietFor(r.last_active);
        return q.days !== null && q.days >= 21;
    });
    if (quiet.length) {
        findings.push({
            id: 'gone-quiet',
            headline: 'Some accounts that were using the app have stopped.',
            evidence: countPhrase(quiet.length, total) + ' built something and ' + hasHave(quiet.length)
                + ' not opened the app for three weeks or more.',
            meaning: 'These are the ones worth an email, because they got far enough to have an opinion about why they stopped.',
            names: quiet.map(r => r.email)
        });
    }

    
    
    
    
    const neverStarted = rows.filter(r => {
        if (hasStarted(r)) return false;
        const age = daysBetween(r.signed_up, new Date().toISOString());
        return age !== null && age >= 7;
    });
    if (neverStarted.length) {
        findings.push({
            id: 'never-started',
            headline: 'Some accounts have never built anything.',
            
            
            
            
            evidence: countPhrase(neverStarted.length, rows.length) + ' on the list signed up over a week ago and still '
                + hasHave(neverStarted.length) + ' no plan, no log and no review.',
            meaning: 'Everything between the signup and the first plan is where these were lost, and the wizard is most of that.',
            names: neverStarted.map(r => r.email)
        });
    }

    
    
    
    
    
    
    const screens = (overview && overview.screens) || [];
    const exits = (overview && overview.exits) || [];
    if (screens.length && exits.length) {
        const viewsFor = {};
        screens.forEach(s => { viewsFor[s.screen] = Number(s.views) || 0; });
        const suspect = exits
            .filter(e => (Number(e.sessions) || 0) >= 5)
            .filter(e => {
                const views = viewsFor[e.screen] || 0;
                
                
                return views >= 5 && (Number(e.sessions) / views) > 0.5;
            });
        if (suspect.length) {
            const worst = suspect[0];
            findings.push({
                id: 'exit-screen',
                headline: 'Visits are ending on ' + worst.screen + '.',
                evidence: inWords(worst.sessions) + ' of the visits that reached ' + worst.screen
                    + ' ended there, out of ' + inWords(viewsFor[worst.screen] || 0) + ' times it was opened.',
                meaning: 'People get to that screen and stop. Either it is the last thing they needed, or it is where they give up.',
                names: []
            });
        }
    }

    if (!findings.length) {
        findings.push({
            id: 'nothing',
            headline: 'Nothing stands out.',
            evidence: 'Across ' + countPhrase(total, total) + ' that have started using the app, none of the patterns worth flagging are showing.',
            meaning: 'That is a real answer, not an empty one. The table below is still there to read.',
            names: []
        });
    }

    return findings;
}

