function isPaying(row) {
    return String(row && row.status || '').toLowerCase() === 'active';
}







function signupSourceBreakdown(rows) {
    const list = Array.isArray(rows) ? rows : [];
    const from = signupSourceTrackingFrom();

    const buckets = {};
    const order = [];
    const bucket = (id, label) => {
        if (!buckets[id]) {
            buckets[id] = { id: id, label: label, signups: 0, started: 0, paying: 0 };
            order.push(id);
        }
        return buckets[id];
    };

    
    
    
    signupSourceList().forEach(c => bucket(c.id, c.label));

    list.forEach(row => {
        const source = String(row && row.source || '').toLowerCase();
        let entry;
        if (knownSignupSource(source)) {
            entry = bucket(source, signupSourceLabel(source));
        } else {
            
            
            
            const joined = String(row && row.signed_up || '');
            entry = joined && joined < from
                ? bucket('before', 'Before link tracking')
                : bucket('direct', 'Direct or unknown');
        }
        entry.signups += 1;
        if (hasStarted(row)) entry.started += 1;
        if (isPaying(row)) entry.paying += 1;
    });

    const channels = signupSourceList()
        .map(c => buckets[c.id])
        .sort((a, b) => b.signups - a.signups);

    const tail = ['direct', 'before']
        .map(id => buckets[id])
        .filter(b => b && b.signups > 0);

    return {
        rows: channels.concat(tail),
        total: list.length,
        tracked: channels.reduce((sum, c) => sum + c.signups, 0)
    };
}






















function signupClicksBySource(clickRows) {
    const map = {};
    (Array.isArray(clickRows) ? clickRows : []).forEach(r => {
        const id = String((r && r.source) || '').toLowerCase();
        if (knownSignupSource(id)) map[id] = Number(r.clicks) || 0;
    });
    return map;
}




function signupClicksSince(clickRows) {
    const days = (Array.isArray(clickRows) ? clickRows : [])
        .map(r => String((r && r.first_day) || ''))
        .filter(d => /^\d{4}-\d{2}-\d{2}$/.test(d))
        .sort();
    if (!days.length) return null;
    return new Date(days[0] + 'T12:00:00Z')
        .toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
}




