let loadedAccounts = null;
let loadedOverviews = {};



let loadedClicks = null;

function showingTestAccounts() {
    const el = document.getElementById('adm-show-test');
    return Boolean(el && el.checked);
}



function whoFilter() {
    const el = document.getElementById('adm-who');
    const value = el ? String(el.value || '') : '';
    return (value === 'beta' || value === 'live') ? value : 'all';
}





function matchesWho(row, who) {
    if (who === 'beta') return Boolean(row && row.beta);
    if (who === 'live') return !(row && row.beta);
    return true;
}

function overviewKey() {
    return whoFilter() + '|' + (showingTestAccounts() ? 'all' : 'real');
}




function visibleRows() {
    const showTest = showingTestAccounts();
    const who = whoFilter();
    return (loadedAccounts || []).filter(r =>
        (showTest || !looksLikeTestAccount(r.email)) && matchesWho(r, who));
}











function excludedUserIds() {
    const showTest = showingTestAccounts();
    const who = whoFilter();
    return (loadedAccounts || [])
        .filter(r => (!showTest && looksLikeTestAccount(r.email)) || !matchesWho(r, who))
        .map(r => r.user_id)
        .filter(Boolean);
}

async function fetchOverview() {
    const key = overviewKey();
    if (loadedOverviews[key]) return loadedOverviews[key];

    try {
        const { data, error } = await window.db.rpc('usage_overview', {
            p_days: 30,
            p_exclude: excludedUserIds()
        });
        if (error) {
            console.warn('Usage overview failed:', error.message);
            return null;
        }
        loadedOverviews[key] = data || null;
        return loadedOverviews[key];
    } catch (err) {
        console.warn('Usage overview failed:', err && err.message);
        return null;
    }
}




async function fetchSignupClicks() {
    try {
        const { data, error } = await window.db.rpc('signup_link_clicks_total');
        if (error) {
            console.warn('Signup link clicks failed:', error.message);
            return { failed: true };
        }
        return { rows: Array.isArray(data) ? data : [] };
    } catch (err) {
        console.warn('Signup link clicks failed:', err && err.message);
        return { failed: true };
    }
}

function paintBody() {
    const body = document.getElementById('adm-body');
    if (!body) return;

    const showTest = showingTestAccounts();
    const who = whoFilter();
    const rows = visibleRows();
    const overview = loadedOverviews[overviewKey()];

    
    
    const hidden = (loadedAccounts || [])
        .filter(r => matchesWho(r, who) && looksLikeTestAccount(r.email)).length;
    const hiddenNote = showTest || hidden === 0
        ? ''
        : ' ' + hidden + (hidden === 1 ? ' test account is' : ' test accounts are')
            + ' hidden, here and in the figures above. That is a guess made from the address, so check the switch before reading anything into a total.';

    const heading = who === 'beta' ? 'The beta group'
                  : who === 'live' ? 'Everyone outside the beta'
                  : 'Every account';
    const lede = who === 'beta'
        ? 'Only accounts flagged as beta testers in the database.'
        : who === 'live'
            ? 'Everyone who is not flagged as a beta tester — the people who have joined since, and anyone who was never in the group.'
            : 'Beta testers and everyone else together.';

    
    
    
    
    body.innerHTML = `
            ${adminFindingsHtml(rows, overview)}

            ${overview
                ? adminOverviewHtml(overview, { who: who, shown: rows.length })
                : '<p class="adm-loading">Counting the screens again for that group…</p>'}

            ${



''}
            ${adminSourcesHtml(rows, loadedClicks)}

            <section class="card adm-panel">
                <h2 class="adm-h2">${escapeText(heading)}</h2>
                <p class="adm-sub">${escapeText(lede + hiddenNote)}</p>
                ${adminAccountsTableHtml(rows)}
            </section>`;
}



function onSwitchToggled() {
    paintBody();
    if (!loadedOverviews[overviewKey()]) {
        fetchOverview().then(paintBody);
    }
}

async function loadAdminData() {
    const body = document.getElementById('adm-body');

    try {
        
        
        const accounts = await window.db.rpc('usage_accounts');

        if (accounts.error) {
            const message = accounts.error.message || '';
            
            
            
            const missing = /does not exist|42883/i.test(message);
            if (body) {
                body.innerHTML = `<p class="adm-empty">${missing
                    ? 'The usage functions are not in the database yet. The migration has not been run against this project.'
                    : 'Could not read the numbers just now. Nothing is wrong with the data; the request did not get through.'}</p>`;
            }
            console.warn('Usage read failed:', message);
            return;
        }

        loadedAccounts = Array.isArray(accounts.data) ? accounts.data : [];
        
        
        const [, clicks] = await Promise.all([fetchOverview(), fetchSignupClicks()]);
        loadedClicks = clicks;
        paintBody();
    } catch (err) {
        if (body) {
            body.innerHTML = '<p class="adm-empty">Could not reach the server. Try Refresh in a moment.</p>';
        }
        console.warn('Usage read failed:', err && err.message);
    }
}

function adminAttachEvents() {
    if (!isAdminAccount()) return;

    const toggle = document.getElementById('adm-show-test');
    if (toggle) toggle.addEventListener('change', onSwitchToggled);

    const who = document.getElementById('adm-who');
    if (who) who.addEventListener('change', onSwitchToggled);

    
    
    
    
    const bodyEl = document.getElementById('adm-body');
    if (bodyEl) {
        bodyEl.addEventListener('click', (e) => {
            const btn = e.target && e.target.closest && e.target.closest('.adm-link-copy');
            if (!btn) return;
            const url = btn.getAttribute('data-link') || '';
            if (!url) return;

            
            
            
            const fallback = () => {
                const field = btn.parentElement && btn.parentElement.querySelector('.adm-link-url');
                if (field && field.select) field.select();
                showToast('Press Ctrl+C to copy the link.', 'info', 6000);
            };
            try {
                navigator.clipboard.writeText(url).then(() => {
                    const was = btn.innerText;
                    btn.innerText = 'Copied';
                    setTimeout(() => { btn.innerText = was; }, 2000);
                }).catch(fallback);
            } catch (err) {
                fallback();
            }
        });
    }

    const refresh = document.getElementById('adm-refresh');
    if (refresh) {
        refresh.addEventListener('click', () => {
            const body = document.getElementById('adm-body');
            if (body) body.innerHTML = '<p class="adm-loading">Reading the numbers…</p>';
            
            
            
            loadedOverviews = {};
            loadAdminData().then(() => showToast('Up to date.'));
        });
    }

    loadAdminData();
}





