let turnstileWidgetId = null;









const AUTH_STEP_TIMEOUT_MS = 8000;

function withTimeout(promise, label) {
    return Promise.race([
        promise,
        new Promise((_, reject) => setTimeout(
            () => reject(new Error('Timed out waiting for ' + label)), AUTH_STEP_TIMEOUT_MS))
    ]);
}

function captchaSiteKey() {
    return window.CEO_TURNSTILE_SITE_KEY || null;
}












function captchaAppliesTo(mode) {
    return mode !== 'reset' && !!captchaSiteKey();
}

function mountCaptcha(mode, attempt = 0, holderId = 'auth-captcha') {
    if (!captchaAppliesTo(mode)) return;

    const holder = document.getElementById(holderId);
    if (!holder) return;

    
    
    
    if (typeof window.turnstile === 'undefined') {
        if (attempt < 40) setTimeout(() => mountCaptcha(mode, attempt + 1, holderId), 150);
        return;
    }

    
    if (turnstileWidgetId !== null) {
        try { window.turnstile.remove(turnstileWidgetId); } catch (err) {  }
        turnstileWidgetId = null;
    }
    holder.innerHTML = '';

    const refresh = () => {
        try { window.turnstile.reset(turnstileWidgetId); } catch (err) {  }
    };

    turnstileWidgetId = window.turnstile.render(holder, {
        sitekey: captchaSiteKey(),
        theme: 'light',
        
        
        
        
        
        'expired-callback': refresh,
        
        
        
        'error-callback': refresh,
    });
}

function captchaToken(mode) {
    if (!captchaAppliesTo(mode) || turnstileWidgetId === null) return undefined;
    try {
        return window.turnstile.getResponse(turnstileWidgetId) || undefined;
    } catch (err) {
        return undefined;
    }
}



function resetCaptcha() {
    if (turnstileWidgetId === null || typeof window.turnstile === 'undefined') return;
    try { window.turnstile.reset(turnstileWidgetId); } catch (err) {  }
}
















function canonicalEmail(email) {
    if (!email) return email;

    const at = email.lastIndexOf('@');
    if (at === -1) return email;

    let local = email.slice(0, at);
    const domain = email.slice(at + 1);
    if (domain !== 'gmail.com' && domain !== 'googlemail.com') return email;

    const plus = local.indexOf('+');
    if (plus !== -1) local = local.slice(0, plus);
    local = local.split('.').join('');

    
    
    if (!local) return email;

    return local + '@gmail.com';
}


















function errorProbe(error) {
    const raw = (error && (error.message || error.error_description)) || '';
    const code = (error && error.code) || '';
    return (code + ' ' + raw).toLowerCase();
}




function isRateLimit(error) {
    const probe = errorProbe(error);
    return probe.includes('over_email_send_rate_limit') ||
        probe.includes('rate limit') ||
        probe.includes('too many requests');
}

function authErrorMessage(error, context) {
    const probe = errorProbe(error);

    
    
    
    if (isRateLimit(error)) {
        return context === 'forgot'
            ? "That email is already on its way. Check your inbox, and your spam folder, before asking for another."
            : "That's a few attempts in quick succession. Give it a minute and try again.";
    }

    
    
    if (probe.includes('captcha')) {
        return "The security check didn't go through. Reload the page and try again.";
    }

    
    if (probe.includes('timed out waiting for') || probe.includes('failed to fetch') || probe.includes('networkerror') || probe.includes('load failed')) {
        return "We couldn't reach the server just now. Check your connection and try again.";
    }

    if (context === 'login') {
        if (probe.includes('invalid login credentials') || probe.includes('invalid_credentials')) {
            return "That email and password don't match. Check the password, or create an account if you haven't yet.";
        }
        if (probe.includes('email not confirmed') || probe.includes('email_not_confirmed')) {
            
            
            return "That account still needs confirming. Open the link in the email we sent you, or use the button below to get a new one.";
        }
        return "We couldn't sign you in just now. Try again, and if it keeps happening use \"Forgot password\" to get back in.";
    }

    if (context === 'signup') {
        if (probe.includes('already registered') || probe.includes('user_already_exists') || probe.includes('already been registered')) {
            return "There's already an account on that email. Log in instead, or use \"Forgot password\" if you can't remember it.";
        }
        if (probe.includes('weak_password') || probe.includes('password should be')) {
            return "That password is too short. Use at least six characters.";
        }
        if (probe.includes('invalid') && probe.includes('email')) {
            return "That doesn't look like a complete email address. Check it and try again.";
        }
        if (probe.includes('signups not allowed') || probe.includes('signup_disabled')) {
            return "New accounts are paused at the moment. Email us and we'll sort it out.";
        }
        return "We couldn't create that account just now. Try again in a moment.";
    }

    if (context === 'forgot') {
        return "We couldn't send that reset email just now. Try again in a moment.";
    }

    
    if (probe.includes('same_password') || probe.includes('should be different')) {
        return "That's the password you already have. Choose a different one.";
    }
    if (probe.includes('weak_password') || probe.includes('password should be')) {
        return "That password is too short. Use at least six characters.";
    }
    if (probe.includes('session') || probe.includes('expired') || probe.includes('jwt')) {
        return "That password link has expired. Ask for a new one and it will work.";
    }
    return "We couldn't change the password just now. Ask for a new link and try again.";
}


function showAuthError(error, context) {
    console.warn('Auth (' + context + ') failed:', (error && error.message) || error);
    showToast(authErrorMessage(error, context), 'error');
}

function isUnconfirmedEmail(error) {
    const probe = errorProbe(error);
    return probe.includes('email not confirmed') || probe.includes('email_not_confirmed');
}















function offerConfirmationResend(email) {
    if (!email) return;
    const form = document.getElementById('auth-form');
    if (!form) return;

    let holder = document.getElementById('auth-resend');
    if (!holder) {
        holder = document.createElement('div');
        holder.id = 'auth-resend';
        holder.style.cssText = 'text-align: center; margin-top: 1rem;';
        holder.innerHTML = `
            <p style="font-size: 0.85rem; color: var(--color-text-muted); margin: 0 0 0.5rem;">
                Link expired, or the email never arrived?
            </p>
            <button type="button" class="btn btn-secondary" style="width: 100%; border-radius: 8px;">
                Send the confirmation email again
            </button>
        `;
        form.insertAdjacentElement('afterend', holder);
    }

    const btn = holder.querySelector('button');
    
    
    const fresh = btn.cloneNode(true);
    btn.replaceWith(fresh);

    fresh.addEventListener('click', async () => {
        if (fresh.disabled) return;

        const token = captchaToken('auth');
        if (captchaAppliesTo('auth') && !token) {
            showToast("Still checking you're human. Give it a second and try again.", 'error');
            return;
        }

        fresh.disabled = true;
        const label = fresh.innerText;
        fresh.innerText = 'Sending...';
        try {
            const { error } = await window.db.auth.resend({
                type: 'signup',
                email: email,
                options: {
                    
                    emailRedirectTo: window.location.origin + window.location.pathname,
                    captchaToken: token
                }
            });
            if (error) {
                
                showAuthError(error, 'forgot');
            } else {
                showToast(
                    "Sent. Open the newest email from us, as the older link will not work. Check your spam folder if it is not there.",
                    'success',
                    10000
                );
            }
        } catch (err) {
            showAuthError(err, 'forgot');
        } finally {
            fresh.disabled = false;
            fresh.innerText = label;
            resetCaptcha();
        }
    });
}


















async function completeSignIn(userId, destination) {
    
    const loaded = await swapStoreForAccount(userId, { quiet: true });

    
    
    
    
    
    
    
    
    if (loaded === false) {
        localStorage.removeItem('ceo_auth');
        try {
            await window.db.auth.signOut({ scope: 'local' });
        } catch (err) {
            console.warn('Could not end the half-made session:', err && err.message);
        }
        window.CEO_SIGNING_IN = false;
        showToast(
            "We couldn't load your account's data just now, so you haven't been signed in and nothing has changed. Check your connection and try again.",
            'error',
            12000
        );
        return false;
    }

    
    
    
    
    
    let access = null;
    try {
        access = await withTimeout(window.refreshAccessState(), 'your account');
    } catch (err) {
        console.warn('Could not read access state in time:', err.message);
    }
    if (!access) {
        
        
        localStorage.setItem('ceo_sub_status', 'trialing');
    }

    localStorage.setItem('ceo_auth', 'true');

    
    
    
    
    if (typeof window.reportTimezone === 'function') window.reportTimezone();

    
    
    
    reloadAt((typeof destination === 'function' ? destination() : destination) || '#/');
}






















let swapInFlight = null;
let swapInFlightFor = null;







function swapStoreForAccount(userId, options = {}) {
    if (!userId) return Promise.resolve(true);
    if (swapInFlight && swapInFlightFor === userId) return swapInFlight;

    swapInFlightFor = userId;
    swapInFlight = runStoreSwap(userId, options).finally(() => {
        swapInFlight = null;
        swapInFlightFor = null;
    });
    return swapInFlight;
}

async function runStoreSwap(userId, options = {}) {
    beginStoreSwap();

    
    
    
    
    
    
    
    
    
    try {
        const outgoing = localStorage.getItem('ceoPlanner_store');
        if (outgoing && outgoing.length > 2) {
            localStorage.setItem('ceoPlanner_rescue_' + new Date().toISOString(), outgoing);
            const rescues = Object.keys(localStorage)
                .filter(k => k.startsWith('ceoPlanner_rescue_'))
                .sort();
            while (rescues.length > 3) localStorage.removeItem(rescues.shift());
        }
    } catch (err) {
        
        console.warn('Could not keep a rescue copy:', err.message);
    }

    localStorage.removeItem('ceoPlanner_store');
    
    
    localStorage.removeItem('ceo_last_sync');
    localStorage.removeItem('ceo_server_stamp');
    localStorage.removeItem('ceo_own_stamps');
    
    
    
    
    localStorage.removeItem('ceo_loops_synced');
    
    
    clearLiveAICache();
    clearAiAllowance();
    
    
    
    clearAfterSetupRoute();
    
    
    setStoreOwner(userId);

    
    try {
        const { data: dbData, error: dbError } = await withTimeout(window.db
            .from('user_data')
            .select('data')
            .eq('user_id', userId)
            .maybeSingle(), 'your saved data');

        if (dbError) throw dbError;

        if (dbData && dbData.data) {
            localStorage.setItem('ceoPlanner_store', JSON.stringify(dbData.data));
            
            
            
            
            
            localStorage.setItem('ceo_last_sync', new Date().toISOString());
            
            
            if (dbData.data.lastSavedAt) localStorage.setItem('ceo_server_stamp', dbData.data.lastSavedAt);
        }
        endStoreSwap();
        return true;
    } catch (err) {
        
        
        
        
        
        
        
        console.warn('Could not load this account\'s data. Cloud saving stays off until reload.', err);
        if (!options.quiet) {
            showToast(
                "We couldn't load your account's data just now. Reload the page before you change anything — nothing will be saved to your account until you do.",
                'error',
                12000
            );
        }
        
        
        
        return false;
    }
}

function authAttachEvents() {
    const form = document.getElementById('auth-form');
    if (!form) return;

    
    
    
    
    
    try {
        if (sessionStorage.getItem('ceo_erased') === '1') {
            sessionStorage.removeItem('ceo_erased');
            showToast('Everything has been erased, from this device and from our servers. You can sign up again any time.', 'success', 9000);
        }
    } catch (err) {
        
    }

    const hash = window.location.hash || '#/';
    const isSignup = hash.startsWith('#/signup');
    const isForgot = hash.startsWith('#/forgot-password');
    const isReset = hash.startsWith('#/reset-password');

    const captchaMode = isReset ? 'reset' : 'auth';
    mountCaptcha(captchaMode);

    
    const hashQuery = hash.includes('?') ? hash.split('?')[1] : '';
    const urlParams = new URLSearchParams(window.location.search || hashQuery);
    const stripeEmail = urlParams.get('email');
    if (stripeEmail && document.getElementById('auth-email')) {
        document.getElementById('auth-email').value = stripeEmail;
    } else if (!isSignup && !isForgot && !isReset) {
        
        
        const rememberedEmail = localStorage.getItem('ceo_remembered_email');
        if (rememberedEmail && document.getElementById('auth-email')) {
            document.getElementById('auth-email').value = rememberedEmail;
        }
        if (rememberedEmail && document.getElementById('auth-remember')) {
            document.getElementById('auth-remember').checked = true;
        }
    }

    form.addEventListener('submit', (e) => {
        e.preventDefault();
        
        const emailEl = document.getElementById('auth-email');
        const rawEmail = emailEl ? emailEl.value : null;
        const email = rawEmail ? canonicalEmail(rawEmail.trim().toLowerCase()) : null;

        const passwordEl = document.getElementById('auth-password');
        const password = passwordEl ? passwordEl.value : null;

        const btn = form.querySelector('button[type="submit"]');
        const originalText = btn.innerText;

        
        
        
        
        const token = captchaToken(captchaMode);
        if (captchaAppliesTo(captchaMode) && !token) {
            showToast("Still checking you're human. Give it a second and try again.", 'error');
            return;
        }

        btn.innerText = "Processing...";
        btn.style.opacity = '0.8';

        if (isForgot) {
            if (email) {
                window.db.auth.resetPasswordForEmail(email, {
                    
                    
                    redirectTo: window.location.origin + window.location.pathname,
                    captchaToken: token
                }).then(({ error }) => {
                    btn.innerText = originalText;
                    btn.style.opacity = '1';
                    resetCaptcha();
                    
                    
                    
                    
                    
                    
                    const rateLimited = error && isRateLimit(error);
                    if (error && !rateLimited) {
                        showAuthError(error, 'forgot');
                    } else {
                        showToast(rateLimited
                            ? "That email is already on its way. Check your inbox, and your spam folder, before asking for another."
                            : "Password reset email sent. Please check your inbox.");
                        window.location.hash = '#/login';
                    }
                });
            }
        } else if (isReset) {
            if (password) {
                window.db.auth.updateUser({ password: password }).then(async ({ error }) => {
                    btn.innerText = originalText;
                    btn.style.opacity = '1';
                    if (error) {
                        showAuthError(error, 'reset');
                    } else {
                        
                        
                        
                        
                        
                        
                        localStorage.removeItem('ceo_auth');
                        try {
                            await window.db.auth.signOut({ scope: 'local' });
                        } catch (err) {
                            console.warn('Could not end the reset session:', err && err.message);
                        }
                        showToast("Password updated. Please log in with your new password.");
                        window.location.hash = '#/login';
                    }
                });
            }
        } else if (isSignup) {
            const name = document.getElementById('auth-name').value;

            
            
            
            
            
            
            
            
            let signupTz = null;
            try {
                signupTz = Intl.DateTimeFormat().resolvedOptions().timeZone || null;
            } catch (err) {
                signupTz = null;
            }

            
            
            
            
            
            
            
            
            
            
            
            const signupSource = pendingSignupSource();

            window.db.auth.signUp({
                email: email,
                password: password,
                options: {
                    data: { name: name, timezone: signupTz, signup_source: signupSource },
                    captchaToken: token,
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    
                    emailRedirectTo: window.location.origin + window.location.pathname
                }
            }).then(async ({ data: signUpData, error: signUpError }) => {
                if (signUpError) {
                    showAuthError(signUpError, 'signup');
                    btn.innerText = originalText;
                    btn.style.opacity = '1';
                    resetCaptcha();
                    
                    
                    
                    
                    return;
                }

                
                
                
                
                clearSignupSource();

                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                
                if (signUpData && signUpData.user && !signUpData.session) {
                    
                    
                    
                    
                    showToast(
                        "Account created. Open the link in the email we've just sent to " +
                        email + " to get started. Check your spam folder if it is not there.",
                        'success',
                        12000
                    );
                    btn.innerText = originalText;
                    btn.style.opacity = '1';
                    resetCaptcha();
                    window.location.hash = '#/login';
                    return;
                }

                
                await new Promise(resolve => setTimeout(resolve, 600));
                const access = await window.refreshAccessState();
                if (!access) {
                    
                    
                    
                    
                    localStorage.setItem('ceo_sub_status', 'trialing');
                }

                
                
                
                
                
                
                
                
                await window.ensureLoopsContact();

                
                
                
                
                localStorage.removeItem('ceoPlanner_store');
                clearLiveAICache();
                clearAiAllowance();
                
                
                
                if (signUpData && signUpData.user) setStoreOwner(signUpData.user.id);

                localStorage.setItem('ceo_auth', 'true');
                
                
                
                
                clearIntendedRoute();
                reloadAt('#/');
            });
        } else {
            
            
            
            
            
            
            
            
            window.CEO_SIGNING_IN = true;
            window.db.auth.signInWithPassword({
                email: email,
                password: password,
                options: { captchaToken: token }
            }).then(async ({ data, error }) => {
                if (error) {
                    window.CEO_SIGNING_IN = false;
                    showAuthError(error, 'login');
                    btn.innerText = originalText;
                    btn.style.opacity = '1';
                    resetCaptcha();
                    
                    
                    if (isUnconfirmedEmail(error)) offerConfirmationResend(email);
                } else {
                    
                    const rememberEl = document.getElementById('auth-remember');
                    if (rememberEl && rememberEl.checked) {
                        localStorage.setItem('ceo_remembered_email', email);
                    } else {
                        localStorage.removeItem('ceo_remembered_email');
                    }

                    
                    
                    
                    
                    
                    
                    
                    
                    const signedIn = await completeSignIn(data.user.id, () => takeIntendedRoute() || '#/');
                    if (signedIn === false) {
                        
                        
                        
                        btn.innerText = originalText;
                        btn.style.opacity = '1';
                        resetCaptcha();
                    }
                }
            }).catch((err) => {
                
                
                window.CEO_SIGNING_IN = false;
                showAuthError(err, 'login');
                btn.innerText = originalText;
                btn.style.opacity = '1';
                resetCaptcha();
            });
        }
    });
}









function redFlagMetricLabel(flag) {
    const metric = String((flag && flag.metric) || '').trim();
    const measure = RED_FLAG_MEASURES[metric];
    return measure ? measure.label : metric;
}




















function flagStandingText(c) {
    const measure = String(c.measureLabel || '').toLowerCase();
    if (c.status === 'early') {
        return escapeText(`${c.actualText} so far — too early ${c.periodLabel || ''} to call this one`.trim());
    }
    if (c.status === 'nodata') {
        return escapeText('Nothing logged against this yet');
    }
    if (c.expectedText) {
        return escapeText(`${c.actualText} — ${measure} — and about ${c.expectedText} is what this point expects`);
    }
    return escapeText(`${c.actualText} — ${measure}`);
}




function flagBarHtml(c) {
    const target = c.flag && c.flag.check ? parseFloat(c.flag.check.value) : NaN;
    if (!Number.isFinite(target) || target <= 0) return '';
    if (!Number.isFinite(c.actual) || !Number.isFinite(c.expected)) return '';
    const pct = (n) => Math.max(0, Math.min(100, (n / target) * 100));
    return `
        <div class="road-flag-bar">
            <div class="road-flag-bartrack">
                <span class="road-flag-barfill" style="width: ${pct(c.actual).toFixed(1)}%;"></span>
                <span class="road-flag-barmark" style="left: ${pct(c.expected).toFixed(1)}%;"></span>
            </div>
            <p class="road-flag-barscale"><span>now</span><span>expected by now</span><span>${escapeText(String(c.flag.threshold || '').trim())}</span></p>
        </div>
    `;
}

function redFlagStatusCell(checked) {
    const sub = (text) => '<span style="display: block; font-size: 0.78rem; color: var(--color-text-muted); margin-top: 0.15rem;">' + text + '</span>';

    
    
    
    
    
    const against = (checked.expectedText && checked.periodLabel)
        ? ' · about ' + checked.expectedText + ' expected by now'
        : '';

    if (checked.status === 'tripped') {
        return '<span style="display: inline-block; background: #FEE2E2; color: #B91C1C; font-weight: 700; padding: 0.15rem 0.45rem; border-radius: 4px; white-space: nowrap;">⚠ ' + checked.actualText + '</span>'
            + sub(checked.measureLabel + against);
    }
    if (checked.status === 'ontrack') {
        return '<span style="display: inline-block; color: #047857; font-weight: 600; white-space: nowrap;">✓ ' + checked.actualText + '</span>'
            + sub(checked.measureLabel + against);
    }
    
    
    
    
    
    if (checked.status === 'early') {
        return '<span style="color: var(--color-text-muted); white-space: nowrap;">' + checked.actualText + ' so far</span>'
            + sub('Too early ' + (checked.periodLabel || '') + ' to call this');
    }
    if (checked.status === 'nodata') {
        return '<span style="color: var(--color-text-muted);">Nothing logged yet</span>'
            + sub(checked.measureLabel);
    }
    return '<span style="color: var(--color-text-muted);">Check this yourself</span>';
}














function roadmapMonthForWeek(weekNumber, fallback) {
    const week = parseInt(weekNumber, 10);
    if (!Number.isInteger(week) || week < 1) return fallback;
    return Math.min(3, Math.ceil(week / 4));
}






function roadmapWeekRow(w, currentWeek) {
    const isCurrent = !w.applied && w.weekNumber === currentWeek;
    const status = w.applied
        ? '<span class="tag-chip road-chip-done">Completed</span>'
        : (isCurrent ? '<span class="tag-chip road-chip-now">This week</span>' : '<span class="tag-chip road-chip-planned">Planned</span>');
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const actions = [
        
        
        ['Visibility', w.visibilityAction],
        ['Revenue', w.revenueAction],
        ['Follow-up', w.followUps]
    ].filter(a => a[1]);
    const cls = 'road-week' + (w.applied ? ' is-done' : '') + (isCurrent ? ' is-current' : '');
    return `
        <details class="${cls}"${isCurrent ? ' open' : ''}>
            <summary>
                <strong class="road-week-label">Week ${w.weekNumber} · Month ${roadmapMonthForWeek(w.weekNumber, w.monthIndex)}</strong>
                <span class="road-week-focus"><strong>Focus:</strong> ${w.winCondition}</span>
                ${w.regeneratedAt ? '<span class="tag-chip road-chip-rewritten">Rewritten</span>' : ''}
                ${status}
                <span class="road-week-chev" aria-hidden="true"></span>
            </summary>
            <div class="road-week-body">
                <div class="road-week-grid">
                    <div class="road-box">
                        <p class="road-box-label">Top 3 priorities</p>
                        <ul class="road-bullets">${(w.topActions || []).map(p => `<li>${p}</li>`).join('')}</ul>
                    </div>
                    <div class="road-box">
                        <p class="road-box-label">This week's actions</p>
                        ${actions.map(a => `<p class="road-action"><span class="tag-chip tag-chip-teal">${a[0]}</span>${a[1]}</p>`).join('')}
                    </div>
                </div>
                <div class="road-box">
                    <!-- NOT "Daily micro-tasks" - Jen, 28 Sept 2026. Under that
                         name they read as a second copy of the Top 3 beside
                         them, and she was right that they are the same work at
                         a finer grain: rule 13b makes dailyThree the breakdown
                         of that week's topPriorities.
                         AND THEY ARE NOT HER DAILY 3. These are w.daily3, the
                         90-day plan's three opening steps for the week and the
                         fallback pool for weekSequence(). The dashboard's Daily
                         3 comes from dailySequence, a separate 15-task weekly
                         sequence. Two different things under almost the same
                         name was half the reason this card read as a repeat, so
                         the label now says what these actually are.
                         NO BACKTICKS IN THIS COMMENT. It sits inside a template
                         literal, so a backtick here ends the string and breaks
                         the bundle - which is exactly what happened when this
                         comment was first written. -->
                    <p class="road-box-label">How this week starts</p>
                    <ul class="road-bullets">${(w.daily3 || []).map(t => `<li>${t}</li>`).join('')}</ul>
                </div>
                <div class="road-check">
                    <p><strong>Success check:</strong> ${w.successCheck || 'Completed the week.'}</p>
                    <!-- Batch item 10. canRegenerateWeek() false used to render an
                         empty string here and a visible locked control on the
                         dashboard, so a Base user was told the feature exists on the
                         dashboard and given no hint of it on the 90-day plan -- which
                         is the screen where wanting to redo a week actually occurs to
                         someone. The gate closed correctly on both; the upgrade prompt
                         was simply missing from the better position.
                         Only on unapplied weeks, matching the condition beside it: a
                         week already lived through cannot be rewritten on any plan, so
                         advertising it there would be a lie. -->
                    ${w.applied ? '' : (canRegenerateWeek()
                        ? `<button type="button" class="btn btn-outline btn-sm btn-roadmap-redo" data-plan-id="${w.id}">Redo this week ${proBadge()}</button>`
                        : proLock('week-regen', 'Redo this week'))}
                </div>
            </div>
        </details>
    `;
}

function renderRoadmap() {
    window.setScreenModule({ attachEvents: roadmapAttachEvents });
    const store = getStore();

    
    const weeks = store.weeklyPlans.filter(p => p.generated);
    if (weeks.length === 0) {
        return `
            ${renderNav()}
            <div class="main-content" style="max-width: 800px; padding-top: 5vh; text-align: center;">
                <h2>No 90-Day Plan Found</h2>
                <p style="color: var(--color-text-muted);">You haven't generated a plan yet. Please go to your dashboard to generate one.</p>
                <a href="#/dashboard" class="btn btn-primary mt-4">Go to Dashboard</a>
            </div>
        `;
    }
    
    const sortedWeeks = [...weeks].sort((a, b) => a.weekNumber - b.weekNumber);

    const themes = store.monthlyThemes || {};
    const redFlags = store.redFlags || [];
    
    
    
    const checkedFlags = evaluateRedFlags(redFlags);
    const trippedFlags = checkedFlags.filter(c => c.status === 'tripped');
    const checkableCount = checkedFlags.filter(c => c.status !== 'unchecked').length;
    
    
    
    
    
    
    
    
    const earlyFlags = checkedFlags.filter(c => c.status === 'early');
    const earlyNote = earlyFlags.length
        ? ' ' + earlyFlags.length + ' of them ' + (earlyFlags.length === 1 ? 'is' : 'are')
            + ' too early in ' + (earlyFlags.length === 1 ? 'its' : 'their') + ' own period to call yet.'
        : '';
    const redFlagSummary = checkableCount === 0
        ? 'These came with your plan before the app could check them for you. Compare each one against your own numbers, or regenerate your plan from the dashboard to have them checked automatically.'
        : (trippedFlags.length
            ? trippedFlags.length + ' of these ' + (trippedFlags.length === 1 ? 'is' : 'are') + ' tripped right now. The corrective action beside ' + (trippedFlags.length === 1 ? 'it' : 'them') + ' is this week\'s job.'
            : 'Checked against your own numbers just now, and against how much of each period has actually run: nothing is tripped.')
        + earlyNote
        + (checkableCount && checkableCount < checkedFlags.length
            
            
            
            ? ' ' + (checkedFlags.length - checkableCount) + ' of the ' + checkedFlags.length
                + (checkedFlags.length - checkableCount === 1 ? ' still needs' : ' still need') + ' checking by eye.'
            : '');
    
    
    
    
    const judgedCount = checkedFlags.filter(c => c.status === 'tripped' || c.status === 'ontrack').length;

    
    
    
    
    
    
    
    
    
    
    
    
    
    const snoozedFlags = trippedFlags.filter(c => isRedFlagSnoozed(c.flag, store));
    const liveFlags = trippedFlags.filter(c => !isRedFlagSnoozed(c.flag, store));
    const watchedFlags = checkedFlags.filter(c => c.status === 'ontrack' || c.status === 'early' || c.status === 'nodata');
    const manualFlags = checkedFlags.filter(c => c.status === 'unchecked');
    const watchedAllFine = watchedFlags.length > 0 && watchedFlags.every(c => c.status === 'ontrack');
    const planningDayName = getPlanningDayName(store);
    const redFlagChip = !checkableCount ? ''
        : (trippedFlags.length
            ? `<span class="tag-chip road-chip-tripped">${trippedFlags.length} tripped</span>`
            : judgedCount
                ? '<span class="tag-chip tag-chip-ok">Nothing is tripped</span>'
                : '<span class="tag-chip tag-chip-teal">Too early to tell</span>');
    
    
    
    
    const buildPlan = store.buildPlan || [];
    const legacyChecklist = buildPlan.length ? [] : (store.setupChecklist || []);
    const usingBuildPlan = buildPlan.length > 0;
    const checklist = usingBuildPlan ? buildPlan : legacyChecklist;

    const planSummary = store.planSummary || "Your 90-Day Roadmap has been generated based on your strategy mode and current bottleneck.";
    const planCalibration = store.planCalibration || "Calibrated for your specific stage.";

    
    const lastRegen = (store.planRegenerations || [])[0] || null;
    const lastRegenReason = lastRegen ? lastRegen.reason : '';
    const lastRegenDate = lastRegen && lastRegen.at
        ? new Date(lastRegen.at).toLocaleDateString('en-GB', { day: 'numeric', month: 'long' })
        : '';

    
    
    const currentWeek = currentRoadmapWeek(store);
    
    
    
    
    const currentMonth = currentWeek ? roadmapMonthForWeek(currentWeek, null) : null;

    
    
    
    
    
    
    
    const math = store.planMath;
    const mathCard = (math && math.known) ? `
            <section class="card road-math" id="goal-maths">
                <p class="road-card-label">What this goal actually takes</p>
                <div class="road-math-tiles">
                    <div class="road-tile"><p class="road-tile-big">${moneyText(math.currency, math.revenueGoal)}</p><p class="road-tile-sub">90-day goal</p></div>
                    <div class="road-tile"><p class="road-tile-big">${Number(math.salesRequired).toLocaleString()}</p><p class="road-tile-sub">sales at ${moneyText(math.currency, math.price)}</p></div>
                    <div class="road-tile"><p class="road-tile-big">${Number(math.unitsRequired).toLocaleString()}</p><p class="road-tile-sub">${math.unitPlural} at ${math.ratePercent}%</p></div>
                    <div class="road-tile"><p class="road-tile-big">~${Number(math.unitsPerWeek).toLocaleString()}</p><p class="road-tile-sub">${Number(math.unitsPerWeek) === 1 ? math.unit : math.unitPlural} a week</p></div>
                </div>
                <p class="road-math-text">${goalMathSentences(math).join(' ')}</p>
                ${modelAssumptionNote(math) ? `<p class="road-model-note">${modelAssumptionNote(math)} <a href="#/settings">Set your business model</a>.</p>` : ''}
                <p class="road-note">These are the app's assumptions, not a verdict on you. If your ${math.unitPlural} convert better than ${math.ratePercent}%, you will need fewer of them. Change the numbers in Settings and regenerate to see it.</p>
            </section>
    ` : '';

    const monthCards = [
        [1, 'Foundation', themes.month1],
        [2, 'Momentum', themes.month2],
        [3, 'Conversion', themes.month3]
    ].map(([n, name, theme]) => {
        const here = n === currentMonth;
        return `
                <section class="${here ? 'soft-panel' : 'card'} road-month">
                    <div class="road-month-head"><p class="road-month-label">Month ${n}</p>${here ? '<span class="tag-chip road-chip-now">You are here</span>' : ''}</div>
                    <h2 class="road-h2">${name}</h2>
                    <p class="road-month-theme">${theme || 'Not set'}</p>
                </section>`;
    }).join('');

    return `
        ${renderNav()}
        <div class="main-content dashboard-layout road-page">
            <!-- Redesign group 3c, 21 Sept 2026: the FRoadmap board. Header;
                 the plan summary as the page banner; the goal arithmetic as
                 four figures; the three months with "You are here"; the build
                 plan as tiles; red flags; the twelve weeks as rows that open.
                 The board's "Watch: setting your 90-day plan" link went in on
                 12 Oct 2026, when Jen recorded it — see components/helpVideos.js. -->
            ${renderPlanDriftBanner(store)}
            <div class="plan-head">
                <div class="plan-head-text">
                    ${currentWeek ? `<p class="page-eyebrow">Week ${currentWeek} of 12${currentMonth ? ' · Month ' + currentMonth : ''}</p>` : ''}
                    <h1 class="plan-title">Your 90-Day Roadmap</h1>
                    ${renderScreenVideoLinks('#/roadmap', store)}
                </div>
                <div class="plan-head-actions">
                    <button type="button" class="btn btn-outline btn-regenerate-plan">Regenerate plan</button>
                </div>
            </div>
            <div id="road-regen-progress"></div>

            <section class="hero road-hero">
                <div class="hero-bg" aria-hidden="true">
                    <span class="hero-dot hero-dot-white"></span>
                    <span class="hero-dot road-dot-pink"></span>
                    <span class="hero-dot hero-dot-yellow"></span>
                </div>
                <p class="road-hero-summary">${planSummary}</p>
                <p class="road-hero-calibration">${planCalibration}</p>
                ${lastRegenReason ? `
                    <!-- Added 20 Sept 2026 with the "tell it why" regenerate.
                         Her own sentence, said back to her: three weeks later
                         she should not have to remember what she asked for, and
                         seeing it here is how she checks the plan listened. -->
                    <p class="road-hero-reason">You asked for this plan on ${lastRegenDate} because: “${escapeText(lastRegenReason)}”</p>` : ''}
            </section>

            ${mathCard}

            <div class="road-months">${monthCards}
            </div>

            <!-- Build Plan (batch item 107) — was "Week 1 Setup Checklist".
                 The prompt scoped that list to week 1, which is why it came back
                 with "set up social media profiles" and "create a simple
                 webpage" and nothing that compounds. This is the quarter's
                 spine: which of the five things a business needs gets built in
                 which week, in the order they depend on each other. The board
                 drew these as tiles without a tick; the tick is kept, because
                 it is saved and people use it. -->
            <section class="card road-build" id="build-plan">
                <div>
                    <h2 class="road-h2">${usingBuildPlan ? 'Your Build Plan' : 'Week 1 Setup Checklist'}</h2>
                    <p class="road-intro">${usingBuildPlan
                        ? 'The systems these 90 days build, in the order they depend on each other. Each one is scheduled into a week below, and once it exists it keeps working for you.'
                        : 'Complete these foundational items before diving into your weekly cadence.'}</p>
                </div>
                <div class="road-build-grid">
                    ${















''}
                    ${checklist.map((item, index) => `
                        <label class="road-build-item${item.done ? ' is-done' : ''}">
                            <span class="road-build-chips">
                                <!-- ⚠️ data-task, not data-index (7 Oct 2026). The index
                                     goes stale the moment a background sync replaces
                                     store.buildPlan, which happens every 60 seconds on
                                     this screen — see setBuildTaskDone in store.js. -->
                                <input type="checkbox" class="setup-checkbox" data-index="${index}" data-task="${escapeText(item.task)}" data-list="${usingBuildPlan ? 'build' : 'setup'}" ${item.done ? 'checked' : ''}>
                                ${usingBuildPlan ? `<span class="tag-chip tag-chip-teal">Week ${item.week}</span>` : ''}
                                <span class="tag-chip road-chip-white">${usingBuildPlan ? item.component : `${item.category || 'task'} · ~${item.estimatedMinutes || 15}m`}</span>
                            </span>
                            <span class="road-build-task">${item.task}</span>
                            ${usingBuildPlan && Array.isArray(item.parts) && item.parts.length
                                ? `<ul class="road-build-parts">${item.parts.map(part => `<li>${escapeText(part)}</li>`).join('')}</ul>`
                                : ''}
                            ${usingBuildPlan && item.why ? `<span class="road-build-why">${item.why}</span>` : ''}
                        </label>
                    `).join('')}
                </div>
                <p class="road-note">If you're unsure about anything here, need help with ideas or how to set things up, you can ask your Executive AI Coach.</p>
            </section>

            <!-- Early warnings. Three groups, by what she can do about it.
                 7 Oct 2026, Jen: "The way this shows on the 90-day plan is still
                 very overwhelming."

                 It was a five-column table with every row weighted the same. One
                 flag was tripped and the page read as five, because the
                 THRESHOLD cell carried the red class on every row whether or not
                 that flag was in trouble; three of the five said "Check this
                 yourself", taking as much room as the one that mattered; and
                 Frequency had a whole column to say "weekly" in a space narrow
                 enough to break the word in half, while nothing is ever done
                 differently because of it.

                 It now sorts by what she can act on: the tripped ones as cards
                 with her own correction set into them and two buttons, then the
                 ones being watched as one line each, then the ones the app
                 cannot read at all, which stop pretending to be warnings and say
                 what they are.

                 ⚠️ THE HEADING IS NO LONGER "RED FLAGS". The section was doing
                 some of the alarming by itself, on a page a founder opens to
                 plan. The store key, the plan prompt and redFlags throughout
                 the code are unchanged — this is the visible name only. -->
            <!-- id: the dashboard's Course Correction note links straight here
                 (#/roadmap?at=early-warnings). See js/anchors.js. -->
            <section class="card road-flags" id="early-warnings">
                <div class="road-flags-head">
                    <h2 class="road-h2">Early warnings</h2>
                    ${renderTooltip("The numbers your 90-day plan said would tell you early that something is drifting, checked against what you have actually logged.", "Each one is measured against how much of its own period has run, so nothing reads as a failure just because the week or the month has only just started. Where one is tripped, the correction beside it is the one your plan already chose.")}
                    <span class="road-spacer"></span>
                    ${redFlags.length ? redFlagChip : ''}
                </div>
                ${redFlags.length ? `<p class="road-flags-summary${trippedFlags.length ? ' is-tripped' : ''}">${redFlagSummary}</p>` : ''}

                ${checkedFlags.length === 0 ? `
                    <p class="road-flags-none">This plan came back without any early warnings. Regenerate the plan from your dashboard if you want them.</p>
                ` : ''}

                ${liveFlags.length ? `
                <div class="road-flag-group">
                    <p class="road-flag-grouphead is-urgent">Do something about this</p>
                    ${liveFlags.map(c => `
                    <article class="road-flag-card">
                        <div class="road-flag-cardtop">
                            <div class="road-flag-cardwho">
                                <h3 class="road-flag-name">${escapeText(redFlagMetricLabel(c.flag))}</h3>
                                <p class="road-flag-standing">${flagStandingText(c)}</p>
                            </div>
                            ${flagBarHtml(c)}
                        </div>
                        <div class="road-flag-fix">
                            <p class="road-flag-fixlabel">What you said you would do about it</p>
                            <p class="road-flag-fixtext">${escapeText(String(c.flag.correctiveAction || '').trim() || 'Your plan did not name a correction for this one.')}</p>
                        </div>
                        <div class="road-flag-actions">
                            <button type="button" class="btn btn-primary btn-sm btn-flag-adopt"
                                    data-metric="${escapeText(String(c.flag.metric || ''))}"
                                    data-action="${escapeText(String(c.flag.correctiveAction || ''))}">Make this my revenue action</button>
                            <button type="button" class="btn btn-outline btn-sm btn-flag-snooze"
                                    data-metric="${escapeText(String(c.flag.metric || ''))}">Not this week</button>
                        </div>
                    </article>
                    `).join('')}
                </div>
                ` : ''}

                ${snoozedFlags.length ? `
                <div class="road-flag-group">
                    <p class="road-flag-grouphead is-quiet">Set aside until ${escapeText(planningDayName)}</p>
                    ${snoozedFlags.map(c => `
                    <div class="road-flag-line is-snoozed">
                        <span class="road-flag-linename">${escapeText(redFlagMetricLabel(c.flag))}</span>
                        <span class="road-flag-linedetail">${flagStandingText(c)}</span>
                        <button type="button" class="btn-flag-wake" data-metric="${escapeText(String(c.flag.metric || ''))}">Bring it back</button>
                    </div>
                    `).join('')}
                </div>
                ` : ''}

                ${watchedFlags.length ? `
                <div class="road-flag-group">
                    <p class="road-flag-grouphead is-ok">Being watched${watchedAllFine ? ', and fine' : ''}</p>
                    ${watchedFlags.map(c => `
                    <div class="road-flag-line">
                        <span class="road-flag-tick ${c.status === 'ontrack' ? 'is-ok' : 'is-early'}">${c.status === 'ontrack' ? '&#10003;' : '&middot;'}</span>
                        <span class="road-flag-linename">${escapeText(redFlagMetricLabel(c.flag))}</span>
                        <span class="road-flag-linedetail">${flagStandingText(c)}</span>
                    </div>
                    `).join('')}
                </div>
                ` : ''}

                ${manualFlags.length ? `
                <div class="road-flag-group">
                    <p class="road-flag-grouphead is-quiet">The app cannot read these &mdash; check them yourself</p>
                    <div class="road-flag-manual">
                        ${manualFlags.map(c => `
                        <div class="road-flag-line">
                            <span class="road-flag-linename">${escapeText(redFlagMetricLabel(c.flag))}</span>
                            <span class="road-flag-linedetail">${escapeText(String(c.flag.threshold || '').trim())}</span>
                        </div>
                        `).join('')}
                        <p class="road-flag-manualnote">These came back without a number the app knows how to read, so nothing here is a verdict. Regenerating your plan from the dashboard will try again, or keep them as your own reminders.</p>
                    </div>
                </div>
                ` : ''}
            </section>

            <!-- 12-Week Roadmap -->
            <section class="card road-weeks" id="execution-plan">
                <div class="road-weeks-head">
                    <h2 class="road-h2">12-Week Execution Plan</h2>
                    <span class="road-spacer"></span>
                    <span class="road-intro">Click a week to open it</span>
                </div>
                <p class="road-note">Your weekly priorities and triplet tasks will automatically populate your "Daily 3" list on the Dashboard to guide your daily focus.</p>
                ${sortedWeeks.map(w => roadmapWeekRow(w, currentWeek)).join('')}
            </section>
        </div>
    `;
}

function roadmapAttachEvents() {
    
    
    
    bindPlanDriftBanner(() => rerenderScreen());

    
    document.querySelectorAll('.setup-checkbox').forEach(cb => {
        cb.addEventListener('change', (e) => {
            
            
            
            const listName = e.target.getAttribute('data-list') === 'build' ? 'buildPlan' : 'setupChecklist';
            const task = e.target.getAttribute('data-task') || '';
            const wrote = setBuildTaskDone(listName, task, e.target.checked);

            if (wrote) {
                
                e.target.closest('label').classList.toggle('is-done', e.target.checked);
                return;
            }

            
            
            
            
            
            e.target.checked = !e.target.checked;
            rerenderScreen();
        });
    });

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    document.querySelectorAll('.btn-flag-adopt').forEach(btn => {
        btn.addEventListener('click', async (e) => {
            const action = e.currentTarget.getAttribute('data-action') || '';
            if (!action.trim()) return;

            const plan = getActivePlan();
            if (!plan) {
                sessionStorage.setItem('pendingRevenueAction', action);
                window.location.hash = '#/monday-plan';
                return;
            }

            const current = String(plan.revenueAction || '').trim();
            if (current && current !== action.trim()) {
                const ok = await showConfirm(
                    `This week's revenue action is currently "${current}". Replacing it with your plan's correction will overwrite what you wrote.`,
                    { title: 'Replace this week\'s revenue action?', confirmText: 'Replace it', cancelText: 'Keep mine' }
                );
                if (!ok) return;
            }

            updateWeeklyPlan(plan.id, { revenueAction: action.trim() });
            trackAction('correction_adopted_from_roadmap');
            showToast('Added to this week as your revenue action.');
            rerenderScreen();
        });
    });

    
    
    document.querySelectorAll('.btn-flag-snooze').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const metric = e.currentTarget.getAttribute('data-metric') || '';
            if (!snoozeRedFlag({ metric })) return;
            trackAction('red_flag_snoozed');
            showToast(`Set aside until ${getPlanningDayName(getStore())}.`);
            rerenderScreen();
        });
    });

    
    
    document.querySelectorAll('.btn-flag-wake').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const metric = e.currentTarget.getAttribute('data-metric') || '';
            const store = getStore();
            const key = redFlagKey({ metric });
            if (!key || !store.redFlagSnoozes || !(key in store.redFlagSnoozes)) return;
            delete store.redFlagSnoozes[key];
            saveStore(store);
            rerenderScreen();
        });
    });

    
    
    
    const btnRegen = document.querySelector('.btn-regenerate-plan');
    if (btnRegen) {
        btnRegen.addEventListener('click', async (e) => {
            const btn = e.currentTarget;
            const reason = await askWhyRegenerating();
            if (reason === null) return;
            btn.disabled = true;
            const applied = await runPlanRegeneration({
                progressEl: document.getElementById('road-regen-progress'),
                skipConfirm: true,
                reason
            });
            btn.disabled = false;
            if (applied) rerenderScreen();
        });
    }

    
    
    document.querySelectorAll('.btn-roadmap-redo').forEach(btn => {
        btn.addEventListener('click', () => {
            showWeekRegenModal(btn.getAttribute('data-plan-id'));
        });
    });
}











const CONFIRM_POLL_MS = 2000;
const CONFIRM_TIMEOUT_MS = 30000;



let confirmAbandoned = false;
let confirmTimer = null;




function hasCheckoutMarker() {
    if (/[?&]checkout=success/.test(window.location.search)) return true;
    const hash = window.location.hash || '';
    const q = hash.indexOf('?');
    return q !== -1 && /[?&]checkout=success/.test(hash.slice(q));
}

function clearCheckoutMarker() {
    const hash = (window.location.hash || '').split('?')[0];
    const url = window.location.pathname + (hash || '#/billing');
    window.history.replaceState({}, '', url);
}

function renderBilling() {
    window.setScreenModule({ attachEvents: billingAttachEvents });

    const status = localStorage.getItem('ceo_sub_status');

    
    
    if (hasCheckoutMarker() && !confirmAbandoned && status !== 'active') {
        return renderConfirmingPayment();
    }

    
    if (status === 'trialing') return renderTrialEnded(true);

    
    if (status === 'trial_expired' || status === 'incomplete') return renderTrialEnded(false);

    
    return renderPaymentProblem();
}



function renderConfirmingPayment() {
    return `
        <div style="min-height: 100vh; display: flex; align-items: center; justify-content: center; background: linear-gradient(135deg, var(--color-primary-light) 0%, var(--color-bg-main) 100%); padding: 1.5rem;">
            <div id="confirm-payment-card" class="card fade-up" style="width: 100%; max-width: 460px; padding: 3rem 2.5rem; text-align: center; box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1); border: 1px solid rgba(255,255,255,0.5); backdrop-filter: blur(10px);">

                <div class="spinner" style="width: 32px; height: 32px; border: 3px solid var(--color-primary-light); border-top: 3px solid var(--color-primary); border-radius: 50%; animation: spin 1s linear infinite; margin: 0 auto 1.5rem;"></div>

                <h2 style="font-size: 1.5rem; color: var(--color-black); margin-bottom: 1rem; letter-spacing: -0.02em;">Confirming your payment</h2>

                <p style="color: var(--color-text-muted); font-size: 1rem; line-height: 1.6; margin-bottom: 0;">
                    Thank you. Your payment has gone through and we're just waiting for it
                    to reach your account. This usually takes a few seconds.
                </p>
            </div>
        </div>
    `;
}















