async function checkAccessNow() {
    const access = await window.refreshAccessState();
    if (!access) return null; 

    if (!window.isLockedOut(access.status)) {
        clearCheckoutMarker();
        
        
        
        
        
        
        
        
        reloadAt('#/dashboard');
        return true;
    }
    return false;
}

function billingAttachEvents() {
    
    if (document.getElementById('confirm-payment-card') && hasCheckoutMarker() && !confirmAbandoned) {
        const startedAt = Date.now();
        if (confirmTimer) clearInterval(confirmTimer);

        confirmTimer = setInterval(async () => {
            const done = await checkAccessNow();
            if (done) {
                clearInterval(confirmTimer);
                confirmTimer = null;
                return;
            }

            if (Date.now() - startedAt >= CONFIRM_TIMEOUT_MS) {
                clearInterval(confirmTimer);
                confirmTimer = null;
                
                
                
                confirmAbandoned = true;
                showToast("Your payment went through, but it hasn't reached your account yet. Give it a minute and press 'Refresh my account', or email " + SUPPORT_EMAIL + " and we'll sort it.", 'error');
                rerenderScreen();
            }
        }, CONFIRM_POLL_MS);
    }

    
    
    
    
    
    const btnExport = document.getElementById('btn-paywall-export');
    if (btnExport) {
        btnExport.addEventListener('click', async () => {
            const original = btnExport.innerHTML;
            btnExport.textContent = 'Preparing your file…';
            btnExport.disabled = true;
            try {
                await exportRevenueCsv();
            } catch (err) {
                console.error('Paywall CSV export failed:', err);
                showToast("We couldn't build that file just now. Try again, or email " + SUPPORT_EMAIL + " and we'll send you a copy.", 'error');
            }
            btnExport.innerHTML = original;
            btnExport.disabled = false;
        });
    }

    const btnRefresh = document.getElementById('btn-refresh-account');
    if (btnRefresh) {
        btnRefresh.addEventListener('click', async (e) => {
            e.preventDefault();
            const original = btnRefresh.textContent;
            btnRefresh.textContent = 'Checking…';
            btnRefresh.style.pointerEvents = 'none';

            const result = await checkAccessNow();

            btnRefresh.textContent = original;
            btnRefresh.style.pointerEvents = '';

            if (result === null) {
                showToast("We couldn't reach the server. Check your connection and try again.", 'error');
            } else if (result === false) {
                showToast("We can't see a payment on this account yet. If you've just paid, give it a minute. If you checked out with a different email address, email " + SUPPORT_EMAIL + " and we'll link it up.", 'error');
            }
            
        });
    }

    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    const checkout = async (baseUrl) => {
        let url = baseUrl;
        try {
            const { data: { session } } = await window.db.auth.getSession();
            const user = session && session.user;
            const add = (key, value) => {
                url += (url.includes('?') ? '&' : '?') + key + '=' + encodeURIComponent(value);
            };
            if (user && user.email) add('prefilled_email', user.email);
            if (user && user.id) add('client_reference_id', user.id);
        } catch (err) {
            console.warn('Could not read the session for checkout:', err.message);
        }
        window.location.href = url;
    };

    const btnAnnual = document.getElementById('btn-annual');
    if (btnAnnual) {
        btnAnnual.addEventListener('click', () => checkout(window.CEO_CHECKOUT_ANNUAL));
    }

    const btnMonthly = document.getElementById('btn-monthly');
    if (btnMonthly) {
        btnMonthly.addEventListener('click', () => checkout(window.CEO_CHECKOUT_MONTHLY));
    }

    const btnProAnnual = document.getElementById('btn-pro-annual');
    if (btnProAnnual) {
        btnProAnnual.addEventListener('click', () => checkout(window.CEO_CHECKOUT_PRO_ANNUAL));
    }

    const btnProMonthly = document.getElementById('btn-pro-monthly');
    if (btnProMonthly) {
        btnProMonthly.addEventListener('click', () => checkout(window.CEO_CHECKOUT_PRO_MONTHLY));
    }

    
    
    
    
    
    const btnPortal = document.getElementById('btn-portal');
    if (btnPortal) {
        btnPortal.addEventListener('click', async () => {
            const original = btnPortal.textContent;
            btnPortal.disabled = true;
            btnPortal.textContent = 'Opening…';

            const failed = await openBillingPortal();

            if (failed) {
                btnPortal.disabled = false;
                btnPortal.textContent = original;
            }
        });
    }

    const btnSignout = document.getElementById('btn-signout');
    if (btnSignout) {
        btnSignout.addEventListener('click', async (e) => {
            e.preventDefault();
            try { await window.db.auth.signOut({ scope: 'local' }); } catch (err) {  }
            localStorage.removeItem('ceo_auth');
            localStorage.removeItem('ceo_sub_status');
            localStorage.removeItem('ceo_trial_ends_at');
            localStorage.removeItem('ceo_plan_tier');
            localStorage.removeItem('ceo_comp_pro');
            
            
            localStorage.removeItem('ceo_cancel_at_period_end');
            localStorage.removeItem('ceo_current_period_end');
            localStorage.removeItem('ceo_pending_plan_tier');
            localStorage.removeItem('ceoPlanner_store');
            
            
            clearStoreOwner();
            
            reloadAt('#/login');
        });
    }
}



























const SURVEY_QUESTIONS = [
    { key: 'used_for', n: 1, label: 'What did you use CEO Planner for most?' },
    { key: 'knew_what_next', n: 2, label: 'Did it help you know what to work on next? Why or why not?', long: true },
    { key: 'confusing', n: 3, label: 'What was confusing, frustrating, or missing?', long: true },
    { key: 'would_keep', n: 4, label: 'Would you keep using it? What would make that a yes?', long: true },
    { key: 'describe', n: 5, label: 'How would you describe CEO Planner to a friend?' }
];

function surveyQuestions() {
    return SURVEY_QUESTIONS.slice();
}





let loadedResponse = null;
let loadState = 'idle'; 

function betaSurveyCache() {
    return loadedResponse;
}


function setBetaSurveyCache(row) {
    loadedResponse = row || null;
    loadState = row ? 'ready' : loadState;
}

function resetBetaSurveyCache() {
    loadedResponse = null;
    loadState = 'idle';
}

async function loadResponse() {
    if (loadState === 'loading' || loadState === 'ready') return;
    loadState = 'loading';

    let user = null;
    try {
        const { data } = await window.db.auth.getSession();
        user = data && data.session && data.session.user;
    } catch (err) {
        loadState = 'failed';
        return;
    }
    if (!user) {
        loadState = 'failed';
        return;
    }

    try {
        const { data, error } = await window.db
            .from('beta_survey_responses')
            .select('*')
            .eq('user_id', user.id)
            .maybeSingle();
        if (error) {
            console.warn('Could not load the beta survey response:', error.message);
            loadState = 'failed';
            return;
        }
        loadedResponse = data || null;
        loadState = 'ready';
        
        
        if (loadedResponse) markBetaSurveyAnswered();
    } catch (err) {
        loadState = 'failed';
        return;
    }

    
    
    
    if (loadedResponse) {
        window.dispatchEvent(new Event('hashchange'));
    }
}







function closingLine() {
    const label = betaClosesLabel();
    const daysLeft = betaDaysLeft();
    if (!label || daysLeft === null) return '';

    if (daysLeft < 0) {
        return `<p class="beta-survey-closing beta-survey-closed">The beta closed on ${label}. Thank you, and if you have something to add you can still change your answers below.</p>`;
    }
    const when = daysLeft === 0
        ? 'Today is the last day to answer.'
        : (daysLeft === 1 ? 'It closes tomorrow.' : `It closes on ${label}.`);
    return `<p class="beta-survey-closing">${when}</p>`;
}

function savedAtLine(row) {
    if (!row || !row.updated_at) return '';
    const d = new Date(row.updated_at);
    if (!Number.isFinite(d.getTime())) return '';
    const when = d.toLocaleDateString(undefined, { day: 'numeric', month: 'long' })
        + ' at ' + d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
    return `<p class="beta-survey-saved">Saved ${when}. You can change any of this until the beta closes.</p>`;
}

function questionHtml(q, row) {
    const value = row && row[q.key] ? String(row[q.key]) : '';
    return `
            <div class="form-group">
                <label class="form-label" for="beta-q-${q.key}">${q.n}. ${q.label}</label>
                <textarea id="beta-q-${q.key}" class="form-textarea" data-survey-key="${q.key}"
                    rows="${q.long ? 5 : 3}">${escapeText(value)}</textarea>
            </div>`;
}








function likelihoodHtml(row) {
    const current = row && row.likelihood ? Number(row.likelihood) : null;
    const options = [];
    for (let n = 1; n <= 10; n++) {
        options.push(`
                    <button type="button" class="beta-scale-btn${current === n ? ' is-chosen' : ''}"
                        data-likelihood="${n}" aria-pressed="${current === n ? 'true' : 'false'}">${n}</button>`);
    }
    return `
            <div class="form-group">
                <span class="form-label" id="beta-likelihood-label">6. On a scale of 1 to 10, how likely are you to keep using it?</span>
                <p class="beta-scale-caption">1 means you would not keep using it at all. 10 means you would definitely keep using it.</p>
                <div class="beta-scale-row" role="group" aria-labelledby="beta-likelihood-label">${options.join('')}
                </div>
            </div>`;
}

function followUpHtml(row) {
    const yes = row && row.follow_up_ok === true;
    const no = row && row.follow_up_ok === false;
    return `
            <div class="form-group">
                <span class="form-label" id="beta-followup-label">7. Can we contact you with a follow-up question?</span>
                <div class="beta-choice-row" role="group" aria-labelledby="beta-followup-label">
                    <button type="button" class="beta-choice-btn${yes ? ' is-chosen' : ''}" data-followup="yes" aria-pressed="${yes ? 'true' : 'false'}">Yes</button>
                    <button type="button" class="beta-choice-btn${no ? ' is-chosen' : ''}" data-followup="no" aria-pressed="${no ? 'true' : 'false'}">No</button>
                </div>
            </div>`;
}

function renderBetaSurvey() {
    window.setScreenModule({ attachEvents: betaSurveyAttachEvents });

    
    
    
    loadResponse();

    const row = loadedResponse;

    
    
    
    if (!isBetaTester()) {
        return `
        ${renderNav()}
        <div class="main-content">
            <div class="card beta-survey-card">
                <h1 class="page-title">Beta feedback</h1>
                <p>This survey is open to the beta testers we invited. Your account is not on that list, so there is nothing for you to fill in here.</p>
                <p>If you think that is wrong, reply to the email we sent you and we will sort it out.</p>
                <p><a href="#/dashboard" class="btn btn-primary">Back to your dashboard</a></p>
            </div>
        </div>`;
    }

    return `
        ${renderNav()}
        <div class="main-content">
            <div class="card beta-survey-card">
                <h1 class="page-title">How was the beta?</h1>
                <p class="beta-survey-intro">Seven questions, and none of them are compulsory. Answer what you have something to say about and leave the rest. This goes to us only — it is never published and never shared.</p>
                ${closingLine()}
                ${savedAtLine(row)}

                ${SURVEY_QUESTIONS.map(q => questionHtml(q, row)).join('')}
                ${likelihoodHtml(row)}
                ${followUpHtml(row)}

                <div class="beta-survey-actions">
                    <button type="button" class="btn btn-primary" id="beta-survey-save">${row ? 'Save changes' : 'Send'}</button>
                </div>
            </div>
        </div>`;
}

function betaSurveyAttachEvents() {
    
    
    const scaleButtons = document.querySelectorAll('.beta-scale-btn');
    scaleButtons.forEach(btn => {
        btn.addEventListener('click', () => {
            scaleButtons.forEach(b => {
                const on = b === btn;
                b.classList.toggle('is-chosen', on);
                b.setAttribute('aria-pressed', on ? 'true' : 'false');
            });
        });
    });

    const choiceButtons = document.querySelectorAll('.beta-choice-btn');
    choiceButtons.forEach(btn => {
        btn.addEventListener('click', () => {
            choiceButtons.forEach(b => {
                const on = b === btn;
                b.classList.toggle('is-chosen', on);
                b.setAttribute('aria-pressed', on ? 'true' : 'false');
            });
        });
    });

    const saveBtn = document.getElementById('beta-survey-save');
    if (!saveBtn) return;

    
    
    let saving = false;
    saveBtn.addEventListener('click', async () => {
        if (saving) return;

        const payload = {};
        SURVEY_QUESTIONS.forEach(q => {
            const el = document.querySelector(`[data-survey-key="${q.key}"]`);
            payload[q.key] = el ? String(el.value || '').trim() || null : null;
        });

        const chosenScale = document.querySelector('.beta-scale-btn.is-chosen');
        payload.likelihood = chosenScale ? Number(chosenScale.getAttribute('data-likelihood')) : null;

        const chosenFollowUp = document.querySelector('.beta-choice-btn.is-chosen');
        payload.follow_up_ok = chosenFollowUp
            ? chosenFollowUp.getAttribute('data-followup') === 'yes'
            : null;

        
        
        
        const hasAnything = SURVEY_QUESTIONS.some(q => payload[q.key])
            || payload.likelihood !== null
            || payload.follow_up_ok !== null;
        if (!hasAnything) {
            showToast('Answer at least one question first, then send it.', 'error');
            return;
        }

        saving = true;
        const originalText = saveBtn.innerText;
        saveBtn.innerText = 'Saving...';
        saveBtn.disabled = true;

        const failure = await saveBetaSurvey(payload);

        saving = false;
        saveBtn.innerText = originalText;
        saveBtn.disabled = false;

        if (failure) {
            
            showToast(failure, 'error', 9000);
            return;
        }

        showToast('Thank you. That has gone straight to us.', 'success', 6000);
        saveBtn.innerText = 'Save changes';
    });
}


async function saveBetaSurvey(payload) {
    let user = null;
    try {
        const { data } = await window.db.auth.getSession();
        user = data && data.session && data.session.user;
    } catch (err) {
        return 'That did not save. The connection dropped before it reached us, so your answers are still here.';
    }
    if (!user) {
        return 'That did not save because you are signed out. Sign in again and your answers are still here.';
    }

    const row = Object.assign({ user_id: user.id }, payload);

    try {
        const { error } = await window.db
            .from('beta_survey_responses')
            
            
            
            .upsert(row, { onConflict: 'user_id' });
        if (error) {
            console.warn('Beta survey save failed:', error.message);
            if (error.code === '42P01') {
                return 'The survey is not switched on yet. Nothing you typed is lost — let us know the survey table is missing.';
            }
            return 'That did not save, and the server did not say why. Your answers are still here to try again.';
        }
    } catch (err) {
        return 'That did not save. The connection dropped before it reached us, so your answers are still here.';
    }

    
    
    loadedResponse = Object.assign({}, loadedResponse || {}, row, {
        updated_at: new Date().toISOString()
    });
    loadState = 'ready';
    
    markBetaSurveyAnswered();
    return null;
}









































const TYPE_LABELS = {
    bug: 'Bug',
    confusing: 'Confusing',
    idea: 'Idea',
    love: 'Love this'
};

function typeLabel(value) {
    return TYPE_LABELS[value] || String(value || 'Feedback');
}



function feedbackWhen(iso) {
    if (!iso) return '';
    const d = new Date(iso);
    if (!Number.isFinite(d.getTime())) return '';
    return d.toLocaleDateString(undefined, { day: 'numeric', month: 'long' })
        + ' at ' + d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });
}











function feedbackFeed(payload) {
    const reports = (payload && Array.isArray(payload.reports)) ? payload.reports : [];
    const surveys = (payload && Array.isArray(payload.surveys)) ? payload.surveys : [];

    const items = [];
    reports.forEach(r => {
        if (!r) return;
        items.push({ kind: 'report', at: r.created_at || '', row: r });
    });
    surveys.forEach(s => {
        if (!s) return;
        items.push({ kind: 'survey', at: s.updated_at || '', row: s });
    });

    items.sort((a, b) => String(b.at).localeCompare(String(a.at)));
    return items;
}








function newPill(item, seen) {
    if (seen && String(item.at) <= String(seen)) return '';
    return '<span class="fbi-new">New</span>';
}

function metaLine(item, seen, typeText, whoText, tail) {
    const parts = [escapeText(whoText), escapeText(feedbackWhen(item.at))];
    (tail || []).forEach(t => { if (t) parts.push(escapeText(t)); });
    return `
            <p class="fbi-meta">
                <span class="fbi-type fbi-type-${escapeText(item.kind === 'survey' ? 'survey' : String(item.row.type || 'other'))}">${escapeText(typeText)}</span>
                ${newPill(item, seen)}
                <span class="fbi-who">${parts.join(' · ')}</span>
            </p>`;
}


function reportCardHtml(item, seen) {
    const row = item.row || {};
    const who = row.email ? String(row.email) : 'an account with no address on file';

    
    
    const tail = [];
    if (row.page) tail.push('on ' + row.page);
    if (row.app_version) tail.push('v' + row.app_version);
    if (row.beta === false) tail.push('not in the beta');

    
    
    
    
    
    const device = [];
    if (row.viewport) device.push(`<p class="fbi-device">Screen ${escapeText(String(row.viewport))}</p>`);
    if (row.user_agent) {
        device.push(`
                <details class="fbi-ua">
                    <summary>Browser details</summary>
                    <p>${escapeText(String(row.user_agent))}</p>
                </details>`);
    }

    return `
        <article class="card fbi-item">
            ${metaLine(item, seen, typeLabel(row.type), who, tail)}
            <p class="fbi-message">${escapeText(String(row.message || ''))}</p>
            ${device.join('')}
        </article>`;
}


function surveyCardHtml(item, seen) {
    const row = item.row || {};
    const who = row.email ? String(row.email) : 'a tester with no address on file';

    const tail = [];
    
    
    if (row.created_at && String(row.created_at).slice(0, 16) !== String(row.updated_at || '').slice(0, 16)) {
        tail.push('first answered ' + feedbackWhen(row.created_at));
    }

    
    
    const answers = surveyQuestions().map(q => {
        const value = row[q.key];
        if (!value) return '';
        return `
            <div class="fbi-answer">
                <p class="fbi-question">${q.n}. ${escapeText(q.label)}</p>
                <p class="fbi-message">${escapeText(String(value))}</p>
            </div>`;
    }).join('');

    
    
    
    
    const likelihood = (row.likelihood === null || row.likelihood === undefined)
        ? ''
        : `
            <div class="fbi-answer">
                <p class="fbi-question">6. How likely are they to keep using it?</p>
                <p class="fbi-message">${escapeText(String(row.likelihood))} out of 10</p>
                <p class="fbi-caption">They were told 1 means they would not keep using it at all, and 10 means they definitely would.</p>
            </div>`;

    const followUp = (row.follow_up_ok === null || row.follow_up_ok === undefined)
        ? ''
        : `
            <div class="fbi-answer">
                <p class="fbi-question">7. Can you contact them with a follow-up question?</p>
                <p class="fbi-message">${row.follow_up_ok ? 'Yes' : 'No'}</p>
            </div>`;

    
    
    const nothingWritten = !answers
        ? '<p class="fbi-caption">They answered the scale but wrote nothing, which is their right — none of the questions are compulsory.</p>'
        : '';

    return `
        <article class="card fbi-item">
            ${metaLine(item, seen, 'Survey', who, tail)}
            ${nothingWritten}
            ${answers}
            ${likelihood}
            ${followUp}
        </article>`;
}

function feedbackFeedHtml(payload, seen) {
    const items = feedbackFeed(payload);

    if (!items.length) {
        return `
        <section class="card adm-panel">
            <h2 class="adm-h2">Nothing yet</h2>
            <p class="adm-sub">Nobody has pressed the Feedback button or answered the end-of-beta survey. When they do it appears here, newest first, and a line at the top of the app tells you it has arrived.</p>
        </section>`;
    }

    return items
        .map(item => item.kind === 'survey' ? surveyCardHtml(item, seen) : reportCardHtml(item, seen))
        .join('');
}



function feedbackCountLine(payload) {
    const reports = (payload && Array.isArray(payload.reports)) ? payload.reports.length : 0;
    const surveys = (payload && Array.isArray(payload.surveys)) ? payload.surveys.length : 0;

    if (!reports && !surveys) return '';

    const parts = [];
    if (reports) parts.push(reports === 1 ? '1 note from the Feedback button' : reports + ' notes from the Feedback button');
    if (surveys) parts.push(surveys === 1 ? '1 answered survey' : surveys + ' answered surveys');
    return parts.join(' and ') + '. Newest first.';
}







let seenOnEntry = null;

function renderFeedbackInbox() {
    window.setScreenModule({ attachEvents: feedbackInboxAttachEvents });

    if (!isAdminAccount()) {
        return `
        ${renderNav()}
        <div class="main-content adm-page">
            <div class="plan-head">
                <div class="plan-head-text">
                    <p class="page-eyebrow">Feedback</p>
                    <h1 class="plan-title">Not your screen</h1>
                    <p class="help-lede">This page is for the account that runs the app. If you think that is you, sign out and back in — the flag is read when you sign in.</p>
                </div>
            </div>
        </div>`;
    }

    seenOnEntry = feedbackSeenAt();

    
    
    const cached = feedbackCache();

    return `
        ${renderNav()}
        <div class="main-content adm-page">
            <div class="plan-head">
                <div class="plan-head-text">
                    <p class="page-eyebrow">Feedback</p>
                    <h1 class="plan-title">What people have told you</h1>
                    <p class="help-lede">Everything sent through the Feedback button and the end-of-beta survey, in their own words. Nothing here is published anywhere and nobody but you can read it.</p>
                </div>
                <div class="adm-head-actions">
                    <button type="button" class="btn btn-ghost" id="fbi-refresh">Refresh</button>
                </div>
            </div>

            <div id="fbi-body">
                ${cached
                    ? `<p class="adm-sub">${escapeText(feedbackCountLine(cached))}</p>${feedbackFeedHtml(cached, seenOnEntry)}`
                    : '<p class="adm-loading">Reading what people sent…</p>'}
            </div>
        </div>`;
}

function paintFeedback(payload) {
    const body = document.getElementById('fbi-body');
    if (!body) return;

    if (!payload) {
        body.innerHTML = '<p class="adm-empty">Could not read the feedback just now. Nothing is wrong with what people sent; the request did not get through. Try Refresh in a moment.</p>';
        return;
    }

    const line = feedbackCountLine(payload);
    body.innerHTML = (line ? `<p class="adm-sub">${escapeText(line)}</p>` : '')
        + feedbackFeedHtml(payload, seenOnEntry);
}









function markSeenFrom(payload) {
    const items = feedbackNewsFrom(payload);
    if (!items.length) return;
    markFeedbackSeen(items[0].at);
}

async function loadFeedback() {
    const payload = await refreshFeedbackNews();
    paintFeedback(payload);
    if (payload) markSeenFrom(payload);
}

function feedbackInboxAttachEvents() {
    if (!isAdminAccount()) return;

    const refresh = document.getElementById('fbi-refresh');
    if (refresh) {
        refresh.addEventListener('click', () => {
            const body = document.getElementById('fbi-body');
            if (body) body.innerHTML = '<p class="adm-loading">Reading what people sent…</p>';
            loadFeedback().then(() => showToast('Up to date.'));
        });
    }

    
    
    
    loadFeedback();
}








