async function handleConfirmedSignup() {
    window.CEO_COMPLETING_CONFIRMATION = true;

    
    try {
        history.replaceState(null, '', window.location.pathname + window.location.search + '#/');
    } catch (err) {
        
    }

    let user = null;
    try {
        
        
        const { data } = await window.db.auth.getSession();
        user = data && data.session && data.session.user;
    } catch (err) {
        console.warn('Could not read the confirmation session:', err && err.message);
    }

    if (!user) {
        window.CEO_COMPLETING_CONFIRMATION = false;
        localStorage.removeItem('ceo_auth');
        try {
            history.replaceState(null, '', window.location.pathname + window.location.search + '#/login');
        } catch (err) {
            window.location.hash = '#/login';
        }
        showToast("Your email is confirmed. Log in to get started.", 'success', 9000);
        router();
        return;
    }

    
    
    const signedIn = await completeSignIn(user.id, () => '#/');
    if (signedIn === false) {
        
        
        
        window.CEO_COMPLETING_CONFIRMATION = false;
        try {
            history.replaceState(null, '', window.location.pathname + window.location.search + '#/login');
        } catch (err) {
            window.location.hash = '#/login';
        }
        router();
    }
}









